INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11776, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "长距离", "is_correct": true, "explanation": "正确。“减少长距离通勤”指减少起终点相隔很远的通勤，与“搬到公司附近”的目的一致。"}, {"text": "近距离", "is_correct": false, "explanation": "语义：“近距离”与“长距离”相反。句中要减少的是长距离通勤，“减少近距离通勤”与语境相悖。"}, {"text": "报纸", "is_correct": false, "explanation": "搭配：“报纸”不是通勤的距离或方式，不能作“通勤”的修饰语。"}, {"text": "花卉", "is_correct": false, "explanation": "搭配：“花卉”指花草植物，与“通勤”无关，不能修饰“通勤”。"}], "explanations": {"长距离": "正确。“减少长距离通勤”指减少起终点相隔很远的通勤，与“搬到公司附近”的目的一致。", "近距离": "语义：“近距离”与“长距离”相反。句中要减少的是长距离通勤，“减少近距离通勤”与语境相悖。", "报纸": "搭配：“报纸”不是通勤的距离或方式，不能作“通勤”的修饰语。", "花卉": "搭配：“花卉”指花草植物，与“通勤”无关，不能修饰“通勤”。"}, "sentence_index": 0, "correct_answer": "长距离"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天坐长距离去上班。", "explanation": "这里应该用〈长途汽车〉。“坐”的宾语应是交通工具，“长距离”只指距离，不能作“坐”的对象。"}, {"text": "他用长距离的方式给员工开会。", "explanation": "这里应该用〈远程〉。“远程”指借助网络等设备远距离进行，如远程会议；“长距离”只说距离，不能表示开会的形式。"}, {"text": "朋友们长距离而来，我们很高兴。", "explanation": "这里应该用〈远道〉。“远道而来”是固定说法，指从远方来；“长距离”只说距离的长短，不能组成这个固定说法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70e02eb2-f66b-4add-bba2-1045639f8f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11776, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "长距离", "is_correct": true, "explanation": "正确。“长距离骑车”指骑很远的路，所以出发前要检查车。"}, {"text": "手机", "is_correct": false, "explanation": "语义：“手机”不能修饰“骑车”，句意不通。"}, {"text": "地铁", "is_correct": false, "explanation": "语义：“地铁”是交通工具，不能修饰“骑车”，“地铁骑车”不成立。"}, {"text": "冷气", "is_correct": false, "explanation": "语义：“冷气”指凉爽的空气，与骑车的路程无关。"}], "explanations": {"长距离": "正确。“长距离骑车”指骑很远的路，所以出发前要检查车。", "手机": "语义：“手机”不能修饰“骑车”，句意不通。", "地铁": "语义：“地铁”是交通工具，不能修饰“骑车”，“地铁骑车”不成立。", "冷气": "语义：“冷气”指凉爽的空气，与骑车的路程无关。"}, "sentence_index": 6, "correct_answer": "长距离"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "北方的冬天很长距离。", "explanation": "这里应该用〈漫长〉。“漫长”可以形容时间长；“长距离”只说空间上的远近，不能形容冬天。"}, {"text": "他长距离生病，身体很弱。", "explanation": "这里应该用〈长期〉。“长期”指时间持续得久，如长期生病；“长距离”只说空间上的远近，不能表示病程的长短。"}, {"text": "他很有长距离的眼光。", "explanation": "这里应该用〈长远〉。“长远眼光”指看得远、考虑长期发展；“长距离”只说空间距离，不能用来形容眼光。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70e02eb2-f66b-4add-bba2-1045639f8f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11776, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一次长距离地旅行。", "corrected_sentence": "这是一次长距离的旅行。", "error_description": "“长距离”作定语修饰名词“旅行”，应该用“的”，写作“长距离的旅行”。句中错用了“地”，属于结构助词错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70e02eb2-f66b-4add-bba2-1045639f8f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11776, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们要完成这段长距离地行程。", "corrected_sentence": "我们要完成这段长距离的行程。", "error_description": "“长距离”作定语修饰名词“行程”时应用“的”，即“长距离的行程”。写成“长距离地行程”，把“地”用在定语后面，属于结构助词错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70e02eb2-f66b-4add-bba2-1045639f8f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11777, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "弹性", "is_correct": true, "explanation": "弹性是刚性在此义（规定、需求不可改变）的反义词，指可伸缩、可调整。"}, {"text": "速度", "is_correct": false, "explanation": "速度与“刚性”不构成反义关系，二者不属于同一语义维度。"}, {"text": "颜色", "is_correct": false, "explanation": "颜色与“刚性”没有反义关系，不是描述同一性质的词。"}, {"text": "温度", "is_correct": false, "explanation": "温度与“刚性”没有反义关系，二者不在同一语义范围内。"}], "correct_answer": "弹性", "explanations": {"弹性": "弹性是刚性在此义（规定、需求不可改变）的反义词，指可伸缩、可调整。", "速度": "速度与“刚性”不构成反义关系，二者不属于同一语义维度。", "颜色": "颜色与“刚性”没有反义关系，不是描述同一性质的词。", "温度": "温度与“刚性”没有反义关系，二者不在同一语义范围内。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c70347ad-27a5-41a9-9ada-627dc309d573') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11777, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "弹性", "is_correct": true, "explanation": "弹性是刚性在此义（规定、需求不可改变）的反义词，指可伸缩、可调整。"}, {"text": "高度", "is_correct": false, "explanation": "高度与“刚性”没有反义关系，不是描述同一性质的词。"}, {"text": "味道", "is_correct": false, "explanation": "味道与“刚性”没有反义关系，二者不在同一语义范围内。"}, {"text": "重量", "is_correct": false, "explanation": "重量与“刚性”没有反义关系，不能与之构成对立。"}], "correct_answer": "弹性", "explanations": {"弹性": "弹性是刚性在此义（规定、需求不可改变）的反义词，指可伸缩、可调整。", "高度": "高度与“刚性”没有反义关系，不是描述同一性质的词。", "味道": "味道与“刚性”没有反义关系，二者不在同一语义范围内。", "重量": "重量与“刚性”没有反义关系，不能与之构成对立。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c70347ad-27a5-41a9-9ada-627dc309d573') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11777, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "形容物体坚硬不易变形，也比喻性格、规则等坚定、不可改变。", "primary_collocate": null, "pronunciation": "gāng xìng", "ipa": "kɑŋ˥˥ ɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "值得注意的是，非洲大陆已有十余国实施不同程度的塑料袋禁令，部分国家甚至对违规生产或进口行为施以刑事处罚，反映出环境政策在资源约束型社会中的刚性取向。", "target_word": "刚性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "该模式通过将高容量轨道交通站点与混合功能用地布局进行耦合设计，使居住、就业、商业与公共服务在步行可达范围内高度集聚，从而在空间结构层面抑制了长距离通勤的刚性需求。", "target_word": "刚性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个规定有刚性，谁也不能随便改。", "target_word": "刚性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房租是每个月必须付的刚性支出。", "target_word": "刚性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校对上课时间有刚性要求。", "target_word": "刚性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种钢的刚性很强，不容易变形。", "target_word": "刚性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的计划缺少弹性，刚性太强。", "target_word": "刚性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "吃饭是每个人的刚性需求。", "target_word": "刚性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司的预算有刚性，不能多花一分钱。", "target_word": "刚性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住房是很多家庭的刚性需求。", "target_word": "刚性", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "刚性需求", "label": "复合"}, {"form": "刚性要求", "label": "复合"}, {"form": "刚性支出", "label": "复合"}], "register": "中性", "sense_fingerprint": "物体坚硬不易变形，也指规则、需求等不可改变的特性", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd34bc2cc-089b-431f-93cf-0515a2573957') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11777, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "刚性", "is_correct": true, "explanation": "刚性指规定严格、不可改变，与前文的“禁令”“刑事处罚”的严厉语境一致。"}, {"text": "宽松性", "is_correct": false, "explanation": "语义：“宽松”与“施以刑事处罚”的严厉语境相矛盾。"}, {"text": "温和性", "is_correct": false, "explanation": "语义：“温和”与“刑事处罚”相冲突，句意不通。"}, {"text": "随意性", "is_correct": false, "explanation": "搭配：“取向”多与“严格”“宽松”等程度词搭配，“随意性”指任意而为，与政策的“取向”搭配不当。"}], "explanations": {"刚性": "刚性指规定严格、不可改变，与前文的“禁令”“刑事处罚”的严厉语境一致。", "宽松性": "语义：“宽松”与“施以刑事处罚”的严厉语境相矛盾。", "温和性": "语义：“温和”与“刑事处罚”相冲突，句意不通。", "随意性": "搭配：“取向”多与“严格”“宽松”等程度词搭配，“随意性”指任意而为，与政策的“取向”搭配不当。"}, "sentence_index": 0, "correct_answer": "刚性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个月的娱乐支出很有刚性，想花多少就花多少。", "explanation": "这里应该用〈弹性〉。刚性指必须支付、不能随意增减的开支，“想花多少就花多少”与之矛盾。"}, {"text": "这种橡胶的刚性很好，拉再长也不断。", "explanation": "这里应该用〈韧性〉。拉长不断说的是韧性，刚性指不易变形，不用于描述抗拉断裂。"}, {"text": "这件毛衣的刚性很高，穿在身上很软和。", "explanation": "这里应该用〈柔软度〉。「穿在身上很软和」说明毛衣柔软，刚性指坚硬、不易变形，二者相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c70347ad-27a5-41a9-9ada-627dc309d573') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11777, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "刚性", "is_correct": true, "explanation": "刚性指计划不可变通，与“太强”搭配，句意通顺。"}, {"text": "灵活性", "is_correct": false, "explanation": "语义：前句说“缺少弹性”，“灵活性太强”与之直接矛盾。"}, {"text": "适应性", "is_correct": false, "explanation": "语义：“适应性太强”与“缺少弹性”的语义相悖，二者不能同时成立。"}, {"text": "通融性", "is_correct": false, "explanation": "语义：“通融性”指可以变通，“通融性太强”与前句“缺少弹性”直接矛盾。"}], "explanations": {"刚性": "刚性指计划不可变通，与“太强”搭配，句意通顺。", "灵活性": "语义：前句说“缺少弹性”，“灵活性太强”与之直接矛盾。", "适应性": "语义：“适应性太强”与“缺少弹性”的语义相悖，二者不能同时成立。", "通融性": "语义：“通融性”指可以变通，“通融性太强”与前句“缺少弹性”直接矛盾。"}, "sentence_index": 6, "correct_answer": "刚性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "参加社团是有刚性的，想参加就参加。", "explanation": "这里应该用〈自愿〉。刚性指必须遵守、不能改变，与“想参加就参加”的自愿性质矛盾。"}, {"text": "这份工作的时间表有刚性，员工可以自己安排。", "explanation": "这里应该用〈灵活〉。“可以自己安排”说明时间可以调整，刚性指不可改变，两者矛盾。"}, {"text": "这项规定很有刚性，大家可以自己决定。", "explanation": "这里应该用〈宽松〉。「大家可以自己决定」说明规定宽松，刚性指不可改变，二者相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c70347ad-27a5-41a9-9ada-627dc309d573') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11777, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这笔支出有很刚性，每个月都得交。", "corrected_sentence": "这笔支出很有刚性，每个月都得交。", "error_description": "错误：「有很刚性」，副词「很」应放在「有」前。正确应为「很有刚性」，「很」修饰「有」，「有」带出“刚性”作宾语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c70347ad-27a5-41a9-9ada-627dc309d573') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11777, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个制度很有刚性性，改起来很难。", "corrected_sentence": "这个制度很有刚性，改起来很难。", "error_description": "错误：「刚性」本身已含「性」，不能再加「性」重复构词。正确应为「很有刚性」，删去多余的「性」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c70347ad-27a5-41a9-9ada-627dc309d573') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
