INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11778, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指液体移动或淌出，如河水、眼泪、血、汗。", "primary_collocate": null, "pronunciation": "liú", "ipa": "ljoʊ˧˥", "syllable_count": 1, "sentences": [{"text": "河水向东流。", "target_word": "流", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他难过得流下了眼泪。", "target_word": "流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的手流血了。", "target_word": "流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天气太热，他一直在流汗。", "target_word": "流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水从杯子里流出来了。", "target_word": "流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨水顺着窗户流下来。", "target_word": "流", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她看完电影，流了很多泪。", "target_word": "流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山下的小河很清，慢慢地流。", "target_word": "流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他摔倒了，腿上流着血。", "target_word": "流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人想起往事，眼泪不停地流。", "target_word": "流", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "流了", "label": "完成体"}, {"form": "流着", "label": "持续体"}, {"form": "流过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "液体（河水、眼泪、血、汗）移动或淌出", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc6c39ff-6648-49e0-a3c7-cae6bdba831d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11778, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "流", "is_correct": true, "explanation": "正确。流 liú，指液体移动，与听到的音一致。"}, {"text": "柳", "is_correct": false, "explanation": "柳 liǔ（第三声）与 liú（第二声）声调不同，意思是柳树。"}, {"text": "六", "is_correct": false, "explanation": "六 liù（第四声）与 liú（第二声）声调不同，意思是数字六。"}, {"text": "溜", "is_correct": false, "explanation": "溜 liū（第一声）与 liú（第二声）声调不同，意思是滑行、溜走。"}, {"text": "牛", "is_correct": false, "explanation": "牛 niú 的声母是 n，与 liú 的 l 不同，意思是牛。"}], "explanations": {"流": "正确。流 liú，指液体移动，与听到的音一致。", "柳": "柳 liǔ（第三声）与 liú（第二声）声调不同，意思是柳树。", "六": "六 liù（第四声）与 liú（第二声）声调不同，意思是数字六。", "溜": "溜 liū（第一声）与 liú（第二声）声调不同，意思是滑行、溜走。", "牛": "牛 niú 的声母是 n，与 liú 的 l 不同，意思是牛。"}, "sentence_index": null, "correct_answer": "流"}, "level_3": {"options": [{"text": "流", "is_correct": true, "explanation": "正确。“河水向东流”表示河水向东流动，“流”指液体移动。"}, {"text": "飞", "is_correct": false, "explanation": "语义：“飞”指在空中移动，河水不会飞，与“河水”搭配不当。"}, {"text": "穿", "is_correct": false, "explanation": "配价：“穿”是及物动词，需要带宾语或处所，“河水向东穿”不成句。"}, {"text": "跳", "is_correct": false, "explanation": "语义：“跳”指身体的跳动，河水不能跳，与句意不符。"}], "explanations": {"流": "正确。“河水向东流”表示河水向东流动，“流”指液体移动。", "飞": "语义：“飞”指在空中移动，河水不会飞，与“河水”搭配不当。", "穿": "配价：“穿”是及物动词，需要带宾语或处所，“河水向东穿”不成句。", "跳": "语义：“跳”指身体的跳动，河水不能跳，与句意不符。"}, "sentence_index": 0, "correct_answer": "流"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "书流到了地上。", "explanation": "这里应该用〈掉〉。“流”多指液体或连续移动，固体书本落下应说〈掉〉。"}, {"text": "球流到了桌子下面。", "explanation": "这里应该用〈滚〉。“流”指液体的流动，球是固体，应说〈滚〉。"}, {"text": "钥匙流进了口袋里。", "explanation": "这里应该用〈装〉。“流”多用于液体或连续移动的东西，钥匙是固体，装进口袋应说〈装〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70e02eb2-f66b-4add-bba2-1045639f8f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11778, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "流", "is_correct": true, "explanation": "正确。“流了很多泪”指眼泪淌出，与“看完电影”的情境相符。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”是用牙齿的动作，眼泪不能被咬，与“泪”搭配不当。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”一般接食物，不接“泪”，“吃了很多泪”不成立。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写”指写字作画，与“泪”无关，句意不通。"}], "explanations": {"流": "正确。“流了很多泪”指眼泪淌出，与“看完电影”的情境相符。", "咬": "语义：“咬”是用牙齿的动作，眼泪不能被咬，与“泪”搭配不当。", "吃": "搭配：“吃”一般接食物，不接“泪”，“吃了很多泪”不成立。", "写": "语义：“写”指写字作画，与“泪”无关，句意不通。"}, "sentence_index": 6, "correct_answer": "流"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把书流在桌上。", "explanation": "这里应该用〈放〉。“流”只用于液体或连续流动的东西，书是固体，不能说流在桌上。"}, {"text": "他把箱子流到了车站。", "explanation": "这里应该用〈拉〉。“流”多用于液体或连续移动，箱子是固体，拖着走应说〈拉〉。"}, {"text": "他把椅子流到了门口。", "explanation": "这里应该用〈搬〉。“流”只用于液体，椅子是固体，搬动应说〈搬〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70e02eb2-f66b-4add-bba2-1045639f8f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11778, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "眼泪从脸上流上去了。", "corrected_sentence": "眼泪从脸上流下来了。", "error_description": "“流”的补语应为“下来”，表示液体向下淌。写成“上去”，方向相反，液体不会向上流，正确形式是“流下来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70e02eb2-f66b-4add-bba2-1045639f8f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11778, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他摔倒了，腿上一直流了着血。", "corrected_sentence": "他摔倒了，腿上一直流着血。", "error_description": "“流”后不能同时带“了”和“着”，持续状态只用“着”，应写作“流着血”。多出的“了”是体标错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70e02eb2-f66b-4add-bba2-1045639f8f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
