INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11779, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使形状或形态固定下来。", "primary_collocate": null, "pronunciation": "dìng xíng", "ipa": "tiŋ˥˩ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "用湿黏土捏好的小花，阴干以后就定形了。", "target_word": "定形", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "热塑料冷却以后，很快就会定形。", "target_word": "定形", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "石膏倒进模子里，一个小时就定形了。", "target_word": "定形", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做完头发，要用发胶帮它定形。", "target_word": "定形", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "蛋糕出炉后要先放一会儿，让它慢慢定形。", "target_word": "定形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鞋子洗过以后，里面塞上纸才能定形。", "target_word": "定形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅把竹子弯好，再用绳子绑着让它定形。", "target_word": "定形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "泥人做好后，要放在太阳下晒干定形。", "target_word": "定形", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "温度太高，这种材料不容易定形。", "target_word": "定形", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件毛衣洗后不会变，因为布料已经定形了。", "target_word": "定形", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "定形了", "label": "完成体"}, {"form": "定了形", "label": "离合形式"}], "register": "中性", "sense_fingerprint": "物体或造型变得固定、不再改变形状", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc6c39ff-6648-49e0-a3c7-cae6bdba831d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11779, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "定形", "is_correct": true, "explanation": "正确。湿黏土阴干后形状固定下来，“定形”指使形状固定，符合句意。"}, {"text": "融化", "is_correct": false, "explanation": "语义：阴干的黏土不会融化，“融化”指固体遇热变为液体，与句意不符。"}, {"text": "点燃", "is_correct": false, "explanation": "语义：黏土不能燃烧，“点燃”指使物体燃烧，与句意不符。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：“唱歌”是人的动作，小花不会唱歌，与句意不符。"}], "explanations": {"定形": "正确。湿黏土阴干后形状固定下来，“定形”指使形状固定，符合句意。", "融化": "语义：阴干的黏土不会融化，“融化”指固体遇热变为液体，与句意不符。", "点燃": "语义：黏土不能燃烧，“点燃”指使物体燃烧，与句意不符。", "唱歌": "语义：“唱歌”是人的动作，小花不会唱歌，与句意不符。"}, "sentence_index": 0, "correct_answer": "定形"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用胶把架子定形在墙上。", "explanation": "这里应该用〈固定〉。定形指物体的形状变得固定，把东西固定在某处要用固定。"}, {"text": "他把房间定形得很干净。", "explanation": "这里应该用〈打扫〉。“定形”只指使物体形状固定，房间变干净要用打扫。"}, {"text": "这盆热水很快就定形了。", "explanation": "这里应该用〈冷却〉。定形指使形状固定，热水温度下降要用冷却，水本身不会定形。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70e02eb2-f66b-4add-bba2-1045639f8f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11779, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "定形", "is_correct": true, "explanation": "正确。绑着是为了让弯好的竹子形状固定，即“定形”。"}, {"text": "褪色", "is_correct": false, "explanation": "语义：“褪色”指颜色变淡，与“绑着”固定形状的目的无关。"}, {"text": "融化", "is_correct": false, "explanation": "搭配：“融化”用于冰雪、金属等受热变液体，竹子不会融化。"}, {"text": "散开", "is_correct": false, "explanation": "语义：“散开”指分散开来，与“绑着”固定的目的相反。"}], "explanations": {"定形": "正确。绑着是为了让弯好的竹子形状固定，即“定形”。", "褪色": "语义：“褪色”指颜色变淡，与“绑着”固定形状的目的无关。", "融化": "搭配：“融化”用于冰雪、金属等受热变液体，竹子不会融化。", "散开": "语义：“散开”指分散开来，与“绑着”固定的目的相反。"}, "sentence_index": 6, "correct_answer": "定形"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把座椅的高度定形好了。", "explanation": "这里应该用〈调整〉。定形指使形状固定，座椅高度的改变要用调整。"}, {"text": "用彩带把房间定形得很漂亮。", "explanation": "这里应该用〈装饰〉。定形只指使形状固定，布置房间要用装饰。"}, {"text": "这家公司一直定形着良好的信誉。", "explanation": "这里应该用〈保持〉。定形只用于物体的形状，信誉的持续要用保持。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70e02eb2-f66b-4add-bba2-1045639f8f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11779, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块泥还没有定形了。", "corrected_sentence": "这块泥还没有定形。", "error_description": "“没有”否定动作的完成，后面不能再加“了”；应写成“还没有定形”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70e02eb2-f66b-4add-bba2-1045639f8f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11779, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块软泥放一天以后就定形地了。", "corrected_sentence": "这块软泥放一天以后就定形了。", "error_description": "“定形”是动词，后面不加“地”，应写成“定形了”；错误写成“定形地了”，多出了状语标记。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70e02eb2-f66b-4add-bba2-1045639f8f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11781, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccd5d667-5798-4d63-99e1-2259594b78fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11781, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccd5d667-5798-4d63-99e1-2259594b78fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11781, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用压力使物体体积缩小或形状改变。", "primary_collocate": null, "pronunciation": "yā suō", "ipa": "ja˥˥ swo˥˥", "syllable_count": 2, "sentences": [{"text": "为了降低运输成本，工厂在装车前先用大型液压机把废旧金属板压缩成规整的方块，使每车能装的重量大幅增加。", "target_word": "压缩", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "这台机器能压缩旧纸箱。", "target_word": "压缩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把衣服压缩进袋子里，行李箱才放得下。", "target_word": "压缩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人用机器把垃圾压缩成小块。", "target_word": "压缩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用真空袋压缩棉被，占的地方小多了。", "target_word": "压缩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机器压缩空气，再把空气送进管子。", "target_word": "压缩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂把铁片压缩成一个小方块。", "target_word": "压缩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个袋子能把枕头压缩得很小。", "target_word": "压缩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "回收站的机器压缩塑料瓶，运输更方便。", "target_word": "压缩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把弹簧用力压缩，它会变短。", "target_word": "压缩", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "压缩了", "label": "体标"}, {"form": "压缩过", "label": "体标"}, {"form": "压缩机", "label": "复合"}, {"form": "壓縮", "label": "繁体"}], "register": "中性", "sense_fingerprint": "施加压力使物体体积变小或形状改变", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbdf62e1-d33e-46df-96e9-4a4484bc7d82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11781, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "压缩", "is_correct": true, "explanation": "正确：“压缩”指用压力使物体体积变小，与“用大型液压机”把金属板压成紧实方块的语境相符。"}, {"text": "扩大", "is_correct": false, "explanation": "语义：“扩大”表示体积变大，与金属板被压成小方块以便多装的目的相反。"}, {"text": "拉伸", "is_correct": false, "explanation": "语义：“拉伸”使物体变长，与压成“规整的方块”的结果相反。"}, {"text": "挥发", "is_correct": false, "explanation": "配价：“挥发”是不及物动词，不能带“废旧金属板”作宾语。"}], "explanations": {"压缩": "正确：“压缩”指用压力使物体体积变小，与“用大型液压机”把金属板压成紧实方块的语境相符。", "扩大": "语义：“扩大”表示体积变大，与金属板被压成小方块以便多装的目的相反。", "拉伸": "语义：“拉伸”使物体变长，与压成“规整的方块”的结果相反。", "挥发": "配价：“挥发”是不及物动词，不能带“废旧金属板”作宾语。"}, "sentence_index": 0, "correct_answer": "压缩"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "人太多，他把我压缩到墙角。", "explanation": "这里应该用〈挤〉。压缩指使物体体积变小，不用于人；把人推到墙角应说〈挤〉。"}, {"text": "他压缩了一下门铃。", "explanation": "这里应该用〈按〉。压缩要求物体体积变小，按门铃只是施一次力，门铃本身不会变小。"}, {"text": "他把钥匙压缩进锁孔。", "explanation": "这里应该用〈插〉。钥匙插入锁孔并不会使钥匙体积变小，应说〈插〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccd5d667-5798-4d63-99e1-2259594b78fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11781, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "压缩", "is_correct": true, "explanation": "正确：“压缩”使铁片体积变小、成为小方块，与“工厂”的加工语境相符。"}, {"text": "粉碎", "is_correct": false, "explanation": "语义：“粉碎”会使铁片碎成零散的颗粒，无法形成完整的小方块。"}, {"text": "拉伸", "is_correct": false, "explanation": "语义：“拉伸”使物体变长，与“小方块”的结果相反。"}, {"text": "捏", "is_correct": false, "explanation": "搭配：“捏”多用于柔软材料，铁片不能用手捏成型，与“工厂”的加工方式不搭。"}], "explanations": {"压缩": "正确：“压缩”使铁片体积变小、成为小方块，与“工厂”的加工语境相符。", "粉碎": "语义：“粉碎”会使铁片碎成零散的颗粒，无法形成完整的小方块。", "拉伸": "语义：“拉伸”使物体变长，与“小方块”的结果相反。", "捏": "搭配：“捏”多用于柔软材料，铁片不能用手捏成型，与“工厂”的加工方式不搭。"}, "sentence_index": 6, "correct_answer": "压缩"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把画压缩在墙上。", "explanation": "这里应该用〈挂〉。压缩是使物体体积变小，把画挂在墙上并不会改变画的体积。"}, {"text": "他把水压缩进杯子里。", "explanation": "这里应该用〈倒〉。水几乎无法被压缩，压缩只用于能被压小的物体。"}, {"text": "他压缩了我的肩膀。", "explanation": "这里应该用〈拍〉。拍肩膀只是轻击，不会使身体变小，不能用〈压缩〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccd5d667-5798-4d63-99e1-2259594b78fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11781, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他用手把海绵压缩一团。", "corrected_sentence": "他用手把海绵压缩成一团。", "error_description": "「压缩」后面要用「成」引出结果，应说「压缩成一团」，不能直接接「一团」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccd5d667-5798-4d63-99e1-2259594b78fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11781, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他没把被子压缩进了袋子里。", "corrected_sentence": "他没把被子压缩进袋子里。", "error_description": "「没」表示动作尚未发生，「没」字句中动词后不能再用「了」，应说「没把被子压缩进袋子里」，不能说「没把被子压缩进了袋子里」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccd5d667-5798-4d63-99e1-2259594b78fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11782, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70e02eb2-f66b-4add-bba2-1045639f8f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11782, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70e02eb2-f66b-4add-bba2-1045639f8f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11782, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指两个物体或地点在空间或时间上的间隔。", "primary_collocate": null, "pronunciation": "jù lí", "ipa": "tɕy˥˩ li˧˥", "syllable_count": 2, "sentences": [{"text": "前后两辆车要保持距离。", "target_word": "距离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们坐得很近，几乎没有距离。", "target_word": "距离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从学校到车站的距离不远。", "target_word": "距离", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "跑步时，他和第二名拉开了距离。", "target_word": "距离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看电视要和屏幕保持一点距离。", "target_word": "距离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子和马路之间有一段距离，很安静。", "target_word": "距离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两排椅子之间要留出距离。", "target_word": "距离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们两家之间有一条河，有一点距离。", "target_word": "距离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "踢球时，人和人要保持一定的距离。", "target_word": "距离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个城市之间的距离有一千多公里。", "target_word": "距离", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一段距离", "label": "量词"}, {"form": "近距离", "label": "复合"}, {"form": "距離", "label": "繁体"}], "register": "中性", "sense_fingerprint": "空间或时间上的间隔", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc6c39ff-6648-49e0-a3c7-cae6bdba831d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11782, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "距离", "is_correct": true, "explanation": "距离 jù lí，意思是空间或时间上的间隔。"}, {"text": "举例", "is_correct": false, "explanation": "声调不同：jǔ lì（第三、第四声）与 jù lí 声调都改变，意思是举例子。"}, {"text": "巨利", "is_correct": false, "explanation": "声调不同：jù lì 的 lì（第四声）与 lí（第二声）不同，意思是巨大的利润。"}, {"text": "聚力", "is_correct": false, "explanation": "声调不同：lì（第四声）与 lí（第二声）不同，聚力 意思是凝聚力量。"}], "explanations": {"距离": "距离 jù lí，意思是空间或时间上的间隔。", "举例": "声调不同：jǔ lì（第三、第四声）与 jù lí 声调都改变，意思是举例子。", "巨利": "声调不同：jù lì 的 lì（第四声）与 lí（第二声）不同，意思是巨大的利润。", "聚力": "声调不同：lì（第四声）与 lí（第二声）不同，聚力 意思是凝聚力量。"}, "sentence_index": null, "correct_answer": "距离"}, "level_3": {"options": [{"text": "距离", "is_correct": true, "explanation": "前后两辆车要保持距离，指车辆之间的空间间隔，符合句意。"}, {"text": "友谊", "is_correct": false, "explanation": "语义：“友谊”只用于人与人之间，车辆之间不说保持友谊。"}, {"text": "笑容", "is_correct": false, "explanation": "语义：“笑容”是人的表情，车辆之间不能保持笑容。"}, {"text": "习惯", "is_correct": false, "explanation": "语义：“习惯”指人的行为方式，与车辆之间的间隔无关。"}], "explanations": {"距离": "前后两辆车要保持距离，指车辆之间的空间间隔，符合句意。", "友谊": "语义：“友谊”只用于人与人之间，车辆之间不说保持友谊。", "笑容": "语义：“笑容”是人的表情，车辆之间不能保持笑容。", "习惯": "语义：“习惯”指人的行为方式，与车辆之间的间隔无关。"}, "sentence_index": 0, "correct_answer": "距离"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他刚距离家，就下起了大雨。", "explanation": "这里应该用〈离开〉。距离表示空间或时间的间隔，人从某处走开要用离开。"}, {"text": "他一直距离着这份工作。", "explanation": "这里应该用〈坚持〉。“距离”只表示空间或时间上的间隔，不能表示人对工作的持续态度，应说〈坚持〉。"}, {"text": "他的字写得很距离。", "explanation": "这里应该用〈工整〉。“距离”只表示间隔，不能用来形容字迹，应说〈工整〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70e02eb2-f66b-4add-bba2-1045639f8f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11782, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "距离", "is_correct": true, "explanation": "两排椅子之间要留出距离，指椅子之间留出空间间隔，符合句意。"}, {"text": "报酬", "is_correct": false, "explanation": "搭配：“留出”不搭配“报酬”，报酬是付给别人的，不能留出。"}, {"text": "病毒", "is_correct": false, "explanation": "语义：“病毒”指致病的微生物，椅子之间不会留出病毒。"}, {"text": "意见", "is_correct": false, "explanation": "搭配：“留出”多接空间、时间，不接“意见”。"}], "explanations": {"距离": "两排椅子之间要留出距离，指椅子之间留出空间间隔，符合句意。", "报酬": "搭配：“留出”不搭配“报酬”，报酬是付给别人的，不能留出。", "病毒": "语义：“病毒”指致病的微生物，椅子之间不会留出病毒。", "意见": "搭配：“留出”多接空间、时间，不接“意见”。"}, "sentence_index": 6, "correct_answer": "距离"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用尺子距离了桌子的长度。", "explanation": "这里应该用〈测量〉。距离指间隔的长短，量出物体的长度要用测量。"}, {"text": "学生们在操场上距离成两排。", "explanation": "这里应该用〈排列〉。距离指间隔，把人或物按顺序摆放要用排列。"}, {"text": "他终于距离了危险。", "explanation": "这里应该用〈脱离〉。距离指间隔，摆脱危险、困境要用脱离。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70e02eb2-f66b-4add-bba2-1045639f8f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11782, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两栋楼之间有一个距离。", "corrected_sentence": "两栋楼之间有一段距离。", "error_description": "“距离”的量词应用“段”，写成“一段距离”；错误写成“一个距离”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70e02eb2-f66b-4add-bba2-1045639f8f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11782, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两个城市之间的距离很多。", "corrected_sentence": "两个城市之间的距离很远。", "error_description": "“距离”说长短、远近，应说“距离很远”。“距离很多”是搭配错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70e02eb2-f66b-4add-bba2-1045639f8f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11783, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccd5d667-5798-4d63-99e1-2259594b78fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11783, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccd5d667-5798-4d63-99e1-2259594b78fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11783, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "从事物最根本、最核心的层面入手，表示影响或改变深入根源。", "primary_collocate": null, "pronunciation": "cóng gēn běn shàng", "ipa": "tsʰʊŋ˧˥ kən˥˥ pən˨˩˦ ʂɑŋ˥˩", "syllable_count": 4, "sentences": [{"text": "这种“以流定形”的规划哲学，不仅压缩了通勤距离与时间成本，更从根本上瓦解了城市蔓延（urban sprawl）所依赖的低密度扩张逻辑，使土地利用效率与环境承载力达成动态耦合。", "target_word": "从根本上", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这种解耦设计，从根本上挑战了当前主流AI系统“模型绑定代理”的固化范式，为用户提供了前所未有的自主控制权。", "target_word": "从根本上", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个问题很难从根本上解决。", "target_word": "从根本上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新技术从根本上改变了我们的生活。", "target_word": "从根本上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "要想学好汉语，得从根本上改变学习方法。", "target_word": "从根本上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这两种做法从根本上就不一样。", "target_word": "从根本上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "只给钱不能从根本上帮助他们。", "target_word": "从根本上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要从根本上提高产品的质量。", "target_word": "从根本上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他和我的看法从根本上不同。", "target_word": "从根本上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "修建水库从根本上缓解了这个地区的干旱。", "target_word": "从根本上", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "从根本上：从事物最基本、最核心的方面入手，表示影响或改变深入根本", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbdf62e1-d33e-46df-96e9-4a4484bc7d82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11783, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "从根本上", "is_correct": true, "explanation": "正确：“从根本上”表示从事物的根本层面产生作用，与“瓦解…逻辑”的深层改变相符。"}, {"text": "从表面上", "is_correct": false, "explanation": "语义：“从表面上”只触及外表，与“从根本上瓦解”所要求的深层作用相反。"}, {"text": "互相", "is_correct": false, "explanation": "语法：“互相”要求双方彼此作用，而句中只有“规划哲学”单方去瓦解“逻辑”，不能用“互相”。"}, {"text": "瞎", "is_correct": false, "explanation": "语域：“瞎”是口语色彩很强的贬义副词，与这段书面、说明性文字不协调。"}], "explanations": {"从根本上": "正确：“从根本上”表示从事物的根本层面产生作用，与“瓦解…逻辑”的深层改变相符。", "从表面上": "语义：“从表面上”只触及外表，与“从根本上瓦解”所要求的深层作用相反。", "互相": "语法：“互相”要求双方彼此作用，而句中只有“规划哲学”单方去瓦解“逻辑”，不能用“互相”。", "瞎": "语域：“瞎”是口语色彩很强的贬义副词，与这段书面、说明性文字不协调。"}, "sentence_index": 0, "correct_answer": "从根本上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他从根本上戴上了帽子。", "explanation": "这里应该用〈随手〉。从根本上指事物的根本层面，不能描写顺手做某个动作的随意状态。"}, {"text": "这个消息从根本上传开了。", "explanation": "这里应该用〈很快〉。从根本上强调事物的根本层面，不能用来描写消息的传播速度。"}, {"text": "我们班从根本上有五十个学生。", "explanation": "这里应该用〈一共〉。从根本上指事物的根本层面，不能用来统计总人数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccd5d667-5798-4d63-99e1-2259594b78fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11783, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "从根本上", "is_correct": true, "explanation": "正确：“从根本上”强调从根本层面解决问题，与“只给钱不能……帮助他们”的语境相符。"}, {"text": "当面", "is_correct": false, "explanation": "搭配：“当面”指面对面进行，不适合修饰“帮助”这种行为的方式。"}, {"text": "一起", "is_correct": false, "explanation": "语义：“一起”表示共同行动，与“只给钱”这种单一手段的语境不合。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不常发生，与“从根本上”所强调的彻底性相反。"}], "explanations": {"从根本上": "正确：“从根本上”强调从根本层面解决问题，与“只给钱不能……帮助他们”的语境相符。", "当面": "搭配：“当面”指面对面进行，不适合修饰“帮助”这种行为的方式。", "一起": "语义：“一起”表示共同行动，与“只给钱”这种单一手段的语境不合。", "偶尔": "语义：“偶尔”表示不常发生，与“从根本上”所强调的彻底性相反。"}, "sentence_index": 6, "correct_answer": "从根本上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "天从根本上下起了大雨。", "explanation": "这里应该用〈突然〉。从根本上指向根源或根本层面，不能用来描写雨骤然开始。"}, {"text": "他从根本上十点到家。", "explanation": "这里应该用〈大概〉。从根本上指根本层面，不能用来估计时间。"}, {"text": "我从根本上去看电影。", "explanation": "这里应该用〈偶尔〉。从根本上强调彻底和根本，不能表示不经常做某事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccd5d667-5798-4d63-99e1-2259594b78fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11783, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个制度从根本上地改变了农村的面貌。", "corrected_sentence": "这个制度从根本上改变了农村的面貌。", "error_description": "错误形式：从根本上地改变；正确形式：从根本上改变。“从根本上”已是完整的状语形式，其后不能再加“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccd5d667-5798-4d63-99e1-2259594b78fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11783, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种新方法能从根本上的解决问题。", "corrected_sentence": "这种新方法能从根本上解决问题。", "error_description": "“从根本上”是状语，后面不能加“的”直接修饰动词。应说“能从根本上解决问题”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccd5d667-5798-4d63-99e1-2259594b78fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
