INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11784, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "比喻崩溃、分裂或完全失败。", "primary_collocate": null, "pronunciation": "wǎ jiě", "ipa": "wa˨˩˦ tɕjɛ˨˩˦", "syllable_count": 2, "sentences": [{"text": "农民、学生、手工业者在共同劳作中重建了濒临瓦解的邻里纽带，形成了非正式但高效的合作网络。", "target_word": "瓦解", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "敌人的计划很快就瓦解了。", "target_word": "瓦解", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "因为长期吵架，这个家庭终于瓦解了。", "target_word": "瓦解", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个团体因为内部矛盾而瓦解。", "target_word": "瓦解", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "坏消息让他的信心慢慢瓦解了。", "target_word": "瓦解", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司瓦解以后，大家各找工作。", "target_word": "瓦解", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要想办法瓦解对方的斗志。", "target_word": "瓦解", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一个谎言就能让多年的信任瓦解。", "target_word": "瓦解", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这支球队的防线在下半场彻底瓦解。", "target_word": "瓦解", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经过几年战争，这个国家的统治瓦解了。", "target_word": "瓦解", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "瓦解了", "label": "体标"}, {"form": "瓦解过", "label": "体标"}], "register": "中性", "sense_fingerprint": "瓦解：组织、关系、信心等抽象的东西崩溃、分裂或被破坏", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbdf62e1-d33e-46df-96e9-4a4484bc7d82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11784, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "增强", "is_correct": false, "explanation": "语义：“濒临”指接近不好的状态，“增强”是向好的方向，与句意相反。"}, {"text": "瓦解", "is_correct": true, "explanation": "正确：濒临瓦解指邻里纽带快要分裂、崩溃，与“重建”形成对照，符合句意。"}, {"text": "切割", "is_correct": false, "explanation": "搭配：“切割”多用于具体物体，纽带一般说断开、切断，“濒临切割”不成立。"}, {"text": "巩固", "is_correct": false, "explanation": "语义：“巩固”指使稳固，与“濒临”所表示的崩坏趋势相反。"}], "explanations": {"增强": "语义：“濒临”指接近不好的状态，“增强”是向好的方向，与句意相反。", "瓦解": "正确：濒临瓦解指邻里纽带快要分裂、崩溃，与“重建”形成对照，符合句意。", "切割": "搭配：“切割”多用于具体物体，纽带一般说断开、切断，“濒临切割”不成立。", "巩固": "语义：“巩固”指使稳固，与“濒临”所表示的崩坏趋势相反。"}, "sentence_index": 0, "correct_answer": "瓦解"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "糖在热水里很快瓦解了。", "explanation": "这里应该用〈溶解〉。瓦解指组织、体系等整体崩溃或分裂，糖在水中化开要用溶解。"}, {"text": "工人先把旧机器瓦解，再一件件运走。", "explanation": "这里应该用〈拆卸〉。瓦解指事物自行崩溃或分散，不用于人有意地把机器拆开。"}, {"text": "铁块在高温下很快瓦解成了液体。", "explanation": "这里应该用〈熔化〉。瓦解指东西裂开或分散，金属受热变成液体要用熔化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccd5d667-5798-4d63-99e1-2259594b78fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11784, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "激发", "is_correct": false, "explanation": "语义：“激发”是振奋斗志，与“我们要想办法……对方”的对抗意图相反。"}, {"text": "打听", "is_correct": false, "explanation": "搭配：“打听”的对象是消息、情况，不能用于“斗志”。"}, {"text": "瓦解", "is_correct": true, "explanation": "正确：瓦解斗志指使对方的意志崩溃，符合“想办法”的对抗语境。"}, {"text": "鼓舞", "is_correct": false, "explanation": "语义：“鼓舞”是给人打气，句中要的是削弱对方，两者方向相反。"}], "explanations": {"激发": "语义：“激发”是振奋斗志，与“我们要想办法……对方”的对抗意图相反。", "打听": "搭配：“打听”的对象是消息、情况，不能用于“斗志”。", "瓦解": "正确：瓦解斗志指使对方的意志崩溃，符合“想办法”的对抗语境。", "鼓舞": "语义：“鼓舞”是给人打气，句中要的是削弱对方，两者方向相反。"}, "sentence_index": 6, "correct_answer": "瓦解"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道数学题可以先瓦解成三个小问题。", "explanation": "这里应该用〈分解〉。瓦解指崩溃、分裂，不用于把题目有条理地拆成几个部分。"}, {"text": "他终于瓦解了那个复杂的结。", "explanation": "这里应该用〈解开〉。瓦解指整体崩溃，不用于把打结的绳子解开。"}, {"text": "工人在山里瓦解了一大片铁矿。", "explanation": "这里应该用〈开采〉。瓦解指东西崩坏或分散，不用于从矿山取出矿石。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccd5d667-5798-4d63-99e1-2259594b78fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11784, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个团体因为内部矛盾瓦解的很快。", "corrected_sentence": "这个团体因为内部矛盾瓦解得很快。", "error_description": "错误形式：瓦解的很快；正确形式：瓦解得很快。程度补语前应用“得”，不用“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccd5d667-5798-4d63-99e1-2259594b78fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11784, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "几场战役之后，他的军队终于瓦解得。", "corrected_sentence": "几场战役之后，他的军队终于瓦解了。", "error_description": "错误形式：瓦解得；正确形式：瓦解了。“得”不能接在动词后单独结束句子，表示完成应用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccd5d667-5798-4d63-99e1-2259594b78fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
