INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11785, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "像蔓草一样不断向周围扩展、延伸。", "primary_collocate": null, "pronunciation": "màn yán", "ipa": "man˥˩ jɛn˧˥", "syllable_count": 2, "sentences": [{"text": "这种病很快在城里蔓延开来。", "target_word": "蔓延", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "恐惧在人群中蔓延。", "target_word": "蔓延", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谣言在网上蔓延，大家都很担心。", "target_word": "蔓延", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "疫情蔓延到了很多国家。", "target_word": "蔓延", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不好的风气不能让它蔓延。", "target_word": "蔓延", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空气里蔓延着一种紧张的气氛。", "target_word": "蔓延", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "悲伤的心情在她心里蔓延。", "target_word": "蔓延", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要阻止病毒继续蔓延。", "target_word": "蔓延", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "笑声从前排蔓延到后排。", "target_word": "蔓延", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大火蔓延得很快。", "target_word": "蔓延", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "蔓延着", "label": "体标"}, {"form": "蔓延了", "label": "体标"}, {"form": "蔓延开来", "label": "复合"}], "register": "中性", "sense_fingerprint": "疾病、情绪等不断向四周扩散", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc6c39ff-6648-49e0-a3c7-cae6bdba831d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11785, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "绽放", "is_correct": false, "explanation": "语义：“绽放”指花朵开放，与“病”无关，不能说病在城里绽放开来。"}, {"text": "荡漾", "is_correct": false, "explanation": "搭配：“荡漾”多用于水波、笑意，不搭配“病”。"}, {"text": "散发", "is_correct": false, "explanation": "搭配：“散发”多搭配气味、光芒，不说病在城里散发开来。"}, {"text": "蔓延", "is_correct": true, "explanation": "正确：“蔓延”指不好的事物不断向四周扩散，与“病很快在城里”搭配。"}], "explanations": {"绽放": "语义：“绽放”指花朵开放，与“病”无关，不能说病在城里绽放开来。", "荡漾": "搭配：“荡漾”多用于水波、笑意，不搭配“病”。", "散发": "搭配：“散发”多搭配气味、光芒，不说病在城里散发开来。", "蔓延": "正确：“蔓延”指不好的事物不断向四周扩散，与“病很快在城里”搭配。"}, "sentence_index": 0, "correct_answer": "蔓延"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把椅子蔓延到了门口。", "explanation": "这里应该用〈挪〉。蔓延指像蔓草一样不断向四周扩展，固体家具被移动要说挪。"}, {"text": "九年义务教育已经蔓延到农村。", "explanation": "这里应该用〈普及〉。蔓延含有负面、失控的意思，推广教育是正面的，要说普及。"}, {"text": "这个孩子的身高正在蔓延。", "explanation": "这里应该用〈长高〉。蔓延指向四周扩散，人的身高增长要说长高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70e02eb2-f66b-4add-bba2-1045639f8f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11785, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”是人或动物在水中的动作，心情不会游泳。"}, {"text": "烘焙", "is_correct": false, "explanation": "搭配：“烘焙”只用于面包、饼干等食物，不说心情被烘焙。"}, {"text": "蔓延", "is_correct": true, "explanation": "正确：“蔓延”指情绪等不断向四周扩散，与“悲伤的心情在她心里”搭配。"}, {"text": "生锈", "is_correct": false, "explanation": "语义：“生锈”指金属被氧化，与心情的扩散无关。"}], "explanations": {"游泳": "语义：“游泳”是人或动物在水中的动作，心情不会游泳。", "烘焙": "搭配：“烘焙”只用于面包、饼干等食物，不说心情被烘焙。", "蔓延": "正确：“蔓延”指情绪等不断向四周扩散，与“悲伤的心情在她心里”搭配。", "生锈": "语义：“生锈”指金属被氧化，与心情的扩散无关。"}, "sentence_index": 6, "correct_answer": "蔓延"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台电脑的内存正在蔓延。", "explanation": "这里应该用〈升级〉。蔓延指不断向四周扩散，给电脑加内存要说升级。"}, {"text": "会议蔓延了两个小时。", "explanation": "这里应该用〈延长〉。蔓延指向四周扩散，时间上拉长要说延长。"}, {"text": "这个月的销量蔓延了。", "explanation": "这里应该用〈增加〉。蔓延指失控的扩散，销量的增长要说增加。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70e02eb2-f66b-4add-bba2-1045639f8f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11785, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种病很快蔓延了到学校。", "corrected_sentence": "这种病很快蔓延到了学校。", "error_description": "“了”位置错误：“蔓延到”之后才接“了”，应说“蔓延到了学校”，不能说“蔓延了到学校”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70e02eb2-f66b-4add-bba2-1045639f8f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11785, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种病蔓延的很快。", "corrected_sentence": "这种病蔓延得很快。", "error_description": "补语标记错误：“蔓延”后面的程度补语要用“得”连接，应说“蔓延得很快”，不能用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70e02eb2-f66b-4add-bba2-1045639f8f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11786, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3a5c6e7-f1d9-4de4-aeed-bd7437ca25e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11786, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3a5c6e7-f1d9-4de4-aeed-bd7437ca25e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11786, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指单位体积内所含物质的数量较少。", "primary_collocate": null, "pronunciation": "dī mì dù", "ipa": "ti˥ mi˥˩ tu˥˩", "syllable_count": 3, "sentences": [{"text": "这种气凝胶以纳米纤维为骨架，内部孔隙占比极高，因此其低密度使它在航天隔热中表现突出，却也导致结构脆弱、难以承受外力。", "target_word": "低密度", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "这种泡沫塑料是低密度材料，所以很轻。", "target_word": "低密度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "低密度的气体比空气轻，会往上飘。", "target_word": "低密度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块海绵很松软，属于低密度物质。", "target_word": "低密度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种多孔材料的低密度让它很适合用来隔热。", "target_word": "低密度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师选用低密度合金，让飞机更轻。", "target_word": "低密度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "低密度泡沫放进水里，会浮在水面上。", "target_word": "低密度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "星际空间里有大量低密度的气体和尘埃。", "target_word": "低密度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种低密度纤维又轻又软，适合做保暖衣。", "target_word": "低密度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "低密度的木材浮力大，常用来做小船。", "target_word": "低密度", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "物质的密度小、质量轻（如低密度材料、低密度气体）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63fd2d9a-045d-4a1d-8a34-0bec3e8012e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11786, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "低密度", "is_correct": true, "explanation": "正确。气凝胶因内部孔隙占比极高而单位体积内物质极少，“低密度”指这一物理性质，只有它能解释隔热表现突出。"}, {"text": "高密度", "is_correct": false, "explanation": "语义：孔隙占比极高的材料不会是高密度，“高密度”与句中“孔隙占比极高”相矛盾。"}, {"text": "高硬度", "is_correct": false, "explanation": "语义：“高硬度”与句中“结构脆弱、难以承受外力”相矛盾，且硬度与隔热表现无关。"}, {"text": "高导热性", "is_correct": false, "explanation": "语义：导热性高会削弱隔热效果，与句中“在航天隔热中表现突出”相反。"}], "explanations": {"低密度": "正确。气凝胶因内部孔隙占比极高而单位体积内物质极少，“低密度”指这一物理性质，只有它能解释隔热表现突出。", "高密度": "语义：孔隙占比极高的材料不会是高密度，“高密度”与句中“孔隙占比极高”相矛盾。", "高硬度": "语义：“高硬度”与句中“结构脆弱、难以承受外力”相矛盾，且硬度与隔热表现无关。", "高导热性": "语义：导热性高会削弱隔热效果，与句中“在航天隔热中表现突出”相反。"}, "sentence_index": 0, "correct_answer": "低密度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这杯果汁是低密度的，喝起来没什么味道。", "explanation": "这里应该用〈浓〉或〈淡〉。果汁、糖水的浓淡指溶质多少，要说“浓”或“淡”；“低密度”只指物质本身单位体积内所含的数量，不用于溶液。"}, {"text": "这块石头是低密度的，搬起来很累。", "explanation": "这里应该用〈重〉。低密度的材料单位体积内物质少，通常较轻；说东西搬起来费力要用“重”，“低密度”不能表示重量。"}, {"text": "这首歌的音量是低密度的，听起来很安静。", "explanation": "这里应该用〈小〉。音量的大小要说“大”或“小”，“低密度”只描述物质或布局的疏密，不用来形容声音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3a5c6e7-f1d9-4de4-aeed-bd7437ca25e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11786, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "低密度", "is_correct": true, "explanation": "正确。低密度指物质单位体积内的数量少，只有它能让泡沫浮在水面上。"}, {"text": "高密度", "is_correct": false, "explanation": "语义：高密度的物质会下沉，与句中“会浮在水面上”的结果相矛盾。"}, {"text": "厚重", "is_correct": false, "explanation": "语义：“厚重”意为又重又厚，与句中“浮在水面上”相矛盾。"}, {"text": "沉重", "is_correct": false, "explanation": "语义：“沉重”指重量大，重的泡沫会下沉，与句中“会浮在水面上”相矛盾。"}], "explanations": {"低密度": "正确。低密度指物质单位体积内的数量少，只有它能让泡沫浮在水面上。", "高密度": "语义：高密度的物质会下沉，与句中“会浮在水面上”的结果相矛盾。", "厚重": "语义：“厚重”意为又重又厚，与句中“浮在水面上”相矛盾。", "沉重": "语义：“沉重”指重量大，重的泡沫会下沉，与句中“会浮在水面上”相矛盾。"}, "sentence_index": 6, "correct_answer": "低密度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家店的价格是低密度的，大家都觉得很贵。", "explanation": "这里应该用〈便宜〉。价格的高低不用“低密度”描述，“低密度”只指物质单位体积内所含的数量少。"}, {"text": "他说话的声音是低密度的，大家都听不清。", "explanation": "这里应该用〈小〉。声音的大小要说“大”或“小”，“低密度”只指物质单位体积内所含的数量少，不用来形容声音。"}, {"text": "这份计划的进度是低密度的，大家都很着急。", "explanation": "这里应该用〈慢〉。进度的快慢要说“快”或“慢”，“低密度”只表示物质的疏密，不能用来说进度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3a5c6e7-f1d9-4de4-aeed-bd7437ca25e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11786, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块泡沫很低密度让它能浮在水上。", "corrected_sentence": "这块泡沫的低密度让它能浮在水上。", "error_description": "错误：“很低密度”。“低密度”不能直接受“很”修饰，应改为“的低密度”作名词性成分。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3a5c6e7-f1d9-4de4-aeed-bd7437ca25e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11786, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块木头比水低密度让它能浮在水面上。", "corrected_sentence": "这块木头的低密度让它能浮在水面上。", "error_description": "错误：“比水低密度”。“低密度”前不能直接加“比水”，它是名词性成分，应用结构助词“的”连接，说“木头的低密度”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3a5c6e7-f1d9-4de4-aeed-bd7437ca25e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
