INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11787, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "扩大范围或规模", "primary_collocate": null, "pronunciation": "kuò zhāng", "ipa": "kʰuɔ˥˩ ʈʂɑŋ˥", "syllable_count": 2, "sentences": [{"text": "这家公司这几年一直在扩张。", "target_word": "扩张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古代的帝国不断向外扩张领土。", "target_word": "扩张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司扩张太快，资金一下子不够了。", "target_word": "扩张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个连锁店正在扩张自己的市场。", "target_word": "扩张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他盲目扩张，结果欠了很多钱。", "target_word": "扩张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家奶茶店计划明年扩张到十个城市。", "target_word": "扩张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家不应该用武力扩张自己的势力。", "target_word": "扩张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了扩张业务，老板又开了两家分店。", "target_word": "扩张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过多年扩张，这家小店变成了大集团。", "target_word": "扩张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "企业扩张过度，管理就会跟不上。", "target_word": "扩张", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "扩张了", "label": "体标：了"}, {"form": "扩张着", "label": "体标：着"}, {"form": "扩张过", "label": "体标：过"}], "register": "中性", "sense_fingerprint": "公司、势力、领土等扩大范围或规模（如扩张市场、盲目扩张）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63fd2d9a-045d-4a1d-8a34-0bec3e8012e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11787, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "扩张", "is_correct": true, "explanation": "正确。“一直在扩张”指公司的范围或规模不断扩大，符合句意。"}, {"text": "唱歌", "is_correct": false, "explanation": "搭配：“唱歌”的施事通常是人，公司不能作为“唱歌”的主体。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：“下雨”的主体只能是天气，与“公司”作主语无法构成合理的动作。"}, {"text": "吃饭", "is_correct": false, "explanation": "搭配：“吃饭”表示进食，公司不能作为进食的主体，句子语义不通。"}], "explanations": {"扩张": "正确。“一直在扩张”指公司的范围或规模不断扩大，符合句意。", "唱歌": "搭配：“唱歌”的施事通常是人，公司不能作为“唱歌”的主体。", "下雨": "语义：“下雨”的主体只能是天气，与“公司”作主语无法构成合理的动作。", "吃饭": "搭配：“吃饭”表示进食，公司不能作为进食的主体，句子语义不通。"}, "sentence_index": 0, "correct_answer": "扩张"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他这个月的体重扩张了不少，最近胖了很多。", "explanation": "这里应该用〈增加〉。体重的增多要说“增加”或“增长”；“扩张”指范围或规模变大，不用于身体重量。"}, {"text": "这个班的成绩扩张了一倍。", "explanation": "这里应该用〈提高〉。成绩的上升要说“提高”；“扩张”指范围或规模变大，不用于学习成绩。"}, {"text": "这个景区的门票价格扩张了三倍。", "explanation": "这里应该用〈上涨〉。价格的升高要说“上涨”；“扩张”只用于范围或规模的扩大，不用于价格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3a5c6e7-f1d9-4de4-aeed-bd7437ca25e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11787, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "扩张", "is_correct": true, "explanation": "正确。“扩张自己的势力”指扩大领土或影响的范围，符合句意。"}, {"text": "欢迎", "is_correct": false, "explanation": "搭配：“欢迎”不能以“势力”作宾语，也与“用武力”的语境不协调。"}, {"text": "感谢", "is_correct": false, "explanation": "搭配：“感谢”的宾语通常是人或帮助，不能用来接“自己的势力”。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝”与“用武力”的主动扩张行为相矛盾，势力也不是可以拒绝的对象。"}], "explanations": {"扩张": "正确。“扩张自己的势力”指扩大领土或影响的范围，符合句意。", "欢迎": "搭配：“欢迎”不能以“势力”作宾语，也与“用武力”的语境不协调。", "感谢": "搭配：“感谢”的宾语通常是人或帮助，不能用来接“自己的势力”。", "拒绝": "语义：“拒绝”与“用武力”的主动扩张行为相矛盾，势力也不是可以拒绝的对象。"}, "sentence_index": 6, "correct_answer": "扩张"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的汉语水平扩张了很多。", "explanation": "这里应该用〈提高〉。水平、能力的上升要说“提高”，“扩张”指范围或规模的扩大。"}, {"text": "这个假期扩张了三天，大家都很开心。", "explanation": "这里应该用〈延长〉。时间的增加要说“延长”；“扩张”指范围或规模变大，不用于时间。"}, {"text": "这个团队的默契正在扩张。", "explanation": "这里应该用〈加深〉。默契程度的提升要说“加深”；“扩张”只用于范围或规模的扩大，不用于人际关系。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3a5c6e7-f1d9-4de4-aeed-bd7437ca25e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11787, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司这几年扩张的很快。", "corrected_sentence": "这家公司这几年扩张得很快。", "error_description": "错误：“扩张的很快”。表示程度的补语要用“得”，不能用“的”，应说“扩张得很快”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3a5c6e7-f1d9-4de4-aeed-bd7437ca25e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11787, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家餐厅明年会扩张过五个城市。", "corrected_sentence": "这家餐厅明年会扩张到五个城市。", "error_description": "错误：“扩张过”。“过”表示过去的经历，不能和“明年会”一起用；表示扩张的范围应说“扩张到五个城市”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3a5c6e7-f1d9-4de4-aeed-bd7437ca25e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
