INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11788, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指资源（如时间、精力）被用到的程度，看能不能用较少投入得到较多结果。", "primary_collocate": null, "pronunciation": "lì yòng xiào lǜ", "ipa": "li˥˩ yʊŋ˥˩ ɕiɑʊ˥˩ ly˥˩", "syllable_count": 4, "sentences": [{"text": "这种“以流定形”的规划哲学，不仅压缩了通勤距离与时间成本，更从根本上瓦解了城市蔓延（urban sprawl）所依赖的低密度扩张逻辑，使土地利用效率与环境承载力达成动态耦合。", "target_word": "利用效率", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "提高时间利用效率，才能完成更多事。", "target_word": "利用效率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很在意学习时间的利用效率。", "target_word": "利用效率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "能源利用效率低，浪费就会很大。", "target_word": "利用效率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台新机器提高了电力利用效率。", "target_word": "利用效率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间太乱，空间的利用效率很低。", "target_word": "利用效率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想提高自己的精力利用效率。", "target_word": "利用效率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的计划能提高一天的利用效率。", "target_word": "利用效率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的土地利用效率越来越高。", "target_word": "利用效率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用这个方法，原料的利用效率提高了一倍。", "target_word": "利用效率", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "时间、精力、能源、土地等资源被利用的程度（如提高利用效率）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63fd2d9a-045d-4a1d-8a34-0bec3e8012e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11788, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "资金投入", "is_correct": false, "explanation": "语义：“资金投入”说的是钱的投放，不是土地被利用的程度，无法与环境承载力达成耦合。"}, {"text": "利用效率", "is_correct": true, "explanation": "正确。“土地利用效率”指土地被利用的程度，与“环境承载力”形成动态耦合，符合句意。"}, {"text": "房价", "is_correct": false, "explanation": "搭配：“房价”一般与房屋连用，不用来说土地的利用状况，不能与环境承载力耦合。"}, {"text": "设计风格", "is_correct": false, "explanation": "语义：“设计风格”是外观或形式上的特点，不是可以与承载力耦合的土地指标。"}], "explanations": {"资金投入": "语义：“资金投入”说的是钱的投放，不是土地被利用的程度，无法与环境承载力达成耦合。", "利用效率": "正确。“土地利用效率”指土地被利用的程度，与“环境承载力”形成动态耦合，符合句意。", "房价": "搭配：“房价”一般与房屋连用，不用来说土地的利用状况，不能与环境承载力耦合。", "设计风格": "语义：“设计风格”是外观或形式上的特点，不是可以与承载力耦合的土地指标。"}, "sentence_index": 0, "correct_answer": "利用效率"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道菜的利用效率很好，大家都爱吃。", "explanation": "这里应该用〈味道〉。利用效率说的是资源被用得是否高效，不指口感好坏，说菜好吃要用〈味道〉。"}, {"text": "这场比赛的利用效率很响亮，大家都很兴奋。", "explanation": "这里应该用〈声音〉。“响亮”形容声音，利用效率指资源被用得是否高效，不指声音大小；说声音大要用〈声音〉。"}, {"text": "这批产品的利用效率很甜，大家都爱买。", "explanation": "这里应该用〈口味〉。“甜”形容味道，利用效率指资源被用得是否高效，不指味道；说食品甜要用〈口味〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3a5c6e7-f1d9-4de4-aeed-bd7437ca25e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11788, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "视力", "is_correct": false, "explanation": "语义：“视力”指眼睛的感光能力，不是精力的一种，不能作为“提高”的对象。"}, {"text": "利用效率", "is_correct": true, "explanation": "正确。“精力利用效率”指精力被用得多有效，与“提高”搭配，符合句意。"}, {"text": "知名度", "is_correct": false, "explanation": "搭配：“知名度”用于人或事物的名气，不能用来修饰“精力”。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”是人的外形特征，不能用“精力”来修饰后作为提高的对象。"}], "explanations": {"视力": "语义：“视力”指眼睛的感光能力，不是精力的一种，不能作为“提高”的对象。", "利用效率": "正确。“精力利用效率”指精力被用得多有效，与“提高”搭配，符合句意。", "知名度": "搭配：“知名度”用于人或事物的名气，不能用来修饰“精力”。", "身高": "体貌：“身高”是人的外形特征，不能用“精力”来修饰后作为提高的对象。"}, "sentence_index": 6, "correct_answer": "利用效率"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天的利用效率很高，我们去公园散步。", "explanation": "这里应该用〈气温〉。利用效率指资源被用到的程度，不用来形容天气的冷热。"}, {"text": "这件衣服的利用效率很便宜，我买了两件。", "explanation": "这里应该用〈价格〉。利用效率不表示价钱高低，说价格便宜要用〈价格〉。"}, {"text": "一场大雨后，河里的利用效率明显上涨。", "explanation": "这里应该用〈水位〉。利用效率不指水面的高低，水面升高要用〈水位〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3a5c6e7-f1d9-4de4-aeed-bd7437ca25e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11788, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公司改革后，资金的利用效率提高得一倍。", "corrected_sentence": "公司改革后，资金的利用效率提高了一倍。", "error_description": "补语错误：“利用效率”作主语时，“提高”后接数量补语要用“了”，应说“提高了一倍”；“提高得一倍”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3a5c6e7-f1d9-4de4-aeed-bd7437ca25e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11788, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这项技术的一个利用效率很高。", "corrected_sentence": "这项技术的利用效率很高。", "error_description": "量词错误：“利用效率”是抽象名词，前面不能直接加个体量词“一个”，应去掉数量短语，说“这项技术的利用效率”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3a5c6e7-f1d9-4de4-aeed-bd7437ca25e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
