INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11789, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3a5c6e7-f1d9-4de4-aeed-bd7437ca25e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11789, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "指物体或系统所能承受的最大负荷或压力。", "primary_collocate": null, "pronunciation": "chéng zài lì", "ipa": "ʈʂʰɤŋ³⁵ tsaɪ⁵¹ li⁵¹", "syllable_count": 3, "sentences": [{"text": "这种“以流定形”的规划哲学，不仅压缩了通勤距离与时间成本，更从根本上瓦解了城市蔓延（urban sprawl）所依赖的低密度扩张逻辑，使土地利用效率与环境承载力达成动态耦合。", "target_word": "承载力", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这座桥的承载力很大，大卡车也能过。", "target_word": "承载力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个架子的承载力不够，放不了这么多书。", "target_word": "承载力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市的人太多，已经超过了环境的承载力。", "target_word": "承载力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师先检查了地面的承载力，再盖房子。", "target_word": "承载力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路的承载力有限，每天只能过一万辆车。", "target_word": "承载力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小船的承载力是十个人，不能再上人了。", "target_word": "承载力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地球的承载力有限，我们要保护环境。", "target_word": "承载力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水变少了，这片草地的承载力也变小了。", "target_word": "承载力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅游的人越来越多，这个小岛的承载力快到极限了。", "target_word": "承载力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "物体或系统能承受的最大负荷", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63fd2d9a-045d-4a1d-8a34-0bec3e8012e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11789, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "学历", "is_correct": false, "explanation": "搭配：“环境学历”不成搭配，“学历”不与“环境”连用。"}, {"text": "工资", "is_correct": false, "explanation": "语义：“工资”是劳动报酬，不能与环境承载力形成耦合。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”是人或物的重量，不是环境可以与承载力耦合的对象。"}, {"text": "承载力", "is_correct": true, "explanation": "正确。“环境承载力”指环境能承受的最大负荷，与“土地利用效率”形成耦合，符合句意。"}], "explanations": {"学历": "搭配：“环境学历”不成搭配，“学历”不与“环境”连用。", "工资": "语义：“工资”是劳动报酬，不能与环境承载力形成耦合。", "体重": "语义：“体重”是人或物的重量，不是环境可以与承载力耦合的对象。", "承载力": "正确。“环境承载力”指环境能承受的最大负荷，与“土地利用效率”形成耦合，符合句意。"}, "sentence_index": 0, "correct_answer": "承载力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块蛋糕的承载力很甜，大家都爱吃。", "explanation": "这里应该用〈口味〉。承载力指物体所能承受的最大负荷，不指味道；说蛋糕甜要用〈口味〉。"}, {"text": "这辆车的承载力很快。", "explanation": "这里应该用〈速度〉。承载力指能承受的最大负荷，说车跑得快慢要用〈速度〉。"}, {"text": "这件衣服的承载力很漂亮，我很喜欢。", "explanation": "这里应该用〈颜色〉。承载力指物体所能承受的最大负荷，不用来形容衣服的颜色，说颜色好看要用〈颜色〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3a5c6e7-f1d9-4de4-aeed-bd7437ca25e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11789, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "船长", "is_correct": false, "explanation": "语义：“小船的船长是十个人”说不通，船长是人，不能作为小船的属性。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”是外观特征，不能用“是十个人”来说明。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“价格”说钱的数额，不用“是十个人”来描述小船。"}, {"text": "承载力", "is_correct": true, "explanation": "正确。“小船的承载力是十个人”说明小船能承载的最大人数，符合句意。"}], "explanations": {"船长": "语义：“小船的船长是十个人”说不通，船长是人，不能作为小船的属性。", "颜色": "语义：“颜色”是外观特征，不能用“是十个人”来说明。", "价格": "搭配：“价格”说钱的数额，不用“是十个人”来描述小船。", "承载力": "正确。“小船的承载力是十个人”说明小船能承载的最大人数，符合句意。"}, "sentence_index": 6, "correct_answer": "承载力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的承载力很大，每次考试都得满分。", "explanation": "这里应该用〈成绩〉。承载力指能承受的最大负荷，不指学习效果；说考试成绩好要用〈成绩〉。"}, {"text": "手机承载力快到极限了，记得充电。", "explanation": "这里应该用〈电量〉。承载力不指电池的剩余电量，说剩余电量要用〈电量〉。"}, {"text": "这杯咖啡的承载力很高，小心烫手。", "explanation": "这里应该用〈温度〉。承载力不指冷热，说咖啡温度高要用〈温度〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3a5c6e7-f1d9-4de4-aeed-bd7437ca25e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11789, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座老桥的一个承载力有限，不能再开进大货车。", "corrected_sentence": "这座老桥的承载力有限，不能再开进大货车。", "error_description": "量词错误：“承载力”是抽象名词，前面不能加个体量词“一个”，应直接说“承载力有限”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3a5c6e7-f1d9-4de4-aeed-bd7437ca25e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11789, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "洪水过后，这座小桥的承载力下降得一半。", "corrected_sentence": "洪水过后，这座小桥的承载力下降了一半。", "error_description": "补语错误：“承载力”作主语时，“下降”后接数量补语要用“了”，应说“下降了一半”；“下降得一半”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3a5c6e7-f1d9-4de4-aeed-bd7437ca25e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
