INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11790, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "通常指经过努力，实现、完成某个目标或协议。", "primary_collocate": null, "pronunciation": "dá chéng", "ipa": "ta³⁵ ʈʂʰɤŋ³⁵", "syllable_count": 2, "sentences": [{"text": "两家公司终于达成了协议。", "target_word": "达成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经过努力，我们达成了目标。", "target_word": "达成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家还没有达成一致。", "target_word": "达成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "双方在价格上达成了共识。", "target_word": "达成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们已经达成合作，下个月开始工作。", "target_word": "达成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她努力学习，终于达成了心愿。", "target_word": "达成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师和家长达成了一个约定。", "target_word": "达成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两国经过谈判，达成和平协议。", "target_word": "达成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次会议没有达成什么协议。", "target_word": "达成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司今年的销售目标已经达成了。", "target_word": "达成", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "达成了", "label": "完成体"}, {"form": "达成过", "label": "经历体"}], "register": "书面语", "sense_fingerprint": "经过努力或商谈而实现目标、协议", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63fd2d9a-045d-4a1d-8a34-0bec3e8012e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11790, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "达成", "is_correct": true, "explanation": "正确。“达成”指经过商议实现协议，与“终于”和“协议”相符。"}, {"text": "吃掉", "is_correct": false, "explanation": "搭配：“吃掉”只能搭配食物，不能说“吃掉协议”。"}, {"text": "开设", "is_correct": false, "explanation": "搭配：“开设”多用于学校、商店、课程，不能搭配“协议”。"}, {"text": "冒犯", "is_correct": false, "explanation": "语义：“冒犯”指得罪人，不能以“协议”作宾语。"}], "explanations": {"达成": "正确。“达成”指经过商议实现协议，与“终于”和“协议”相符。", "吃掉": "搭配：“吃掉”只能搭配食物，不能说“吃掉协议”。", "开设": "搭配：“开设”多用于学校、商店、课程，不能搭配“协议”。", "冒犯": "语义：“冒犯”指得罪人，不能以“协议”作宾语。"}, "sentence_index": 0, "correct_answer": "达成"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们终于达成了山顶。", "explanation": "这里应该用〈到达〉。“达成”的对象是目标、协议等抽象事物，不能指具体地点。"}, {"text": "他终于达成了作业。", "explanation": "这里应该用〈完成〉。“达成”多指实现目标或达成协议，不用于作业这类日常事务。"}, {"text": "他达成了这次比赛。", "explanation": "这里应该用〈参加〉。“达成”不能带比赛、活动这类场合作宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3a5c6e7-f1d9-4de4-aeed-bd7437ca25e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11790, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "达成", "is_correct": true, "explanation": "正确。“达成”指经过商议实现约定，与“老师和家长”相符。"}, {"text": "驾驶", "is_correct": false, "explanation": "搭配：“驾驶”只能搭配车辆等，不能说“驾驶约定”。"}, {"text": "驯服", "is_correct": false, "explanation": "语义：“驯服”针对动物或烈性事物，不能用于“约定”。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”针对场地或物品，不能搭配“约定”。"}], "explanations": {"达成": "正确。“达成”指经过商议实现约定，与“老师和家长”相符。", "驾驶": "搭配：“驾驶”只能搭配车辆等，不能说“驾驶约定”。", "驯服": "语义：“驯服”针对动物或烈性事物，不能用于“约定”。", "打扫": "搭配：“打扫”针对场地或物品，不能搭配“约定”。"}, "sentence_index": 6, "correct_answer": "达成"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今年公司的成本达成了百分之十。", "explanation": "这里应该用〈达到〉。“达成”的对象是目标、协议等，不能直接接数量；说数值到了某个水平要用〈达到〉。"}, {"text": "我在路上达成了老朋友。", "explanation": "这里应该用〈遇到〉。“达成”需要目标或协议作宾语，不能用于偶然遇见的人。"}, {"text": "今年的销售额达成了去年。", "explanation": "这里应该用〈超过〉。“达成”表示实现目标，不能表示数量超出去年的水平。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3a5c6e7-f1d9-4de4-aeed-bd7437ca25e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11790, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会议结束前，双方终于达成着一致。", "corrected_sentence": "会议结束前，双方终于达成了一致。", "error_description": "错误：“达成着”。“着”表示动作持续或状态存续，与“终于”表示结果已经完成的语境不符。应说「达成了一致」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3a5c6e7-f1d9-4de4-aeed-bd7437ca25e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11790, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次比赛我们没有达成了目标。", "corrected_sentence": "这次比赛我们没有达成目标。", "error_description": "“没有”否定已经发生的结果，不能再与“了”同用。应说「没有达成目标」，不能说「没有达成了目标」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3a5c6e7-f1d9-4de4-aeed-bd7437ca25e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
