INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11792, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "实证指通过实际观察、实验或经验获得的证据，用来证明某个观点或事实的真实性。", "primary_collocate": null, "pronunciation": "shí zhèng", "ipa": "ʂɻ̩³⁵ ʈʂɤŋ⁵¹", "syllable_count": 2, "sentences": [{"text": "实证研究表明，TOD区域居民的日均机动车出行频次较传统社区降低40%，而骑行与步行等零碳出行方式的分担率则提升近三倍，形成自强化的环保正循环。", "target_word": "实证", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个结论还缺少可靠的实证。", "target_word": "实证", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "研究者用大量实证支持自己的观点。", "target_word": "实证", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有实证，这个说法很难让人相信。", "target_word": "实证", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这篇论文提供了很多有力的实证。", "target_word": "实证", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们需要更多实证来检验这个假设。", "target_word": "实证", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生根据实证选择治疗方法。", "target_word": "实证", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "实验结果成了这个理论的重要实证。", "target_word": "实证", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "专家要求先找到实证，再下结论。", "target_word": "实证", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她收集了三年的实证，写成了报告。", "target_word": "实证", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "實證", "label": "繁体"}, {"form": "实证研究", "label": "复合"}, {"form": "实证分析", "label": "复合"}], "register": "书面", "sense_fingerprint": "通过观察、实验获得的、用来证明观点真实的证据", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eddf536e-727f-466d-9471-e2a4e4949a17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11792, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "实证", "is_correct": true, "explanation": "正确。实证指通过实际观察、实验获得的证据。"}, {"text": "施政", "is_correct": false, "explanation": "shī（第一声）与 shí（第二声）声调不同，意思是施行政策。"}, {"text": "市政", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）声调不同，意思是城市的行政事务。"}, {"text": "失政", "is_correct": false, "explanation": "shī（第一声）与 shí（第二声）声调不同，意思是政治上的失误。"}, {"text": "石阵", "is_correct": false, "explanation": "zhèn 与 zhèng 只差韵尾（n 与 ng），意思是石头排成的阵势。"}], "explanations": {"实证": "正确。实证指通过实际观察、实验获得的证据。", "施政": "shī（第一声）与 shí（第二声）声调不同，意思是施行政策。", "市政": "shì（第四声）与 shí（第二声）声调不同，意思是城市的行政事务。", "失政": "shī（第一声）与 shí（第二声）声调不同，意思是政治上的失误。", "石阵": "zhèn 与 zhèng 只差韵尾（n 与 ng），意思是石头排成的阵势。"}, "sentence_index": null, "correct_answer": "实证"}, "level_3": {"options": [{"text": "实证", "is_correct": true, "explanation": "正确。“实证研究”指以观察和数据为依据的研究。"}, {"text": "童话", "is_correct": false, "explanation": "语义：童话是虚构的故事，与“研究表明”后面的机动车出行数据不相符。"}, {"text": "神话", "is_correct": false, "explanation": "语义：神话是古人想象的故事，不能作为日均出行频次的研究依据。"}, {"text": "谣言", "is_correct": false, "explanation": "语域：“谣言”带贬义，与这句学术报告的书面语域不合，也无法得出数据结论。"}], "explanations": {"实证": "正确。“实证研究”指以观察和数据为依据的研究。", "童话": "语义：童话是虚构的故事，与“研究表明”后面的机动车出行数据不相符。", "神话": "语义：神话是古人想象的故事，不能作为日均出行频次的研究依据。", "谣言": "语域：“谣言”带贬义，与这句学术报告的书面语域不合，也无法得出数据结论。"}, "sentence_index": 0, "correct_answer": "实证"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "证人在法庭上陈述了实证。", "explanation": "这里应该用〈证词〉。证词是证人的陈述；实证是通过观察或实验得来的材料，不能用来指证人说的话。"}, {"text": "他用一把实证来支持自己的观点。", "explanation": "这里应该用〈项〉。实证是抽象的证据，不能用量词“把”计量，“把”通常用于有柄的器具。"}, {"text": "医生给他开了实证，让他请假。", "explanation": "这里应该用〈证明〉。“开”搭配“证明”（证明书），实证是通过观察或实验得来的证据，不能当作开给病人请假的证明文件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ead0f57e-393d-43ff-b200-52770069b672') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11792, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "实证", "is_correct": true, "explanation": "正确。“根据实证”指以观察、实验得到的证据为依据。"}, {"text": "心情", "is_correct": false, "explanation": "语义：心情不是治疗方法的科学依据，“根据心情”选择治疗方法不合理。"}, {"text": "星座", "is_correct": false, "explanation": "语义：星座不属于经观察或实验得到的证据，不能作为医疗决策的依据。"}, {"text": "玩意", "is_correct": false, "explanation": "语域：“玩意”是口语，与这里的医学书面语域不合，也不能作为选择治疗方法的依据。"}], "explanations": {"实证": "正确。“根据实证”指以观察、实验得到的证据为依据。", "心情": "语义：心情不是治疗方法的科学依据，“根据心情”选择治疗方法不合理。", "星座": "语义：星座不属于经观察或实验得到的证据，不能作为医疗决策的依据。", "玩意": "语域：“玩意”是口语，与这里的医学书面语域不合，也不能作为选择治疗方法的依据。"}, "sentence_index": 6, "correct_answer": "实证"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她花三年时间发明了一套实证，写成了报告。", "explanation": "这里应该用〈收集〉。“发明”指创造出新事物，实证是已经存在的证据材料，应该说“收集”。"}, {"text": "她花三年时间演奏了一套实证，写成了报告。", "explanation": "这里应该用〈收集〉。“演奏”用于乐器和乐曲，实证是证据，不能被演奏。"}, {"text": "她花三年时间吃掉了一份实证，写成了报告。", "explanation": "这里应该用〈收集〉。“吃掉”用于食物，实证是证据材料，不能被吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ead0f57e-393d-43ff-b200-52770069b672') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11792, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个结论还需要三张实证来支持。", "corrected_sentence": "这个结论还需要更多实证来支持。", "error_description": "量词错误：“张”用于纸张、照片等平面的东西，“实证”是抽象的证据，不能用“张”计量。错误为“三张实证”，正确为“更多实证”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ead0f57e-393d-43ff-b200-52770069b672') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11792, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他去年收集了不少根实证，才完成了这份报告。", "corrected_sentence": "他去年收集了不少实证，才完成了这份报告。", "error_description": "量词错误：“根”用于细长的东西，“实证”是抽象的证据，不能用“根”计量。错误为“不少根实证”，正确为“不少实证”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ead0f57e-393d-43ff-b200-52770069b672') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
