INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11794, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "机动车是指由动力装置驱动或牵引，在道路上行驶的轮式车辆，包括汽车、摩托车等。", "primary_collocate": null, "pronunciation": "jī dòng chē", "ipa": "tɕi⁵⁵ tʊŋ⁵¹ ʈʂʰɤ⁵⁵", "syllable_count": 3, "sentences": [{"text": "实证研究表明，TOD区域居民的日均机动车出行频次较传统社区降低40%，而骑行与步行等零碳出行方式的分担率则提升近三倍，形成自强化的环保正循环。", "target_word": "机动车", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "机动车必须在道路右侧行驶。", "target_word": "机动车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条路禁止机动车通行。", "target_word": "机动车", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "城市里的机动车越来越多。", "target_word": "机动车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开机动车要有驾驶证。", "target_word": "机动车", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "机动车排放的尾气会污染空气。", "target_word": "机动车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公园门口不允许机动车停放。", "target_word": "机动车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "交警昨天检查了我的机动车。", "target_word": "机动车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座城市限制机动车的数量。", "target_word": "机动车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "机动车和自行车要走不同的车道。", "target_word": "机动车", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "機動車", "label": "繁体"}, {"form": "辆", "label": "量词"}, {"form": "非机动车", "label": "复合"}], "register": "书面", "sense_fingerprint": "由动力装置驱动、在道路上行驶的轮式车辆", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eddf536e-727f-466d-9471-e2a4e4949a17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11794, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "机动车", "is_correct": true, "explanation": "正确。“日均机动车出行频次”指机动车的日均出行次数。"}, {"text": "蔬菜", "is_correct": false, "explanation": "语义：蔬菜不能出行，“日均蔬菜出行频次”不成立。"}, {"text": "宠物", "is_correct": false, "explanation": "语义：宠物不是出行的交通工具，与这段研究数据无关。"}, {"text": "玩具", "is_correct": false, "explanation": "搭配：“出行频次”通常指人或车辆的出行，“玩具”不能与之搭配。"}], "explanations": {"机动车": "正确。“日均机动车出行频次”指机动车的日均出行次数。", "蔬菜": "语义：蔬菜不能出行，“日均蔬菜出行频次”不成立。", "宠物": "语义：宠物不是出行的交通工具，与这段研究数据无关。", "玩具": "搭配：“出行频次”通常指人或车辆的出行，“玩具”不能与之搭配。"}, "sentence_index": 0, "correct_answer": "机动车"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家门口停着一张机动车。", "explanation": "这里应该用〈辆〉。机动车是车辆，计量用“辆”；“张”用于纸张、桌子等平面的东西。"}, {"text": "他在院子里种了一辆机动车。", "explanation": "这里应该用〈买〉或〈停〉。“种”用于植物，机动车是车辆，不能种植。"}, {"text": "他每天给机动车喂饭，然后出门上班。", "explanation": "这里应该用〈加油〉。“喂”用于动物，机动车是车辆，不能喂饭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ead0f57e-393d-43ff-b200-52770069b672') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11794, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "机动车", "is_correct": true, "explanation": "正确。“不允许机动车停放”指禁止机动车停放在公园门口。"}, {"text": "花朵", "is_correct": false, "explanation": "语义：花朵不是能停放的物体，这句话不成立。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会“停放”，与“不允许”的语境不合。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“停放”的对象须是可移动的物体，“空气”不能停放。"}], "explanations": {"机动车": "正确。“不允许机动车停放”指禁止机动车停放在公园门口。", "花朵": "语义：花朵不是能停放的物体，这句话不成立。", "石头": "语义：石头不会“停放”，与“不允许”的语境不合。", "空气": "搭配：“停放”的对象须是可移动的物体，“空气”不能停放。"}, "sentence_index": 6, "correct_answer": "机动车"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天骑着机动车去上班，一路上使劲踩脚踏板。", "explanation": "这里说的是自行车，应该用〈自行车〉。机动车靠动力装置驱动，靠踩脚踏板前进的不是机动车。"}, {"text": "这个孩子踩着机动车在广场上滑，玩得很开心。", "explanation": "这里说的是滑板车，应该用〈滑板车〉。机动车靠动力驱动，滑板车要靠脚蹬地前进。"}, {"text": "他每天蹬着机动车送货，车上装满了水果。", "explanation": "这里说的是靠人力蹬的三轮车，应该用〈三轮车〉。机动车不需要人蹬。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ead0f57e-393d-43ff-b200-52770069b672') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11794, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小区门口停着两张机动车。", "corrected_sentence": "小区门口停着两辆机动车。", "error_description": "量词错误：机动车是车辆，计量用“辆”，“张”用于纸张、桌子等平面的东西。错误为“两张机动车”，正确为“两辆机动车”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ead0f57e-393d-43ff-b200-52770069b672') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11794, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨天交警在小区门口检查了那几张机动车。", "corrected_sentence": "昨天交警在小区门口检查了那几辆机动车。", "error_description": "量词错误：机动车是车辆，计量用“辆”，“张”用于纸张、桌子等平面的东西。错误为“那几张机动车”，正确为“那几辆机动车”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ead0f57e-393d-43ff-b200-52770069b672') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
