INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11795, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指一段时间内某事件发生的次数。", "primary_collocate": null, "pronunciation": "pín cì", "ipa": "pʰin³⁵ tsʰɹ̩⁵¹", "syllable_count": 2, "sentences": [{"text": "实证研究表明，TOD区域居民的日均机动车出行频次较传统社区降低40%，而骑行与步行等零碳出行方式的分担率则提升近三倍，形成自强化的环保正循环。", "target_word": "频次", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他去健身房的频次很高。", "target_word": "频次", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "医生问我头疼的频次。", "target_word": "频次", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个月地铁的发车频次增加了。", "target_word": "频次", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "降低使用手机的频次对眼睛好。", "target_word": "频次", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司提高了检查的频次。", "target_word": "频次", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个词在书里出现的频次很低。", "target_word": "频次", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每周锻炼的频次最好不少于三次。", "target_word": "频次", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地震发生的频次与地区有关。", "target_word": "频次", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "研究者记录了孩子哭闹的频次。", "target_word": "频次", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "頻次", "label": "繁体"}, {"form": "出现频次", "label": "复合"}, {"form": "使用频次", "label": "复合"}], "register": "书面", "sense_fingerprint": "一段时间内某事件发生的次数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eddf536e-727f-466d-9471-e2a4e4949a17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11795, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "频次", "is_correct": true, "explanation": "正确：“频次”指一段时间内的次数，与“降低40%”搭配，说明出行次数减少。"}, {"text": "步数", "is_correct": false, "explanation": "语义：机动车出行不产生步数，“机动车出行步数”与“机动车”语义不相容。"}, {"text": "方式", "is_correct": false, "explanation": "搭配：“降低”用于数量，不能说“出行方式降低40%”。"}, {"text": "票价", "is_correct": false, "explanation": "语义：票价多指公共交通的收费，与“机动车出行”的语境不符。"}], "explanations": {"频次": "正确：“频次”指一段时间内的次数，与“降低40%”搭配，说明出行次数减少。", "步数": "语义：机动车出行不产生步数，“机动车出行步数”与“机动车”语义不相容。", "方式": "搭配：“降低”用于数量，不能说“出行方式降低40%”。", "票价": "语义：票价多指公共交通的收费，与“机动车出行”的语境不符。"}, "sentence_index": 0, "correct_answer": "频次"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台电机的工作频次是五十赫兹。", "explanation": "这里应该用〈频率〉。频次指一段时间内发生的次数，不用来表示“赫兹”这类周期性的速率。"}, {"text": "这个地区的失业频次是百分之五。", "explanation": "这里应该用〈比率〉。频次是次数，不能表示占总体的比例。"}, {"text": "男女的频次是一比一。", "explanation": "这里应该用〈比例〉。频次指发生次数，不能表示两个数量之间的比例关系。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ead0f57e-393d-43ff-b200-52770069b672') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11795, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "频次", "is_correct": true, "explanation": "正确：“频次”指次数，与“出现”“很低”搭配，说明词在书中出现的次数少。"}, {"text": "音量", "is_correct": false, "explanation": "语义：书里出现的是文字，没有音量，与“在书里”的语境冲突。"}, {"text": "个头", "is_correct": false, "explanation": "语义：“个头”只说人或物体的身材大小，不能用来形容词在书中出现的情况。"}, {"text": "语调", "is_correct": false, "explanation": "语义：文字没有语调，“在书里出现的语调”与语境相冲突。"}], "explanations": {"频次": "正确：“频次”指次数，与“出现”“很低”搭配，说明词在书中出现的次数少。", "音量": "语义：书里出现的是文字，没有音量，与“在书里”的语境冲突。", "个头": "语义：“个头”只说人或物体的身材大小，不能用来形容词在书中出现的情况。", "语调": "语义：文字没有语调，“在书里出现的语调”与语境相冲突。"}, "sentence_index": 6, "correct_answer": "频次"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份资料里记着孩子哭闹的频次，平均是十分钟。", "explanation": "这里应该用〈时长〉。频次指事件发生的次数，不能用来表示持续的时间。"}, {"text": "这箱苹果的频次是三十个。", "explanation": "这里应该用〈数量〉。频次指事件发生的次数，不能用来计算物品的个数。"}, {"text": "这次看病的频次是五十元。", "explanation": "这里应该用〈费用〉。频次指事件发生的次数，不能用来表示花掉的钱数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ead0f57e-393d-43ff-b200-52770069b672') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11795, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们每周开会的一只频次很高。", "corrected_sentence": "我们每周开会的频次很高。", "error_description": "错误在于频次前多加了量词“一只”。“只”是动物等的量词，不能修饰抽象的频次，应直接说“开会的频次很高”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ead0f57e-393d-43ff-b200-52770069b672') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11795, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个词在课文里出现的频次很长。", "corrected_sentence": "这个词在课文里出现的频次很高。", "error_description": "搭配错误：“频次”是次数，用“高/低”来说，不能用“长/短”。错误为“频次很长”，正确为“频次很高”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ead0f57e-393d-43ff-b200-52770069b672') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
