INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11796, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指骑自行车或骑马等运动或出行。", "primary_collocate": null, "pronunciation": "qí xíng", "ipa": "tɕʰi˧˥ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "实证研究表明，TOD区域居民的日均机动车出行频次较传统社区降低40%，而骑行与步行等零碳出行方式的分担率则提升近三倍，形成自强化的环保正循环。", "target_word": "骑行", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "周末我们一起去海边骑行。", "target_word": "骑行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他喜欢骑行，每个周末都出去。", "target_word": "骑行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我昨天骑行了二十公里。", "target_word": "骑行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条路风景很美，适合骑行。", "target_word": "骑行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "骑行时一定要戴头盔。", "target_word": "骑行", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他骑行去上班，不坐地铁。", "target_word": "骑行", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们骑行过很多城市。", "target_word": "骑行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "骑行比跑步更轻松，我更喜欢。", "target_word": "骑行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她参加了一个骑行俱乐部。", "target_word": "骑行", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "骑行了", "label": "体标"}, {"form": "骑行过", "label": "体标"}, {"form": "騎行", "label": "繁体"}], "register": "中性", "sense_fingerprint": "骑自行车或骑马进行的运动或出行", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eddf536e-727f-466d-9471-e2a4e4949a17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11796, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "骑行", "is_correct": true, "explanation": "正确：“骑行”与“步行”并列，同为出行方式，与“零碳出行方式”相符。"}, {"text": "驾车", "is_correct": false, "explanation": "语义：驾车会排放碳，不属于“零碳出行”，与前文语境冲突。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：游泳不是出行方式，与“步行等零碳出行方式”不相容。"}, {"text": "坐飞机", "is_correct": false, "explanation": "语义：坐飞机排放较多碳，与“零碳出行方式”相悖。"}], "explanations": {"骑行": "正确：“骑行”与“步行”并列，同为出行方式，与“零碳出行方式”相符。", "驾车": "语义：驾车会排放碳，不属于“零碳出行”，与前文语境冲突。", "游泳": "语义：游泳不是出行方式，与“步行等零碳出行方式”不相容。", "坐飞机": "语义：坐飞机排放较多碳，与“零碳出行方式”相悖。"}, "sentence_index": 0, "correct_answer": "骑行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天骑行地铁上班。", "explanation": "这里应该用〈乘坐〉。骑行只指骑自行车或骑马，不能用于地铁。"}, {"text": "他每天骑行汽车上班。", "explanation": "这里应该用〈驾驶〉。骑行只指骑自行车或骑马，驾驶汽车不能说“骑行”。"}, {"text": "他们租了一条船在湖上骑行。", "explanation": "这里应该用〈划船〉。骑行指骑车或骑马，划船要用“划”，不能用“骑行”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ead0f57e-393d-43ff-b200-52770069b672') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11796, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "骑行", "is_correct": true, "explanation": "正确：“骑行”作状语，说明去上班的方式，与“不坐地铁”形成对比。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：睡觉不能作为去上班的方式，语义不通。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：唱歌不是去上班的交通方式，与“去上班”的语境冲突。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：跳舞不是通勤方式，与“去上班”的语境冲突。"}], "explanations": {"骑行": "正确：“骑行”作状语，说明去上班的方式，与“不坐地铁”形成对比。", "睡觉": "语义：睡觉不能作为去上班的方式，语义不通。", "唱歌": "语义：唱歌不是去上班的交通方式，与“去上班”的语境冲突。", "跳舞": "语义：跳舞不是通勤方式，与“去上班”的语境冲突。"}, "sentence_index": 6, "correct_answer": "骑行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们骑行火车去杭州。", "explanation": "这里应该用〈坐〉。骑行不能用于火车，乘火车要用“坐”。"}, {"text": "他骑行飞机去上海。", "explanation": "这里应该用〈开〉。骑行只指骑车或骑马，驾驶飞机要用“开”。"}, {"text": "他们骑行公交去学校。", "explanation": "这里应该用〈乘〉。骑行不能用于公交车，乘公交要用“乘”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ead0f57e-393d-43ff-b200-52770069b672') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11796, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他骑行得快很。", "corrected_sentence": "他骑行得很快。", "error_description": "错误在于“很”的位置。形容词作补语时“很”应放在形容词前，应说“骑行得很快”，不说“骑行得快很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ead0f57e-393d-43ff-b200-52770069b672') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11796, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她骑行地很稳。", "corrected_sentence": "她骑行得很稳。", "error_description": "错误在于“地”。动词后作补语要用“得”，不能用“地”，应说“骑行得很稳”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ead0f57e-393d-43ff-b200-52770069b672') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
