INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11797, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ead0f57e-393d-43ff-b200-52770069b672') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11797, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "共同承担一部分责任或工作。", "primary_collocate": null, "pronunciation": "fēn dān", "ipa": "fən˥ tan˥", "syllable_count": 2, "sentences": [{"text": "研究表明，居民之间若能共同分担照料老人的责任，家庭的整体压力便会明显降低。", "target_word": "分担", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "家里的事，我们一起分担。", "target_word": "分担", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈太累了，我来分担一些家务。", "target_word": "分担", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友帮我分担了不少压力。", "target_word": "分担", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两个人分担工作，比较轻松。", "target_word": "分担", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司让大家分担这次的费用。", "target_word": "分担", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想为父母分担一点责任。", "target_word": "分担", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房租由三个人一起分担。", "target_word": "分担", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你可以和同事分担这个任务。", "target_word": "分担", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谢谢你帮我分担这么多工作。", "target_word": "分担", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "分担了", "label": "体标"}, {"form": "分担过", "label": "体标"}, {"form": "分担着", "label": "体标"}, {"form": "分擔", "label": "繁体"}], "register": "中性", "sense_fingerprint": "与他人共同承担一部分责任、压力或费用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eddf536e-727f-466d-9471-e2a4e4949a17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11797, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分担", "is_correct": true, "explanation": "正确：“共同分担照料老人的责任”指居民共同承担，符合语境。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：“共同拒绝责任”与“压力明显降低”的语境相反，不能表示共同承担。"}, {"text": "散步", "is_correct": false, "explanation": "搭配：“散步”不能与“照料老人的责任”搭配。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”与照料老人无关，不能与“责任”搭配。"}], "explanations": {"分担": "正确：“共同分担照料老人的责任”指居民共同承担，符合语境。", "拒绝": "语义：“共同拒绝责任”与“压力明显降低”的语境相反，不能表示共同承担。", "散步": "搭配：“散步”不能与“照料老人的责任”搭配。", "游泳": "语义：“游泳”与照料老人无关，不能与“责任”搭配。"}, "sentence_index": 0, "correct_answer": "分担"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "朋友帮我分担了很多快乐。", "explanation": "这里应该用〈分享〉。分担用于压力、责任、费用等负担，快乐要用〈分享〉。"}, {"text": "周末我去医院分担生病的奶奶。", "explanation": "这里应该用〈看望〉。分担指共同承担工作或责任，不能用来指去探望别人。"}, {"text": "我分担了这次的比赛。", "explanation": "这里应该用〈参加〉。分担指共同承担一部分责任或工作，参加比赛不能说分担。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ead0f57e-393d-43ff-b200-52770069b672') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11797, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分担", "is_correct": true, "explanation": "正确：“分担一点责任”指与父母共同承担，符合语境。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语一般是食物，不能说“吃一点责任”。"}, {"text": "买", "is_correct": false, "explanation": "搭配：“买”不能用于责任这类抽象事物。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“为父母唱一点责任”不合常理，与语境不符。"}], "explanations": {"分担": "正确：“分担一点责任”指与父母共同承担，符合语境。", "吃": "搭配：“吃”的宾语一般是食物，不能说“吃一点责任”。", "买": "搭配：“买”不能用于责任这类抽象事物。", "唱": "语义：“为父母唱一点责任”不合常理，与语境不符。"}, "sentence_index": 6, "correct_answer": "分担"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们分担了那位老人。", "explanation": "这里应该用〈照顾〉。分担的宾语是工作、责任或费用，不能直接指人。"}, {"text": "我分担了这幅画。", "explanation": "这里应该用〈欣赏〉。分担不能用于画作，欣赏画作要用〈欣赏〉。"}, {"text": "他分担了这座城市。", "explanation": "这里应该用〈游览〉。分担的宾语不能是地点，游览城市要用〈游览〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ead0f57e-393d-43ff-b200-52770069b672') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11797, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "上个月我们一起分担着这笔费用。", "corrected_sentence": "上个月我们一起分担了这笔费用。", "error_description": "体标误用：错误形式“分担着”，正确形式“分担了”。“上个月”表示动作已经完成，应该用“了”，不能用表示持续的“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ead0f57e-393d-43ff-b200-52770069b672') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11797, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们分担了了这次的工作。", "corrected_sentence": "我们分担了这次的工作。", "error_description": "错误形式“分担了了”，多出一个“了”；正确形式“分担了”。“了”表示动作完成，同一句中只用一次，重复的“了”不符合汉语习惯。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ead0f57e-393d-43ff-b200-52770069b672') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
