INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11799, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "几乎达到某个数量或程度", "primary_collocate": null, "pronunciation": "jìn", "ipa": "tɕin˥˩", "syllable_count": 1, "sentences": [{"text": "这个城市有近一千万人。", "target_word": "近", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他等了近三个小时。", "target_word": "近", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "参加比赛的学生近两百人。", "target_word": "近", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书我看了近一个月。", "target_word": "近", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他今年近五十岁了。", "target_word": "近", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店的东西卖了近一半。", "target_word": "近", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "教室里坐着近四十个学生。", "target_word": "近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她存了近一万块钱。", "target_word": "近", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条河长近三百公里。", "target_word": "近", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我在北京住了近五年。", "target_word": "近", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "将近", "label": "复合"}, {"form": "近乎", "label": "复合"}], "register": "中性", "sense_fingerprint": "接近某个数量，差一点达到（近三百人）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eddf536e-727f-466d-9471-e2a4e4949a17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11799, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "近", "is_correct": true, "explanation": "正确：“近”读 jìn（第四声），表示接近某个数量。"}, {"text": "紧", "is_correct": false, "explanation": "jǐn（第三声）与 jìn（第四声）声调不同，意思是紧张、紧密。"}, {"text": "信", "is_correct": false, "explanation": "xìn 与 jìn 声母不同（x 与 j），意思是信件、相信。"}, {"text": "静", "is_correct": false, "explanation": "jìng 与 jìn 韵母不同（-ng 与 -n），意思是安静。"}, {"text": "金", "is_correct": false, "explanation": "jīn（第一声）与 jìn（第四声）声调不同，意思是金子。"}], "explanations": {"近": "正确：“近”读 jìn（第四声），表示接近某个数量。", "紧": "jǐn（第三声）与 jìn（第四声）声调不同，意思是紧张、紧密。", "信": "xìn 与 jìn 声母不同（x 与 j），意思是信件、相信。", "静": "jìng 与 jìn 韵母不同（-ng 与 -n），意思是安静。", "金": "jīn（第一声）与 jìn（第四声）声调不同，意思是金子。"}, "sentence_index": null, "correct_answer": "近"}, "level_3": {"options": [{"text": "近", "is_correct": true, "explanation": "正确：“近一千万”表示接近一千万，与“有”搭配，符合语境。"}, {"text": "远", "is_correct": false, "explanation": "语义：“远”表示距离远，不能修饰人数。"}, {"text": "高", "is_correct": false, "explanation": "搭配：“高”描述高度，不能用来修饰人数。"}, {"text": "深", "is_correct": false, "explanation": "语义：“深”形容深度，与人数无关。"}], "explanations": {"近": "正确：“近一千万”表示接近一千万，与“有”搭配，符合语境。", "远": "语义：“远”表示距离远，不能修饰人数。", "高": "搭配：“高”描述高度，不能用来修饰人数。", "深": "语义：“深”形容深度，与人数无关。"}, "sentence_index": 0, "correct_answer": "近"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我花了近两千块，正好是两千块。", "explanation": "这里应该用〈整〉。“近”表示接近但未达到，恰好两千块要用〈整〉，不能说“近两千块”。"}, {"text": "这次考试我考了近一百分，比满分还多。", "explanation": "这里应该用〈超过〉。“近”表示接近但未达到，比满分还多要用〈超过〉。"}, {"text": "这家店的东西近卖光了，连一件也没剩。", "explanation": "这里应该用〈全部〉。“近”表示接近但未达到，东西全部卖完要用〈全部〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ead0f57e-393d-43ff-b200-52770069b672') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11799, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "近", "is_correct": true, "explanation": "正确：“近”读 jìn（第四声），表示接近某个数量。"}, {"text": "今", "is_correct": false, "explanation": "jīn（第一声）与 jìn（第四声）声调不同，意思是今天。"}, {"text": "俊", "is_correct": false, "explanation": "jùn 与 jìn 韵母不同（-un 与 -in），意思是英俊。"}, {"text": "敬", "is_correct": false, "explanation": "jìng 与 jìn 韵母不同（-ng 与 -n），意思是尊敬。"}, {"text": "镜", "is_correct": false, "explanation": "jìng 与 jìn 韵母不同（-ng 与 -n），意思是镜子。"}], "explanations": {"近": "正确：“近”读 jìn（第四声），表示接近某个数量。", "今": "jīn（第一声）与 jìn（第四声）声调不同，意思是今天。", "俊": "jùn 与 jìn 韵母不同（-un 与 -in），意思是英俊。", "敬": "jìng 与 jìn 韵母不同（-ng 与 -n），意思是尊敬。", "镜": "jìng 与 jìn 韵母不同（-ng 与 -n），意思是镜子。"}, "sentence_index": null, "correct_answer": "近"}, "level_3": {"options": [{"text": "近", "is_correct": true, "explanation": "正确：“近四十个学生”表示接近四十人，与“坐着”的语境相符。"}, {"text": "长", "is_correct": false, "explanation": "语义：“长”形容长度，不能修饰人数。"}, {"text": "厚", "is_correct": false, "explanation": "搭配：“厚”用于物体的厚度，不能说“坐着厚四十个学生”。"}, {"text": "宽", "is_correct": false, "explanation": "语义：“宽”形容宽度，与人数无关。"}], "explanations": {"近": "正确：“近四十个学生”表示接近四十人，与“坐着”的语境相符。", "长": "语义：“长”形容长度，不能修饰人数。", "厚": "搭配：“厚”用于物体的厚度，不能说“坐着厚四十个学生”。", "宽": "语义：“宽”形容宽度，与人数无关。"}, "sentence_index": 6, "correct_answer": "近"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他今年刚好近五十岁了。", "explanation": "这里应该用〈整〉。“近”表示接近但未达到，恰好五十岁要用〈整〉。"}, {"text": "这次作业我写了近十页，最后一共写了十二页。", "explanation": "这里应该用〈超过〉。“近”只表示接近但未达到十页，写到十二页要用〈超过〉。"}, {"text": "他每天工作近十个小时，每天都在十二个小时以上。", "explanation": "这里应该用〈超过〉。“近”表示接近但未达到，每天都在十二个小时以上要用〈超过〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ead0f57e-393d-43ff-b200-52770069b672') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11799, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在这家公司工作了很近十年。", "corrected_sentence": "他在这家公司工作了近十年。", "error_description": "错误形式“很近十年”，正确形式“近十年”。表示接近某个数量的“近”直接放在数量词前，不能用“很”修饰。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ead0f57e-393d-43ff-b200-52770069b672') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11799, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个地方近了一百年没有变化。", "corrected_sentence": "这个地方近一百年没有变化。", "error_description": "错误形式“近了一百年”，正确形式“近一百年”。表示接近某个数量的“近”直接放在数量词前，不能加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ead0f57e-393d-43ff-b200-52770069b672') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
