INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11801, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "事物周而复始地运动或变化。", "primary_collocate": null, "pronunciation": "xún huán", "ipa": "ɕyn˧˥ xwan˧˥", "syllable_count": 2, "sentences": [{"text": "四季不停地循环，年复一年。", "target_word": "循环", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "白天和黑夜每天循环，从不停止。", "target_word": "循环", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的生活每天循环：上班、吃饭、睡觉。", "target_word": "循环", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经济有高有低，这样循环了好几年。", "target_word": "循环", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春夏秋冬循环一次就是一年。", "target_word": "循环", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个游戏的关卡循环出现，没有尽头。", "target_word": "循环", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "月亮的圆缺每个月循环一次。", "target_word": "循环", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "日子循环着，他觉得很无聊。", "target_word": "循环", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边的潮水涨落，每天循环两次。", "target_word": "循环", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每年的雨季和旱季都会循环一次。", "target_word": "循环", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "循環", "label": "繁体"}, {"form": "良性循环", "label": "复合"}, {"form": "恶性循环", "label": "复合"}], "register": "中性", "sense_fingerprint": "动词，事物按一定顺序周而复始地重复（四季循环、日子循环）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df7e06a5-aa40-4d69-893b-a969f8b578f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11801, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "循环", "is_correct": true, "explanation": "循环：动词，指周而复始地运动或变化，与“不停地”和“年复一年”相符。"}, {"text": "停留", "is_correct": false, "explanation": "语义：“停留”指暂时不动，与“不停地”矛盾，四季也不会停留。"}, {"text": "休息", "is_correct": false, "explanation": "搭配：“休息”一般用于人，不说四季“不停地休息”，搭配不当。"}, {"text": "结束", "is_correct": false, "explanation": "语义：“结束”表示终止，与“年复一年”的重复不符。"}], "explanations": {"循环": "循环：动词，指周而复始地运动或变化，与“不停地”和“年复一年”相符。", "停留": "语义：“停留”指暂时不动，与“不停地”矛盾，四季也不会停留。", "休息": "搭配：“休息”一般用于人，不说四季“不停地休息”，搭配不当。", "结束": "语义：“结束”表示终止，与“年复一年”的重复不符。"}, "sentence_index": 0, "correct_answer": "循环"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对这件事循环道歉了好几次。", "explanation": "这里应该用〈反复〉。循环指事物按固定顺序周而复始地运动或变化，不用来形容人一次次地做同一件事。"}, {"text": "他的成绩循环提高了，每次考试都更好。", "explanation": "这里应该用〈稳步〉。循环指周而复始，不表示持续上升；成绩稳步提高不能用“循环”。"}, {"text": "这次考试他循环得了第一名。", "explanation": "这里应该用〈获得〉。循环指周而复始，不表示一次性得到名次；〈循环〉在此不表示获得义。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8e394ba-5d70-4d05-976c-ff686d21fbf2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11801, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "循环", "is_correct": true, "explanation": "循环：动词，指周而复始地重复，与“每个月……一次”相符。"}, {"text": "诞生", "is_correct": false, "explanation": "语义：“诞生”指新事物出现，月亮的圆缺不是一次性诞生，与句意不符。"}, {"text": "消失", "is_correct": false, "explanation": "语义：“消失”表示不再存在，但圆缺之后又会重现，与句意冲突。"}, {"text": "生长", "is_correct": false, "explanation": "搭配：“生长”多用于生物或植物，不用于月亮圆缺的变化，搭配不当。"}], "explanations": {"循环": "循环：动词，指周而复始地重复，与“每个月……一次”相符。", "诞生": "语义：“诞生”指新事物出现，月亮的圆缺不是一次性诞生，与句意不符。", "消失": "语义：“消失”表示不再存在，但圆缺之后又会重现，与句意冲突。", "生长": "搭配：“生长”多用于生物或植物，不用于月亮圆缺的变化，搭配不当。"}, "sentence_index": 6, "correct_answer": "循环"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件事他循环负责到底。", "explanation": "这里应该用〈亲自〉。循环指周而复始，不能用来表示本人动手去做，应说“亲自负责”。"}, {"text": "他循环叮嘱我别忘了带钥匙。", "explanation": "这里应该用〈再三〉。循环指按固定顺序周而复始，不用来形容人一次次地叮嘱。"}, {"text": "他的脸色很循环，像是喝了酒。", "explanation": "这里应该用〈红〉。循环指周而复始，不能形容脸色的颜色，“很循环”不这么用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8e394ba-5d70-4d05-976c-ff686d21fbf2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11801, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个规律每隔几年就会循环一个。", "corrected_sentence": "这个规律每隔几年就会循环一次。", "error_description": "“循环”作动词，其后的动量补语应用量词“次”，不能用“个”，应说“循环一次”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8e394ba-5d70-4d05-976c-ff686d21fbf2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11801, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种现象循环的很规律。", "corrected_sentence": "这种现象循环得很规律。", "error_description": "“循环”后接状态补语，须用结构助词“得”连接，不能用“的”，应说“循环得很规律”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8e394ba-5d70-4d05-976c-ff686d21fbf2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
