INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11803, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指进入环境后使环境质量下降、危害人类健康或生态平衡的物质。", "primary_collocate": null, "pronunciation": "wū rǎn wù", "ipa": "u˥ ʐan˨˩˦ u˥˩", "syllable_count": 3, "sentences": [{"text": "这些污染物会让空气变脏。", "target_word": "污染物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工厂排出的污染物让河水变黑了。", "target_word": "污染物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "汽车尾气是空气中的污染物。", "target_word": "污染物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种污染物对人的身体有害。", "target_word": "污染物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "河里的污染物越来越多。", "target_word": "污染物", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "工人用机器清除水里的污染物。", "target_word": "污染物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "垃圾烧了以后会产生污染物。", "target_word": "污染物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "植物能吸收空气中的一些污染物。", "target_word": "污染物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家工厂的污染物排放超过了标准。", "target_word": "污染物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨水把地上的污染物冲进了河里。", "target_word": "污染物", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "大气污染物", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词，污染环境、危害健康的有害物质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df7e06a5-aa40-4d69-893b-a969f8b578f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11803, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "污染物", "is_correct": true, "explanation": "污染物是危害环境的有害物质，会让空气变脏，符合句意。"}, {"text": "鲜花", "is_correct": false, "explanation": "语义：鲜花不会让空气变脏，与常识相反。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本是学习用书，不会让空气变脏，句意不通。"}, {"text": "节日", "is_correct": false, "explanation": "语义：节日是时间概念，不是物质，不能让空气变脏。"}], "explanations": {"污染物": "污染物是危害环境的有害物质，会让空气变脏，符合句意。", "鲜花": "语义：鲜花不会让空气变脏，与常识相反。", "课本": "语义：课本是学习用书，不会让空气变脏，句意不通。", "节日": "语义：节日是时间概念，不是物质，不能让空气变脏。"}, "sentence_index": 0, "correct_answer": "污染物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家工厂是河水变黑的主要污染物。", "explanation": "这里应该用〈污染源〉。污染物指有害物质本身，排放它的工厂是污染源，两者不能互换。"}, {"text": "河边停着一辆污染物。", "explanation": "这里把污染物当成了车辆来计量。污染物是有害物质，计量它要用〈种〉，不能用车辆的量词。"}, {"text": "我在河里捞到一只污染物。", "explanation": "这里把污染物当成了动物来计量。污染物是物质，计量它要用〈种〉，不能用于动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8e394ba-5d70-4d05-976c-ff686d21fbf2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11803, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "污染物", "is_correct": true, "explanation": "污染物是燃烧或排放后产生的有害物质，能与「产生」搭配，符合句意。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：垃圾烧了不会产生玩具，句意不通。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴是乐器，垃圾燃烧不会产生钢琴，句意不通。"}, {"text": "星期", "is_correct": false, "explanation": "语义：星期是时间单位，不是物质，燃烧不能产生星期。"}], "explanations": {"污染物": "污染物是燃烧或排放后产生的有害物质，能与「产生」搭配，符合句意。", "玩具": "语义：垃圾烧了不会产生玩具，句意不通。", "钢琴": "语义：钢琴是乐器，垃圾燃烧不会产生钢琴，句意不通。", "星期": "语义：星期是时间单位，不是物质，燃烧不能产生星期。"}, "sentence_index": 6, "correct_answer": "污染物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子们用污染物搭了一座城堡，玩得很开心。", "explanation": "这里应该用〈积木〉。积木是给孩子搭着玩的玩具，污染物是有害物质，不能用来搭东西。"}, {"text": "农民把这些污染物晒在院子里，准备过冬。", "explanation": "这里应该用〈粮食〉。粮食可以晒干储存，污染物是有害物质，不能拿来晾晒过冬。"}, {"text": "博物馆里陈列着一件珍贵的污染物，值得好好保存。", "explanation": "这里应该用〈文物〉。文物有历史和艺术价值，值得保存；污染物指有害物质，不能用来珍藏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8e394ba-5d70-4d05-976c-ff686d21fbf2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11803, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条河里有一只污染物。", "corrected_sentence": "这条河里有一种污染物。", "error_description": "「一只」错误，应改为「一种」。污染物是物质，要用量词「种」；「只」多用于动物，不能用来计量污染物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8e394ba-5d70-4d05-976c-ff686d21fbf2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11803, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人用机器清除水里的一根污染物。", "corrected_sentence": "工人用机器清除水里的一种污染物。", "error_description": "「一根」错误，应改为「一种」。污染物是物质，要用量词「种」；「根」多用于细长的物体，不能用来计量污染物。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8e394ba-5d70-4d05-976c-ff686d21fbf2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
