INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11804, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c70347ad-27a5-41a9-9ada-627dc309d573') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11804, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "减少污染物的排放，通常是减少二氧化碳等温室气体的排放。", "primary_collocate": null, "pronunciation": "jiǎn pái", "ipa": "tɕjɛn˨˩˦ pʰaɪ˧˥", "syllable_count": 2, "sentences": [{"text": "这种自下而上的监管创新虽推动局部减排，却导致法规碎片化与跨区域执法难题。", "target_word": "减排", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "进一步解构“环保”这一复合型价值命题，公共交通的生态意义已从单纯的污染物减排，延展至生态系统服务功能的修复与再生。", "target_word": "减排", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "工厂安装新机器后，减排的效果很好。", "target_word": "减排", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府要求各大工厂今年减排百分之十。", "target_word": "减排", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "少开车也是一种减排的办法。", "target_word": "减排", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个城市已经减排了很多二氧化碳。", "target_word": "减排", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了减排，工厂换用了干净的能源。", "target_word": "减排", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多国家都在努力减排。", "target_word": "减排", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们一直在研究怎么减排。", "target_word": "减排", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司去年减排过三成的废气。", "target_word": "减排", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "减排了", "label": "体标"}, {"form": "减排过", "label": "体标"}, {"form": "节能减排", "label": "复合"}], "register": "中性", "sense_fingerprint": "减少污染物或温室气体的排放量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd34bc2cc-089b-431f-93cf-0515a2573957') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11804, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "减排", "is_correct": true, "explanation": "正确。“推动局部减排”指推动局部减少排放，与“虽……却导致法规碎片化”的让步语境相合。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“推动局部睡觉”与“监管创新”“法规”毫无关联，句意不通。"}, {"text": "恋爱", "is_correct": false, "explanation": "语义：“推动局部恋爱”与“监管创新”“法规”毫无关联，句意不通。"}, {"text": "生病", "is_correct": false, "explanation": "语义：监管创新不会“推动”人生病，与后文法规问题无关，句意不通。"}], "explanations": {"减排": "正确。“推动局部减排”指推动局部减少排放，与“虽……却导致法规碎片化”的让步语境相合。", "睡觉": "语义：“推动局部睡觉”与“监管创新”“法规”毫无关联，句意不通。", "恋爱": "语义：“推动局部恋爱”与“监管创新”“法规”毫无关联，句意不通。", "生病": "语义：监管创新不会“推动”人生病，与后文法规问题无关，句意不通。"}, "sentence_index": 0, "correct_answer": "减排"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个月我的体重减排了三公斤。", "explanation": "这里应该用〈减少〉。减排专指废气、二氧化碳等排放物的减少，体重要用减少。"}, {"text": "医生说他的血压减排了。", "explanation": "这里应该用〈降低〉。减排只用于排放物，血压要说降低。"}, {"text": "这家公司今年减排了三百万元。", "explanation": "这里应该用〈节约〉。减排的对象是排放物，钱要用节约。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c70347ad-27a5-41a9-9ada-627dc309d573') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11804, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "减排", "is_correct": true, "explanation": "正确。“为了减排”表示换用干净能源的目的，与句意相合。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：“为了结婚”作为换用能源的目的，句意不通。"}, {"text": "辞职", "is_correct": false, "explanation": "语义：工厂换用能源与“辞职”的目的毫无关系，句子说不通。"}, {"text": "失眠", "is_correct": false, "explanation": "搭配：“失眠”与“换用干净的能源”不搭配，作为目的说不通。"}], "explanations": {"减排": "正确。“为了减排”表示换用干净能源的目的，与句意相合。", "结婚": "语义：“为了结婚”作为换用能源的目的，句意不通。", "辞职": "语义：工厂换用能源与“辞职”的目的毫无关系，句子说不通。", "失眠": "搭配：“失眠”与“换用干净的能源”不搭配，作为目的说不通。"}, "sentence_index": 6, "correct_answer": "减排"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们把路程减排了两公里。", "explanation": "这里应该用〈缩短〉。减排只用于废气、二氧化碳等排放物，路程要用缩短。"}, {"text": "政府减排了这家企业的税。", "explanation": "这里应该用〈减免〉。减排的对象是排放物，税要用减免。"}, {"text": "编辑减排了文章的三段。", "explanation": "这里应该用〈删减〉。减排不能用于文章的段落，删去段落要用删减。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c70347ad-27a5-41a9-9ada-627dc309d573') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11804, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家化工厂明年把废气减排了两成。", "corrected_sentence": "这家化工厂明年把废气减排两成。", "error_description": "时间与体标冲突：「明年」指将来，「了」表示已完成的动作，二者不能同用。应去掉「了」，说「明年把废气减排两成」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c70347ad-27a5-41a9-9ada-627dc309d573') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11804, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工厂去年减排着三成废气。", "corrected_sentence": "工厂去年减排了三成废气。", "error_description": "“着”表示动作持续或状态保持，与表示已完成的“去年”相冲突。应使用“了”，说“减排了三成废气”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c70347ad-27a5-41a9-9ada-627dc309d573') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
