INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11805, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "使某种概念或作用范围变得更广", "primary_collocate": null, "pronunciation": "yán zhǎn", "ipa": "jɛn˧˥ ʈʂan˨˩˦", "syllable_count": 2, "sentences": [{"text": "进一步解构“环保”这一复合型价值命题，公共交通的生态意义已从单纯的污染物减排，延展至生态系统服务功能的修复与再生。", "target_word": "延展", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "此外，主动流动控制技术，如边界层吸入或合成射流，正在被探索用于实时调节气流分离，进一步延展飞行包线。", "target_word": "延展", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个想法后来延展到了教育领域。", "target_word": "延展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把这个概念延展到生活里。", "target_word": "延展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这门课的思路还可以继续延展到其他学科。", "target_word": "延展", "complexity_tier": "T3", "furigana": "zhè mén kè de sī lù hái kě yǐ jì xù yán zhǎn dào qí tā xué kē", "sentence_source": "generated"}, {"text": "他把环保的意思延展到了饮食上。", "target_word": "延展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种说法的范围延展得很广。", "target_word": "延展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想把服务延展到农村。", "target_word": "延展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们可以把这个话题再延展一点。", "target_word": "延展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个词的意思慢慢延展到新的语境中。", "target_word": "延展", "complexity_tier": "T3", "furigana": "zhè ge cí de yì si màn man yán zhǎn dào xīn de yǔ jìng zhōng", "sentence_source": "generated"}], "morphological_forms": [{"form": "延展了", "label": "体标（了）"}, {"form": "延展着", "label": "体标（着）"}, {"form": "延展过", "label": "体标（过）"}, {"form": "延展性", "label": "复合"}], "register": "书面", "sense_fingerprint": "把概念、影响或范围扩大到新的领域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f51b7060-190e-43be-9474-2cfe868f2248') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11805, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "延展", "is_correct": true, "explanation": "正确。“延展至”表示概念或作用范围向外扩大到新的领域，与句中“从…减排，…至…修复与再生”的范围拓展一致。"}, {"text": "收缩", "is_correct": false, "explanation": "语义：“收缩”是缩小、收紧，与句中意义范围向外扩展的方向相反，不能说收缩至生态系统服务功能。"}, {"text": "缩减", "is_correct": false, "explanation": "语义：“缩减”是减少、削减，与“延展至”所表达的扩大方向相反。"}, {"text": "回落", "is_correct": false, "explanation": "搭配：“回落”多用于水位、价格、数值的下降，不说意义回落至某个功能领域，句意不通。"}], "explanations": {"延展": "正确。“延展至”表示概念或作用范围向外扩大到新的领域，与句中“从…减排，…至…修复与再生”的范围拓展一致。", "收缩": "语义：“收缩”是缩小、收紧，与句中意义范围向外扩展的方向相反，不能说收缩至生态系统服务功能。", "缩减": "语义：“缩减”是减少、削减，与“延展至”所表达的扩大方向相反。", "回落": "搭配：“回落”多用于水位、价格、数值的下降，不说意义回落至某个功能领域，句意不通。"}, "sentence_index": 0, "correct_answer": "延展"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把假期延展了一周。", "explanation": "这里应该用〈延长〉。延展指概念、影响或作用范围向外扩大，假期这类时间的增加要用延长。"}, {"text": "这个消息延展得很快，全村都知道了。", "explanation": "这里应该用〈传开〉。消息在人群中扩散要用传开，延展指概念或作用范围扩大到新的领域。"}, {"text": "这门手艺延展了两百年。", "explanation": "这里应该用〈延续〉。手艺、传统在时间上的持续要用延续，延展指概念或作用范围向外扩大，不用于计算持续的年数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb8b5ac8-0f38-4132-9264-c2063c12f1d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11805, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "延展", "is_correct": true, "explanation": "正确。“范围延展得很广”指说法所涉及的范围向外扩大，与“很广”一致。"}, {"text": "缩小", "is_correct": false, "explanation": "语义：“缩小”指范围变窄，与后面的“很广”矛盾，不能说范围缩小得很广。"}, {"text": "压缩", "is_correct": false, "explanation": "搭配：“压缩”多用于篇幅、时间、开支，不说范围压缩得很广，句子意思不通。"}, {"text": "限制", "is_correct": false, "explanation": "语义：“限制”是约束、限定，与“范围…很广”的意思相反，不能说范围限制得很广。"}], "explanations": {"延展": "正确。“范围延展得很广”指说法所涉及的范围向外扩大，与“很广”一致。", "缩小": "语义：“缩小”指范围变窄，与后面的“很广”矛盾，不能说范围缩小得很广。", "压缩": "搭配：“压缩”多用于篇幅、时间、开支，不说范围压缩得很广，句子意思不通。", "限制": "语义：“限制”是约束、限定，与“范围…很广”的意思相反，不能说范围限制得很广。"}, "sentence_index": 6, "correct_answer": "延展"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次培训让他的水平延展了不少。", "explanation": "这里应该用〈提高〉。水平、质量的上升要用提高，延展指范围向外扩大，不用来修饰水平。"}, {"text": "这本词典延展到了五万词条。", "explanation": "这里应该用〈扩充〉。词条、内容的增添要用扩充，延展用于范围向外拓展，不指数量的增加。"}, {"text": "这次谈话让我们的感情延展了不少。", "explanation": "这里应该用〈加深〉。感情的深化要用加深，延展指概念或作用范围向外扩大，不用于描述感情的深浅。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb8b5ac8-0f38-4132-9264-c2063c12f1d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11805, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这套方法可以延展其他行业。", "corrected_sentence": "这套方法可以延展到其他行业。", "error_description": "错误：“延展其他行业”，正确：“延展到其他行业”。“延展”后要接表示终点的“到”，漏掉“到”，句子不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb8b5ac8-0f38-4132-9264-c2063c12f1d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11805, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校想把这个活动延展到了社区。", "corrected_sentence": "学校想把这个活动延展到社区。", "error_description": "错误：“想把这个活动延展到了社区”，正确：“想把这个活动延展到社区”。“想”表示还没实现的打算，后面的“延展”不能带表示完成的“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb8b5ac8-0f38-4132-9264-c2063c12f1d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
