INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11807, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "为他人或集体提供帮助或做事情。", "primary_collocate": null, "pronunciation": "fú wù", "ipa": "fu˧˥ u˥˩", "syllable_count": 2, "sentences": [{"text": "他在医院工作，每天为病人服务。", "target_word": "服务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师愿意一辈子为学生服务。", "target_word": "服务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王加入了志愿者队伍，为社区服务。", "target_word": "服务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察的工作就是为大家服务。", "target_word": "服务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在银行工作，每天为客人服务。", "target_word": "服务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司为全国的客户服务。", "target_word": "服务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生要认真地为每个病人服务。", "target_word": "服务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他为公司服务了二十年。", "target_word": "服务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小组专门为老年人服务。", "target_word": "服务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆为市民服务，周末也开门。", "target_word": "服务", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "服务了", "label": "体标"}, {"form": "服务过", "label": "体标"}, {"form": "服务员", "label": "复合"}], "register": "中性", "sense_fingerprint": "为人、集体或单位工作，提供帮助", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df7e06a5-aa40-4d69-893b-a969f8b578f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11807, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "服务", "is_correct": true, "explanation": "服务指为病人提供照料和帮助，符合「在医院工作」的句意。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：睡觉是自己的事，不能替病人去做，句意不通。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：游泳无法替他人完成，「为病人游泳」说不通。"}, {"text": "生气", "is_correct": false, "explanation": "语义：“生气”是发怒，与“为病人服务”的帮助之义不符，不能替病人去生气。"}], "explanations": {"服务": "服务指为病人提供照料和帮助，符合「在医院工作」的句意。", "睡觉": "语义：睡觉是自己的事，不能替病人去做，句意不通。", "游泳": "语义：游泳无法替他人完成，「为病人游泳」说不通。", "生气": "语义：“生气”是发怒，与“为病人服务”的帮助之义不符，不能替病人去生气。"}, "sentence_index": 0, "correct_answer": "服务"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "农民每天在地里服务，种庄稼。", "explanation": "这里应该用〈劳动〉。服务是为别人提供帮助，在地里种庄稼是劳动，不能说「在地里服务」。"}, {"text": "士兵必须服务命令，不能随便改变。", "explanation": "这里应该用〈服从〉。服从指听从命令和规定，服务指为人提供帮助，不能用来表示听从。"}, {"text": "他从不肯服务，遇到困难也不退缩。", "explanation": "这里应该用〈服输〉。服输指承认失败、不逞强，服务无法表达这个意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8e394ba-5d70-4d05-976c-ff686d21fbf2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11807, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "服务", "is_correct": true, "explanation": "服务指认真地为病人提供照料和帮助，符合句中「认真地」的说法。"}, {"text": "发脾气", "is_correct": false, "explanation": "语义：对病人发脾气与「认真地」照顾的态度相反，句意不通。"}, {"text": "迟到", "is_correct": false, "explanation": "语义：“迟到”是自己的行为，不能替病人去迟到，与“认真地为每个病人”服务的意思不符。"}, {"text": "考试", "is_correct": false, "explanation": "语义：考试无法替病人完成，「为每个病人考试」说不通。"}], "explanations": {"服务": "服务指认真地为病人提供照料和帮助，符合句中「认真地」的说法。", "发脾气": "语义：对病人发脾气与「认真地」照顾的态度相反，句意不通。", "迟到": "语义：“迟到”是自己的行为，不能替病人去迟到，与“认真地为每个病人”服务的意思不符。", "考试": "语义：考试无法替病人完成，「为每个病人考试」说不通。"}, "sentence_index": 6, "correct_answer": "服务"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生叮嘱他每天饭后服务，不能忘记。", "explanation": "这里应该用〈服药〉。服药指吃药，服务不能用来指吃药。"}, {"text": "他输了比赛，心里很不服务。", "explanation": "这里应该用〈服气〉。服气指心里信服、认输，服务不能表达这种心理。"}, {"text": "他穿着一身新服务，走进了会场。", "explanation": "这里应该用〈服装〉。服装是衣物，可以穿；服务是动作，不能穿在身上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8e394ba-5d70-4d05-976c-ff686d21fbf2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11807, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他每天病人服务到深夜。", "corrected_sentence": "他每天为病人服务到深夜。", "error_description": "“服务”是动词，宾语应放在它后面或用“为”引出，不能直接把“病人”放在“服务”前面。应说“每天为病人服务到深夜”或“每天服务病人到深夜”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8e394ba-5d70-4d05-976c-ff686d21fbf2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11807, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "图书馆每天为市民服务了到深夜。", "corrected_sentence": "图书馆每天为市民服务到深夜。", "error_description": "“了”是动态助词，不能插在动词“服务”与补语“到深夜”之间，应说“服务到深夜”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8e394ba-5d70-4d05-976c-ff686d21fbf2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11808, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "破坏", "is_correct": true, "explanation": "破坏与修复构成反义：修复是使损坏之物恢复，破坏是使之损坏。"}, {"text": "建造", "is_correct": false, "explanation": "与修复无反义关系：建造是从无到有地造，并非修复的相反。"}, {"text": "购买", "is_correct": false, "explanation": "与修复无反义关系：购买是获得物品，与修复不构成相对的动作。"}, {"text": "打扫", "is_correct": false, "explanation": "与修复无反义关系：打扫指清除脏物，不与修复相对。"}], "correct_answer": "破坏", "explanations": {"破坏": "破坏与修复构成反义：修复是使损坏之物恢复，破坏是使之损坏。", "建造": "与修复无反义关系：建造是从无到有地造，并非修复的相反。", "购买": "与修复无反义关系：购买是获得物品，与修复不构成相对的动作。", "打扫": "与修复无反义关系：打扫指清除脏物，不与修复相对。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8e394ba-5d70-4d05-976c-ff686d21fbf2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11808, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "破坏", "is_correct": true, "explanation": "破坏与修复构成反义：修复是使损坏之物恢复，破坏是使之损坏。"}, {"text": "种植", "is_correct": false, "explanation": "与修复无反义关系：种植是栽培植物，与修复不构成相对的动作。"}, {"text": "浏览", "is_correct": false, "explanation": "与修复无反义关系：浏览是快速查看，与修复不相对。"}, {"text": "雕刻", "is_correct": false, "explanation": "与修复无反义关系：雕刻是用工具刻出形状，与修复不相对。"}], "correct_answer": "破坏", "explanations": {"破坏": "破坏与修复构成反义：修复是使损坏之物恢复，破坏是使之损坏。", "种植": "与修复无反义关系：种植是栽培植物，与修复不构成相对的动作。", "浏览": "与修复无反义关系：浏览是快速查看，与修复不相对。", "雕刻": "与修复无反义关系：雕刻是用工具刻出形状，与修复不相对。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8e394ba-5d70-4d05-976c-ff686d21fbf2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11808, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "修理损坏的东西，使其恢复原来的样子或功能。", "primary_collocate": null, "pronunciation": "xiū fù", "ipa": "ɕiou˥ fu˥˩", "syllable_count": 2, "sentences": [{"text": "工人们正在修复这座古老的桥。", "target_word": "修复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家花了三年时间修复这幅旧画。", "target_word": "修复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座古庙已经修复好了。", "target_word": "修复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们想把坏了的城墙修复成原来的样子。", "target_word": "修复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆请专家修复破碎的花瓶。", "target_word": "修复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震以后，政府很快修复了公路。", "target_word": "修复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "修复这台老收音机需要很长时间。", "target_word": "修复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用电脑修复了这张旧照片。", "target_word": "修复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老房子修复以后，看起来和以前一样。", "target_word": "修复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "铁路公司在夜里修复了坏掉的铁轨。", "target_word": "修复", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "修复了", "label": "体标"}, {"form": "修复过", "label": "体标"}, {"form": "修复好", "label": "复合"}], "register": "中性", "sense_fingerprint": "修理损坏之物，使其恢复原样或功能", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df7e06a5-aa40-4d69-893b-a969f8b578f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11808, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "修复", "is_correct": true, "explanation": "修复 xiū fù：修理损坏的东西，使其恢复原样。"}, {"text": "吸附", "is_correct": false, "explanation": "吸附 xī fù 第一音节韵母为单元音 -i，与修复 xiū 的复韵母 -iu 不同，意思是吸附。"}, {"text": "心腹", "is_correct": false, "explanation": "心腹 xīn fù 第一音节韵母为 -in，与修复 xiū 的 -iu 不同，意思是心腹、亲信。"}, {"text": "胸腹", "is_correct": false, "explanation": "胸腹 xiōng fù 第一音节韵母为 -iong，与修复 xiū 的 -iu 不同，意思是胸部和腹部。"}, {"text": "小腹", "is_correct": false, "explanation": "小腹 xiǎo fù 第一音节为第三声且韵母为 -iao，与修复 xiū（第一声）不同，意思是下腹部。"}], "explanations": {"修复": "修复 xiū fù：修理损坏的东西，使其恢复原样。", "吸附": "吸附 xī fù 第一音节韵母为单元音 -i，与修复 xiū 的复韵母 -iu 不同，意思是吸附。", "心腹": "心腹 xīn fù 第一音节韵母为 -in，与修复 xiū 的 -iu 不同，意思是心腹、亲信。", "胸腹": "胸腹 xiōng fù 第一音节韵母为 -iong，与修复 xiū 的 -iu 不同，意思是胸部和腹部。", "小腹": "小腹 xiǎo fù 第一音节为第三声且韵母为 -iao，与修复 xiū（第一声）不同，意思是下腹部。"}, "sentence_index": null, "correct_answer": "修复"}, "level_3": {"options": [{"text": "修复", "is_correct": true, "explanation": "正确：修复指把损坏的桥修好、恢复原样，与“古老的桥”需要修补的语境相符。"}, {"text": "建造", "is_correct": false, "explanation": "语义：“建造”指从无到有地新建，与“古老的”桥相矛盾。"}, {"text": "翻译", "is_correct": false, "explanation": "搭配：“翻译”的对象是语言或文字，不能说翻译一座桥。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”的对象是食物，不能说煮一座桥。"}], "explanations": {"修复": "正确：修复指把损坏的桥修好、恢复原样，与“古老的桥”需要修补的语境相符。", "建造": "语义：“建造”指从无到有地新建，与“古老的”桥相矛盾。", "翻译": "搭配：“翻译”的对象是语言或文字，不能说翻译一座桥。", "煮": "搭配：“煮”的对象是食物，不能说煮一座桥。"}, "sentence_index": 0, "correct_answer": "修复"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本教材每隔三年修复一次。", "explanation": "这里应该用〈修订〉。修复用于恢复损坏之物，教材的更新改版要说修订。"}, {"text": "政府今年计划修复三条新公路。", "explanation": "这里应该用〈修建〉。修复指把损坏的东西恢复原样，新公路要说修建。"}, {"text": "园丁每天早上把草坪修复得整整齐齐。", "explanation": "这里应该用〈修剪〉。修复用于恢复损坏之物，草坪的修整要说修剪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8e394ba-5d70-4d05-976c-ff686d21fbf2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11808, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "修复", "is_correct": true, "explanation": "修复 xiū fù：修理损坏的东西，使其恢复原样。"}, {"text": "西服", "is_correct": false, "explanation": "西服 xī fú 第一音节韵母为 -i，第二音节为第二声 fú，与修复 xiū fù 不同，意思是西装。"}, {"text": "心服", "is_correct": false, "explanation": "心服 xīn fú 第一音节韵母为 -in，第二音节为第二声 fú，与修复不同，意思是心里信服。"}, {"text": "幸福", "is_correct": false, "explanation": "幸福 xìng fú 第一音节为第四声且韵母为 -ing，第二音节为第二声 fú，与修复不同，意思是幸福。"}], "explanations": {"修复": "修复 xiū fù：修理损坏的东西，使其恢复原样。", "西服": "西服 xī fú 第一音节韵母为 -i，第二音节为第二声 fú，与修复 xiū fù 不同，意思是西装。", "心服": "心服 xīn fú 第一音节韵母为 -in，第二音节为第二声 fú，与修复不同，意思是心里信服。", "幸福": "幸福 xìng fú 第一音节为第四声且韵母为 -ing，第二音节为第二声 fú，与修复不同，意思是幸福。"}, "sentence_index": null, "correct_answer": "修复"}, "level_3": {"options": [{"text": "修复", "is_correct": true, "explanation": "正确：修复指让坏掉的收音机恢复功能，与“需要很长时间”相符。"}, {"text": "出版", "is_correct": false, "explanation": "语义：“出版”指印行书刊或作品，收音机不能出版。"}, {"text": "打印", "is_correct": false, "explanation": "搭配：“打印”的对象是文件或图片，不能打印一台收音机。"}, {"text": "烹饪", "is_correct": false, "explanation": "搭配：“烹饪”的对象是食物，不能烹饪收音机。"}], "explanations": {"修复": "正确：修复指让坏掉的收音机恢复功能，与“需要很长时间”相符。", "出版": "语义：“出版”指印行书刊或作品，收音机不能出版。", "打印": "搭配：“打印”的对象是文件或图片，不能打印一台收音机。", "烹饪": "搭配：“烹饪”的对象是食物，不能烹饪收音机。"}, "sentence_index": 6, "correct_answer": "修复"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位作家每周都在修复自己的小说。", "explanation": "这里应该用〈修改〉。修复用于把坏掉的东西修好，小说的改动要说修改。"}, {"text": "老师正在修复学生的作文。", "explanation": "这里应该用〈修改〉。修复用于把损坏的东西恢复原样，改作文要说修改。"}, {"text": "她每天早上在镜子前修复自己的仪容。", "explanation": "这里应该用〈修饰〉。修复用于恢复损坏之物，打理仪容要说修饰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8e394ba-5d70-4d05-976c-ff686d21fbf2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
