INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11809, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指生物或自然物受损、断裂后重新长出，恢复生机。", "primary_collocate": null, "pronunciation": "zài shēng", "ipa": "tsaɪ̯˥˩ ʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "进一步解构“环保”这一复合型价值命题，公共交通的生态意义已从单纯的污染物减排，延展至生态系统服务功能的修复与再生。", "target_word": "再生", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "大火以后，这片森林慢慢开始再生。", "target_word": "再生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "壁虎的尾巴断了，还能再生。", "target_word": "再生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河边的湿地需要几年才能再生。", "target_word": "再生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牛吃掉这种草以后，它很快再生。", "target_word": "再生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家想让受伤的皮肤再生。", "target_word": "再生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨后，干枯的草地又开始再生。", "target_word": "再生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海星断了一条腕，也能再生。", "target_word": "再生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片红树林的再生用了十年。", "target_word": "再生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有些植物的根断了，也能再生。", "target_word": "再生", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "再生资源", "label": "复合"}, {"form": "再生能力", "label": "复合"}], "register": "中性", "sense_fingerprint": "生物或自然物损坏后重新长出、恢复生机", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3c9b1ce-420a-4bbc-97dd-366c624344ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11809, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "再生", "is_correct": true, "explanation": "正确答案：再生（zài shēng），指生物或自然物损坏后重新长出。"}, {"text": "再扔", "is_correct": false, "explanation": "rēng 与 shēng 声母不同（r／sh），意思是再扔掉。"}, {"text": "再伸", "is_correct": false, "explanation": "shēn 与 shēng 韵尾不同（n／ng），意思是再伸展。"}, {"text": "再省", "is_correct": false, "explanation": "shěng（第三声）与 shēng（第一声）声调不同，意思是再节省。"}, {"text": "再称", "is_correct": false, "explanation": "chēng 与 shēng 声母不同（ch／sh），意思是再称一次。"}], "explanations": {"再生": "正确答案：再生（zài shēng），指生物或自然物损坏后重新长出。", "再扔": "rēng 与 shēng 声母不同（r／sh），意思是再扔掉。", "再伸": "shēn 与 shēng 韵尾不同（n／ng），意思是再伸展。", "再省": "shěng（第三声）与 shēng（第一声）声调不同，意思是再节省。", "再称": "chēng 与 shēng 声母不同（ch／sh），意思是再称一次。"}, "sentence_index": null, "correct_answer": "再生"}, "level_3": {"options": [{"text": "再生", "is_correct": true, "explanation": "正确：这里指生态系统功能的恢复性再生，与前文讲的“生态意义”相符。"}, {"text": "污染", "is_correct": false, "explanation": "语义：污染与前文的“减排”相反，不能描述生态意义的延展。"}, {"text": "破坏", "is_correct": false, "explanation": "语义：破坏与“修复”相反，表达负面影响，与生态意义不符。"}, {"text": "消耗", "is_correct": false, "explanation": "搭配：消耗多指资源被用掉，不能与“修复”并列说“修复与消耗”。"}], "explanations": {"再生": "正确：这里指生态系统功能的恢复性再生，与前文讲的“生态意义”相符。", "污染": "语义：污染与前文的“减排”相反，不能描述生态意义的延展。", "破坏": "语义：破坏与“修复”相反，表达负面影响，与生态意义不符。", "消耗": "搭配：消耗多指资源被用掉，不能与“修复”并列说“修复与消耗”。"}, "sentence_index": 0, "correct_answer": "再生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张老照片已经再生得很清楚了。", "explanation": "这里应该用〈复原〉。再生指生物或自然物重新长出，老照片只是恢复原样，要说“复原”。"}, {"text": "这个城市的交通已经再生正常了。", "explanation": "这里应该用〈恢复〉。再生指生物或自然物重新长出，交通不是生物，要说“恢复正常”。"}, {"text": "地震后，政府正在再生学校。", "explanation": "这里应该用〈重建〉。再生只用于生物或自然物重新长出，学校被毁后要“重建”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65de5bc4-b62f-4ec2-9482-df726991680b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11809, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "再生", "is_correct": true, "explanation": "正确答案：再生（zài shēng），指生物或自然物损坏后重新长出。"}, {"text": "再盛", "is_correct": false, "explanation": "shèng（第四声）与 shēng（第一声）声调不同，意思是再盛一碗饭。"}, {"text": "再争", "is_correct": false, "explanation": "zhēng 与 shēng 声母不同（zh／sh），意思是争取，不是再生。"}, {"text": "再深", "is_correct": false, "explanation": "shēn 与 shēng 韵尾不同（n／ng），意思是再深一些。"}], "explanations": {"再生": "正确答案：再生（zài shēng），指生物或自然物损坏后重新长出。", "再盛": "shèng（第四声）与 shēng（第一声）声调不同，意思是再盛一碗饭。", "再争": "zhēng 与 shēng 声母不同（zh／sh），意思是争取，不是再生。", "再深": "shēn 与 shēng 韵尾不同（n／ng），意思是再深一些。"}, "sentence_index": null, "correct_answer": "再生"}, "level_3": {"options": [{"text": "再生", "is_correct": true, "explanation": "正确：雨后干枯的草地重新长出草，符合“再生”的生物义。"}, {"text": "腐烂", "is_correct": false, "explanation": "语义：腐烂是败坏，与雨后恢复生机的语境相反。"}, {"text": "凋谢", "is_correct": false, "explanation": "搭配：凋谢多用于花，不说草地凋谢。"}, {"text": "枯萎", "is_correct": false, "explanation": "语义：枯萎与“又开始”表示的恢复之意相反，也与前文“干枯”重复。"}], "explanations": {"再生": "正确：雨后干枯的草地重新长出草，符合“再生”的生物义。", "腐烂": "语义：腐烂是败坏，与雨后恢复生机的语境相反。", "凋谢": "搭配：凋谢多用于花，不说草地凋谢。", "枯萎": "语义：枯萎与“又开始”表示的恢复之意相反，也与前文“干枯”重复。"}, "sentence_index": 6, "correct_answer": "再生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "墙上的洞已经再生好了。", "explanation": "这里应该用〈修补〉。再生指生物或自然物重新长出，墙上的洞只是补好，要说“修补”。"}, {"text": "这件花瓶摔碎后已经自己再生了。", "explanation": "这里应该用〈修复〉。再生用于生物或自然物重新长出，花瓶是人工制品，要说“修复”。"}, {"text": "我的手机摔坏了，已经自己再生好了。", "explanation": "这里应该用〈修好〉。再生不能用于手机等机器，坏了的机器要“修好”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65de5bc4-b62f-4ec2-9482-df726991680b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11809, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "树桩砍掉以后，又慢慢再生的。", "corrected_sentence": "树桩砍掉以后，又慢慢再生了。", "error_description": "句末的“了”被换成了“的”。“再生”后面表示变化已经发生，要用“了”，说“再生了”；“再生的”不能作句末谓语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65de5bc4-b62f-4ec2-9482-df726991680b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11809, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "螃蟹断了腿以后，很快就能再生来。", "corrected_sentence": "螃蟹断了腿以后，很快就能再生出来。", "error_description": "趋向补语漏了“出”。表示重新长出，要说“再生出来”，只说“再生来”不成句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65de5bc4-b62f-4ec2-9482-df726991680b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
