INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11810, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0916f1a2-4269-47b8-aa72-5fc4a9a9257b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11810, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "城市中供车辆和行人通行的道路，通常包括机动车道、非机动车道和人行道。", "primary_collocate": null, "pronunciation": "chéng shì dào lù", "ipa": "ʈʂʰɤŋ˧˥ ʂɻ̩˥˩ taʊ˥˩ lu˥˩", "syllable_count": 4, "sentences": [{"text": "当城市道路资源从私人汽车的过度占用中被释放，其空间再分配可催生大规模绿色基础设施建设：原本用于停车的空间转化为线性公园、雨水花园与生物廊道，不仅增强城市碳汇能力，更缓解热岛效应并提升生物多样性。", "target_word": "城市道路", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "城市道路上有机动车道和人行道。", "target_word": "城市道路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条城市道路每天都有很多车经过。", "target_word": "城市道路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市道路旁边种着很多树。", "target_word": "城市道路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府正在修一条新的城市道路。", "target_word": "城市道路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市道路的人行道比以前宽了。", "target_word": "城市道路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早上八点，城市道路上特别堵。", "target_word": "城市道路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市道路上的红绿灯突然坏了。", "target_word": "城市道路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市道路上的非机动车道是给骑自行车的人用的。", "target_word": "城市道路", "complexity_tier": "T3", "furigana": "chéng shì dào lù shàng de fēi jī dòng chē dào shì gěi qí zì xíng chē de rén yòng de", "sentence_source": "generated"}, {"text": "新的城市道路让上班的人少花了很多时间。", "target_word": "城市道路", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}], "register": "中性", "sense_fingerprint": "城市中供车辆和行人通行的道路，含机动车道、非机动车道、人行道", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '869a6818-447d-4435-b360-0323be8c2be3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11810, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "城市道路", "is_correct": true, "explanation": "正确：城市道路是被私人汽车占用、之后可以重新分配的空间，与句意相合。"}, {"text": "农田", "is_correct": false, "explanation": "语义：农田是用来种庄稼的土地，不会被私人汽车占用。"}, {"text": "河流", "is_correct": false, "explanation": "搭配：汽车不会占用河流，“河流资源从私人汽车的过度占用中被释放”说不通。"}, {"text": "湿地", "is_correct": false, "explanation": "语义：湿地是自然生态区，与汽车占用空间并转为绿地的语境无关。"}], "explanations": {"城市道路": "正确：城市道路是被私人汽车占用、之后可以重新分配的空间，与句意相合。", "农田": "语义：农田是用来种庄稼的土地，不会被私人汽车占用。", "河流": "搭配：汽车不会占用河流，“河流资源从私人汽车的过度占用中被释放”说不通。", "湿地": "语义：湿地是自然生态区，与汽车占用空间并转为绿地的语境无关。"}, "sentence_index": 0, "correct_answer": "城市道路"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条城市道路穿过很多村庄，一直通到外省。", "explanation": "这里应该用〈公路〉。城市道路只指城市里的道路，不用于穿过村庄、通往外省的长途道路。"}, {"text": "城市道路里住着很多老北京人。", "explanation": "这里应该用〈胡同〉。城市道路是供车辆和行人通行的道路，不指可以住人的小巷。"}, {"text": "他选择了一条通向成功的城市道路。", "explanation": "这里应该用〈途径〉。“道路”可比喻通向目标的途径，“城市道路”只指城市里供车辆和行人通行的路，不能这样比喻。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0916f1a2-4269-47b8-aa72-5fc4a9a9257b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11810, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "城市道路", "is_correct": true, "explanation": "正确：城市道路上有车辆通行，“特别堵”指车辆拥挤，句意相合。"}, {"text": "天空", "is_correct": false, "explanation": "语义：车辆不在天空中行驶，“天空上特别堵”不合常理。"}, {"text": "海面", "is_correct": false, "explanation": "语义：海面上没有车辆通行，不能说堵车。"}, {"text": "田野", "is_correct": false, "explanation": "搭配：田野不是车辆通行的场所，“田野上特别堵”没有对应的交通情境。"}], "explanations": {"城市道路": "正确：城市道路上有车辆通行，“特别堵”指车辆拥挤，句意相合。", "天空": "语义：车辆不在天空中行驶，“天空上特别堵”不合常理。", "海面": "语义：海面上没有车辆通行，不能说堵车。", "田野": "搭配：田野不是车辆通行的场所，“田野上特别堵”没有对应的交通情境。"}, "sentence_index": 6, "correct_answer": "城市道路"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条城市道路每天有很多趟火车经过。", "explanation": "这里应该用〈铁路〉。火车行驶在铁路上，城市道路供车辆和行人通行，不供火车使用。"}, {"text": "飞机在城市道路上起飞。", "explanation": "这里应该用〈跑道〉。飞机起飞要在跑道上进行，城市道路不供飞机使用。"}, {"text": "我每天坐城市道路去上班。", "explanation": "这里应该用〈地铁〉。“坐”的对象应是交通工具，城市道路是供通行的路，不能乘坐。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0916f1a2-4269-47b8-aa72-5fc4a9a9257b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11810, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府新修了一座城市道路。", "corrected_sentence": "政府新修了一条城市道路。", "error_description": "量词错误：“座”多用于山、桥、楼等，道路应该用量词“条”，应为“一条城市道路”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0916f1a2-4269-47b8-aa72-5fc4a9a9257b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11810, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们正在修这条的城市道路。", "corrected_sentence": "我们正在修这条城市道路。", "error_description": "助词错误：“这条”与名词之间不能加“的”，应去掉“的”，为“这条城市道路”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0916f1a2-4269-47b8-aa72-5fc4a9a9257b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
