INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11811, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb8b5ac8-0f38-4132-9264-c2063c12f1d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11811, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把某物或某段时间用来做某事，使之不再空闲。", "primary_collocate": null, "pronunciation": "zhàn yòng", "ipa": "ʈʂan˥˩ jʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "当城市道路资源从私人汽车的过度占用中被释放，其空间再分配可催生大规模绿色基础设施建设：原本用于停车的空间转化为线性公园、雨水花园与生物廊道，不仅增强城市碳汇能力，更缓解热岛效应并提升生物多样性。", "target_word": "占用", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "其中，厨余垃圾作为家庭废弃物中占比最高的组成部分，若仅以填埋或焚烧方式处置，不仅占用土地资源，更会产生甲烷等强效温室气体，加剧全球气候危机。", "target_word": "占用", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "停着的车占用了人行道。", "target_word": "占用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要占用消防通道。", "target_word": "占用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这堆东西占用了半个房间。", "target_word": "占用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友占用了我的座位。", "target_word": "占用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们今天要占用一下教室。", "target_word": "占用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂占用了很多农田。", "target_word": "占用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别占用公共停车位。", "target_word": "占用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把杂物放着，占用了走廊。", "target_word": "占用", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "占用了", "label": "体标（了）"}, {"form": "占用着", "label": "体标（着）"}, {"form": "占用过", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "占着场地、物品或资源，使别人不能使用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f51b7060-190e-43be-9474-2cfe868f2248') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11811, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "占用", "is_correct": true, "explanation": "正确。“过度占用”指私人汽车长期占据道路资源，与句中资源被释放的语境相符。"}, {"text": "保护", "is_correct": false, "explanation": "语义：“过度保护”与资源被释放的意思相反，不能说资源从过度保护中被释放。"}, {"text": "报废", "is_correct": false, "explanation": "语义：“报废”指作废，道路资源不能从报废中被释放，句意不通。"}, {"text": "维修", "is_correct": false, "explanation": "搭配：“维修”多用于设施、设备，不说道路资源被过度维修。"}], "explanations": {"占用": "正确。“过度占用”指私人汽车长期占据道路资源，与句中资源被释放的语境相符。", "保护": "语义：“过度保护”与资源被释放的意思相反，不能说资源从过度保护中被释放。", "报废": "语义：“报废”指作废，道路资源不能从报废中被释放，句意不通。", "维修": "搭配：“维修”多用于设施、设备，不说道路资源被过度维修。"}, "sentence_index": 0, "correct_answer": "占用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "敌军占用了这座城市。", "explanation": "这里应该用〈占领〉。军队或势力控制一地要用占领，占用指暂时使用某处或某物，不用于军事控制。"}, {"text": "他占用了冠军的宝座。", "explanation": "这里应该用〈占据〉。占据指占有某个位置或地位，“宝座”这类地位要用占据，占用不用于此类地位。"}, {"text": "这位投资者占用了这家公司百分之三十的股份。", "explanation": "这里应该用〈占有〉。股份等所有权要用占有，占用指暂时使用，不表示拥有。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb8b5ac8-0f38-4132-9264-c2063c12f1d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11811, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "占用", "is_correct": true, "explanation": "正确。“我们今天要占用一下教室”指暂时使用教室，与句意一致。"}, {"text": "预习", "is_correct": false, "explanation": "搭配：“预习”的对象是课文、功课，不能用于教室，不说预习一下教室。"}, {"text": "呼吸", "is_correct": false, "explanation": "配价：“呼吸”是不及物动词，不能带“教室”作宾语。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，与教室无关，句子不成立。"}], "explanations": {"占用": "正确。“我们今天要占用一下教室”指暂时使用教室，与句意一致。", "预习": "搭配：“预习”的对象是课文、功课，不能用于教室，不说预习一下教室。", "呼吸": "配价：“呼吸”是不及物动词，不能带“教室”作宾语。", "吃": "语义：“吃”指进食，与教室无关，句子不成立。"}, "sentence_index": 6, "correct_answer": "占用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他总想占用别人的便宜。", "explanation": "这里应该用〈占便宜〉。这是固定说法，表示利用别人的好处，“占用”不能与“便宜”搭配。"}, {"text": "这场比赛中，我们占用了先机。", "explanation": "这里应该用〈占先机〉。“先机”这类说法要用占，占用指暂时使用某处或某物。"}, {"text": "这次辩论他们占用了上风。", "explanation": "这里应该用〈占上风〉。“上风”是固定搭配，表示处于有利地位，占用不能与之搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb8b5ac8-0f38-4132-9264-c2063c12f1d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11811, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事把我的时间占用。", "corrected_sentence": "这件事把我的时间占用了。", "error_description": "错误：“把我的时间占用”，正确：“把我的时间占用了”。用“把”字句时，动词后要有“了”“着”等成分，“占用”不能直接结束句子。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb8b5ac8-0f38-4132-9264-c2063c12f1d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11811, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们可以占用了这间会议室。", "corrected_sentence": "我们可以占用这间会议室。", "error_description": "错误：“可以占用了”，正确：“可以占用”。“可以”表示可能，后面的动词不能再带表示完成的“了”，应删去“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb8b5ac8-0f38-4132-9264-c2063c12f1d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
