INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11815, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "将车辆停放在某处，使发动机停止运转。", "primary_collocate": null, "pronunciation": "tíng chē", "ipa": "tʰiŋ˧˥ ʈʂʰɤ˥", "syllable_count": 2, "sentences": [{"text": "当城市道路资源从私人汽车的过度占用中被释放，其空间再分配可催生大规模绿色基础设施建设：原本用于停车的空间转化为线性公园、雨水花园与生物廊道，不仅增强城市碳汇能力，更缓解热岛效应并提升生物多样性。", "target_word": "停车", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这里不能停车，警察会罚款。", "target_word": "停车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在商场门口停车，然后进去买东西。", "target_word": "停车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请在白线里面停车。", "target_word": "停车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他开到路边停车，接了一个电话。", "target_word": "停车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院附近很难停车。", "target_word": "停车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说：“前面可以停车。”", "target_word": "停车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨时，他在大树下停车休息。", "target_word": "停车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末去市中心，停车很难，常常要绕好几圈。", "target_word": "停车", "complexity_tier": "T3", "furigana": "zhōu mò qù shì zhōng xīn tíng chē hěn nán cháng cháng yào rào hǎo jǐ quān", "sentence_source": "generated"}, {"text": "我不敢在很窄的路上停车。", "target_word": "停车", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "停了车", "label": "体标"}, {"form": "停过车", "label": "体标"}, {"form": "停车场", "label": "复合"}], "register": "中性", "sense_fingerprint": "把车辆停放在某处并熄火", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '869a6818-447d-4435-b360-0323be8c2be3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11815, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "停车", "is_correct": true, "explanation": "正确：“用于停车的空间”指停放车辆的空间，与私人汽车占用道路的语境吻合。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：游泳需要水域，与停放汽车的空间不符。"}, {"text": "上课", "is_correct": false, "explanation": "语义：上课需要教室，与汽车占用的空间无关。"}, {"text": "洗澡", "is_correct": false, "explanation": "搭配：洗澡要在浴室进行，“用于洗澡的空间”与私人汽车占用的语境不合。"}], "explanations": {"停车": "正确：“用于停车的空间”指停放车辆的空间，与私人汽车占用道路的语境吻合。", "游泳": "语义：游泳需要水域，与停放汽车的空间不符。", "上课": "语义：上课需要教室，与汽车占用的空间无关。", "洗澡": "搭配：洗澡要在浴室进行，“用于洗澡的空间”与私人汽车占用的语境不合。"}, "sentence_index": 0, "correct_answer": "停车"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "比赛因为下雨停车了。", "explanation": "这里应该用〈停止〉。停车只用于车辆，比赛停下来要说“停止”。"}, {"text": "货船在码头停车，等待装货。", "explanation": "这里应该用〈停靠〉。船只靠岸要说“停靠”，“停车”只用于汽车等车辆。"}, {"text": "晚上突然停车，房间很黑。", "explanation": "这里应该用〈停电〉。电力中断说停电，停车只指车辆停下。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0916f1a2-4269-47b8-aa72-5fc4a9a9257b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11815, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "停车", "is_correct": true, "explanation": "正确：“前面可以停车”是行车中允许车辆停下的说法，句意相合。"}, {"text": "呼吸", "is_correct": false, "explanation": "语义：呼吸不是车里可以被允许去做的动作，与“前面可以”的指令不合。"}, {"text": "发光", "is_correct": false, "explanation": "语义：车不会因为“前面可以”而发光，句意不通。"}, {"text": "生病", "is_correct": false, "explanation": "搭配：“前面可以生病”不是行车中的指示，搭配不成立。"}], "explanations": {"停车": "正确：“前面可以停车”是行车中允许车辆停下的说法，句意相合。", "呼吸": "语义：呼吸不是车里可以被允许去做的动作，与“前面可以”的指令不合。", "发光": "语义：车不会因为“前面可以”而发光，句意不通。", "生病": "搭配：“前面可以生病”不是行车中的指示，搭配不成立。"}, "sentence_index": 6, "correct_answer": "停车"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个城市我只停车了三天。", "explanation": "这里应该用〈停留〉。停车只指车辆停下，人在城市里逗留要说“停留”。"}, {"text": "因为下大雪，学校停车了三天。", "explanation": "这里应该用〈停课〉。“停车”指车辆停下，学校暂停上课要说“停课”。"}, {"text": "因为装修，饭店停车了。", "explanation": "这里应该用〈停业〉。“停车”只用于车辆，店铺暂停营业要说“停业”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0916f1a2-4269-47b8-aa72-5fc4a9a9257b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11815, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "司机在路边停车车，查看了一下地图。", "corrected_sentence": "司机在路边停车，查看了一下地图。", "error_description": "宾语重复：“停车”已含“车”，后面不能再加“车”，应为“在路边停车”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0916f1a2-4269-47b8-aa72-5fc4a9a9257b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11815, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在路边停车着，等朋友。", "corrected_sentence": "他在路边停着车，等朋友。", "error_description": "离合词位置错误：“着”应插在“停”与“车”之间，应为“停着车”，不能说“停车着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0916f1a2-4269-47b8-aa72-5fc4a9a9257b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
