INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11818, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "种植花草树木、供人观赏游玩的园地。", "primary_collocate": null, "pronunciation": "huā yuán", "ipa": "xua˥ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "当城市道路资源从私人汽车的过度占用中被释放，其空间再分配可催生大规模绿色基础设施建设：原本用于停车的空间转化为线性公园、雨水花园与生物廊道，不仅增强城市碳汇能力，更缓解热岛效应并提升生物多样性。", "target_word": "花园", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "我家后面有一个很大的花园。", "target_word": "花园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花园里开着红色和黄色的花。", "target_word": "花园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我们常常带孩子去花园玩。", "target_word": "花园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶每天早上在花园里浇花。", "target_word": "花园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座花园里有很多老树和小路。", "target_word": "花园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园旁边新建了一座漂亮的花园。", "target_word": "花园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "傍晚，大家坐在花园的长椅上聊天。", "target_word": "花园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花园的门口站着一位老人。", "target_word": "花园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个花园春天最美，很多人来拍照。", "target_word": "花园", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "后花园", "label": "复合"}, {"form": "花園", "label": "繁体"}], "register": "中性", "sense_fingerprint": "花园·名词·供人观赏游玩的园地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52c220fe-4ca5-4e18-bbc7-fbfacac2c9f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11818, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "花园", "is_correct": true, "explanation": "正确：「雨水花园」是一种绿化设施，与「线性公园」「生物廊道」同属绿色基础设施。"}, {"text": "停车场", "is_correct": false, "explanation": "搭配：「雨水」后面接的应是绿地或雨水设施，「雨水停车场」不成词。"}, {"text": "工厂", "is_correct": false, "explanation": "语义：句子讲的是绿色基础设施，工厂不属于绿化空间。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流不是人工建造的园地，句子需要的是可以种植和观赏的绿地。"}], "explanations": {"花园": "正确：「雨水花园」是一种绿化设施，与「线性公园」「生物廊道」同属绿色基础设施。", "停车场": "搭配：「雨水」后面接的应是绿地或雨水设施，「雨水停车场」不成词。", "工厂": "语义：句子讲的是绿色基础设施，工厂不属于绿化空间。", "河流": "语义：河流不是人工建造的园地，句子需要的是可以种植和观赏的绿地。"}, "sentence_index": 0, "correct_answer": "花园"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人在花园里生产了很多汽车。", "explanation": "这里应该用〈工厂〉。花园是种植花草树木、供人观赏游玩的园地，不是生产汽车的地方，应说〈工厂〉。"}, {"text": "我们小区新建了一只花园。", "explanation": "这里应该用〈座〉或〈个〉。「只」用于动物或成对的器官，不用于花园这类场所。"}, {"text": "我们家阳台上种了一条花园。", "explanation": "这里应该用〈个〉或〈座〉。「条」用于长条形事物，不用于花园这类场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6651a80d-9ff8-4af5-98fb-ee2d392b3a9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11818, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "花园", "is_correct": true, "explanation": "正确：指供人观赏游玩的园地，与「新建」「漂亮」搭配，符合语境。"}, {"text": "词典", "is_correct": false, "explanation": "语义：词典不是可以「新建」的园地，句子讲的是绿地。"}, {"text": "蔬菜", "is_correct": false, "explanation": "搭配：量词「座」不能用于蔬菜，「一座漂亮的蔬菜」不成立。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲不能被「新建」为园地，句子讲的是城市绿化建设。"}], "explanations": {"花园": "正确：指供人观赏游玩的园地，与「新建」「漂亮」搭配，符合语境。", "词典": "语义：词典不是可以「新建」的园地，句子讲的是绿地。", "蔬菜": "搭配：量词「座」不能用于蔬菜，「一座漂亮的蔬菜」不成立。", "歌曲": "语义：歌曲不能被「新建」为园地，句子讲的是城市绿化建设。"}, "sentence_index": 6, "correct_answer": "花园"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家门口有一棵花园。", "explanation": "这里应该用〈座〉或〈个〉。「棵」用于树木，不用于花园这类场所。"}, {"text": "这个花园里养着很多老虎。", "explanation": "这里应该用〈动物园〉。花园是供人观赏游玩的种植园地，不养老虎，养野生动物要用〈动物园〉。"}, {"text": "我们买了一台花园。", "explanation": "这里应该用〈座〉或〈个〉。「台」用于机器、设备，不用于花园这类场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6651a80d-9ff8-4af5-98fb-ee2d392b3a9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11818, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "社区里有一座大很的花园。", "corrected_sentence": "社区里有一座很大的花园。", "error_description": "语序错误：程度副词「很」须放在形容词之前，应说「很大」，不能说「大很」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6651a80d-9ff8-4af5-98fb-ee2d392b3a9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11818, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "下午，孩子们在一条花园里放风筝。", "corrected_sentence": "下午，孩子们在一座花园里放风筝。", "error_description": "量词错误：「条」用于长条形事物，不能修饰花园；花园应用「座」或「个」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6651a80d-9ff8-4af5-98fb-ee2d392b3a9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
