INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11820, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d3d6948-7184-40c2-8d04-dba1fc89ab25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11820, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "廊道指有顶棚的通道，如建筑物内的走廊或园林中的长廊。", "primary_collocate": null, "pronunciation": "láng dào", "ipa": "lɑŋ˧˥ tɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "老城区改造中，原本用于停车的空间被改建为带顶棚的步行廊道，两侧栽满绿植，既能遮风挡雨，又把沿街的商铺与附近的公园串联起来，显著提升了居民的步行体验与公共空间品质。", "target_word": "廊道", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "在大型公园的规划中，设计者沿湖岸修建了一段带顶棚的廊道，既为游客遮挡夏日强光，也让人们在雨天依然能从容欣赏湖景。", "target_word": "廊道", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "公园里有一条廊道，下雨时我们可以在里面散步。", "target_word": "廊道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座老房子有一条木头廊道，夏天很凉快。", "target_word": "廊道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酒店的廊道很安静，墙上挂着很多画。", "target_word": "廊道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，大家站在廊道里等雨停。", "target_word": "廊道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们在教学楼的廊道里跑来跑去。", "target_word": "廊道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "沿着廊道往前走，就能看到湖边的小亭子。", "target_word": "廊道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条廊道连接着两栋楼，走路五分钟就到。", "target_word": "廊道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "园林里的廊道两边有花，走在里面很舒服。", "target_word": "廊道", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}], "register": "中性", "sense_fingerprint": "有顶棚的通道（走廊、长廊）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52a47307-49a6-4e93-9fed-15de8bc7b402') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11820, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "车道", "is_correct": false, "explanation": "语义：「车道」是供车辆行驶的路面，与「带顶棚的步行」空间相矛盾，不能填入。"}, {"text": "高速公路", "is_correct": false, "explanation": "语义：「高速公路」供汽车高速通行，既不步行也不带顶棚，与句中的步行空间不合。"}, {"text": "廊道", "is_correct": true, "explanation": "正确：「廊道」指有顶棚的通道，与句中「带顶棚的步行」空间相合。"}, {"text": "停车场", "is_correct": false, "explanation": "语义：「停车场」供车辆停放，与「步行」空间矛盾；且前文已提到「停车」，重复。"}], "explanations": {"车道": "语义：「车道」是供车辆行驶的路面，与「带顶棚的步行」空间相矛盾，不能填入。", "高速公路": "语义：「高速公路」供汽车高速通行，既不步行也不带顶棚，与句中的步行空间不合。", "廊道": "正确：「廊道」指有顶棚的通道，与句中「带顶棚的步行」空间相合。", "停车场": "语义：「停车场」供车辆停放，与「步行」空间矛盾；且前文已提到「停车」，重复。"}, "sentence_index": 0, "correct_answer": "廊道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "火车穿过了一条长长的廊道。", "explanation": "这里应该用〈隧道〉。隧道是穿越山体或地下的通道，廊道指房屋内外有顶棚的通道，不用于山体中的通道。"}, {"text": "这条山间廊道又陡又窄，很难走。", "explanation": "这里应该用〈小路〉。廊道指有顶棚的通道，山间小路露天，不能称廊道。"}, {"text": "我把书放进廊道里，然后锁上了。", "explanation": "这里应该用〈抽屉〉。抽屉是家具里放东西、能上锁的部分；廊道是供人行走的有顶通道，不能放进东西再锁上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d3d6948-7184-40c2-8d04-dba1fc89ab25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11820, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "课本", "is_correct": false, "explanation": "语义：课本是书籍，不是可以让孩子们奔跑的空间，与“跑来跑去”不合。"}, {"text": "黑板", "is_correct": false, "explanation": "搭配：“在……里跑来跑去”要求可容人移动的空间，“黑板”是平面，不能这样搭配。"}, {"text": "廊道", "is_correct": true, "explanation": "“廊道”指教学楼内有顶棚的通道，孩子们可以在里面跑动，符合句意。"}, {"text": "课桌", "is_correct": false, "explanation": "语义：课桌是放置物品的家具，不能作为人跑动的处所。"}], "explanations": {"课本": "语义：课本是书籍，不是可以让孩子们奔跑的空间，与“跑来跑去”不合。", "黑板": "搭配：“在……里跑来跑去”要求可容人移动的空间，“黑板”是平面，不能这样搭配。", "廊道": "“廊道”指教学楼内有顶棚的通道，孩子们可以在里面跑动，符合句意。", "课桌": "语义：课桌是放置物品的家具，不能作为人跑动的处所。"}, "sentence_index": 6, "correct_answer": "廊道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "汽车沿着廊道一直开就到了。", "explanation": "这里应该用〈车道〉。廊道是供人行走的有顶通道，车辆不能行驶其中，车道才是车辆通行的路面。"}, {"text": "我们沿着廊道一直爬到了顶层。", "explanation": "这里应该用〈楼梯〉。廊道是水平的有顶通道，不能用于向上攀登楼层。"}, {"text": "妈妈把剩菜放进廊道里，免得坏了。", "explanation": "这里应该用〈冰箱〉。冰箱用来冷藏食物；廊道是供人行走的有顶通道，不能保鲜食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d3d6948-7184-40c2-8d04-dba1fc89ab25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11820, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "园子东边有一只廊道，雨天也能安心散步。", "corrected_sentence": "园子东边有一条廊道，雨天也能安心散步。", "error_description": "量词错误：“廊道”是线状通道，量词用“条”，“只”用于动物或成对器物，不能修饰廊道。正确说法是“一条廊道”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d3d6948-7184-40c2-8d04-dba1fc89ab25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11820, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "湖边那条长长地廊道，夏天走在里面很凉快。", "corrected_sentence": "湖边那条长长的廊道，夏天走在里面很凉快。", "error_description": "结构助词错误：修饰名词“廊道”的形容词短语后应用“的”，“地”用于修饰动词，不能接在名词前。正确说法是“长长的廊道”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d3d6948-7184-40c2-8d04-dba1fc89ab25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
