INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11823, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指城市因建筑密集、人口集中、人为热源多等因素，导致气温明显高于周围郊区的现象。", "primary_collocate": null, "pronunciation": "rè dǎo", "ipa": "ʐɤ⁵¹ tɑʊ̯²¹⁴", "syllable_count": 2, "sentences": [{"text": "城市建筑越密集，热岛就越容易让夜间的气温居高不下。", "target_word": "热岛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府通过容积率奖励、税收减免等政策工具，引导私人投资流向具备生态服务功能的建设项目，从而降低公共财政在污水处理、热岛缓解与空气治理方面的长期支出。", "target_word": "热岛", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "大城市的热岛尤为明显。", "target_word": "热岛", "complexity_tier": "T3", "furigana": "dà chéngshì de rè dǎo yóuwéi míngxiǎn", "sentence_source": "generated"}, {"text": "城市热岛让夜里也很热。", "target_word": "热岛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "树多的地方，热岛没有那么严重。", "target_word": "热岛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家说，热岛会让城市用电更多。", "target_word": "热岛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多种树可以减轻热岛。", "target_word": "热岛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为什么大城市会出现热岛呢？", "target_word": "热岛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屋顶种草能缓解热岛。", "target_word": "热岛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市越大，热岛就越明显。", "target_word": "热岛", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "热岛效应", "label": "复合"}, {"form": "城市热岛", "label": "复合"}], "register": "书面", "sense_fingerprint": "城市气温高于郊区的现象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f51b7060-190e-43be-9474-2cfe868f2248') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11823, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "热岛", "is_correct": true, "explanation": "正确。“热岛”指城市气温高于郊区的现象，会使夜间气温居高不下。"}, {"text": "噪声", "is_correct": false, "explanation": "语义：噪声是声音污染，与气温无关，不能让夜间气温居高不下。"}, {"text": "酸雨", "is_correct": false, "explanation": "语义：酸雨是降水污染，不是气温现象，不能让夜间气温居高不下。"}, {"text": "海啸", "is_correct": false, "explanation": "语义：海啸是海浪灾害，与城市夜间气温无关，句意不通。"}], "explanations": {"热岛": "正确。“热岛”指城市气温高于郊区的现象，会使夜间气温居高不下。", "噪声": "语义：噪声是声音污染，与气温无关，不能让夜间气温居高不下。", "酸雨": "语义：酸雨是降水污染，不是气温现象，不能让夜间气温居高不下。", "海啸": "语义：海啸是海浪灾害，与城市夜间气温无关，句意不通。"}, "sentence_index": 0, "correct_answer": "热岛"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场演唱会的热岛让大家都很兴奋。", "explanation": "这里应该用〈热潮〉。热岛指城市气温高于郊区的现象，不能比喻热闹的场面，应说热潮。"}, {"text": "这座热岛上有很多椰子树。", "explanation": "此处把“热岛”误解为岛屿。热岛指城市气温高于郊区的现象，不指岛屿。"}, {"text": "他是个热岛，对谁都很热情。", "explanation": "这里把热岛当成了形容人性格的〈热心〉。热岛指城市气温现象，不能用来指人或形容性格，应说“他很热心”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb8b5ac8-0f38-4132-9264-c2063c12f1d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11823, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "热岛", "is_correct": true, "explanation": "热岛：城市气温高于郊区的现象，是“减轻”的对象。"}, {"text": "气温", "is_correct": false, "explanation": "搭配：“减轻”多用于负担、痛苦，说气温应用“降低”。"}, {"text": "时间", "is_correct": false, "explanation": "语义：时间不是需要减轻的负担，“减轻时间”没有意义。"}, {"text": "工资", "is_correct": false, "explanation": "语义：工资不是需要减轻的负担，“减轻工资”不合理。"}], "explanations": {"热岛": "热岛：城市气温高于郊区的现象，是“减轻”的对象。", "气温": "搭配：“减轻”多用于负担、痛苦，说气温应用“降低”。", "时间": "语义：时间不是需要减轻的负担，“减轻时间”没有意义。", "工资": "语义：工资不是需要减轻的负担，“减轻工资”不合理。"}, "sentence_index": 6, "correct_answer": "热岛"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把热岛放进包里带走了。", "explanation": "这里把热岛当成了〈物品〉，一件可以装进包里的东西。热岛指城市气温现象，不能被放进包里带走。"}, {"text": "烈日当空的时候，热岛也当空。", "explanation": "这里把热岛当成了〈太阳〉，一个高悬天空的天体。热岛指城市气温现象，不能像太阳一样悬在空中。"}, {"text": "冬天我们家的热岛很好用。", "explanation": "这里应该用〈暖气〉。热岛指城市比郊区更热的现象，不是取暖设备；这句说的是取暖设备，应用“暖气”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb8b5ac8-0f38-4132-9264-c2063c12f1d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11823, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个城市形成了一只热岛。", "corrected_sentence": "这个城市形成了一个热岛。", "error_description": "量词错误：“热岛”前应用“个”，不能用“只”（“只”多用于动物等）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb8b5ac8-0f38-4132-9264-c2063c12f1d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11823, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "许多大城市都出现了热岛们。", "corrected_sentence": "许多大城市都出现了热岛。", "error_description": "词缀错误：“们”只加在指人的名词后，“热岛”是现象名词，不能加“们”表示复数。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb8b5ac8-0f38-4132-9264-c2063c12f1d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11824, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "手动", "is_correct": true, "explanation": "正确。手动指靠人力操作，与电动靠电力驱动正好相对。"}, {"text": "陈旧", "is_correct": false, "explanation": "陈旧指东西老旧，与动力来源无关，不是电动的反义词。"}, {"text": "简陋", "is_correct": false, "explanation": "简陋指设备粗糙、简单，与动力来源无关，不构成相对关系。"}, {"text": "稳定", "is_correct": false, "explanation": "稳定指状态平稳不变，与电动的动力来源不构成相对关系。"}], "correct_answer": "手动", "explanations": {"手动": "正确。手动指靠人力操作，与电动靠电力驱动正好相对。", "陈旧": "陈旧指东西老旧，与动力来源无关，不是电动的反义词。", "简陋": "简陋指设备粗糙、简单，与动力来源无关，不构成相对关系。", "稳定": "稳定指状态平稳不变，与电动的动力来源不构成相对关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0916f1a2-4269-47b8-aa72-5fc4a9a9257b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11824, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "手动", "is_correct": true, "explanation": "正确。手动指靠人力操作，与电动靠电力驱动正好相对。"}, {"text": "粗糙", "is_correct": false, "explanation": "粗糙指表面不光滑，与动力来源无关，不构成相对关系。"}, {"text": "狭窄", "is_correct": false, "explanation": "狭窄指空间小，与动力来源无关，不构成相对关系。"}, {"text": "柔软", "is_correct": false, "explanation": "柔软指质地软，与动力来源无关，不构成相对关系。"}], "correct_answer": "手动", "explanations": {"手动": "正确。手动指靠人力操作，与电动靠电力驱动正好相对。", "粗糙": "粗糙指表面不光滑，与动力来源无关，不构成相对关系。", "狭窄": "狭窄指空间小，与动力来源无关，不构成相对关系。", "柔软": "柔软指质地软，与动力来源无关，不构成相对关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0916f1a2-4269-47b8-aa72-5fc4a9a9257b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11824, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "电动指以电力作为动力来源的，比如电动车、电动玩具。", "primary_collocate": null, "pronunciation": "diàn dòng", "ipa": "tjɛn˥˩ tʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "此外，把公交车队改为电动的，并接入可再生能源供电系统，正在推动交通运输部门实现深度脱碳。", "target_word": "电动", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "这辆车是电动的，不用加油。", "target_word": "电动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他骑的那辆自行车是电动的，上坡很省力。", "target_word": "电动", "complexity_tier": "T3", "furigana": "tā qí de nà liàng zì xíng chē shì diàn dòng de, shàng pō hěn shěng lì", "sentence_source": "generated"}, {"text": "这个小区里的快递车，有不少是电动的。", "target_word": "电动", "complexity_tier": "T3", "furigana": "zhè ge xiǎo qū lǐ de kuài dì chē, yǒu bù shǎo shì diàn dòng de", "sentence_source": "generated"}, {"text": "这把牙刷是电动的，刷得很干净。", "target_word": "电动", "complexity_tier": "T3", "furigana": "zhè bǎ yá shuā shì diàn dòng de, shuā de hěn gān jìng", "sentence_source": "generated"}, {"text": "他开的车是电动的，平时只需要在家充电。", "target_word": "电动", "complexity_tier": "T3", "furigana": "tā kāi de chē shì diàn dòng de, píng shí zhǐ xū yào zài jiā chōng diàn", "sentence_source": "generated"}, {"text": "这座城市的出租车很多都是电动的。", "target_word": "电动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的小熊是电动的，会自己唱歌。", "target_word": "电动", "complexity_tier": "T3", "furigana": "hái zi de xiǎo xióng shì diàn dòng de, huì zì jǐ chàng gē", "sentence_source": "generated"}, {"text": "我想买一辆电动的小汽车，因为它很安静。", "target_word": "电动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们公司把旧车都换成了电动的。", "target_word": "电动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "電動", "label": "繁体"}, {"form": "电动车", "label": "复合"}, {"form": "电动化", "label": "复合"}], "register": "中性", "sense_fingerprint": "以电力为动力来源的（电动车、电动玩具）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '869a6818-447d-4435-b360-0323be8c2be3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11824, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "电动", "is_correct": true, "explanation": "正确。电动指以电力作为动力来源。"}, {"text": "店东", "is_correct": false, "explanation": "dōng（第一声）与 dòng（第四声）声调不同，店东指店铺的主人。"}, {"text": "调动", "is_correct": false, "explanation": "diào（第四声）与 diàn 韵母不同（ao 与 an），调动指调配或改变位置。"}, {"text": "变动", "is_correct": false, "explanation": "biàn（第四声）与 diàn 声母不同（b 与 d），变动指改变、变化。"}], "explanations": {"电动": "正确。电动指以电力作为动力来源。", "店东": "dōng（第一声）与 dòng（第四声）声调不同，店东指店铺的主人。", "调动": "diào（第四声）与 diàn 韵母不同（ao 与 an），调动指调配或改变位置。", "变动": "biàn（第四声）与 diàn 声母不同（b 与 d），变动指改变、变化。"}, "sentence_index": null, "correct_answer": "电动"}, "level_3": {"options": [{"text": "电动", "is_correct": true, "explanation": "正确。“改为电动的”指改用电力驱动，符合语境。"}, {"text": "手动", "is_correct": false, "explanation": "语义：手动靠人力操作，与公交车改用电力驱动的方向相反。"}, {"text": "人工", "is_correct": false, "explanation": "语义：人工指靠人力完成，不能表示公交车的动力转型。"}, {"text": "燃油", "is_correct": false, "explanation": "语义：燃油动力与公交车改用电力、深度脱碳的方向相反，句意不通。"}], "explanations": {"电动": "正确。“改为电动的”指改用电力驱动，符合语境。", "手动": "语义：手动靠人力操作，与公交车改用电力驱动的方向相反。", "人工": "语义：人工指靠人力完成，不能表示公交车的动力转型。", "燃油": "语义：燃油动力与公交车改用电力、深度脱碳的方向相反，句意不通。"}, "sentence_index": 0, "correct_answer": "电动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这篇文章是电动的，读起来很有趣。", "explanation": "这里应该用〈生动〉。电动只指靠电力驱动的物体，不能用来形容文章。"}, {"text": "这位老人是电动的，走路很快。", "explanation": "这里应该用〈矫健〉。电动只说靠电力驱动的物体，不能说人是电动的。"}, {"text": "这块蛋糕是电动的，吃起来很软。", "explanation": "这里应该用〈香甜〉。电动只用于靠电力驱动的物体，蛋糕不能说电动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0916f1a2-4269-47b8-aa72-5fc4a9a9257b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11824, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "电动", "is_correct": true, "explanation": "正确。电动指以电力作为动力来源。"}, {"text": "颠动", "is_correct": false, "explanation": "diān（第一声）与 diàn（第四声）声调不同，颠动指上下或前后晃动。"}, {"text": "点动", "is_correct": false, "explanation": "diǎn（第三声）与 diàn（第四声）声调不同，点动指机器短时间启动后即停。"}, {"text": "滇东", "is_correct": false, "explanation": "diān dōng（第一声、第一声）与 diàn dòng（第四声、第四声）声调不同，滇东指云南东部。"}], "explanations": {"电动": "正确。电动指以电力作为动力来源。", "颠动": "diān（第一声）与 diàn（第四声）声调不同，颠动指上下或前后晃动。", "点动": "diǎn（第三声）与 diàn（第四声）声调不同，点动指机器短时间启动后即停。", "滇东": "diān dōng（第一声、第一声）与 diàn dòng（第四声、第四声）声调不同，滇东指云南东部。"}, "sentence_index": null, "correct_answer": "电动"}, "level_3": {"options": [{"text": "电动", "is_correct": true, "explanation": "正确。电动的出租车靠电力驱动，符合语境。"}, {"text": "木制", "is_correct": false, "explanation": "语义：出租车是机动车，不会大多是木制的。"}, {"text": "石质", "is_correct": false, "explanation": "语义：石质的车无法行驶，与出租车的常识不符。"}, {"text": "纸糊", "is_correct": false, "explanation": "语义：出租车是机动车，不会是纸糊的，句意不通。"}], "explanations": {"电动": "正确。电动的出租车靠电力驱动，符合语境。", "木制": "语义：出租车是机动车，不会大多是木制的。", "石质": "语义：石质的车无法行驶，与出租车的常识不符。", "纸糊": "语义：出租车是机动车，不会是纸糊的，句意不通。"}, "sentence_index": 6, "correct_answer": "电动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "院子里的那棵大树是电动的，每年长得很快。", "explanation": "这里应该用〈茂盛〉。电动只用于靠电力驱动的物体，树是植物，不能说电动。"}, {"text": "这堂课是电动的，学生都很喜欢上。", "explanation": "这里应该用〈有趣〉。电动说的是动力来源，不能形容课堂的趣味。"}, {"text": "这盆花的颜色是电动的，看起来很亮。", "explanation": "这里应该用〈鲜艳〉。电动只说靠电力驱动的东西，不能形容颜色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0916f1a2-4269-47b8-aa72-5fc4a9a9257b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11824, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这张躺椅可以电动动调节角度，躺着很舒服。", "corrected_sentence": "这张躺椅可以电动调节角度，躺着很舒服。", "error_description": "词内重复：“电动”是固定词语，末尾的“动”不能重复，应说“可以电动调节角度”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0916f1a2-4269-47b8-aa72-5fc4a9a9257b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11824, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台洗衣机是电动的的，每次洗得很干净。", "corrected_sentence": "这台洗衣机是电动的，每次洗得很干净。", "error_description": "助词重复：“的”不能连用两次，应为“这台洗衣机是电动的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0916f1a2-4269-47b8-aa72-5fc4a9a9257b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
