INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11825, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指自然界中能够不断再生、取之不尽用之不竭的能源，如太阳能、风能、水能等。", "primary_collocate": null, "pronunciation": "zài shēng néng yuán", "ipa": "tsaɪ˥˩ ʂɤŋ˥ nɤŋ˧˥ ɥɛn˧˥", "syllable_count": 4, "sentences": [{"text": "此外，电动公交车队的普及与再生能源供电系统的整合，正在推动交通运输部门实现深度脱碳。", "target_word": "再生能源", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "早期文明对再生能源的利用，体现为对自然力的直接转化。", "target_word": "再生能源", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "工业革命后，化石能源的大规模使用掩盖了再生能源的发展轨迹。", "target_word": "再生能源", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "太阳能和风能都是再生能源。", "target_word": "再生能源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个国家正在大力发展再生能源。", "target_word": "再生能源", "complexity_tier": "T3", "furigana": "zhè ge guó jiā zhèng zài dà lì fā zhǎn zài shēng néng yuán", "sentence_source": "generated"}, {"text": "利用再生能源发电，可以减少空气污染。", "target_word": "再生能源", "complexity_tier": "T3", "furigana": "lì yòng zài shēng néng yuán fā diàn, kě yǐ jiǎn shǎo kōng qì wū rǎn", "sentence_source": "generated"}, {"text": "水能是一种再生能源，用不完。", "target_word": "再生能源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们学校的屋顶装了太阳能板，用的是再生能源。", "target_word": "再生能源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "和石油不同，再生能源不会越用越少。", "target_word": "再生能源", "complexity_tier": "T3", "furigana": "hé shí yóu bù tóng, zài shēng néng yuán bú huì yuè yòng yuè shǎo", "sentence_source": "generated"}, {"text": "今年这个城市有三成的电来自再生能源。", "target_word": "再生能源", "complexity_tier": "T3", "furigana": "jīn nián zhè ge chéng shì yǒu sān chéng de diàn lái zì zài shēng néng yuán", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "可再生能源", "label": "复合"}], "register": "书面", "sense_fingerprint": "能不断再生的自然能源（太阳能、风能）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52a47307-49a6-4e93-9fed-15de8bc7b402') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11825, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "再生能源", "is_correct": true, "explanation": "正确：“再生能源”指能不断再生的能源，与“供电系统”搭配，符合句中“电动公交车队”与“深度脱碳”的语境。"}, {"text": "化石能源", "is_correct": false, "explanation": "语义：化石能源来自煤、石油等化石燃料，燃烧会排放大量碳，与“深度脱碳”的语境相反。"}, {"text": "天然气", "is_correct": false, "explanation": "语义：天然气属于化石能源，燃烧仍会排放二氧化碳，与“深度脱碳”的目标冲突。"}, {"text": "煤炭", "is_correct": false, "explanation": "语义：煤炭是高碳化石燃料，燃烧排放大量二氧化碳，与“深度脱碳”的语境相反。"}], "explanations": {"再生能源": "正确：“再生能源”指能不断再生的能源，与“供电系统”搭配，符合句中“电动公交车队”与“深度脱碳”的语境。", "化石能源": "语义：化石能源来自煤、石油等化石燃料，燃烧会排放大量碳，与“深度脱碳”的语境相反。", "天然气": "语义：天然气属于化石能源，燃烧仍会排放二氧化碳，与“深度脱碳”的目标冲突。", "煤炭": "语义：煤炭是高碳化石燃料，燃烧排放大量二氧化碳，与“深度脱碳”的语境相反。"}, "sentence_index": 0, "correct_answer": "再生能源"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "石油属于再生能源。", "explanation": "这里应该用〈化石能源〉。石油会用完，不能不断再生，不属于“再生能源”的义项。"}, {"text": "这些废品都是可以回收利用的再生能源。", "explanation": "这里应该用〈再生资源〉。废品是可回收利用的物资，不是能源；“再生能源”专指能不断再生的能源，不能用来指废品。"}, {"text": "我的爸爸是再生能源。", "explanation": "这里“再生能源”取能源类别的义项（如太阳能、风能），表示一类能源，不能用来指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d3d6948-7184-40c2-8d04-dba1fc89ab25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11825, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "再生能源", "is_correct": true, "explanation": "正确：“一种再生能源”指能不断再生的能源，与“用不完”的语境一致。"}, {"text": "煤炭", "is_correct": false, "explanation": "语义：煤炭是会越用越少的化石燃料，与“用不完”的语境相反。"}, {"text": "石油", "is_correct": false, "explanation": "语义：石油也是有限的化石能源，会用完，与“用不完”矛盾。"}, {"text": "电池", "is_correct": false, "explanation": "搭配：水能是能源的来源，“一种电池”不能归入能源的类别，电池只是储能装置。"}], "explanations": {"再生能源": "正确：“一种再生能源”指能不断再生的能源，与“用不完”的语境一致。", "煤炭": "语义：煤炭是会越用越少的化石燃料，与“用不完”的语境相反。", "石油": "语义：石油也是有限的化石能源，会用完，与“用不完”矛盾。", "电池": "搭配：水能是能源的来源，“一种电池”不能归入能源的类别，电池只是储能装置。"}, "sentence_index": 6, "correct_answer": "再生能源"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆跑车的再生能源很强。", "explanation": "这里应该用〈动力〉。动力指推动车辆的力量，可以说“很强”；“再生能源”是能源的类别，不能说“很强”。"}, {"text": "运动以后，身体需要补充再生能源。", "explanation": "这里应该用〈能量〉。身体补充的是热量等能量，不是能源的种类，不能说补充“再生能源”。"}, {"text": "我把再生能源放进了冰箱里。", "explanation": "这里应该用〈剩菜〉。“再生能源”是太阳能、风能这类能源，不是能放进冰箱的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d3d6948-7184-40c2-8d04-dba1fc89ab25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11825, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "潮汐能是一座再生能源，可以一直用。", "corrected_sentence": "潮汐能是一种再生能源，可以一直用。", "error_description": "量词错误：“再生能源”是能源，应用量词“种”；“座”用于建筑、山等大型物体，不能用于能源。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d3d6948-7184-40c2-8d04-dba1fc89ab25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11825, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "市政府决定优先发生再生能源。", "corrected_sentence": "市政府决定优先发展再生能源。", "error_description": "搭配错误：“再生能源”是能源，不能与“发生”搭配；“发生”指事情出现，应用动词“发展”，说“优先发展再生能源”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d3d6948-7184-40c2-8d04-dba1fc89ab25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
