INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11826, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "供电系统是指发电、输电、配电等环节组成的，为用户提供电力的整体网络。", "primary_collocate": null, "pronunciation": "gōng diàn xì tǒng", "ipa": "kʊŋ˥ tjɛn˥˩ ɕi˥˩ tʰʊŋ˨˩˦", "syllable_count": 4, "sentences": [{"text": "此外，电动化公交车队的普及与可再生能源供电系统的整合，正在推动交通运输部门实现深度脱碳。", "target_word": "供电系统", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "这个城市的供电系统很稳定。", "target_word": "供电系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "供电系统包括发电、输电和配电。", "target_word": "供电系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们正在检查村里的供电系统。", "target_word": "供电系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下大雨以后，供电系统出了问题。", "target_word": "供电系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新的供电系统让全城的用户都用上了电。", "target_word": "供电系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院有一套备用的供电系统。", "target_word": "供电系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小区的供电系统去年重新修过。", "target_word": "供电系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府决定改造老旧的供电系统。", "target_word": "供电系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "供电系统由电厂、电线和变电站组成。", "target_word": "供电系统", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "供電系統", "label": "繁体"}], "register": "书面", "sense_fingerprint": "由发电、输电、配电组成、向用户送电的整体网络", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '869a6818-447d-4435-b360-0323be8c2be3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11826, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "供电系统", "is_correct": true, "explanation": "正确：供电系统指输配电的整体网络，能与“可再生能源”搭配，也能被“整合”。"}, {"text": "饮用水系统", "is_correct": false, "explanation": "语义：可再生能源指风能、太阳能等能源，饮用水系统不是能源设施，句中的“整合”对象应是能源网络。"}, {"text": "公共厕所", "is_correct": false, "explanation": "语义：厕所与能源供应和交通脱碳无关，不能成为“整合”的对象。"}, {"text": "烘焙作坊", "is_correct": false, "explanation": "搭配：“可再生能源”修饰的应是能源设施，“烘焙作坊”是食品加工场所，两者不搭配。"}], "explanations": {"供电系统": "正确：供电系统指输配电的整体网络，能与“可再生能源”搭配，也能被“整合”。", "饮用水系统": "语义：可再生能源指风能、太阳能等能源，饮用水系统不是能源设施，句中的“整合”对象应是能源网络。", "公共厕所": "语义：厕所与能源供应和交通脱碳无关，不能成为“整合”的对象。", "烘焙作坊": "搭配：“可再生能源”修饰的应是能源设施，“烘焙作坊”是食品加工场所，两者不搭配。"}, "sentence_index": 0, "correct_answer": "供电系统"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这套供电系统里流的是干净的饮用水。", "explanation": "这里应该用〈自来水管道〉。输送饮用水的是自来水管道，供电系统输送的是电力，不输送水。"}, {"text": "晚上的供电系统很亮，屋里像白天一样。", "explanation": "这里应该用〈灯〉。“亮”是发光物的特征，供电系统只输送电力，本身不发光。"}, {"text": "院子里的供电系统漏了水，流得到处都是。", "explanation": "这里应该用〈水管〉。“漏水”是水管的状态，供电系统输送的是电力，不会漏水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0916f1a2-4269-47b8-aa72-5fc4a9a9257b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11826, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "供电系统", "is_correct": true, "explanation": "正确：「备用的供电系统」指医院在停电时使用的供电设施，符合语境。"}, {"text": "交响乐团", "is_correct": false, "explanation": "语义：医院的备用项目应是设施，交响乐团是表演团体，不能作为备用设施。"}, {"text": "游泳池", "is_correct": false, "explanation": "语义：句中语境要求备用的是供电设施，医院里的游泳池与停电时的用电无关。"}, {"text": "围墙", "is_correct": false, "explanation": "搭配：“一套”用于成套的设备，围墙应说“一道”，“一套围墙”搭配不当。"}], "explanations": {"供电系统": "正确：「备用的供电系统」指医院在停电时使用的供电设施，符合语境。", "交响乐团": "语义：医院的备用项目应是设施，交响乐团是表演团体，不能作为备用设施。", "游泳池": "语义：句中语境要求备用的是供电设施，医院里的游泳池与停电时的用电无关。", "围墙": "搭配：“一套”用于成套的设备，围墙应说“一道”，“一套围墙”搭配不当。"}, "sentence_index": 6, "correct_answer": "供电系统"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "厨房的供电系统一拧就出水。", "explanation": "这里应该用〈水龙头〉。拧开就出水是水龙头的功能，供电系统不能拧，也不出水。"}, {"text": "冬天家里的供电系统很暖和。", "explanation": "这里应该用〈暖气〉。“暖和”是取暖设备的特征，供电系统不发热。"}, {"text": "墙上的供电系统可以插两个插头。", "explanation": "这里应该用〈插座〉。插头插进去的是插座，供电系统是输送电力的网络，不能被插。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0916f1a2-4269-47b8-aa72-5fc4a9a9257b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11826, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "电工已经把供电系统修到了。", "corrected_sentence": "电工已经把供电系统修好了。", "error_description": "补语错误：把设备修到能用，应说“修好”，不能说“修到”，“修到”表示的意思与句子不符。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0916f1a2-4269-47b8-aa72-5fc4a9a9257b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11826, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人们把一根供电系统装好了。", "corrected_sentence": "工人们把一套供电系统装好了。", "error_description": "量词错误：“供电系统”是成套设备，应说“一套”，不能说“一根”，“根”用于细长的物件。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0916f1a2-4269-47b8-aa72-5fc4a9a9257b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
