INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11827, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "部门是指机关、企业、团体中按职能划分的各个单位。", "primary_collocate": null, "pronunciation": "bù mén", "ipa": "pu˥˩ mən˧˥", "syllable_count": 2, "sentences": [{"text": "我在公司的财务部门工作。", "target_word": "部门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个部门一共有十五个人。", "target_word": "部门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想申请去销售部门。", "target_word": "部门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各部门的经理今天下午要开会。", "target_word": "部门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府部门明年会有新的规定。", "target_word": "部门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人事部门正在招聘新同事。", "target_word": "部门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事要先问问相关部门。", "target_word": "部门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在教育部门做了十年管理工作。", "target_word": "部门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们部门的同事都很友好。", "target_word": "部门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院的每个部门都要遵守这个规则。", "target_word": "部门", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "部門", "label": "繁体"}, {"form": "部门经理", "label": "复合"}], "register": "中性", "sense_fingerprint": "机关、企业、团体中按职能划分的单位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '869a6818-447d-4435-b360-0323be8c2be3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11827, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "部门", "is_correct": true, "explanation": "正确：“财务部门”指公司中负责财务职能的单位，符合“在……工作”的语境。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房不是按职能划分的单位，“财务厨房”与句意不符。"}, {"text": "操场", "is_correct": false, "explanation": "语义：操场是运动场所，不是财务工作的单位。"}, {"text": "工地", "is_correct": false, "explanation": "搭配：“财务”后面接的应是机构单位，“工地”是施工场所，两者不搭配。"}], "explanations": {"部门": "正确：“财务部门”指公司中负责财务职能的单位，符合“在……工作”的语境。", "厨房": "语义：厨房不是按职能划分的单位，“财务厨房”与句意不符。", "操场": "语义：操场是运动场所，不是财务工作的单位。", "工地": "搭配：“财务”后面接的应是机构单位，“工地”是施工场所，两者不搭配。"}, "sentence_index": 0, "correct_answer": "部门"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本书的每一部门都很有意思。", "explanation": "这里应该用〈部分〉。部分指整体中的一块，书的组成部分要用“部分”，部门指机构单位，不能用于书。"}, {"text": "这台机器的每个部门都要定期检查。", "explanation": "这里应该用〈部件〉。机器的零件要用“部件”，部门指机构单位，不能指机器的零件。"}, {"text": "“河”这个字的部门是“氵”。", "explanation": "这里应该用〈部首〉。汉字的偏旁归类要用“部首”，部门指机构中的单位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0916f1a2-4269-47b8-aa72-5fc4a9a9257b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11827, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "部门", "is_correct": true, "explanation": "正确：“相关部门”指与此事有关的机构单位，符合“问问”的语境。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园不是按职能划分的单位，与“相关”的含义不符。"}, {"text": "篮球", "is_correct": false, "explanation": "语义：篮球是体育用品，不能作为需要询问的相关机构。"}, {"text": "水果", "is_correct": false, "explanation": "搭配：“问问”后面接的应是人或机构，“水果”是物品，两者不搭配。"}], "explanations": {"部门": "正确：“相关部门”指与此事有关的机构单位，符合“问问”的语境。", "花园": "语义：花园不是按职能划分的单位，与“相关”的含义不符。", "篮球": "语义：篮球是体育用品，不能作为需要询问的相关机构。", "水果": "搭配：“问问”后面接的应是人或机构，“水果”是物品，两者不搭配。"}, "sentence_index": 6, "correct_answer": "部门"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "膝盖是人体的重要部门，要好好保护。", "explanation": "这里应该用〈部位〉。身体的某一处要用“部位”，部门指机构单位，不能指身体的一部分。"}, {"text": "这次行动的部门很周密。", "explanation": "这里应该用〈部署〉。行动的安排要用“部署”，部门指机构单位，不能指行动的安排。"}, {"text": "这座城市最高的部门有一百层。", "explanation": "这里应该用〈大楼〉。有楼层的是建筑物，部门是机构中的单位，没有楼层。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0916f1a2-4269-47b8-aa72-5fc4a9a9257b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11827, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公司成立了一家新部门。", "corrected_sentence": "公司成立了一个新部门。", "error_description": "量词错误：“部门”是机构内部的单位，应用“个”计量，“家”用于独立的公司、商店等，应说“一个新部门”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0916f1a2-4269-47b8-aa72-5fc4a9a9257b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11827, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个部门去年成立了过。", "corrected_sentence": "这个部门去年成立过。", "error_description": "体标错误：表示曾经发生过的事要用“过”，“了”与“过”不能同时用在“成立”后，应说“成立过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0916f1a2-4269-47b8-aa72-5fc4a9a9257b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
