INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11829, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "减少或去除某种物质中的碳元素，常指减少二氧化碳排放的过程。", "primary_collocate": null, "pronunciation": "tuō tàn", "ipa": "tʰuɔ˥ tʰan˥˩", "syllable_count": 2, "sentences": [{"text": "此外，电动化公交 fleet 的普及与可再生能源供电系统的整合，正在推动交通运输部门实现深度脱碳。", "target_word": "脱碳", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "钢铁行业的脱碳需要很多时间和资金。", "target_word": "脱碳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家把电力脱碳当作第一步。", "target_word": "脱碳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "脱碳的目标是减少二氧化碳排放。", "target_word": "脱碳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市交通的脱碳离不开电动公交车。", "target_word": "脱碳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家说，建筑行业的脱碳还有很长的路要走。", "target_word": "脱碳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份报告讲的是能源系统的脱碳。", "target_word": "脱碳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水泥行业的脱碳比电力行业更难。", "target_word": "脱碳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府为工业脱碳提供了资金支持。", "target_word": "脱碳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全球脱碳的速度还不够快。", "target_word": "脱碳", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "脫碳", "label": "繁体"}], "register": "书面", "sense_fingerprint": "脱碳·名词·减少碳排放的过程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52c220fe-4ca5-4e18-bbc7-fbfacac2c9f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11829, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "脱碳", "is_correct": true, "explanation": "正确：指减少碳排放的转变过程，与“深度”和“推动……实现”搭配。"}, {"text": "碳排放", "is_correct": false, "explanation": "搭配：「实现」后面要接「转型」「目标」这类过程名词，不能接「碳排放」这种数量或状态名词。"}, {"text": "公交", "is_correct": false, "explanation": "语义：句子讲的是整个交通运输部门的减碳转变，公交只是其中一种车辆，不能作为“实现深度”的结果。"}, {"text": "能源", "is_correct": false, "explanation": "语义：前文已经说明是能源供电系统的整合，此处需要的是一个减少碳排放的过程，而不是能源本身。"}], "explanations": {"脱碳": "正确：指减少碳排放的转变过程，与“深度”和“推动……实现”搭配。", "碳排放": "搭配：「实现」后面要接「转型」「目标」这类过程名词，不能接「碳排放」这种数量或状态名词。", "公交": "语义：句子讲的是整个交通运输部门的减碳转变，公交只是其中一种车辆，不能作为“实现深度”的结果。", "能源": "语义：前文已经说明是能源供电系统的整合，此处需要的是一个减少碳排放的过程，而不是能源本身。"}, "sentence_index": 0, "correct_answer": "脱碳"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个水箱每个月都要脱碳一次。", "explanation": "这里应该用〈清洗〉。脱碳指去除某种物质中的碳元素，这里要做的是清除水箱污垢，应说〈清洗〉。"}, {"text": "这家工厂去年脱碳了两万吨二氧化碳。", "explanation": "这里应该用〈减排〉。脱碳指去除碳的过程，不直接计量排放量，说减少的排放量要用〈减排〉。"}, {"text": "我们要尽快脱碳二氧化碳的排放。", "explanation": "这里应该用〈减少〉。脱碳针对含碳的物质（如钢铁、能源系统），不能直接带「排放」作宾语；说减少二氧化碳排放要用〈减少〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6651a80d-9ff8-4af5-98fb-ee2d392b3a9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11829, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "脱碳", "is_correct": true, "explanation": "正确：指降低能源系统碳排放的过程，是报告的主题。"}, {"text": "香水", "is_correct": false, "explanation": "语义：这份报告讲的是能源系统减碳，与香水无关，「讲的是」后接「香水」不成立。"}, {"text": "发型", "is_correct": false, "explanation": "语义：这份报告讲的是能源减碳问题，不涉及发型。"}, {"text": "食谱", "is_correct": false, "explanation": "语义：这份报告讲的是能源减碳问题，不是食谱。"}], "explanations": {"脱碳": "正确：指降低能源系统碳排放的过程，是报告的主题。", "香水": "语义：这份报告讲的是能源系统减碳，与香水无关，「讲的是」后接「香水」不成立。", "发型": "语义：这份报告讲的是能源减碳问题，不涉及发型。", "食谱": "语义：这份报告讲的是能源减碳问题，不是食谱。"}, "sentence_index": 6, "correct_answer": "脱碳"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "衣服上有油渍，妈妈用洗衣粉给它脱碳。", "explanation": "这里应该用〈去污〉。脱碳指去除物质中的碳或减少碳排放，去掉衣服上的油渍要说〈去污〉。"}, {"text": "洗好的蔬菜要先用离心机脱碳，再下锅。", "explanation": "这里应该用〈脱水〉。脱碳是去除钢铁等物质中的碳，蔬菜要去掉的是水分，应说〈脱水〉。"}, {"text": "他感冒了，医生让他多喝水脱碳。", "explanation": "这里应该用〈退烧〉。脱碳与身体疾病无关，感冒发烧要说〈退烧〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6651a80d-9ff8-4af5-98fb-ee2d392b3a9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11829, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座城市今年完成了一只大规模的脱碳。", "corrected_sentence": "这座城市今年完成了一次大规模的脱碳。", "error_description": "量词错误：「脱碳」是过程名词，应该用「次」计量，不能用「只」。正确的说法是「一次大规模的脱碳」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6651a80d-9ff8-4af5-98fb-ee2d392b3a9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11829, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家公司已经完成了一张脱碳。", "corrected_sentence": "这家公司已经完成了一次脱碳。", "error_description": "量词错误：「张」用于纸张、桌子等平面物品，不能计量脱碳这种过程；过程名词应用「次」。正确的说法是「一次脱碳」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6651a80d-9ff8-4af5-98fb-ee2d392b3a9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
