INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11833, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指采取措施改善和保护自然环境，减少污染和破坏。", "primary_collocate": null, "pronunciation": "huán jìng zhì lǐ", "ipa": "xwan³⁵ tɕiŋ⁵¹ ʈʂʅ⁵¹ li²¹⁴", "syllable_count": 4, "sentences": [{"text": "在政策工具与技术创新的双重驱动下，公共交通已成为连接个体行为选择与全球环境治理的微观枢纽——每个乘客在刷卡入闸的瞬间，实际上都在以具身化的方式参与一场分布式治理实践，其累积效应足以对国家乃至全球的碳预算产生实质性影响。", "target_word": "环境治理", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "联合国环境规划署在1972年斯德哥尔摩人类环境会议后，将此类标准化符号纳入全球环境治理的技术建议之中。", "target_word": "环境治理", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "政府每年在环境治理上花很多钱。", "target_word": "环境治理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "环境治理需要每个人一起努力。", "target_word": "环境治理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的环境治理做得很好。", "target_word": "环境治理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水变干净，是环境治理的结果。", "target_word": "环境治理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在一家公司做环境治理工作。", "target_word": "环境治理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "环境治理不能只靠政府。", "target_word": "环境治理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学校开了环境治理的课。", "target_word": "环境治理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的环境治理能让空气变好。", "target_word": "环境治理", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "全球环境治理", "label": "复合"}, {"form": "环境治理工作", "label": "复合"}], "register": "书面", "sense_fingerprint": "改善和保护自然环境的措施", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f51b7060-190e-43be-9474-2cfe868f2248') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11833, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "环境治理", "is_correct": true, "explanation": "环境治理：指改善和保护自然环境的措施，作“枢纽”的修饰语，与“全球”搭配。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能构成“全球……微观枢纽”，句意不通。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲不能构成“全球……微观枢纽”，句意不通。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语说法，不合这句书面语的语域。"}], "explanations": {"环境治理": "环境治理：指改善和保护自然环境的措施，作“枢纽”的修饰语，与“全球”搭配。", "天气": "语义：天气不能构成“全球……微观枢纽”，句意不通。", "歌曲": "语义：歌曲不能构成“全球……微观枢纽”，句意不通。", "玩意儿": "语域：“玩意儿”是口语说法，不合这句书面语的语域。"}, "sentence_index": 0, "correct_answer": "环境治理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家工厂造成了严重的环境治理。", "explanation": "这里应该用〈环境污染〉。造成的是污染，治理是对污染的改善，二者不能互换。"}, {"text": "这家餐厅的环境治理很好吃。", "explanation": "这里把环境治理说成了可以“好吃”的东西，应该说〈饭菜〉。环境治理是改善环境的活动，不能用来形容食物。"}, {"text": "工人用环境治理清理了河道。", "explanation": "这里应该用〈机器〉。环境治理指改善和保护环境的活动，不是可以用来清理河道的工具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb8b5ac8-0f38-4132-9264-c2063c12f1d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11833, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "环境治理", "is_correct": true, "explanation": "环境治理：指改善和保护自然环境的措施，作“工作”的修饰语。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不是工作，“做石头工作”说不通。"}, {"text": "午饭", "is_correct": false, "explanation": "语义：午饭不是工作，“做午饭工作”说不通。"}, {"text": "饭碗", "is_correct": false, "explanation": "语义：“饭碗”指盛饭的碗（或比喻职业），“做饭碗工作”说不通。"}], "explanations": {"环境治理": "环境治理：指改善和保护自然环境的措施，作“工作”的修饰语。", "石头": "语义：石头不是工作，“做石头工作”说不通。", "午饭": "语义：午饭不是工作，“做午饭工作”说不通。", "饭碗": "语义：“饭碗”指盛饭的碗（或比喻职业），“做饭碗工作”说不通。"}, "sentence_index": 6, "correct_answer": "环境治理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我买了一个环境治理，放在家里。", "explanation": "这里把环境治理当成了〈商品〉，可以买回家摆放的东西。环境治理是一种活动，不能这样买卖。"}, {"text": "这里的空气很干净，环境治理也很干净。", "explanation": "这里把环境治理当成了〈场所〉，即可以用“干净”形容的地方。环境治理是改善环境的活动，不能用干净形容。"}, {"text": "他的感冒环境治理好了。", "explanation": "环境治理指改善自然环境，不能用来说病情；治疗病症应说“治好”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb8b5ac8-0f38-4132-9264-c2063c12f1d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11833, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们正在进行一只环境治理。", "corrected_sentence": "我们正在进行一项环境治理。", "error_description": "量词错误：“环境治理”是抽象的活动，量词应用“项”，不能用“只”（“只”多用于动物等）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb8b5ac8-0f38-4132-9264-c2063c12f1d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11833, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "许多城市都在加强环境治理们。", "corrected_sentence": "许多城市都在加强环境治理。", "error_description": "词缀错误：“们”只加在指人的名词后，“环境治理”是抽象名词，不能加“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb8b5ac8-0f38-4132-9264-c2063c12f1d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
