INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11834, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指事物相互连接的中心环节或关键部分；也指重要的地点或事物。", "primary_collocate": null, "pronunciation": "shū niǔ", "ipa": "ʂu˥ nioʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "在政策工具与技术创新的双重驱动下，公共交通已成为连接个体行为选择与全球环境治理的微观枢纽——每个乘客在刷卡入闸的瞬间，实际上都在以具身化的方式参与一场分布式环境治理实践，其累积效应足以对国家乃至全球的碳预算产生实质性影响。", "target_word": "枢纽", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "蜜蜂在这一网络中扮演着“生态枢纽”的角色——它们穿梭于不同植物之间，促进基因流动，增强植物种群的适应潜力，从而提升整个生态系统的抗逆能力。", "target_word": "枢纽", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这座火车站是南北交通的枢纽。", "target_word": "枢纽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校是连接家庭和社会的枢纽。", "target_word": "枢纽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个港口是海上运输的重要枢纽。", "target_word": "枢纽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小王是公司里各部门沟通的枢纽。", "target_word": "枢纽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "郑州是中国重要的铁路枢纽，很多火车都经过这里。", "target_word": "枢纽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个机场是东南亚航线的枢纽。", "target_word": "枢纽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个车站是公交线路的枢纽，很多人在这里换车。", "target_word": "枢纽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个广场是全城文化活动的枢纽。", "target_word": "枢纽", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "交通枢纽", "label": "复合"}, {"form": "枢纽站", "label": "复合"}, {"form": "樞紐", "label": "繁体"}], "register": "书面", "sense_fingerprint": "事物联系的中心环节；重要的交汇地点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52a47307-49a6-4e93-9fed-15de8bc7b402') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11834, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "车厢", "is_correct": false, "explanation": "语义：“车厢”指车辆中乘客所在的部分，与“连接个体与全球治理”的抽象语境不合。"}, {"text": "枢纽", "is_correct": true, "explanation": "“枢纽”指事物相互连接的中心环节，符合“连接个体行为选择与全球环境治理”的语境。"}, {"text": "乐章", "is_correct": false, "explanation": "语义：“乐章”指音乐的段落，与公共交通和环境治理无关。"}, {"text": "账户", "is_correct": false, "explanation": "搭配：“微观账户”不成立，“账户”是记录资金的凭证，无法充当连接个体与全球治理的中介。"}], "explanations": {"车厢": "语义：“车厢”指车辆中乘客所在的部分，与“连接个体与全球治理”的抽象语境不合。", "枢纽": "“枢纽”指事物相互连接的中心环节，符合“连接个体行为选择与全球环境治理”的语境。", "乐章": "语义：“乐章”指音乐的段落，与公共交通和环境治理无关。", "账户": "搭配：“微观账户”不成立，“账户”是记录资金的凭证，无法充当连接个体与全球治理的中介。"}, "sentence_index": 0, "correct_answer": "枢纽"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这扇门的枢纽已经生锈，转动时发出响声。", "explanation": "这里应该用〈合页〉。合页是门上连接门板和门框的金属零件；“枢纽”指交通或事物联系的中心，不指零件。"}, {"text": "这副眼镜的枢纽断了，镜腿合不上。", "explanation": "这里应该用〈铰链〉。铰链是让镜腿转动的小零件；“枢纽”指重要的连接中心或地点，不指零件。"}, {"text": "创新是企业的枢纽竞争力。", "explanation": "这里应该用〈核心〉。“核心竞争力”是固定搭配，“枢纽”不能修饰“竞争力”，二者意思不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d3d6948-7184-40c2-8d04-dba1fc89ab25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11834, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "诗人", "is_correct": false, "explanation": "搭配：“铁路”修饰的应是线路或设施，不能修饰人物“诗人”。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：“花瓶”是盛花的器具，与“很多火车都经过这里”的交通语境不合。"}, {"text": "枢纽", "is_correct": true, "explanation": "“枢纽”指交通中的汇集中心，“铁路枢纽”符合句意。"}, {"text": "字典", "is_correct": false, "explanation": "语义：“字典”是工具书，不是火车经过的地点，与“火车都经过这里”矛盾。"}], "explanations": {"诗人": "搭配：“铁路”修饰的应是线路或设施，不能修饰人物“诗人”。", "花瓶": "语义：“花瓶”是盛花的器具，与“很多火车都经过这里”的交通语境不合。", "枢纽": "“枢纽”指交通中的汇集中心，“铁路枢纽”符合句意。", "字典": "语义：“字典”是工具书，不是火车经过的地点，与“火车都经过这里”矛盾。"}, "sentence_index": 6, "correct_answer": "枢纽"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司的枢纽技术是芯片设计。", "explanation": "这里应该用〈核心〉。“核心技术”是固定搭配，“枢纽”不能修饰“技术”，二者意思不同。"}, {"text": "他的膝盖枢纽受伤了。", "explanation": "这里应该用〈关节〉。枢纽指交通或机构中的连接中心，人体的骨节不叫枢纽。"}, {"text": "子弹打中了他的枢纽。", "explanation": "这里应该用〈要害〉。枢纽指连接中心或重要地点，不用来指人体部位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d3d6948-7184-40c2-8d04-dba1fc89ab25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11834, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座新车站是西南地区的一条交通枢纽。", "corrected_sentence": "这座新车站是西南地区的一个交通枢纽。", "error_description": "量词错误：“枢纽”的量词用“个”，“条”用于线状事物，不能修饰枢纽。正确说法是“一个交通枢纽”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d3d6948-7184-40c2-8d04-dba1fc89ab25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11834, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座车站是全国地交通枢纽。", "corrected_sentence": "这座车站是全国的交通枢纽。", "error_description": "结构助词错误：“全国”修饰名词“交通枢纽”时应用“的”，“地”用于修饰动词或形容词，不能接在名词修饰语之后。正确说法是“全国的交通枢纽”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d3d6948-7184-40c2-8d04-dba1fc89ab25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
