INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11835, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "乘坐火车、汽车、飞机等交通工具的人。", "primary_collocate": null, "pronunciation": "chéng kè", "ipa": "ʈʂʰɤŋ˧˥ kʰɤ˥˩", "syllable_count": 2, "sentences": [{"text": "公共汽车上的乘客很多。", "target_word": "乘客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乘客请在黄线后面等车。", "target_word": "乘客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机上的乘客都系好了安全带。", "target_word": "乘客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位乘客忘了拿他的包。", "target_word": "乘客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出租车司机问乘客要去哪里。", "target_word": "乘客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车到站后，乘客们陆续下车。", "target_word": "乘客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁里的乘客大多在看手机。", "target_word": "乘客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请乘客保管好自己的行李。", "target_word": "乘客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机提醒乘客坐稳扶好。", "target_word": "乘客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨天，坐车的乘客比平时多。", "target_word": "乘客", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位乘客", "label": "量词"}, {"form": "一名乘客", "label": "量词"}], "register": "中性", "sense_fingerprint": "乘坐火车、汽车、飞机等交通工具的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83fd6bf9-3bac-4e2e-a8b7-ad5e5b0c673f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11835, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "乘客", "is_correct": true, "explanation": "正确：乘坐公共汽车等交通工具的人，这里指车上的人。"}, {"text": "飞机", "is_correct": false, "explanation": "语义：飞机不会出现在公共汽车上，句子说的是车上的人很多。"}, {"text": "汽油", "is_correct": false, "explanation": "语义：汽油是燃料，不是乘车的人，句子说的是车上的人很多，句意不通。"}, {"text": "石头", "is_correct": false, "explanation": "语义：公共汽车上不会有很多石头，与句子的意思不符。"}], "explanations": {"乘客": "正确：乘坐公共汽车等交通工具的人，这里指车上的人。", "飞机": "语义：飞机不会出现在公共汽车上，句子说的是车上的人很多。", "汽油": "语义：汽油是燃料，不是乘车的人，句子说的是车上的人很多，句意不通。", "石头": "语义：公共汽车上不会有很多石头，与句子的意思不符。"}, "sentence_index": 0, "correct_answer": "乘客"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们家来了一位乘客，陪我们吃饭。", "explanation": "这里应该用〈客人〉。乘客指乘坐交通工具的人，来家里做客的人应说〈客人〉。"}, {"text": "超市里的乘客排成长队结账。", "explanation": "这里应该用〈顾客〉。乘客指乘坐交通工具的人，在店里买东西的人应说〈顾客〉。"}, {"text": "办公室来了一位乘客，找经理谈事情。", "explanation": "这里应该用〈访客〉。乘客指乘车的人，到办公室找人的应说〈访客〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0087a302-9e61-4b40-bf3e-cdd7e8f5a6fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11835, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "乘客", "is_correct": true, "explanation": "正确：乘坐地铁的人，这里指车厢里的人。"}, {"text": "老鼠", "is_correct": false, "explanation": "语义：地铁里的老鼠不会看手机，句子说的是乘车的人。"}, {"text": "客官", "is_correct": false, "explanation": "语域：“客官”是旧式称呼，现代口语中不用来指乘地铁的人。"}, {"text": "树叶", "is_correct": false, "explanation": "语义：树叶不会在地铁里看手机，与句子的意思不符。"}], "explanations": {"乘客": "正确：乘坐地铁的人，这里指车厢里的人。", "老鼠": "语义：地铁里的老鼠不会看手机，句子说的是乘车的人。", "客官": "语域：“客官”是旧式称呼，现代口语中不用来指乘地铁的人。", "树叶": "语义：树叶不会在地铁里看手机，与句子的意思不符。"}, "sentence_index": 6, "correct_answer": "乘客"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座古城每天有很多乘客。", "explanation": "这里应该用〈游客〉。乘客指乘坐交通工具的人，来景点观光的人应说〈游客〉。"}, {"text": "剧场里的乘客坐满了，都在等表演开始。", "explanation": "这里应该用〈观众〉。乘客指乘车的人，看演出的人应说〈观众〉。"}, {"text": "医院里的乘客排着队等候看病。", "explanation": "这里应该用〈病人〉。乘客指乘车的人，等候看病的人应说〈病人〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0087a302-9e61-4b40-bf3e-cdd7e8f5a6fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11835, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公交车上有三只乘客。", "corrected_sentence": "公交车上有三名乘客。", "error_description": "“乘客”指人，量词应用“名”或“位”，不能用“只”（“只”多用于动物）。应说“三名乘客”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0087a302-9e61-4b40-bf3e-cdd7e8f5a6fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11835, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "车上坐着一位乘客们。", "corrected_sentence": "车上坐着一位乘客。", "error_description": "“们”表示复数，不能与数量词“一位”连用；有了数量词，“乘客”就已经计量清楚。应说“一位乘客”，去掉“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0087a302-9e61-4b40-bf3e-cdd7e8f5a6fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
