INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11836, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使用银行卡、信用卡等卡片在刷卡机上划过，以完成支付、身份验证或记录等操作。", "primary_collocate": null, "pronunciation": "shuā kǎ", "ipa": "ʂwa˥ kʰa˨˩˦", "syllable_count": 2, "sentences": [{"text": "在政策工具与技术创新的双重驱动下，公共交通已成为连接个体行为选择与全球环境治理的微观枢纽——每个乘客在刷卡入闸的瞬间，实际上都在以具身化的方式参与一场分布式环境治理实践，其累积效应足以对国家乃至全球的碳预算产生实质性影响。", "target_word": "刷卡", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "进地铁站的时候，请先刷卡。", "target_word": "刷卡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在超市刷卡付了钱。", "target_word": "刷卡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家小店不能刷卡，只能给现金。", "target_word": "刷卡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "员工每天上班都要刷卡开门。", "target_word": "刷卡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公交车上可以刷卡，也可以用手机付钱。", "target_word": "刷卡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他刷卡买了一件新衣服。", "target_word": "刷卡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请在机器上刷卡。", "target_word": "刷卡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酒店的客人要刷卡才能坐电梯。", "target_word": "刷卡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在饭馆吃完饭，你可以刷卡结账。", "target_word": "刷卡", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "刷了卡", "label": "体标"}, {"form": "刷过卡", "label": "体标"}, {"form": "刷卡机", "label": "复合"}], "register": "中性", "sense_fingerprint": "刷卡·动词·用卡片在机器上划过完成支付或验证", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52c220fe-4ca5-4e18-bbc7-fbfacac2c9f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11836, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "刷卡", "is_correct": true, "explanation": "刷卡：用卡在闸机上划过，是入闸前的通行动作，与“入闸的瞬间”衔接。"}, {"text": "吵架", "is_correct": false, "explanation": "语义：乘客吵架与闸机通行无关，句中讲的是交通与环境治理，两者不能搭配。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：唱歌不是通过闸机的动作，放在这里与句子的论述不相干。"}, {"text": "蹭", "is_correct": false, "explanation": "语义：「蹭」指白占便宜，与乘客正常刷卡入闸的行为相悖，口语化也与书面语域不符。"}], "explanations": {"刷卡": "刷卡：用卡在闸机上划过，是入闸前的通行动作，与“入闸的瞬间”衔接。", "吵架": "语义：乘客吵架与闸机通行无关，句中讲的是交通与环境治理，两者不能搭配。", "唱歌": "语义：唱歌不是通过闸机的动作，放在这里与句子的论述不相干。", "蹭": "语义：「蹭」指白占便宜，与乘客正常刷卡入闸的行为相悖，口语化也与书面语域不符。"}, "sentence_index": 0, "correct_answer": "刷卡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他刷卡捡起了一袋垃圾。", "explanation": "这里应该用〈捡〉。刷卡指用卡在机器上划过完成付款或开门，与捡垃圾无关，应说〈捡〉。"}, {"text": "我没带卡，直接刷卡进了门。", "explanation": "这里应该用〈刷脸〉。刷卡要用卡片，没带卡时靠面部识别进门要说“刷脸”，与“没带卡”矛盾。"}, {"text": "妈妈刷卡给我一个红包。", "explanation": "这里应该用〈发〉。刷卡是在机器上划卡付款或开门，不能用来把红包送给别人；发红包要说“发”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6651a80d-9ff8-4af5-98fb-ee2d392b3a9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11836, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "刷卡", "is_correct": true, "explanation": "刷卡：用卡在机器上划过付款，符合“买了一件新衣服”的购物语境。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：跳舞与购物的动作无关，句子讲的是买衣服，两者放在一起说不通。"}, {"text": "发呆", "is_correct": false, "explanation": "语义：发呆无法完成购买动作，句中“买了一件新衣服”是明确的消费行为。"}, {"text": "点燃", "is_correct": false, "explanation": "搭配：“点燃”的对象是火、蜡烛等，不能用来修饰买衣服这一动作。"}], "explanations": {"刷卡": "刷卡：用卡在机器上划过付款，符合“买了一件新衣服”的购物语境。", "跳舞": "语义：跳舞与购物的动作无关，句子讲的是买衣服，两者放在一起说不通。", "发呆": "语义：发呆无法完成购买动作，句中“买了一件新衣服”是明确的消费行为。", "点燃": "搭配：“点燃”的对象是火、蜡烛等，不能用来修饰买衣服这一动作。"}, "sentence_index": 6, "correct_answer": "刷卡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他刷卡量了一下体温。", "explanation": "这里应该用〈测〉。刷卡是在机器上划卡付款或开门，不能用来测体温；测体温要说“测”，不说“刷卡”。"}, {"text": "他用刷卡把地板擦干净了。", "explanation": "这里应该用〈拖把〉。刷卡指用卡在机器上划过完成付款或开门，不是清洁工具；擦地板要用〈拖把〉。"}, {"text": "他在合同最后一页刷卡。", "explanation": "这里应该用〈签字〉。刷卡要在机器上划过，不能用在纸质合同上；在文件上确认要说“签字”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6651a80d-9ff8-4af5-98fb-ee2d392b3a9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11836, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把刷卡用的那只卡忘在家里了。", "corrected_sentence": "他把刷卡用的那张卡忘在家里了。", "error_description": "错在“那只卡”。卡应用量词“张”，正确说法是“那张卡”，不说“那只卡”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6651a80d-9ff8-4af5-98fb-ee2d392b3a9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11836, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他昨天在商店刷卡着买了一件新衣服。", "corrected_sentence": "他昨天在商店刷卡买了一件新衣服。", "error_description": "错在「刷卡着」：「刷卡」在这里表示买衣服的方式，是已经完成的动作，后面不能加表示持续的「着」。应说「刷卡买了一件新衣服」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6651a80d-9ff8-4af5-98fb-ee2d392b3a9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
