INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11837, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6651a80d-9ff8-4af5-98fb-ee2d392b3a9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11837, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "进入闸机或闸门，通常指通过刷卡或扫码进入地铁站、停车场等场所。", "primary_collocate": null, "pronunciation": "rù zhá", "ipa": "ʐu˥˩ ʈʂa˧˥", "syllable_count": 2, "sentences": [{"text": "在政策工具与技术创新的双重驱动下，公共交通已成为连接个体行为选择与全球环境治理的微观枢纽——每个乘客在刷卡入闸的瞬间，实际上都在以具身化的方式参与一场分布式环境治理实践，其累积效应足以对国家乃至全球的碳预算产生实质性影响。", "target_word": "入闸", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "早上我刷卡入闸，坐地铁去上班。", "target_word": "入闸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿出手机，扫码入闸。", "target_word": "入闸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先刷卡，再入闸。", "target_word": "入闸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的卡没钱了，不能入闸。", "target_word": "入闸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人太多，大家在站口排队入闸。", "target_word": "入闸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩免票，跟着妈妈入闸。", "target_word": "入闸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他入闸以后，才发现坐错了方向。", "target_word": "入闸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "刷了卡，闸机却没开，我没能入闸。", "target_word": "入闸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开车到停车场，先扫码入闸。", "target_word": "入闸", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "刷卡或扫码后通过闸机进入站点或场所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52c220fe-4ca5-4e18-bbc7-fbfacac2c9f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11837, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "入闸", "is_correct": true, "explanation": "入闸：走进闸机进入站内，与前面的“刷卡”相接，指进站这一动作。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：唱歌不是通过闸机的动作，放在“刷卡……的瞬间”中语义不通。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：跳舞与刷卡通行的动作无关，句子讲的是交通与环境治理。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：吃饭与刷卡通过闸机的动作无关，放在“刷卡……的瞬间”中语义不通。"}], "explanations": {"入闸": "入闸：走进闸机进入站内，与前面的“刷卡”相接，指进站这一动作。", "唱歌": "语义：唱歌不是通过闸机的动作，放在“刷卡……的瞬间”中语义不通。", "跳舞": "语义：跳舞与刷卡通行的动作无关，句子讲的是交通与环境治理。", "吃饭": "语义：吃饭与刷卡通过闸机的动作无关，放在“刷卡……的瞬间”中语义不通。"}, "sentence_index": 0, "correct_answer": "入闸"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在售票窗口入闸。", "explanation": "这里应该用〈买票〉。“入闸”指通过闸机进站或停车场，买票要在售票窗口办，不能用“入闸”来表示。"}, {"text": "他在站台入闸，等车去上班。", "explanation": "这里应该用〈上车〉。“入闸”指通过闸机，站台不是闸机所在处；乘车要说“上车”，不说“入闸”。"}, {"text": "到站后他入闸了。", "explanation": "这里应该用〈出闸〉。到站后是离开闸机，要说“出闸”；“入闸”是走进闸机，不能用在到站离开时。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6651a80d-9ff8-4af5-98fb-ee2d392b3a9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11837, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "入闸", "is_correct": true, "explanation": "入闸：通过闸门进入，符合“小孩免票，跟着妈妈”进场的语境。"}, {"text": "买票", "is_correct": false, "explanation": "语义：句中已说小孩免票，再说“买票”与前半句矛盾。"}, {"text": "付款", "is_correct": false, "explanation": "语义：免票就不用付款，说“付款”与句意相反。"}, {"text": "倒垃圾", "is_correct": false, "explanation": "语义：句子讲的是免票的小孩跟着妈妈进站，与「倒垃圾」毫无关联。"}], "explanations": {"入闸": "入闸：通过闸门进入，符合“小孩免票，跟着妈妈”进场的语境。", "买票": "语义：句中已说小孩免票，再说“买票”与前半句矛盾。", "付款": "语义：免票就不用付款，说“付款”与句意相反。", "倒垃圾": "语义：句子讲的是免票的小孩跟着妈妈进站，与「倒垃圾」毫无关联。"}, "sentence_index": 6, "correct_answer": "入闸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "列车缓缓入闸，乘客陆续下车。", "explanation": "这里应该用〈进站〉。“入闸”指通过闸机，列车进站要说“进站”，不能用“入闸”来形容列车。"}, {"text": "他推门入闸。", "explanation": "这里应该用〈进屋〉。“入闸”专指通过闸机，不用于走进房间；推门进屋要说“进屋”。"}, {"text": "他在马路上入闸，过了斑马线。", "explanation": "这里应该用〈过〉。「入闸」指通过闸机，马路上没有闸机，过斑马线应说〈过〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6651a80d-9ff8-4af5-98fb-ee2d392b3a9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11837, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他刷卡以后很快闸入了，入闸的人很多。", "corrected_sentence": "他刷卡以后很快入闸了，入闸的人很多。", "error_description": "错在“闸入”。“入闸”是动宾结构，应说“入闸”，不说“闸入”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6651a80d-9ff8-4af5-98fb-ee2d392b3a9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11837, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他以前入闸过，知道怎么刷卡。", "corrected_sentence": "他以前入过闸，知道怎么刷卡。", "error_description": "错在“入闸过”。“过”要紧跟动词，应说“入过闸”，不说“入闸过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6651a80d-9ff8-4af5-98fb-ee2d392b3a9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11838, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6651a80d-9ff8-4af5-98fb-ee2d392b3a9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
