INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11838, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示真实情况，与表面可能不同。", "primary_collocate": null, "pronunciation": "shí jì shàng", "ipa": "/ʂɨ˧˥ tɕi˥˩ ʂɑŋ˥˩/", "syllable_count": 3, "sentences": [{"text": "他看起来很轻松，实际上非常紧张。", "target_word": "实际上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店很小，实际上东西很全。", "target_word": "实际上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家以为她是中国人，实际上她是日本人。", "target_word": "实际上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你觉得很难，实际上这个问题很简单。", "target_word": "实际上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说自己很忙，实际上一直在玩手机。", "target_word": "实际上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服看着便宜，实际上花了不少钱。", "target_word": "实际上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她笑着说没事，实际上心里很难过。", "target_word": "实际上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上说很容易，实际上做起来很难。", "target_word": "实际上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地方听说很远，实际上坐地铁二十分钟就到。", "target_word": "实际上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是经理，实际上公司的事都是小王在做。", "target_word": "实际上", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "点明与表面印象相反的真实情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52c220fe-4ca5-4e18-bbc7-fbfacac2c9f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11838, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "实际上", "is_correct": true, "explanation": "正确：“看起来很轻松”与“非常紧张”形成反差，需要表示真实情况的“实际上”。"}, {"text": "当然", "is_correct": false, "explanation": "语义：“当然”表示理所当然，与“看起来很轻松”之后的转折不相容。"}, {"text": "根本", "is_correct": false, "explanation": "搭配：“根本”多与否定词连用（根本不紧张），不能修饰“非常紧张”。"}, {"text": "几乎", "is_correct": false, "explanation": "搭配：“几乎”表示接近但未达到，不能与“非常”同现修饰“紧张”。"}], "explanations": {"实际上": "正确：“看起来很轻松”与“非常紧张”形成反差，需要表示真实情况的“实际上”。", "当然": "语义：“当然”表示理所当然，与“看起来很轻松”之后的转折不相容。", "根本": "搭配：“根本”多与否定词连用（根本不紧张），不能修饰“非常紧张”。", "几乎": "搭配：“几乎”表示接近但未达到，不能与“非常”同现修饰“紧张”。"}, "sentence_index": 0, "correct_answer": "实际上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条路实际上似乎很近。", "explanation": "这里应该用〈表面上〉（从外表看）。实际上强调与表象相反的真实情况，不能用来描述“似乎”所表示的表象。"}, {"text": "我们要实际上解决这个问题。", "explanation": "这里应该用〈切实〉（副词，指认真、实实在在地做）。实际上只说明情况，不表示做事的态度。"}, {"text": "他说话实际上好像很冷静。", "explanation": "这里应该用〈表面上〉（从外表看）。实际上强调真实情况，不能用来描述“好像”所表示的印象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6651a80d-9ff8-4af5-98fb-ee2d392b3a9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11838, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "实际上", "is_correct": true, "explanation": "正确：“笑着说没事”与“心里很难过”形成反差，需要点明真实情况的“实际上”。"}, {"text": "非常", "is_correct": false, "explanation": "语义：“非常”只表示程度高，不能引出与前文“说没事”相反的真实情况，放在这里句子不通。"}, {"text": "已", "is_correct": false, "explanation": "语域：“已”是书面语，口语中单用不自然，且不能直接修饰“心里很难过”。"}, {"text": "立即", "is_correct": false, "explanation": "语义：“立即”表示立刻开始某一动作，与“心里很难过”这一状态不搭。"}], "explanations": {"实际上": "正确：“笑着说没事”与“心里很难过”形成反差，需要点明真实情况的“实际上”。", "非常": "语义：“非常”只表示程度高，不能引出与前文“说没事”相反的真实情况，放在这里句子不通。", "已": "语域：“已”是书面语，口语中单用不自然，且不能直接修饰“心里很难过”。", "立即": "语义：“立即”表示立刻开始某一动作，与“心里很难过”这一状态不搭。"}, "sentence_index": 6, "correct_answer": "实际上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的计划实际上看上去十分周密。", "explanation": "这里应该用〈表面上〉（从外表看）。实际上强调与表象相反的真实情况，不能用来描述“看上去”所表示的外表。"}, {"text": "这家店实际上仿佛很冷清。", "explanation": "这里应该用〈表面上〉（从外表看）。实际上强调真实情况，不能用来描述“仿佛”所表示的印象。"}, {"text": "她实际上像是很开心。", "explanation": "这里应该用〈表面上〉（从外表看）。实际上强调真实情况，不能用来描述“像是”所表示的表象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6651a80d-9ff8-4af5-98fb-ee2d392b3a9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11838, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份报告看起来很完整，实际上实际上还有很多漏洞。", "corrected_sentence": "这份报告看起来很完整，实际上还有很多漏洞。", "error_description": "错误形式：“实际上实际上还有”；正确形式：“实际上还有”。“实际上”是副词，引出与表面不同的真实情况，这里只需用一次，重复属于赘余。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6651a80d-9ff8-4af5-98fb-ee2d392b3a9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11838, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份工作看起来很轻松，实际上了很累。", "corrected_sentence": "这份工作看起来很轻松，实际上很累。", "error_description": "错误形式：“实际上了”；正确形式：“实际上”。“了”是动态助词，不能附着在副词“实际上”之后；这里只需陈述真实情况，不需要“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6651a80d-9ff8-4af5-98fb-ee2d392b3a9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11843, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "决算", "is_correct": true, "explanation": "决算是对已完成的收支做的结算，与预算（事先的计划）相对。"}, {"text": "河流", "is_correct": false, "explanation": "河流与预算没有反义关系，是另一类名词。"}, {"text": "窗户", "is_correct": false, "explanation": "窗户与预算没有反义关系，是另一类名词。"}, {"text": "天气", "is_correct": false, "explanation": "天气与预算没有反义关系，是另一类名词。"}], "correct_answer": "决算", "explanations": {"决算": "决算是对已完成的收支做的结算，与预算（事先的计划）相对。", "河流": "河流与预算没有反义关系，是另一类名词。", "窗户": "窗户与预算没有反义关系，是另一类名词。", "天气": "天气与预算没有反义关系，是另一类名词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0087a302-9e61-4b40-bf3e-cdd7e8f5a6fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11843, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "决算", "is_correct": true, "explanation": "决算是对已完成的收支做的结算，与预算（事先的计划）相对。"}, {"text": "桌子", "is_correct": false, "explanation": "桌子与预算没有反义关系，是另一类名词。"}, {"text": "雨水", "is_correct": false, "explanation": "雨水与预算没有反义关系，是另一类名词。"}, {"text": "书包", "is_correct": false, "explanation": "书包与预算没有反义关系，是另一类名词。"}], "correct_answer": "决算", "explanations": {"决算": "决算是对已完成的收支做的结算，与预算（事先的计划）相对。", "桌子": "桌子与预算没有反义关系，是另一类名词。", "雨水": "雨水与预算没有反义关系，是另一类名词。", "书包": "书包与预算没有反义关系，是另一类名词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0087a302-9e61-4b40-bf3e-cdd7e8f5a6fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11843, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "预算指对未来一定时期内收入和支出的计划安排。", "primary_collocate": null, "pronunciation": "yù suàn", "ipa": "y˥˩ suan˥˩", "syllable_count": 2, "sentences": [{"text": "我们公司今年的预算很紧。", "target_word": "预算", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次旅行的预算是五千元。", "target_word": "预算", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师请同学们先做一份预算。", "target_word": "预算", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "超出预算的东西，我们不买。", "target_word": "预算", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校明年的教育预算增加了。", "target_word": "预算", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他做好预算，每个月都按计划花钱。", "target_word": "预算", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "买房前，你要先看看自己的预算。", "target_word": "预算", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个项目的预算太少，工人拿不到工资。", "target_word": "预算", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府公布了新一年的预算。", "target_word": "预算", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "婚礼的预算不能超过十万元。", "target_word": "预算", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一笔预算", "label": "量词"}, {"form": "预算表", "label": "复合"}, {"form": "預算", "label": "繁体"}], "register": "中性", "sense_fingerprint": "对未来一段时间收入和支出做出的计划安排（机构、项目、国家）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83fd6bf9-3bac-4e2e-a8b7-ad5e5b0c673f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11843, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "预算", "is_correct": true, "explanation": "“预算很紧”指计划中的钱不宽裕，与“公司今年的”搭配自然。"}, {"text": "人口", "is_correct": false, "explanation": "语义：人口指一个国家或地区的居民总数，不属于公司，也不能说“很紧”。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“天气”不能说“很紧”，“公司今年的天气”也不通。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“年龄”不能用“很紧”来形容。"}], "explanations": {"预算": "“预算很紧”指计划中的钱不宽裕，与“公司今年的”搭配自然。", "人口": "语义：人口指一个国家或地区的居民总数，不属于公司，也不能说“很紧”。", "天气": "搭配：“天气”不能说“很紧”，“公司今年的天气”也不通。", "年龄": "搭配：“年龄”不能用“很紧”来形容。"}, "sentence_index": 0, "correct_answer": "预算"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我预算他明天不会来。", "explanation": "这里应该用〈估计〉。预算是对收支的计划安排，不能用来推测某人会不会来。"}, {"text": "我们提前预算了一个包厢。", "explanation": "这里应该用〈预定〉。预算是对收支的计划安排，不能用来订包厢。"}, {"text": "明天会下雨，气象台的预算很准确。", "explanation": "这里应该用〈预测〉。预算是对收支的计划安排，不能用来判断天气是否准确；气象台的判断叫预测。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0087a302-9e61-4b40-bf3e-cdd7e8f5a6fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11843, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "预算", "is_correct": true, "explanation": "“自己的预算”指买房前打算花的钱，符合语境。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”与买房前的打算无关，句子读来不通。"}, {"text": "作业", "is_correct": false, "explanation": "语义：“作业”是学习任务，与买房的语境不符。"}, {"text": "年份", "is_correct": false, "explanation": "搭配：“看看自己的年份”不成搭配，年份不能用“看看自己的”来说。"}], "explanations": {"预算": "“自己的预算”指买房前打算花的钱，符合语境。", "颜色": "语义：“颜色”与买房前的打算无关，句子读来不通。", "作业": "语义：“作业”是学习任务，与买房的语境不符。", "年份": "搭配：“看看自己的年份”不成搭配，年份不能用“看看自己的”来说。"}, "sentence_index": 6, "correct_answer": "预算"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们已经付清了这笔预算。", "explanation": "这里应该用〈开支〉。预算是计划，不能“付清”；付清的是开支。"}, {"text": "这些乌云是下雨的预算。", "explanation": "这里应该用〈预兆〉。预算是对收支的计划安排，不能用来表示自然现象的征兆。"}, {"text": "我每天晚上都预算功课。", "explanation": "这里应该用〈预习〉。预算是对收支的计划安排，不能用来指学习新功课。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0087a302-9e61-4b40-bf3e-cdd7e8f5a6fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11843, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公司今年定下了一把预算。", "corrected_sentence": "公司今年定下了一笔预算。", "error_description": "量词错误：“预算”应搭配量词“笔”，说“一笔预算”。“把”用于有柄的东西，如刀、伞，不能用来数预算。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0087a302-9e61-4b40-bf3e-cdd7e8f5a6fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11843, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "政府公布了新一年的一条预算。", "corrected_sentence": "政府公布了新一年的一笔预算。", "error_description": "量词错误：“预算”应搭配量词“笔”，说“一笔预算”；“条”用于长条形的东西或消息、新闻，不能用来数预算。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0087a302-9e61-4b40-bf3e-cdd7e8f5a6fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
