INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11844, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指事物或问题中最关键、最根本的部分，不表面。", "primary_collocate": null, "pronunciation": "shí zhì xìng", "ipa": "ʂʐ̩˧˥ ʈʂʐ̩˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "在政策工具与技术创新的双重驱动下，公共交通已成为连接个体行为选择与全球环境治理的微观枢纽——每个乘客在刷卡入闸的瞬间，实际上都在以具身化的方式参与一场分布式环境治理实践，其累积效应足以对国家乃至全球的碳预算产生实质性影响。", "target_word": "实质性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "两国谈判终于有了实质性进展。", "target_word": "实质性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个会议没有讨论实质性问题。", "target_word": "实质性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新政策对农民有实质性帮助。", "target_word": "实质性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的话很多，却没有实质性内容。", "target_word": "实质性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司需要采取实质性措施减少浪费。", "target_word": "实质性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次改革带来了实质性变化。", "target_word": "实质性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家只谈表面，没有实质性的办法。", "target_word": "实质性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这项研究取得了实质性成果。", "target_word": "实质性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们需要的是实质性的支持，不是口号。", "target_word": "实质性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "實質性", "label": "繁体"}], "register": "书面", "sense_fingerprint": "触及事物根本、不流于表面的（多作定语：实质性影响、实质性进展）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83fd6bf9-3bac-4e2e-a8b7-ad5e5b0c673f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11844, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "实质性", "is_correct": true, "explanation": "“产生实质性影响”指真正、切实的影响，符合句意。"}, {"text": "清澈", "is_correct": false, "explanation": "搭配：“清澈”形容水或眼神，不能修饰“影响”。"}, {"text": "甜蜜", "is_correct": false, "explanation": "语义：“甜蜜”指感情上的愉快，与碳预算的影响不相干。"}, {"text": "狭窄", "is_correct": false, "explanation": "搭配：“狭窄”说空间，不能修饰“影响”。"}], "explanations": {"实质性": "“产生实质性影响”指真正、切实的影响，符合句意。", "清澈": "搭配：“清澈”形容水或眼神，不能修饰“影响”。", "甜蜜": "语义：“甜蜜”指感情上的愉快，与碳预算的影响不相干。", "狭窄": "搭配：“狭窄”说空间，不能修饰“影响”。"}, "sentence_index": 0, "correct_answer": "实质性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是一位实质性的老师。", "explanation": "这里应该用〈真正〉。实质性用于修饰事情、问题或成果，不用来形容人。"}, {"text": "这件衣服是实质性的红色。", "explanation": "这里应该用〈鲜艳〉。实质性是“根本、不流于表面”，不能拿来形容颜色的鲜艳程度。"}, {"text": "这顿饭的味道是实质性的。", "explanation": "这里应该用〈可口〉。实质性是“根本、不流于表面”，不能用来形容味道这类感受。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0087a302-9e61-4b40-bf3e-cdd7e8f5a6fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11844, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "实质性", "is_correct": true, "explanation": "“带来了实质性变化”指真正有分量的变化，符合句意。"}, {"text": "湿润", "is_correct": false, "explanation": "语义：“湿润”形容物体或空气的状态，不能形容变化的程度。"}, {"text": "碧绿", "is_correct": false, "explanation": "搭配：“碧绿”是颜色，不能修饰“变化”。"}, {"text": "软绵绵", "is_correct": false, "explanation": "搭配：“软绵绵”形容质地，不能用来说“变化”。"}], "explanations": {"实质性": "“带来了实质性变化”指真正有分量的变化，符合句意。", "湿润": "语义：“湿润”形容物体或空气的状态，不能形容变化的程度。", "碧绿": "搭配：“碧绿”是颜色，不能修饰“变化”。", "软绵绵": "搭配：“软绵绵”形容质地，不能用来说“变化”。"}, "sentence_index": 6, "correct_answer": "实质性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首歌的旋律是实质性的。", "explanation": "这里应该用〈优美〉。实质性是“根本、不流于表面”，不能用来形容旋律这类听觉感受。"}, {"text": "他的笑容是实质性的。", "explanation": "这里应该用〈灿烂〉或〈温和〉。实质性是“根本、不流于表面”，不能用来形容笑容这类表情。"}, {"text": "这座山很实质性，爬上去要三个小时。", "explanation": "这里应该用〈高〉。实质性是“根本、不流于表面”，用来修饰问题、进展、成果，不能形容山的高度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0087a302-9e61-4b40-bf3e-cdd7e8f5a6fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11844, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府要采取实质性地措施。", "corrected_sentence": "政府要采取实质性措施。", "error_description": "结构助词误用：“实质性”修饰名词“措施”，作定语时直接放在名词前，不用“地”。“地”用于修饰动词，应删去。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0087a302-9e61-4b40-bf3e-cdd7e8f5a6fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11844, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个方案有实质性地效果。", "corrected_sentence": "这个方案有实质性的效果。", "error_description": "结构助词误用：“实质性”修饰名词“效果”，应用“的”，不用“地”。“地”用于修饰动词或形容词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0087a302-9e61-4b40-bf3e-cdd7e8f5a6fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11847, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "偏私", "is_correct": true, "explanation": "正确：指不公正、偏袒某一方，与“公正”构成反义。"}, {"text": "明亮", "is_correct": false, "explanation": "与“公正”没有反义关系，指光线充足或颜色鲜亮。"}, {"text": "缓慢", "is_correct": false, "explanation": "与“公正”没有反义关系，指速度不快。"}, {"text": "轻松", "is_correct": false, "explanation": "与“公正”没有反义关系，指不费力或心情舒畅。"}], "correct_answer": "偏私", "explanations": {"偏私": "正确：指不公正、偏袒某一方，与“公正”构成反义。", "明亮": "与“公正”没有反义关系，指光线充足或颜色鲜亮。", "缓慢": "与“公正”没有反义关系，指速度不快。", "轻松": "与“公正”没有反义关系，指不费力或心情舒畅。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0087a302-9e61-4b40-bf3e-cdd7e8f5a6fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11847, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "偏颇", "is_correct": true, "explanation": "正确：指看法或处理偏向一方、不公平，与“公正”构成反义。"}, {"text": "柔软", "is_correct": false, "explanation": "与“公正”没有反义关系，指物体不硬。"}, {"text": "热烈", "is_correct": false, "explanation": "与“公正”没有反义关系，指情绪高涨或气氛热闹。"}, {"text": "清新", "is_correct": false, "explanation": "与“公正”没有反义关系，指干净新鲜。"}], "correct_answer": "偏颇", "explanations": {"偏颇": "正确：指看法或处理偏向一方、不公平，与“公正”构成反义。", "柔软": "与“公正”没有反义关系，指物体不硬。", "热烈": "与“公正”没有反义关系，指情绪高涨或气氛热闹。", "清新": "与“公正”没有反义关系，指干净新鲜。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0087a302-9e61-4b40-bf3e-cdd7e8f5a6fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11847, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指公平正直，没有偏私。", "primary_collocate": null, "pronunciation": "gōng zhèng", "ipa": "kʊŋ˥ ʈʂɤŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这种将日常通勤转化为生态公民实践的转化机制，正是现代城市文明迈向韧性与公正转型的深层密码。", "target_word": "公正", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这位法官处理案件很公正。", "target_word": "公正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师对每个学生都很公正。", "target_word": "公正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛需要一个公正的裁判。", "target_word": "公正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都相信他会公正地做决定。", "target_word": "公正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做事很公正，从不偏向朋友。", "target_word": "公正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律面前，人人都应得到公正的对待。", "target_word": "公正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛的结果很公正，没人有意见。", "target_word": "公正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理公正地分了奖金。", "target_word": "公正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我觉得这样分配很公正。", "target_word": "公正", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不公正", "label": "复合"}, {"form": "公正性", "label": "复合"}], "register": "书面", "sense_fingerprint": "公平正直、没有偏私（用于人、裁决、制度）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83fd6bf9-3bac-4e2e-a8b7-ad5e5b0c673f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11847, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "公正", "is_correct": true, "explanation": "正确：公平正直，没有偏私。"}, {"text": "工整", "is_correct": false, "explanation": "zhěng（第三声）与 zhèng（第四声）声调不同，意思是整齐、规范。"}, {"text": "更正", "is_correct": false, "explanation": "gēng 与 gōng 韵母不同（-eng 与 -ong），意思是改正错误。"}, {"text": "公章", "is_correct": false, "explanation": "zhāng（第一声）与 zhèng（第四声）韵母和声调都不同，意思是公用的印章。"}], "explanations": {"公正": "正确：公平正直，没有偏私。", "工整": "zhěng（第三声）与 zhèng（第四声）声调不同，意思是整齐、规范。", "更正": "gēng 与 gōng 韵母不同（-eng 与 -ong），意思是改正错误。", "公章": "zhāng（第一声）与 zhèng（第四声）韵母和声调都不同，意思是公用的印章。"}, "sentence_index": null, "correct_answer": "公正"}, "level_3": {"options": [{"text": "公正", "is_correct": true, "explanation": "正确：修饰“转型”的形容词，指公平、不偏私，与“韧性”“生态”的理念一致。"}, {"text": "懒惰", "is_correct": false, "explanation": "语义：“懒惰”与“韧性”的理念相反，句子强调坚韧的转型。"}, {"text": "幼稚", "is_correct": false, "explanation": "语义：“幼稚”与“深层密码”和“现代城市文明”的语境不符。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容人或物的体形，不能用来修饰“转型”。"}], "explanations": {"公正": "正确：修饰“转型”的形容词，指公平、不偏私，与“韧性”“生态”的理念一致。", "懒惰": "语义：“懒惰”与“韧性”的理念相反，句子强调坚韧的转型。", "幼稚": "语义：“幼稚”与“深层密码”和“现代城市文明”的语境不符。", "高大": "体貌：“高大”形容人或物的体形，不能用来修饰“转型”。"}, "sentence_index": 0, "correct_answer": "公正"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这碗汤的味道很公正。", "explanation": "这里应该用〈鲜美〉。公正用于人、裁决和制度，味道的好坏要说〈鲜美〉。"}, {"text": "这道题的答案很公正。", "explanation": "这里应该用〈正确〉。公正指公平无偏，答案的对错要说〈正确〉。"}, {"text": "教室里的桌椅摆得很公正。", "explanation": "这里应该用〈整齐〉。公正用于人、裁决和制度，摆放的整齐要说〈整齐〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0087a302-9e61-4b40-bf3e-cdd7e8f5a6fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11847, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "公正", "is_correct": true, "explanation": "正确：修饰“对待”的形容词，指一视同仁。"}, {"text": "随便", "is_correct": false, "explanation": "语域：“随便”口语化，与“法律面前”的书面语境不搭。"}, {"text": "任性", "is_correct": false, "explanation": "语义：“任性”指不顾道理，与法律要求的平等对待相反。"}, {"text": "偏心", "is_correct": false, "explanation": "语义：“偏心”指对人不一视同仁，与“人人都应”的说法矛盾。"}], "explanations": {"公正": "正确：修饰“对待”的形容词，指一视同仁。", "随便": "语域：“随便”口语化，与“法律面前”的书面语境不搭。", "任性": "语义：“任性”指不顾道理，与法律要求的平等对待相反。", "偏心": "语义：“偏心”指对人不一视同仁，与“人人都应”的说法矛盾。"}, "sentence_index": 6, "correct_answer": "公正"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个数字计算得很公正。", "explanation": "这里应该用〈准确〉。公正用于人、裁决和制度，计算的对错要说〈准确〉。"}, {"text": "这间教室很公正，窗户很大。", "explanation": "这里应该用〈宽敞〉。公正不用来形容空间，形容房间的大小要说〈宽敞〉。"}, {"text": "这朵花很公正，颜色很美。", "explanation": "这里应该用〈鲜艳〉。公正是评价人或制度的，形容花的颜色要说〈鲜艳〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0087a302-9e61-4b40-bf3e-cdd7e8f5a6fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11847, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "裁判公正的判了这场比赛的胜负。", "corrected_sentence": "裁判公正地判了这场比赛的胜负。", "error_description": "“公正”在句中修饰动词“判”，作状语应用“地”，不用“的”：应说“公正地判”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0087a302-9e61-4b40-bf3e-cdd7e8f5a6fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11847, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他这样做没公正，大家都不满意。", "corrected_sentence": "他这样做不公正，大家都不满意。", "error_description": "形容词的否定要用“不”，不用“没”：应说“不公正”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0087a302-9e61-4b40-bf3e-cdd7e8f5a6fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
