INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11848, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '960307d4-24f9-4acb-a09d-8179ea218fd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11848, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "在中文中，''密码''指用来验证身份或加密信息的秘密代码，通常由字符或数字组成。", "primary_collocate": null, "pronunciation": "mì mǎ", "ipa": "mi˥˩ ma˨˩˦", "syllable_count": 2, "sentences": [{"text": "这个保险箱只有输入正确的密码才能打开。", "target_word": "密码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我忘了手机的密码，打不开屏幕。", "target_word": "密码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请输入六位数字的密码，然后点确认。", "target_word": "密码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了安全，密码不要告诉别人。", "target_word": "密码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行卡的密码太简单，别人容易猜出来。", "target_word": "密码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每三个月换一次邮箱密码。", "target_word": "密码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个网站要求密码里有字母和数字。", "target_word": "密码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "密码输错三次，账号就会锁住。", "target_word": "密码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把电脑的密码写在了本子上。", "target_word": "密码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "登录账号时，要先输入用户名和密码。", "target_word": "密码", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "密码锁", "label": "复合"}, {"form": "密碼", "label": "繁体"}], "register": "中性", "sense_fingerprint": "验证身份或加密信息的秘密代码", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4275a2c9-4bff-40c5-ac87-bdb8abddd072') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11848, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "密码", "is_correct": true, "explanation": "正确：“输入正确的密码”指验证身份的秘密代码，与“才能打开”的语境相符。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机不能被“输入”来打开保险箱，“输入正确的手机”读不通。"}, {"text": "地图", "is_correct": false, "explanation": "语义：地图不能被“输入”，“输入正确的地图”读不通。"}, {"text": "水龙头", "is_correct": false, "explanation": "语义：水龙头不能被“输入”，“输入正确的水龙头”读不通。"}], "explanations": {"密码": "正确：“输入正确的密码”指验证身份的秘密代码，与“才能打开”的语境相符。", "手机": "语义：手机不能被“输入”来打开保险箱，“输入正确的手机”读不通。", "地图": "语义：地图不能被“输入”，“输入正确的地图”读不通。", "水龙头": "语义：水龙头不能被“输入”，“输入正确的水龙头”读不通。"}, "sentence_index": 0, "correct_answer": "密码"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我记住了一把密码，就能开门了。", "explanation": "这里应该用〈个〉。〈把〉用于有柄的器具，密码用〈个〉或〈组〉。"}, {"text": "请刷密码进入大楼。", "explanation": "这里应该用〈门禁卡〉。〈刷〉用于卡片，密码要说〈输入〉。"}, {"text": "我量了量密码的尺寸，很满意。", "explanation": "〈尺寸〉描述有形物体的大小，密码没有尺寸，描述它应说〈长度〉或〈位数〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '960307d4-24f9-4acb-a09d-8179ea218fd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11848, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "密码", "is_correct": true, "explanation": "正确：网站要求的是密码里包含字母和数字，「里」后面接的是这一对象。"}, {"text": "香蕉", "is_correct": false, "explanation": "语义：香蕉是水果，网站不会要求它含有字母和数字，句子说不通。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：「要求」带的内容应是条件或规则，天气不能作为网站要求的内容。"}, {"text": "窗户", "is_correct": false, "explanation": "配价：「要求」需要能被提出条件的内容，窗户是具体物件，不能被网站要求。"}], "explanations": {"密码": "正确：网站要求的是密码里包含字母和数字，「里」后面接的是这一对象。", "香蕉": "语义：香蕉是水果，网站不会要求它含有字母和数字，句子说不通。", "天气": "搭配：「要求」带的内容应是条件或规则，天气不能作为网站要求的内容。", "窗户": "配价：「要求」需要能被提出条件的内容，窗户是具体物件，不能被网站要求。"}, "sentence_index": 6, "correct_answer": "密码"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "请填写收货密码。", "explanation": "这里应该用〈地址〉。收货要填写的是地址，密码用于登录或解锁，不能用来收货。"}, {"text": "请安装新密码。", "explanation": "这里应该用〈设置〉。〈安装〉用于软件和设备，设置密码要说〈设置〉。"}, {"text": "他每天早上喝一口密码，精神很好。", "explanation": "这里应该用〈牛奶〉。〈喝〉的宾语必须是饮品或食物，密码不能喝，应换成〈牛奶〉这类可以饮用的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '960307d4-24f9-4acb-a09d-8179ea218fd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11848, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我重新设了一把邮箱密码。", "corrected_sentence": "我重新设了一个邮箱密码。", "error_description": "量词错误：「把」用于有柄的器具，不用于密码。密码应说「一个邮箱密码」，正确句为「我重新设了一个邮箱密码。」", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '960307d4-24f9-4acb-a09d-8179ea218fd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11848, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把邮箱密码吃了。", "corrected_sentence": "他把邮箱密码换了。", "error_description": "搭配错误：「吃」的宾语须是食物，密码不能吃。这里应改为「换」，正确句为「他把邮箱密码换了。」", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '960307d4-24f9-4acb-a09d-8179ea218fd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11854, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '499b1f08-7089-4fce-8232-e7e87bcbf736') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11854, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '499b1f08-7089-4fce-8232-e7e87bcbf736') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11854, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "地图是地理信息的图形表示，用来显示区域内的地形、道路、行政区划和地标等空间分布。", "primary_collocate": null, "pronunciation": "dì tú", "ipa": "ti˥˩ tʰu˧˥", "syllable_count": 2, "sentences": [{"text": "比如，一个人开车，一个人看地图，一个人找路。", "target_word": "地图", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "我看不懂这张地图。", "target_word": "地图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把地图放在桌子上。", "target_word": "地图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机里有一张地图，可以找路。", "target_word": "地图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在地图上找到了这个城市。", "target_word": "地图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张地图上有很多河。", "target_word": "地图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们看了一张中国地图。", "target_word": "地图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅行时，我总带着一张地图。", "target_word": "地图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上的路很多，我们走哪一条？", "target_word": "地图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把地图打开，看我们在哪里。", "target_word": "地图", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "张", "label": "量词"}, {"form": "电子地图", "label": "复合词"}, {"form": "世界地图", "label": "复合词"}, {"form": "中国地图", "label": "复合词"}], "register": "中性", "sense_fingerprint": "用图形显示地形、道路和区划的地理信息图", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d698ce0-810b-4db1-bf3a-88dde9784e24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11854, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地图", "is_correct": true, "explanation": "地图：用图形显示地形和道路，正是找路时要看的东西。"}, {"text": "收音机", "is_correct": false, "explanation": "搭配：收音机是用来听的，不能说“看收音机”。"}, {"text": "音乐", "is_correct": false, "explanation": "搭配：音乐要用耳朵听，不能说“看音乐”。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙与找路无关，看钥匙不能帮助找路，句意不通。"}], "explanations": {"地图": "地图：用图形显示地形和道路，正是找路时要看的东西。", "收音机": "搭配：收音机是用来听的，不能说“看收音机”。", "音乐": "搭配：音乐要用耳朵听，不能说“看音乐”。", "钥匙": "语义：钥匙与找路无关，看钥匙不能帮助找路，句意不通。"}, "sentence_index": 0, "correct_answer": "地图"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "路口立着的地图告诉我们现在几点了。", "explanation": "这里应该用〈钟〉。地图标出地理位置，不显示时间，看时间要用钟表。"}, {"text": "这份地图是我的新地址。", "explanation": "这里应该用〈地址〉。地图是画出地形的图，不是住址。"}, {"text": "这张地图是去年在海边唱的。", "explanation": "这里应该用〈歌〉。唱的是歌，地图不能唱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '499b1f08-7089-4fce-8232-e7e87bcbf736') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11854, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地图", "is_correct": true, "explanation": "地图：老师给学生看的中国地图，符合句意。"}, {"text": "课本", "is_correct": false, "explanation": "搭配：“张”不用于书本，应说“一本”，这里的量词搭配不当。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不是可以给人看的图，句意不通。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流是自然水体，不是纸上的图，不能用“一张”来量。"}], "explanations": {"地图": "地图：老师给学生看的中国地图，符合句意。", "课本": "搭配：“张”不用于书本，应说“一本”，这里的量词搭配不当。", "石头": "语义：石头不是可以给人看的图，句意不通。", "河流": "语义：河流是自然水体，不是纸上的图，不能用“一张”来量。"}, "sentence_index": 6, "correct_answer": "地图"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份地图教我们怎么用手机。", "explanation": "这里应该用〈说明书〉。说明书讲操作方法，地图只显示地理位置，不教人怎么用手机。"}, {"text": "我用地图给朋友发了一封信。", "explanation": "这里应该用〈邮箱〉。发信要用邮箱，地图只显示地理位置，不能用来发信。"}, {"text": "工人看着地图，把房子一间一间盖起来。", "explanation": "这里应该用〈图纸〉。盖房子要按建筑图纸，地图只标出地形和道路。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '499b1f08-7089-4fce-8232-e7e87bcbf736') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11854, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在地图找到了学校。", "corrected_sentence": "我在地图上找到了学校。", "error_description": "表示在平面的图上找到，“地图”后要加方位词“上”，应说“在地图上”。错误在于省略了“上”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '499b1f08-7089-4fce-8232-e7e87bcbf736') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11854, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张地图下标着学校。", "corrected_sentence": "这张地图上标着学校。", "error_description": "表示标在平面的图上，“地图”后应接方位词“上”，应说“地图上”。错误在于把“上”误写成“下”，“地图下”表示的方位不对。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '499b1f08-7089-4fce-8232-e7e87bcbf736') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
