INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11855, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "寻找，试图发现或得到某人或某物。", "primary_collocate": null, "pronunciation": "zhǎo", "ipa": "ʈʂaʊ̯˨˩˦", "syllable_count": 1, "sentences": [{"text": "比如，一个人开车，一个人看地图，一个人找路。", "target_word": "找", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "我到处找我的手机，可是没找到。", "target_word": "找", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在操场上找他的同学。", "target_word": "找", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子哭着找妈妈。", "target_word": "找", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗在花园里找它的球。", "target_word": "找", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我找了很久，还是没找到钥匙。", "target_word": "找", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她找过那家店，但是迷路了。", "target_word": "找", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请帮我找一下我的眼镜。", "target_word": "找", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们一起去找迷路的小猫吧。", "target_word": "找", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他正低头找掉在地上的笔。", "target_word": "找", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "找了", "label": "完成体"}, {"form": "找过", "label": "经历体"}, {"form": "找找", "label": "重叠"}, {"form": "寻找", "label": "复合词"}], "register": "中性", "sense_fingerprint": "为了发现或得到某人某物而寻找", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba150852-d904-4479-b91a-fa17ed59eed5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11855, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "找", "is_correct": true, "explanation": "正确答案：找（zhǎo），表示寻找。"}, {"text": "早", "is_correct": false, "explanation": "zǎo 与 zhǎo 声母不同（z 与 zh），意思是早晨。"}, {"text": "照", "is_correct": false, "explanation": "zhào（第四声）与 zhǎo（第三声）声调不同，意思是照射、照片。"}, {"text": "招", "is_correct": false, "explanation": "zhāo（第一声）与 zhǎo（第三声）声调不同，意思是招手、招呼。"}, {"text": "草", "is_correct": false, "explanation": "cǎo 与 zhǎo 声母不同（c 与 zh），意思是草。"}], "explanations": {"找": "正确答案：找（zhǎo），表示寻找。", "早": "zǎo 与 zhǎo 声母不同（z 与 zh），意思是早晨。", "照": "zhào（第四声）与 zhǎo（第三声）声调不同，意思是照射、照片。", "招": "zhāo（第一声）与 zhǎo（第三声）声调不同，意思是招手、招呼。", "草": "cǎo 与 zhǎo 声母不同（c 与 zh），意思是草。"}, "sentence_index": null, "correct_answer": "找"}, "level_3": {"options": [{"text": "修", "is_correct": false, "explanation": "语义：“修”指修建或维修，与句中“开车、看地图”的行路场景不合。"}, {"text": "找", "is_correct": true, "explanation": "正确答案：找，表示寻找道路。"}, {"text": "挖", "is_correct": false, "explanation": "语义：“挖”指挖掘，与“开车、看地图”的场景不合。"}, {"text": "扫", "is_correct": false, "explanation": "搭配：“扫路”指清扫路面，与句中找路的语境不合。"}], "explanations": {"修": "语义：“修”指修建或维修，与句中“开车、看地图”的行路场景不合。", "找": "正确答案：找，表示寻找道路。", "挖": "语义：“挖”指挖掘，与“开车、看地图”的场景不合。", "扫": "搭配：“扫路”指清扫路面，与句中找路的语境不合。"}, "sentence_index": 0, "correct_answer": "找"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这部电影找了很多人的心。", "explanation": "这里应该用〈打动〉。找是寻找，不能与“心”搭配表示感动，应说“打动很多人的心”。"}, {"text": "他在大家心中找了一个深刻的印象。", "explanation": "这里应该用〈留下〉。找是寻找，不能与“印象”搭配表示留下印象，应说“留下深刻的印象”。"}, {"text": "妈妈正在厨房找饭，我们马上就可以吃了。", "explanation": "这里应该用〈做〉。找是寻找，不表示烹饪，做饭要用“做”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa9ffce2-6301-4596-a3e0-50b80ebb44d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11855, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "找", "is_correct": true, "explanation": "正确答案：找（zhǎo），表示寻找。"}, {"text": "澡", "is_correct": false, "explanation": "zǎo 与 zhǎo 声母不同（z 与 zh），意思是洗澡。"}, {"text": "罩", "is_correct": false, "explanation": "zhào（第四声）与 zhǎo（第三声）声调不同，意思是罩子。"}, {"text": "爪", "is_correct": false, "explanation": "zhuǎ 与 zhǎo 韵母不同（ua 与 ao），意思是爪子。"}, {"text": "炒", "is_correct": false, "explanation": "chǎo 与 zhǎo 声母不同（ch 与 zh），意思是炒菜。"}], "explanations": {"找": "正确答案：找（zhǎo），表示寻找。", "澡": "zǎo 与 zhǎo 声母不同（z 与 zh），意思是洗澡。", "罩": "zhào（第四声）与 zhǎo（第三声）声调不同，意思是罩子。", "爪": "zhuǎ 与 zhǎo 韵母不同（ua 与 ao），意思是爪子。", "炒": "chǎo 与 zhǎo 声母不同（ch 与 zh），意思是炒菜。"}, "sentence_index": null, "correct_answer": "找"}, "level_3": {"options": [{"text": "拆", "is_correct": false, "explanation": "语义：“拆”指拆除，与句中“找过那家店”的寻找语境不合。"}, {"text": "找", "is_correct": true, "explanation": "正确答案：找，表示寻找那家店。"}, {"text": "关", "is_correct": false, "explanation": "语义：关闭营业，与句中“找过那家店，但是迷路了”的寻找语境不合。"}, {"text": "砸", "is_correct": false, "explanation": "搭配：“砸”多与“东西”“门窗”搭配，表示打坏，与“找过那家店”的说法不搭。"}], "explanations": {"拆": "语义：“拆”指拆除，与句中“找过那家店”的寻找语境不合。", "找": "正确答案：找，表示寻找那家店。", "关": "语义：关闭营业，与句中“找过那家店，但是迷路了”的寻找语境不合。", "砸": "搭配：“砸”多与“东西”“门窗”搭配，表示打坏，与“找过那家店”的说法不搭。"}, "sentence_index": 6, "correct_answer": "找"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他找了一声叹息。", "explanation": "这里应该用〈发出〉。找是寻找，不能与“叹息”搭配表示发出声音，应说“发出一声叹息”。"}, {"text": "妈妈正在用布找桌子。", "explanation": "这里应该用〈擦〉。找是寻找，不表示擦拭桌面。"}, {"text": "他每天晚上找一个小时的书。", "explanation": "这里应该用〈看〉。找是寻找，不表示阅读，读书要用“看书”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa9ffce2-6301-4596-a3e0-50b80ebb44d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11855, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天找了过张经理，但是他不在。", "corrected_sentence": "我昨天找过张经理，但是他不在。", "error_description": "错误在“找了过”。表示经历只用“过”，“了”与“过”不能同时用在动词后；正确说法是“找过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa9ffce2-6301-4596-a3e0-50b80ebb44d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11855, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他终于找了到那封信。", "corrected_sentence": "他终于找到了那封信。", "error_description": "错误在“找了到”。结果补语“到”必须紧跟动词，应为“找到”，再加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa9ffce2-6301-4596-a3e0-50b80ebb44d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11860, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "赢", "is_correct": true, "explanation": "“赢”与“输”在比赛胜负上正好相对，是反义词。"}, {"text": "跑", "is_correct": false, "explanation": "“跑”指快速移动，与“输”没有反义关系。"}, {"text": "写", "is_correct": false, "explanation": "“写”指书写文字，与“输”没有反义关系。"}, {"text": "吃", "is_correct": false, "explanation": "“吃”指把食物咽下，与“输”没有反义关系。"}], "correct_answer": "赢", "explanations": {"赢": "“赢”与“输”在比赛胜负上正好相对，是反义词。", "跑": "“跑”指快速移动，与“输”没有反义关系。", "写": "“写”指书写文字，与“输”没有反义关系。", "吃": "“吃”指把食物咽下，与“输”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1481fe-33c0-4c92-b450-0540642db1fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11860, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "赢", "is_correct": true, "explanation": "“赢”与“输”在比赛胜负上正好相对，是反义词。"}, {"text": "唱", "is_correct": false, "explanation": "“唱”指发出歌声，与“输”没有反义关系。"}, {"text": "走", "is_correct": false, "explanation": "“走”指行走或离开，与“输”没有反义关系。"}, {"text": "读", "is_correct": false, "explanation": "“读”指看文字并发出声音，与“输”没有反义关系。"}], "correct_answer": "赢", "explanations": {"赢": "“赢”与“输”在比赛胜负上正好相对，是反义词。", "唱": "“唱”指发出歌声，与“输”没有反义关系。", "走": "“走”指行走或离开，与“输”没有反义关系。", "读": "“读”指看文字并发出声音，与“输”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1481fe-33c0-4c92-b450-0540642db1fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11860, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在比赛、竞争或争论中失败，与“赢”相对。", "primary_collocate": null, "pronunciation": "shū", "ipa": "ʂu˥", "syllable_count": 1, "sentences": [{"text": "这场比赛我们输得很惨。", "target_word": "输", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次辩论他们输得心服口服。", "target_word": "输", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不肯承认自己输了。", "target_word": "输", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们队昨天输了比赛。", "target_word": "输", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他下棋总是输给哥哥。", "target_word": "输", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这场球我们输了三分。", "target_word": "输", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她不怕输，只怕不努力。", "target_word": "输", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛输了，大家都很难过。", "target_word": "输", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们在辩论中输给了对手。", "target_word": "输", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你输了，该请我吃饭。", "target_word": "输", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "输了", "label": "体标（了）"}, {"form": "输过", "label": "体标（过）"}, {"form": "输掉", "label": "复合词"}, {"form": "输赢", "label": "复合词"}], "register": "通用", "sense_fingerprint": "在比赛、竞争或争论中失败，与赢相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0a0f57a-406e-4360-81b4-dcb946f1ae89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11860, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "输", "is_correct": true, "explanation": "shū（第一声），意思是在比赛、竞争中失败，与“赢”相对，是正确答案。"}, {"text": "熟", "is_correct": false, "explanation": "shú（第二声）与 shū（第一声）声调不同，意思是熟悉或成熟。"}, {"text": "属", "is_correct": false, "explanation": "shǔ（第三声）与 shū（第一声）声调不同，意思是属于。"}, {"text": "数", "is_correct": false, "explanation": "shù（第四声）与 shū（第一声）声调不同，意思是数字。"}, {"text": "树", "is_correct": false, "explanation": "shù（第四声）与 shū（第一声）声调不同，意思是树木。"}], "explanations": {"输": "shū（第一声），意思是在比赛、竞争中失败，与“赢”相对，是正确答案。", "熟": "shú（第二声）与 shū（第一声）声调不同，意思是熟悉或成熟。", "属": "shǔ（第三声）与 shū（第一声）声调不同，意思是属于。", "数": "shù（第四声）与 shū（第一声）声调不同，意思是数字。", "树": "shù（第四声）与 shū（第一声）声调不同，意思是树木。"}, "sentence_index": null, "correct_answer": "输"}, "level_3": {"options": [{"text": "输", "is_correct": true, "explanation": "“输得很惨”指比赛失利，与“这场比赛”的语境相合。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写”指书写文字，“写得很惨”与比赛无关。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不用于描述比赛结果，“唱得很惨”不成立。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”指烹饪，与比赛无关。"}], "explanations": {"输": "“输得很惨”指比赛失利，与“这场比赛”的语境相合。", "写": "语义：“写”指书写文字，“写得很惨”与比赛无关。", "唱": "搭配：“唱”不用于描述比赛结果，“唱得很惨”不成立。", "煮": "语义：“煮”指烹饪，与比赛无关。"}, "sentence_index": 0, "correct_answer": "输"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台手机输了，屏幕碎成了好几块。", "explanation": "这里应该用〈摔坏〉。输用于比赛、竞争中的胜负，器物损坏要用摔坏。"}, {"text": "这次实验输了，我们只好重新来过。", "explanation": "这里应该用〈失败〉。输用于比赛、竞争中的胜负，实验没有成功要说失败。"}, {"text": "我的钥匙输了，找了一早上。", "explanation": "这里应该用〈丢〉。输只用于比赛、竞争等胜负，东西丢失要用丢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1481fe-33c0-4c92-b450-0540642db1fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11860, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "输", "is_correct": true, "explanation": "shū（第一声），意思是在比赛、竞争中失败，与“赢”相对，是正确答案。"}, {"text": "暑", "is_correct": false, "explanation": "shǔ（第三声）与 shū（第一声）声调不同，意思是炎热的暑天。"}, {"text": "竖", "is_correct": false, "explanation": "shù（第四声）与 shū（第一声）声调不同，意思是竖直、直立。"}, {"text": "收", "is_correct": false, "explanation": "shōu（第一声）与 shū（第一声）声调相同，但韵母不同（ou 与 u），意思是收取。"}], "explanations": {"输": "shū（第一声），意思是在比赛、竞争中失败，与“赢”相对，是正确答案。", "暑": "shǔ（第三声）与 shū（第一声）声调不同，意思是炎热的暑天。", "竖": "shù（第四声）与 shū（第一声）声调不同，意思是竖直、直立。", "收": "shōu（第一声）与 shū（第一声）声调相同，但韵母不同（ou 与 u），意思是收取。"}, "sentence_index": null, "correct_answer": "输"}, "level_3": {"options": [{"text": "输", "is_correct": true, "explanation": "“不怕输”与“只怕不努力”相对应，表示不怕失败，符合句意。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”是丢弃的意思，“不怕扔”与后半句的语境不符，句子说不通。"}, {"text": "砍", "is_correct": false, "explanation": "语义：“砍”指用刀斧切断，“不怕砍”与句子表达的态度不符。"}, {"text": "撕", "is_correct": false, "explanation": "搭配：“撕”不能与“怕”构成合理的动宾关系，“不怕撕”不成立。"}], "explanations": {"输": "“不怕输”与“只怕不努力”相对应，表示不怕失败，符合句意。", "扔": "语义：“扔”是丢弃的意思，“不怕扔”与后半句的语境不符，句子说不通。", "砍": "语义：“砍”指用刀斧切断，“不怕砍”与句子表达的态度不符。", "撕": "搭配：“撕”不能与“怕”构成合理的动宾关系，“不怕撕”不成立。"}, "sentence_index": 6, "correct_answer": "输"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他输了一下午的时间在网上。", "explanation": "这里应该用〈浪费〉。输用于比赛、竞争中的胜负，时间白白耗去要用浪费。"}, {"text": "他因为事故输了听力。", "explanation": "这里应该用〈丧失〉。输用于比赛、竞争中的胜负，身体机能或能力的失去要用丧失。"}, {"text": "他输了一个好朋友，心里很难过。", "explanation": "这里应该用〈失去〉。输表示竞争中的失败，失去朋友要用失去。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1481fe-33c0-4c92-b450-0540642db1fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11860, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这一次我们输了给隔壁班。", "corrected_sentence": "这一次我们输给了隔壁班。", "error_description": "错误形式“输了给”，正确形式“输给了”。“输给”是固定的动词加“给”的组合，“了”应放在“给”的后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1481fe-33c0-4c92-b450-0540642db1fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11860, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们输了掉那场比赛。", "corrected_sentence": "我们输掉了那场比赛。", "error_description": "错误形式“输了掉”，正确形式“输掉了”。“输掉”是动词加结果补语的复合词，“了”要放在“掉”的后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1481fe-33c0-4c92-b450-0540642db1fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
