INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11863, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "进行某项工作或活动", "primary_collocate": null, "pronunciation": "zuò shì", "ipa": "tswo˥˩ ʂʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "大家一起做事，城市会更美丽。", "target_word": "做事", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "他做事很认真，从不迟到。", "target_word": "做事", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "周末我们一起做事，很快就完成了。", "target_word": "做事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "志愿者们在社区里做事，帮助老人。", "target_word": "做事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们学会做事，也学会合作。", "target_word": "做事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每天忙着做事，没有时间休息。", "target_word": "做事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家分工做事，活儿干得很快。", "target_word": "做事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "会议结束后，我们马上去做事。", "target_word": "做事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让同学们一起做事，不要只说话。", "target_word": "做事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校组织学生到农村做事，体验生活。", "target_word": "做事", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "做了事", "label": "体标（了）"}, {"form": "做过事", "label": "体标（过）"}], "register": "口语", "sense_fingerprint": "做事：参与、进行某项具体的工作或活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '344206f6-976f-4874-8f0d-c04e78e16151') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11863, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "做事", "is_correct": true, "explanation": "正确。做事指进行某项工作或活动。"}, {"text": "错事", "is_correct": false, "explanation": "cuò（第四声）与 zuò 声母不同（c 与 z），意思是做错的事。"}, {"text": "作诗", "is_correct": false, "explanation": "shī（第一声）与 shì（第四声）声调不同，意思是写诗。"}, {"text": "坐实", "is_correct": false, "explanation": "shí（第二声）与 shì 声调不同，意思是证实、确定。"}], "explanations": {"做事": "正确。做事指进行某项工作或活动。", "错事": "cuò（第四声）与 zuò 声母不同（c 与 z），意思是做错的事。", "作诗": "shī（第一声）与 shì（第四声）声调不同，意思是写诗。", "坐实": "shí（第二声）与 shì 声调不同，意思是证实、确定。"}, "sentence_index": null, "correct_answer": "做事"}, "level_3": {"options": [{"text": "做事", "is_correct": true, "explanation": "正确。“大家一起做事”指共同进行有益的工作，与“城市会更美丽”的结果相符。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：大家一起睡觉与“城市会更美丽”之间没有因果关系。"}, {"text": "吵架", "is_correct": false, "explanation": "语义：大家一起吵架不会让城市变美，与后句的结果矛盾。"}, {"text": "发呆", "is_correct": false, "explanation": "搭配：“一起发呆”后接“城市会更美丽”，结果语义不通。"}], "explanations": {"做事": "正确。“大家一起做事”指共同进行有益的工作，与“城市会更美丽”的结果相符。", "睡觉": "语义：大家一起睡觉与“城市会更美丽”之间没有因果关系。", "吵架": "语义：大家一起吵架不会让城市变美，与后句的结果矛盾。", "发呆": "搭配：“一起发呆”后接“城市会更美丽”，结果语义不通。"}, "sentence_index": 0, "correct_answer": "做事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我下午要去派出所做事，先把身份证带齐。", "explanation": "这里应该用〈办事〉。去派出所、银行等处理手续时用“办事”，“做事”指进行工作或活动，不用于办理手续。"}, {"text": "我们放假了，想去商场做事，买几件新衣服。", "explanation": "这里应该用〈购物〉。逛商场买衣服要说“购物”或“买东西”，“做事”指进行工作或活动，不指购买。"}, {"text": "他去理发店做事，剪了一个新发型。", "explanation": "这里应该用〈理发〉。去理发店剪头发要说“理发”，“做事”不指理发。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d6a21e1-dfee-4f95-afc8-4b11b1c0d1a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11863, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "做事", "is_correct": true, "explanation": "正确。“大家分工做事”指分担工作，与“活儿干得很快”相符。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：分工唱歌不能让活儿干得快，与后句矛盾。"}, {"text": "打盹", "is_correct": false, "explanation": "语义：打盹不是可以分工的工作，与“活儿干得很快”矛盾。"}, {"text": "休息", "is_correct": false, "explanation": "搭配：“分工”后接的应是可分担的工作，“休息”不能分工。"}], "explanations": {"做事": "正确。“大家分工做事”指分担工作，与“活儿干得很快”相符。", "唱歌": "语义：分工唱歌不能让活儿干得快，与后句矛盾。", "打盹": "语义：打盹不是可以分工的工作，与“活儿干得很快”矛盾。", "休息": "搭配：“分工”后接的应是可分担的工作，“休息”不能分工。"}, "sentence_index": 6, "correct_answer": "做事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我周末去公园做事，拍了很多照片。", "explanation": "这里应该用〈拍照〉。在景点拍照要说“拍照”，“做事”不指拍摄。"}, {"text": "我去药店做事，买了一盒感冒药。", "explanation": "这里应该用〈买药〉。去药店买药要说“买药”，“做事”不指购买。"}, {"text": "我头发太长了，明天要去做事，剪短一点。", "explanation": "这里应该用〈理发〉。剪头发要说“理发”，“做事”指进行工作或活动，不指理发。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d6a21e1-dfee-4f95-afc8-4b11b1c0d1a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11863, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一直在做了事，从来不停下来。", "corrected_sentence": "他一直在做事，从来不停下来。", "error_description": "“做事”的“了”位置错误。“一直在……”表示进行中，不能接“了”，应说“一直在做事”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d6a21e1-dfee-4f95-afc8-4b11b1c0d1a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11863, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他做事得很快，大家都夸他。", "corrected_sentence": "他做事做得很快，大家都夸他。", "error_description": "补语结构错误。“做事”后的补语要用“做得……”，缺少“做”会使句子不通，应说“做事做得很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d6a21e1-dfee-4f95-afc8-4b11b1c0d1a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
