INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11865, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "指比赛或竞争中有胜利也有失败，结果不固定。", "primary_collocate": null, "pronunciation": "yǒu shū yǒu yíng", "ipa": "joʊ̯˨˩˦ ʂu˥˥ joʊ̯˨˩˦ iŋ˧˥", "syllable_count": 4, "sentences": [{"text": "我和哥哥下棋，有输有赢。", "target_word": "有输有赢", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这两个队水平差不多，比赛总是有输有赢。", "target_word": "有输有赢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们打了一年球，有输有赢，谁也没有一直赢。", "target_word": "有输有赢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "玩游戏有输有赢，别因为输了就不高兴。", "target_word": "有输有赢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛有输有赢，这很正常。", "target_word": "有输有赢", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个月我和朋友打牌，有输有赢，最后差不多。", "target_word": "有输有赢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们两个人比了五场，有输有赢。", "target_word": "有输有赢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小王和小李打乒乓球，总是有输有赢。", "target_word": "有输有赢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老朋友见面就下棋，几年来一直有输有赢。", "target_word": "有输有赢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们踢球水平差不多，常常有输有赢。", "target_word": "有输有赢", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "比赛或竞争中有胜有败，结果不固定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1031e19-faab-40d9-8d4c-621f2590ab55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11865, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有输有赢", "is_correct": true, "explanation": "正确。这里指两人下棋互有胜负，结果不固定。"}, {"text": "很好吃", "is_correct": false, "explanation": "语义：“很好吃”形容味道，不能用来说下棋的结果，句子不通。"}, {"text": "放在阳台", "is_correct": false, "explanation": "搭配：“放在阳台”针对物品，不能用来说下棋的结果。"}, {"text": "会唱歌", "is_correct": false, "explanation": "语义：“会唱歌”与下棋的胜负无关，句子不通。"}], "explanations": {"有输有赢": "正确。这里指两人下棋互有胜负，结果不固定。", "很好吃": "语义：“很好吃”形容味道，不能用来说下棋的结果，句子不通。", "放在阳台": "搭配：“放在阳台”针对物品，不能用来说下棋的结果。", "会唱歌": "语义：“会唱歌”与下棋的胜负无关，句子不通。"}, "sentence_index": 0, "correct_answer": "有输有赢"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司每个月的利润有输有赢。", "explanation": "这里应该用〈有赚有赔〉。有输有赢用于比赛或竞争的胜负，经营的盈亏要说有赚有赔。"}, {"text": "今年的气温有输有赢。", "explanation": "这里应该用〈有高有低〉。有输有赢只用于比赛或竞争，气温的起伏要说有高有低。"}, {"text": "他的病情这几天有输有赢。", "explanation": "这里应该用〈时好时坏〉。有输有赢指比赛结果，病情的变化要说时好时坏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25dba7a4-1b67-453f-ab61-ccae91d0c914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11865, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有输有赢", "is_correct": true, "explanation": "正确。这里指两人比赛五场，胜负交替出现。"}, {"text": "很漂亮", "is_correct": false, "explanation": "语义：“很漂亮”形容外表，不能说明比赛的结果。"}, {"text": "去上学", "is_correct": false, "explanation": "语义：“去上学”与五场比赛的胜负无关，句子不通。"}, {"text": "赢光", "is_correct": false, "explanation": "搭配：“赢光”指把对方的东西全部拿走，不用来描述比赛的场次结果。"}], "explanations": {"有输有赢": "正确。这里指两人比赛五场，胜负交替出现。", "很漂亮": "语义：“很漂亮”形容外表，不能说明比赛的结果。", "去上学": "语义：“去上学”与五场比赛的胜负无关，句子不通。", "赢光": "搭配：“赢光”指把对方的东西全部拿走，不用来描述比赛的场次结果。"}, "sentence_index": 6, "correct_answer": "有输有赢"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他处理这件事有输有赢。", "explanation": "这里应该用〈有轻有重〉。有输有赢只用于比赛或竞争，处理事情的分寸要说有轻有重。"}, {"text": "他讲故事时有输有赢，大家很喜欢听。", "explanation": "这里应该用〈有声有色〉。有输有赢只用于比赛或竞争，讲故事的精彩程度要说有声有色。"}, {"text": "这件事的经过有输有赢，大家听得很清楚。", "explanation": "这里应该用〈有头有尾〉。有输有赢指比赛结果，事情的始末完整要说有头有尾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25dba7a4-1b67-453f-ab61-ccae91d0c914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11865, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两家公司竞争激烈，很有输有赢。", "corrected_sentence": "这两家公司竞争激烈，有输有赢。", "error_description": "“有输有赢”是固定说法，前面不能加程度副词“很”修饰。正确的说法是直接说“有输有赢”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25dba7a4-1b67-453f-ab61-ccae91d0c914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11865, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们俩打牌，总是有输有赢了。", "corrected_sentence": "他们俩打牌，总是有输有赢。", "error_description": "“有输有赢”描述反复出现的胜负，本身不带“了”；加“了”表示完成，与“总是”表示的习惯性情况不符。正确的说法是“总是有输有赢”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25dba7a4-1b67-453f-ab61-ccae91d0c914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
