INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11867, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "画", "is_correct": false, "explanation": "画：与“连在一起”没有反义关系，“画”指用线条和颜色描绘形象。"}, {"text": "跑", "is_correct": false, "explanation": "跑：与“连在一起”没有反义关系，“跑”指快速移动双腿前进。"}, {"text": "断开", "is_correct": true, "explanation": "断开：与“连在一起”意思相反，指设备之间的连接被切断。"}, {"text": "跳", "is_correct": false, "explanation": "跳：与“连在一起”没有反义关系，“跳”指身体离开地面再落下。"}], "correct_answer": "断开", "explanations": {"画": "画：与“连在一起”没有反义关系，“画”指用线条和颜色描绘形象。", "跑": "跑：与“连在一起”没有反义关系，“跑”指快速移动双腿前进。", "断开": "断开：与“连在一起”意思相反，指设备之间的连接被切断。", "跳": "跳：与“连在一起”没有反义关系，“跳”指身体离开地面再落下。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cf1193-53d8-46f6-ba17-01097053aa32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11867, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用设备互相连接，以便交流或合作", "primary_collocate": null, "pronunciation": "lián zài yì qǐ", "ipa": "ljɛn tsaɪ i tɕʰi", "syllable_count": 4, "sentences": [{"text": "在虚拟世界里，人们用电脑或手机连在一起。", "target_word": "连在一起", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "公司的电脑都连在一起，工作很方便。", "target_word": "连在一起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们用网络连在一起开会。", "target_word": "连在一起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家里的手机和音箱连在一起了。", "target_word": "连在一起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让全班的平板连在一起上课。", "target_word": "连在一起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不同国家的同学用视频连在一起学习。", "target_word": "连在一起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把手机和电视连在一起看比赛。", "target_word": "连在一起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些机器连在一起，可以一起工作。", "target_word": "连在一起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多玩家在网上连在一起玩游戏。", "target_word": "连在一起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院的电脑连在一起，医生能看病人的信息。", "target_word": "连在一起", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "连在一起了", "label": "完成体"}, {"form": "連在一起", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用设备或网络互相连接以便交流合作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '618ae9a4-f14e-4a14-a72f-8b79178904af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11867, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "蒸", "is_correct": false, "explanation": "搭配：“蒸”用于食物，不能说“用电脑或手机蒸”。"}, {"text": "连在一起", "is_correct": true, "explanation": "连在一起：用设备互相连接，以便交流或合作，与“用电脑或手机”的语境相符。"}, {"text": "散步", "is_correct": false, "explanation": "搭配：“散步”是人在路上慢走，不能用电脑或手机来散步。"}, {"text": "拆", "is_correct": false, "explanation": "配价：“拆”要带宾语，如“拆机器”，这里缺少宾语，句子说不通。"}], "explanations": {"蒸": "搭配：“蒸”用于食物，不能说“用电脑或手机蒸”。", "连在一起": "连在一起：用设备互相连接，以便交流或合作，与“用电脑或手机”的语境相符。", "散步": "搭配：“散步”是人在路上慢走，不能用电脑或手机来散步。", "拆": "配价：“拆”要带宾语，如“拆机器”，这里缺少宾语，句子说不通。"}, "sentence_index": 0, "correct_answer": "连在一起"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这几条线索连在一起，就能看出事情的真相。", "explanation": "这里说的是把线索联系起来思考，是“连在一起”的另一个义项；本句没有用设备互相连接的意思。"}, {"text": "两个人的心连在一起，互相理解。", "explanation": "这里说的是人心相通，属于“连在一起”的感情义项，不是设备之间的互相连接。"}, {"text": "小王连在一起迟到了三次。", "explanation": "这里应该用〈连续〉。“连在一起”指事物相互接合，不表示时间上接连不断。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cf1193-53d8-46f6-ba17-01097053aa32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11867, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "翻译", "is_correct": false, "explanation": "语义：“翻译”指把一种语言转换成另一种语言，与“手机和电视”不搭，句子说不通。"}, {"text": "连在一起", "is_correct": true, "explanation": "连在一起：用设备互相连接，使手机和电视能一起使用，与“看比赛”的语境相符。"}, {"text": "尝", "is_correct": false, "explanation": "搭配：“尝”一般用于食物，不能说“尝手机和电视”。"}, {"text": "跑", "is_correct": false, "explanation": "搭配：“跑”指人或动物快速移动，手机和电视不能跑。"}], "explanations": {"翻译": "语义：“翻译”指把一种语言转换成另一种语言，与“手机和电视”不搭，句子说不通。", "连在一起": "连在一起：用设备互相连接，使手机和电视能一起使用，与“看比赛”的语境相符。", "尝": "搭配：“尝”一般用于食物，不能说“尝手机和电视”。", "跑": "搭配：“跑”指人或动物快速移动，手机和电视不能跑。"}, "sentence_index": 6, "correct_answer": "连在一起"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这两根绳子连在一起，就能拉动重物。", "explanation": "这里说的是物体接合成整体，是“连在一起”的另一个义项；本句讲的是绳子，与用设备互相连接的义项不同。"}, {"text": "这两种药连在一起，会产生危险。", "explanation": "这里应该用〈混在一起〉。“连在一起”指物体接合，药物相混要说“混在一起”。"}, {"text": "同学们连在一起排队。", "explanation": "这里说的是人身体相连排队，属于“连在一起”的物理接合义项，不是用设备互相连接。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cf1193-53d8-46f6-ba17-01097053aa32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11867, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "办公室的电脑把连在一起了，大家就能共享资料。", "corrected_sentence": "办公室的电脑连在一起了，大家就能共享资料。", "error_description": "“把”字句中，“把”后必须带宾语。这里“把”后直接接动词“连”，没有宾语，应去掉“把”，说“电脑连在一起了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cf1193-53d8-46f6-ba17-01097053aa32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11867, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这几台服务器很连在一起，数据传得很快。", "corrected_sentence": "这几台服务器都连在一起，数据传得很快。", "error_description": "“很”是程度副词，不能修饰“连在一起”这类动词结构；应去掉“很”，可用“都”表示范围，正确为“都连在一起”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cf1193-53d8-46f6-ba17-01097053aa32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11871, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68dd2c7e-def6-4884-8dc1-6e403cd7c618') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11871, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68dd2c7e-def6-4884-8dc1-6e403cd7c618') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11871, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "战胜、击败对手或敌人。", "primary_collocate": null, "pronunciation": "dǎ bài", "ipa": "ta˨˩ pai̯˥˩", "syllable_count": 2, "sentences": [{"text": "比如，要打败一个很强的怪物，一个人很难成功，但五个人一起计划、互相帮助，就容易多了。", "target_word": "打败", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "我们队打败了对手，进了决赛。", "target_word": "打败", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想打败最强的敌人。", "target_word": "打败", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这支军队打败了入侵的敌人。", "target_word": "打败", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明的哥哥打败了所有的对手。", "target_word": "打败", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弱小的国家有时也能打败强大的敌人。", "target_word": "打败", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用智慧打败了比他强的人。", "target_word": "打败", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "勇敢的战士打败了凶恶的敌人。", "target_word": "打败", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻的国王打败了邻国的军队。", "target_word": "打败", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们一定要打败这个强大的对手。", "target_word": "打败", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "打败了", "label": "体标"}, {"form": "打败过", "label": "体标"}, {"form": "打不败", "label": "可能补语"}], "register": "中性", "sense_fingerprint": "战胜、击败对手或敌人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c87be3b-a562-4471-8594-119adfda2aa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11871, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "打败", "is_correct": true, "explanation": "正确：“要打败一个很强的怪物”指战胜、击败敌人，符合句意。"}, {"text": "打量", "is_correct": false, "explanation": "语义：“打量”指仔细看，不能战胜怪物，句意不通。"}, {"text": "打扮", "is_correct": false, "explanation": "搭配：“打扮”用于装扮人或物，不能与怪物的战斗语境搭配。"}, {"text": "打开", "is_correct": false, "explanation": "配价：“打开”的宾语须是可以开启的物体，怪物不能被打开。"}], "explanations": {"打败": "正确：“要打败一个很强的怪物”指战胜、击败敌人，符合句意。", "打量": "语义：“打量”指仔细看，不能战胜怪物，句意不通。", "打扮": "搭配：“打扮”用于装扮人或物，不能与怪物的战斗语境搭配。", "打开": "配价：“打开”的宾语须是可以开启的物体，怪物不能被打开。"}, "sentence_index": 0, "correct_answer": "打败"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们的球队打败了这场比赛。", "explanation": "这里应该用〈赢〉。赢的对象可以是比赛，打败的对象必须是对手或敌人。"}, {"text": "炸弹打败了这座城市。", "explanation": "这里应该用〈摧毁〉。炸弹毁坏城市要用摧毁，打败只用于对手或敌人。"}, {"text": "子弹打败了目标。", "explanation": "这里应该用〈击中〉。子弹打到目标要用击中，打败的对象须是有抵抗力的对手。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68dd2c7e-def6-4884-8dc1-6e403cd7c618') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11871, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "打败", "is_correct": true, "explanation": "正确：“用智慧打败了比他强的人”表示战胜对手，符合句意。"}, {"text": "打伤", "is_correct": false, "explanation": "搭配：“用智慧”不能打伤人，“打伤”指用力击伤身体。"}, {"text": "打碎", "is_correct": false, "explanation": "语义：“打碎”指弄破物体，与“比他强的人”不符，句意不通。"}, {"text": "打扫", "is_correct": false, "explanation": "配价：“打扫”的宾语须是场所或物品，不能用于人。"}], "explanations": {"打败": "正确：“用智慧打败了比他强的人”表示战胜对手，符合句意。", "打伤": "搭配：“用智慧”不能打伤人，“打伤”指用力击伤身体。", "打碎": "语义：“打碎”指弄破物体，与“比他强的人”不符，句意不通。", "打扫": "配价：“打扫”的宾语须是场所或物品，不能用于人。"}, "sentence_index": 6, "correct_answer": "打败"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一下午打败了三张桌子。", "explanation": "这里应该用〈搬〉。搬桌子要用搬，“打败”的对象须是对手或敌人，不能用于桌子。"}, {"text": "我们打败了这本书。", "explanation": "这里应该用〈读完〉。读完书要说读完，“打败”的对象须是对手或敌人，不能用于书。"}, {"text": "小狗打败了那块石头。", "explanation": "这里应该用〈踢〉。踢石头要用踢，“打败”的对象须是对手或敌人，不能用于石头。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68dd2c7e-def6-4884-8dc1-6e403cd7c618') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11871, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们队去年打败过了这支球队。", "corrected_sentence": "我们队去年打败过这支球队。", "error_description": "体标叠用：表示经历用“过”，不能再加“了”。应说“打败过这支球队”，不说“打败过了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68dd2c7e-def6-4884-8dc1-6e403cd7c618') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11871, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这支军队被敌人打败着了。", "corrected_sentence": "这支军队被敌人打败了。", "error_description": "错误在于体标的叠用。“打败”表示一次性的结果，不表示持续，不能加“着”；应说“被敌人打败了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68dd2c7e-def6-4884-8dc1-6e403cd7c618') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11872, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "弱", "is_correct": true, "explanation": "正确：“弱”与“强”在“超过一般水平”的意义上互为反义。"}, {"text": "温柔", "is_correct": false, "explanation": "“温柔”形容性情，与“很强”的程度义没有反义关系。"}, {"text": "便宜", "is_correct": false, "explanation": "“便宜”说价格，与“很强”无反义关系。"}, {"text": "清楚", "is_correct": false, "explanation": "“清楚”形容明白、分明，与“很强”无反义关系。"}], "correct_answer": "弱", "explanations": {"弱": "正确：“弱”与“强”在“超过一般水平”的意义上互为反义。", "温柔": "“温柔”形容性情，与“很强”的程度义没有反义关系。", "便宜": "“便宜”说价格，与“很强”无反义关系。", "清楚": "“清楚”形容明白、分明，与“很强”无反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68dd2c7e-def6-4884-8dc1-6e403cd7c618') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11872, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "弱", "is_correct": true, "explanation": "正确：“弱”与“强”在“超过一般水平”的意义上互为反义。"}, {"text": "慢", "is_correct": false, "explanation": "“慢”说速度，与“很强”无反义关系。"}, {"text": "亮", "is_correct": false, "explanation": "“亮”说光线或颜色，与“很强”无反义关系。"}, {"text": "整齐", "is_correct": false, "explanation": "“整齐”说排列有序，与“很强”无反义关系。"}], "correct_answer": "弱", "explanations": {"弱": "正确：“弱”与“强”在“超过一般水平”的意义上互为反义。", "慢": "“慢”说速度，与“很强”无反义关系。", "亮": "“亮”说光线或颜色，与“很强”无反义关系。", "整齐": "“整齐”说排列有序，与“很强”无反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68dd2c7e-def6-4884-8dc1-6e403cd7c618') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11872, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容程度非常高，超过一般水平。", "primary_collocate": null, "pronunciation": "hěn qiáng", "ipa": "xən˨˩ tɕʰjɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "比如，要打败一个很强的怪物，一个人很难成功，但五个人一起计划、互相帮助，就容易多了。", "target_word": "很强", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这家公司的竞争力很强，所以客人越来越多。", "target_word": "很强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的责任心很强，老师交的事总能做好。", "target_word": "很强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个手机的信号很强，山上也能打电话。", "target_word": "很强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的学习能力很强，一看就会。", "target_word": "很强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天中午的阳光很强，出门要戴帽子。", "target_word": "很强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种药的药效很强，一天只能吃一次。", "target_word": "很强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的好奇心很强，什么都想问一问。", "target_word": "很强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛，对手的实力很强，我们要认真准备。", "target_word": "很强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天风很强，我的帽子飞走了。", "target_word": "很强", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "很強", "label": "繁体"}], "register": "中性", "sense_fingerprint": "程度高：形容能力、信号、效果等超过一般水平", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c87be3b-a562-4471-8594-119adfda2aa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11872, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "很强", "is_correct": true, "explanation": "正确：很强形容怪物的力量超过一般水平，与后文“一个人很难成功”相合。"}, {"text": "很弱", "is_correct": false, "explanation": "语义：“很弱”与后文“一个人很难成功”的语境相反，怪物若很弱就不难打败。"}, {"text": "很便宜", "is_correct": false, "explanation": "搭配：“便宜”说价格，不用来形容怪物。"}, {"text": "很干净", "is_correct": false, "explanation": "搭配：“干净”不用来形容怪物的力量或性质。"}], "explanations": {"很强": "正确：很强形容怪物的力量超过一般水平，与后文“一个人很难成功”相合。", "很弱": "语义：“很弱”与后文“一个人很难成功”的语境相反，怪物若很弱就不难打败。", "很便宜": "搭配：“便宜”说价格，不用来形容怪物。", "很干净": "搭配：“干净”不用来形容怪物的力量或性质。"}, "sentence_index": 0, "correct_answer": "很强"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这间屋子的面积很强，住三个人正好。", "explanation": "这里应该用〈大〉。面积是尺寸，要用“大”；“很强”只用于能力、效果等超过一般水平的情况。"}, {"text": "他的身高很强，在班里排第一。", "explanation": "这里应该用〈高〉。身高是纵向的高度，要用“高”；“很强”不用来说身高。"}, {"text": "这条河很强，两岸都是树。", "explanation": "这里应该用〈长〉。河的长度要用“长”，“很强”不用于说长度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68dd2c7e-def6-4884-8dc1-6e403cd7c618') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11872, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "很强", "is_correct": true, "explanation": "正确：很强形容药效的作用超过一般水平，与“一天只能吃一次”相合。"}, {"text": "很新鲜", "is_correct": false, "explanation": "搭配：“新鲜”说食物的状态，不用来形容药效。"}, {"text": "很甜", "is_correct": false, "explanation": "搭配：“甜”说味道，不用来形容药效。"}, {"text": "很聪明", "is_correct": false, "explanation": "语义：药没有智力，“很聪明”无法形容药效。"}], "explanations": {"很强": "正确：很强形容药效的作用超过一般水平，与“一天只能吃一次”相合。", "很新鲜": "搭配：“新鲜”说食物的状态，不用来形容药效。", "很甜": "搭配：“甜”说味道，不用来形容药效。", "很聪明": "语义：药没有智力，“很聪明”无法形容药效。"}, "sentence_index": 6, "correct_answer": "很强"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家离学校很强，每天要坐一个小时的车。", "explanation": "这里应该用〈远〉。距离要用“远”，“很强”不用来说距离。"}, {"text": "这次台风造成的损失很强，很多房子都倒了。", "explanation": "这里应该用〈严重〉。损失的程度要用“严重”，“很强”只用于能力、效果等超过一般水平的情况。"}, {"text": "这袋大米很强，我一个人提不动。", "explanation": "这里应该用〈重〉。物体的重量要用“重”，“很强”不用于说重量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68dd2c7e-def6-4884-8dc1-6e403cd7c618') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11872, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他有很强力气，能搬动这张桌子。", "corrected_sentence": "他有很强的力气，能搬动这张桌子。", "error_description": "的字缺失：“很强”修饰名词“力气”时要加“的”，应说“很强的力气”，不说“很强力气”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68dd2c7e-def6-4884-8dc1-6e403cd7c618') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11872, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个孩子的记忆力太很强，老师讲过的内容都记得住。", "corrected_sentence": "这个孩子的记忆力很强，老师讲过的内容都记得住。", "error_description": "程度副词叠用：“太”和“很”都表示程度，不能同时修饰“强”。应说“很强”，不说“太很强”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68dd2c7e-def6-4884-8dc1-6e403cd7c618') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
