INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11875, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "两个或以上的人彼此为对方提供帮助，共同完成事情。", "primary_collocate": null, "pronunciation": "hù xiāng bāng zhù", "ipa": "xu˥˩ ɕjɑŋ˥ pɑŋ˥ ʈʂu˥˩", "syllable_count": 4, "sentences": [{"text": "比如，要打败一个很强的怪物，一个人很难成功，但五个人一起计划、互相帮助，就容易多了。", "target_word": "互相帮助", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "同学们在学习上要互相帮助。", "target_word": "互相帮助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居之间互相帮助，生活就会更方便。", "target_word": "互相帮助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们小组的人互相帮助，很快做完了作业。", "target_word": "互相帮助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做事情的时候，朋友应该互相帮助。", "target_word": "互相帮助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两家公司互相帮助，一起完成了这个工作。", "target_word": "互相帮助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爬山的时候，大家互相帮助，最后都到了山顶。", "target_word": "互相帮助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的团队里，每个人都愿意互相帮助。", "target_word": "互相帮助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同事们互相帮助，把问题很快解决了。", "target_word": "互相帮助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校希望学生们学会互相帮助。", "target_word": "互相帮助", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "互相幫助", "label": "繁体"}], "register": "中性", "sense_fingerprint": "多人彼此帮助，合作把事情完成", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c87be3b-a562-4471-8594-119adfda2aa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11875, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "互相帮助", "is_correct": true, "explanation": "正确：“一起计划”与“互相帮助”呼应，表示几个人彼此帮忙、共同完成事情。"}, {"text": "独自完成", "is_correct": false, "explanation": "语义：与“五个人一起计划”矛盾，句子强调合作，不能说独自完成。"}, {"text": "争吵", "is_correct": false, "explanation": "语义：争吵会让事情更难，与“就容易多了”的结果相反。"}, {"text": "推辞", "is_correct": false, "explanation": "语义：推辞是不肯接受别人的邀请或好意，与“一起计划”“就容易多了”的合作语境不符。"}], "explanations": {"互相帮助": "正确：“一起计划”与“互相帮助”呼应，表示几个人彼此帮忙、共同完成事情。", "独自完成": "语义：与“五个人一起计划”矛盾，句子强调合作，不能说独自完成。", "争吵": "语义：争吵会让事情更难，与“就容易多了”的结果相反。", "推辞": "语义：推辞是不肯接受别人的邀请或好意，与“一起计划”“就容易多了”的合作语境不符。"}, "sentence_index": 0, "correct_answer": "互相帮助"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这些企业每年互相帮助山区的学校。", "explanation": "这里应该用〈资助〉。互相帮助指双方彼此帮忙，企业向学校提供经费是单方面的，应该用“资助”。"}, {"text": "家长们一直互相帮助孩子们学画画。", "explanation": "这里应该用〈支持〉。互相帮助指彼此帮忙，家长对孩子是单方面的鼓励和支持，应该用“支持”。"}, {"text": "老师们每天互相帮助学生写作文。", "explanation": "这里应该用〈指导〉。互相帮助要求双方彼此帮忙，老师教学生写作文是单向的，应该用“指导”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68dd2c7e-def6-4884-8dc1-6e403cd7c618') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11875, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "互相帮助", "is_correct": true, "explanation": "正确：“爬山”与“最后都到了山顶”说明大家彼此帮忙、共同前进。"}, {"text": "各自放弃", "is_correct": false, "explanation": "语义：与“最后都到了山顶”矛盾，各自放弃就不可能大家都到达山顶。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：大家都拒绝（不肯做），就不会“最后都到了山顶”，与语境矛盾。"}, {"text": "独自下山", "is_correct": false, "explanation": "语义：独自下山与“大家”以及“最后都到了山顶”的说法矛盾。"}], "explanations": {"互相帮助": "正确：“爬山”与“最后都到了山顶”说明大家彼此帮忙、共同前进。", "各自放弃": "语义：与“最后都到了山顶”矛盾，各自放弃就不可能大家都到达山顶。", "拒绝": "语义：大家都拒绝（不肯做），就不会“最后都到了山顶”，与语境矛盾。", "独自下山": "语义：独自下山与“大家”以及“最后都到了山顶”的说法矛盾。"}, "sentence_index": 6, "correct_answer": "互相帮助"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "几位亲戚互相帮助病中的老人去医院。", "explanation": "这里应该用〈陪伴〉。互相帮助指彼此帮忙，亲戚陪着病中的老人去医院是单方面的，应该用“陪伴”。"}, {"text": "我的父母一直互相帮助我。", "explanation": "这里应该用〈照顾〉。互相帮助要求双方彼此帮忙，父母对孩子是单方面的照顾，应该用“照顾”。"}, {"text": "几位同学常常互相帮助他，让他很有信心。", "explanation": "这里应该用〈鼓励〉。互相帮助指双方彼此帮忙，同学给他信心是单方面的，应该用“鼓励”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68dd2c7e-def6-4884-8dc1-6e403cd7c618') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11875, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "同学们很互相帮助，很快做完了作业。", "corrected_sentence": "同学们互相帮助，很快做完了作业。", "error_description": "程度副词误用：“互相”是副词，不能被程度副词“很”修饰，应说“互相帮助”，不说“很互相帮助”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68dd2c7e-def6-4884-8dc1-6e403cd7c618') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11875, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们俩住在一起，常常把互相帮助，生活很开心。", "corrected_sentence": "他们俩住在一起，常常互相帮助，生活很开心。", "error_description": "“把”字句错误：“互相帮助”是不带宾语的动词，不能用在“把”字句中，应去掉“把”，说“常常互相帮助”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68dd2c7e-def6-4884-8dc1-6e403cd7c618') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11878, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'daf369d4-aa4f-4ace-874e-273aacb8e532') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11878, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'daf369d4-aa4f-4ace-874e-273aacb8e532') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11878, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "有组织地排列在一起的一群人。", "primary_collocate": null, "pronunciation": "duì wu", "ipa": "twei˥˩ wu", "syllable_count": 2, "sentences": [{"text": "比如两个队伍比赛，看谁先拿到旗帜或者谁得分更高。", "target_word": "队伍", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "虽然大家在竞争，但每个队伍内部还是需要协作。", "target_word": "队伍", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "我们的队伍今天赢了比赛。", "target_word": "队伍", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这支队伍有十个人，大家分工明确。", "target_word": "队伍", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司正在组建一支新的队伍。", "target_word": "队伍", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们的队伍在比赛中得了第一名。", "target_word": "队伍", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "救援队伍已经到达了现场。", "target_word": "队伍", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新加入的队员很快融入了队伍。", "target_word": "队伍", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们队伍里每个人都很努力。", "target_word": "队伍", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想加入你们的队伍，可以吗？", "target_word": "队伍", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "支队伍", "label": "量词"}], "register": "中性", "sense_fingerprint": "队伍·有组织的一群人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3b89829-f41d-414c-8971-ebd909ad5235') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11878, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "队伍", "is_correct": true, "explanation": "正确答案。“两个队伍比赛”指两组有组织的团体相互竞赛，句意通顺。"}, {"text": "人群", "is_correct": false, "explanation": "语义：“人群”是没有组织的聚集，不能让两个人群“比赛”。"}, {"text": "人数", "is_correct": false, "explanation": "搭配：“人数”是数量，不能用来比赛。"}, {"text": "行列", "is_correct": false, "explanation": "语义：“行列”指排列的队形，两个行列不会参加比赛。"}], "explanations": {"队伍": "正确答案。“两个队伍比赛”指两组有组织的团体相互竞赛，句意通顺。", "人群": "语义：“人群”是没有组织的聚集，不能让两个人群“比赛”。", "人数": "搭配：“人数”是数量，不能用来比赛。", "行列": "语义：“行列”指排列的队形，两个行列不会参加比赛。"}, "sentence_index": 0, "correct_answer": "队伍"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把队伍装进了书包里。", "explanation": "这里应该用〈资料〉。“队伍”指有组织的一群人，不能当作能装进书包的东西。"}, {"text": "一场大雨过后，队伍里的小草都绿了。", "explanation": "这里应该用〈草地〉。“队伍”指一群人，不能指长满小草的地方。"}, {"text": "我把队伍折成了纸飞机。", "explanation": "这里应该用〈纸张〉。“队伍”指一群人，不能当作折纸飞机的材料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'daf369d4-aa4f-4ace-874e-273aacb8e532') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11878, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "队伍", "is_correct": true, "explanation": "正确答案。“救援队伍已经到达了现场”指救援的团体抵达，句意通顺。"}, {"text": "心跳", "is_correct": false, "explanation": "语义：“心跳”是身体的搏动，不能作为救援力量“到达现场”，句意不通。"}, {"text": "人数", "is_correct": false, "explanation": "搭配：“人数”是数量，不能说“人数已经到达了现场”。"}, {"text": "体温", "is_correct": false, "explanation": "语义：“体温”是身体的温度，与救援到达现场的语义完全无关。"}], "explanations": {"队伍": "正确答案。“救援队伍已经到达了现场”指救援的团体抵达，句意通顺。", "心跳": "语义：“心跳”是身体的搏动，不能作为救援力量“到达现场”，句意不通。", "人数": "搭配：“人数”是数量，不能说“人数已经到达了现场”。", "体温": "语义：“体温”是身体的温度，与救援到达现场的语义完全无关。"}, "sentence_index": 6, "correct_answer": "队伍"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这支队伍很重，我搬不动。", "explanation": "这里应该用〈东西〉。“队伍”指一群人，不能说它很重、可以搬动。"}, {"text": "他的队伍是一把椅子。", "explanation": "这里的“队伍”指有组织的团体，不能指一把椅子，句子在此义下不成立。"}, {"text": "她的队伍是一只猫。", "explanation": "这里的“队伍”指的是团体，不能指一只动物，句子在此义下不成立。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'daf369d4-aa4f-4ace-874e-273aacb8e532') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11878, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次比赛有五只队伍参加。", "corrected_sentence": "这次比赛有五支队伍参加。", "error_description": "错误在于量词。“队伍”的量词是“支”，不能用“只”，正确说法是“五支队伍”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'daf369d4-aa4f-4ace-874e-273aacb8e532') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11878, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一只救援队伍已经出发了。", "corrected_sentence": "一支救援队伍已经出发了。", "error_description": "错误在于量词。“队伍”作为团体时量词是“支”，“只”不能用于队伍，正确说法是“一支救援队伍”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'daf369d4-aa4f-4ace-874e-273aacb8e532') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11880, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'daf369d4-aa4f-4ace-874e-273aacb8e532') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
