INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11880, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "作为标志的布制品，通常悬挂在杆上，用于象征国家、政党、组织、团体或某种主张。", "primary_collocate": null, "pronunciation": "qí zhì", "ipa": "tɕʰi˧˥ ʈʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "比如两个队伍比赛，看谁先拿到旗帜或者谁得分更高。", "target_word": "旗帜", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "学生们举着红色的旗帜走进操场。", "target_word": "旗帜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山顶上插着一面旗帜，风一吹就动。", "target_word": "旗帜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动员入场时，手里拿着国家的旗帜。", "target_word": "旗帜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把旗帜挂在门口的杆子上。", "target_word": "旗帜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这面旗帜是用红布做的，很大。", "target_word": "旗帜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛开始前，队员们一起升起了旗帜。", "target_word": "旗帜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风很大，旗帜在空中飘得很高。", "target_word": "旗帜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把写着队名的旗帜带到了球场。", "target_word": "旗帜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在游行时挥动着手里的旗帜。", "target_word": "旗帜", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "面", "label": "量词"}, {"form": "旗幟", "label": "繁体"}], "register": "中性", "sense_fingerprint": "挂在杆上、象征国家或团体的布制标志", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3b89829-f41d-414c-8971-ebd909ad5235') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11880, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "旗帜", "is_correct": true, "explanation": "正确答案：旗帜（qí zhì），指作为标志的布制品。"}, {"text": "骑士", "is_correct": false, "explanation": "shì 与 zhì 声母不同（sh 与 zh），声调相同，意思是骑士，不是旗帜。"}, {"text": "气质", "is_correct": false, "explanation": "qì（第四声）与 qí（第二声）声调不同，意思是气质，不是旗帜。"}, {"text": "起止", "is_correct": false, "explanation": "qǐ 与 qí 声调不同，zhǐ 与 zhì 声调也不同，意思是起点和终点，不是旗帜。"}], "explanations": {"旗帜": "正确答案：旗帜（qí zhì），指作为标志的布制品。", "骑士": "shì 与 zhì 声母不同（sh 与 zh），声调相同，意思是骑士，不是旗帜。", "气质": "qì（第四声）与 qí（第二声）声调不同，意思是气质，不是旗帜。", "起止": "qǐ 与 qí 声调不同，zhǐ 与 zhì 声调也不同，意思是起点和终点，不是旗帜。"}, "sentence_index": null, "correct_answer": "旗帜"}, "level_3": {"options": [{"text": "旗帜", "is_correct": true, "explanation": "正确：“拿到旗帜”指在比赛中取得作为标志的旗子，符合语境。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“拿到”后不能接“天气”，天气无法被拿到手里。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“拿到空气”不成立，空气无法被拿到。"}, {"text": "故事", "is_correct": false, "explanation": "语义：故事不是比赛中可以争取拿到的物件，与“比赛、得分”的语境不符。"}], "explanations": {"旗帜": "正确：“拿到旗帜”指在比赛中取得作为标志的旗子，符合语境。", "天气": "搭配：“拿到”后不能接“天气”，天气无法被拿到手里。", "空气": "搭配：“拿到空气”不成立，空气无法被拿到。", "故事": "语义：故事不是比赛中可以争取拿到的物件，与“比赛、得分”的语境不符。"}, "sentence_index": 0, "correct_answer": "旗帜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她穿着红色的旗帜去参加婚礼。", "explanation": "这里应该用〈旗袍〉。旗袍是穿在身上的服装，旗帜是布制标志，不能穿。"}, {"text": "他用一面旗帜撬开了瓶盖。", "explanation": "这里应该用〈开瓶器〉。旗帜是布制标志，不能用来撬开瓶盖。"}, {"text": "妈妈系着旗帜在厨房做饭。", "explanation": "这里应该用〈围裙〉。围裙系在身上防油污，旗帜是标志，不能当围裙用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'daf369d4-aa4f-4ace-874e-273aacb8e532') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11880, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "旗帜", "is_correct": true, "explanation": "正确答案：旗帜（qí zhì），指作为标志的布制品。"}, {"text": "奇事", "is_correct": false, "explanation": "shì 与 zhì 声母不同（sh 与 zh），意思是奇怪的事情，不是旗帜。"}, {"text": "器质", "is_correct": false, "explanation": "qì（第四声）与 qí（第二声）声调不同，意思是器官的物质结构，不是旗帜。"}, {"text": "启智", "is_correct": false, "explanation": "qǐ（第三声）与 qí（第二声）声调不同，意思是开启智慧，不是旗帜。"}], "explanations": {"旗帜": "正确答案：旗帜（qí zhì），指作为标志的布制品。", "奇事": "shì 与 zhì 声母不同（sh 与 zh），意思是奇怪的事情，不是旗帜。", "器质": "qì（第四声）与 qí（第二声）声调不同，意思是器官的物质结构，不是旗帜。", "启智": "qǐ（第三声）与 qí（第二声）声调不同，意思是开启智慧，不是旗帜。"}, "sentence_index": null, "correct_answer": "旗帜"}, "level_3": {"options": [{"text": "旗帜", "is_correct": true, "explanation": "正确：“升起了旗帜”是标准搭配，符合比赛开始时的情境。"}, {"text": "歌曲", "is_correct": false, "explanation": "搭配：“升起”用于旗帜、太阳等，不能说“升起歌曲”。"}, {"text": "规则", "is_correct": false, "explanation": "搭配：规则不能被“升起”，说“升起了规则”不通。"}, {"text": "比分", "is_correct": false, "explanation": "语义：比分是数字结果，不能被升起，与句子语境不符。"}], "explanations": {"旗帜": "正确：“升起了旗帜”是标准搭配，符合比赛开始时的情境。", "歌曲": "搭配：“升起”用于旗帜、太阳等，不能说“升起歌曲”。", "规则": "搭配：规则不能被“升起”，说“升起了规则”不通。", "比分": "语义：比分是数字结果，不能被升起，与句子语境不符。"}, "sentence_index": 6, "correct_answer": "旗帜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "下雨了，他撑着旗帜走回家。", "explanation": "这里应该用〈雨伞〉。撑在头顶挡雨的是雨伞，旗帜是标志，不能用来挡雨。"}, {"text": "她提着旗帜去超市买菜。", "explanation": "这里应该用〈篮子〉。买菜时提着装东西的是篮子，旗帜是标志，不能用来装菜。"}, {"text": "他拿着旗帜在院子里扫地。", "explanation": "这里应该用〈扫帚〉。扫地用的是扫帚，旗帜是标志，不能用来扫地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'daf369d4-aa4f-4ace-874e-273aacb8e532') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11880, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把一个旗帜挂在了墙上。", "corrected_sentence": "他把一面旗帜挂在了墙上。", "error_description": "量词错误：“旗帜”应用量词“面”，不能用“个”。“面”用于有平面的布制品，正确说法是“一面旗帜”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'daf369d4-aa4f-4ace-874e-273aacb8e532') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11880, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们挥舞着旗帜着，大家都很高兴。", "corrected_sentence": "孩子们挥舞着旗帜，大家都很高兴。", "error_description": "多余的“着”：“挥舞”后已用“着”表示持续，宾语“旗帜”之后不能再加“着”，应删去。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'daf369d4-aa4f-4ace-874e-273aacb8e532') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11881, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "失分", "is_correct": true, "explanation": "正确：“失分”与“得分”构成反义，指比赛中失去分数。"}, {"text": "防守", "is_correct": false, "explanation": "防守：是阻止对方得分的行为，与“得分”不构成反义。"}, {"text": "传球", "is_correct": false, "explanation": "传球：是进攻配合的动作，与“得分”没有反义关系。"}, {"text": "盖帽", "is_correct": false, "explanation": "盖帽：是拦截对方投篮的动作，与“得分”不构成反义。"}], "correct_answer": "失分", "explanations": {"失分": "正确：“失分”与“得分”构成反义，指比赛中失去分数。", "防守": "防守：是阻止对方得分的行为，与“得分”不构成反义。", "传球": "传球：是进攻配合的动作，与“得分”没有反义关系。", "盖帽": "盖帽：是拦截对方投篮的动作，与“得分”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'daf369d4-aa4f-4ace-874e-273aacb8e532') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11881, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "失分", "is_correct": true, "explanation": "正确：“失分”与“得分”构成反义，指比赛中失去分数。"}, {"text": "犯规", "is_correct": false, "explanation": "犯规：指违反比赛规则，与“得分”不构成反义。"}, {"text": "射门", "is_correct": false, "explanation": "射门：是尝试得分的动作，与“得分”不是反义关系。"}, {"text": "运球", "is_correct": false, "explanation": "运球：是带球移动的动作，与“得分”没有反义关系。"}], "correct_answer": "失分", "explanations": {"失分": "正确：“失分”与“得分”构成反义，指比赛中失去分数。", "犯规": "犯规：指违反比赛规则，与“得分”不构成反义。", "射门": "射门：是尝试得分的动作，与“得分”不是反义关系。", "运球": "运球：是带球移动的动作，与“得分”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'daf369d4-aa4f-4ace-874e-273aacb8e532') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11881, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在比赛、考试或游戏中获得分数。", "primary_collocate": null, "pronunciation": "dé fēn", "ipa": "tɤ˧˥ fən˥˥", "syllable_count": 2, "sentences": [{"text": "比如两个队伍比赛，看谁先拿到旗帜或者谁得分更高。", "target_word": "得分", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这场比赛他一个人得分最多。", "target_word": "得分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们队在最后一分钟得分了。", "target_word": "得分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他踢进一个球，球队终于得分了。", "target_word": "得分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "考试时，认真写作文才能得分。", "target_word": "得分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "玩游戏时，吃到金币就能得分。", "target_word": "得分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她投了三个球，每次都得分。", "target_word": "得分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "对方的防守很好，我们一直没有得分。", "target_word": "得分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他是球队里最会得分的人。", "target_word": "得分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "上半场我们没得分，下半场才开始得分。", "target_word": "得分", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "得分了", "label": "体标"}, {"form": "得分过", "label": "体标"}], "register": "中性", "sense_fingerprint": "在比赛、考试或游戏中获得分数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3b89829-f41d-414c-8971-ebd909ad5235') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11881, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "得分", "is_correct": true, "explanation": "正确：“得分”指在比赛中获得分数，与“谁……更高”的比较相符。"}, {"text": "游泳", "is_correct": false, "explanation": "搭配：“谁……更高”比较的应是得分这类数量，“游泳”不能这样比较。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：“唱歌”与比赛中谁分数高无关，不能用“更高”比较。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”与比赛拿分无关，句子不成立。"}], "explanations": {"得分": "正确：“得分”指在比赛中获得分数，与“谁……更高”的比较相符。", "游泳": "搭配：“谁……更高”比较的应是得分这类数量，“游泳”不能这样比较。", "唱歌": "语义：“唱歌”与比赛中谁分数高无关，不能用“更高”比较。", "睡觉": "语义：“睡觉”与比赛拿分无关，句子不成立。"}, "sentence_index": 0, "correct_answer": "得分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈在厨房做饭，很快就得分了。", "explanation": "这里把“得分”用成了“做成、完成（事情）”的意思，与本释义“在比赛、考试或游戏中获得分数”不符。"}, {"text": "小猫在院子里抓到一只蝴蝶，就得分了。", "explanation": "这里把“得分”用成了“抓到、得到（东西）”的意思，与本释义“在比赛、考试或游戏中获得分数”不符。"}, {"text": "我这个月的工资很高，得分了很多。", "explanation": "这里把“得分”用成了“赚得、有收入（钱）”的意思，与本释义不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'daf369d4-aa4f-4ace-874e-273aacb8e532') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11881, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "得分", "is_correct": true, "explanation": "正确：“每次都得分”指每次投球都获得分数，与前句语境一致。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：“下雨”与投球比赛无关，句子不成立。"}, {"text": "咳嗽", "is_correct": false, "explanation": "搭配：“每次都咳嗽”与“投了三个球”之间没有合理的搭配关系。"}, {"text": "写作业", "is_correct": false, "explanation": "语义：“写作业”与投篮的比赛情境无关。"}], "explanations": {"得分": "正确：“每次都得分”指每次投球都获得分数，与前句语境一致。", "下雨": "语义：“下雨”与投球比赛无关，句子不成立。", "咳嗽": "搭配：“每次都咳嗽”与“投了三个球”之间没有合理的搭配关系。", "写作业": "语义：“写作业”与投篮的比赛情境无关。"}, "sentence_index": 6, "correct_answer": "得分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在书店买了几本书，每人都得分了一本。", "explanation": "这里把“得分”用成了“分配、分发（物品）”的意思，与本释义不符。"}, {"text": "这个月的房租很贵，我的钱都得分了。", "explanation": "这里把“得分”用成了“花费、支出（钱）”的意思，与本释义不符。"}, {"text": "他在地铁上读报纸，读到一半就得分了。", "explanation": "这里把“得分”用成了“读完、完成（阅读）”的意思，与本释义不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'daf369d4-aa4f-4ace-874e-273aacb8e532') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11881, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她把球队得分了。", "corrected_sentence": "她为球队得分了。", "error_description": "介词错误：为某队取得分数要用介词“为”，不能用“把”。应说“她为球队得分了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'daf369d4-aa4f-4ace-874e-273aacb8e532') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11881, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这一局，他终于得分着。", "corrected_sentence": "这一局，他终于得分了。", "error_description": "“着”错误：“得分”表示一次性完成的动作，不能用“着”表示持续，应说“终于得分了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'daf369d4-aa4f-4ace-874e-273aacb8e532') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
