INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11884, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'daf369d4-aa4f-4ace-874e-273aacb8e532') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11884, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指一个团队或组织的负责人，负责指挥和协调。", "primary_collocate": null, "pronunciation": "duì zhǎng", "ipa": "tweɪ˥˩ ʈʂɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "好的团队会听队长的指挥，有人负责进攻，有人保护队友。", "target_word": "队长", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "我们的队长每天第一个到球场。", "target_word": "队长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "队长对大家说：“别着急，慢慢来。”", "target_word": "队长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛前，队长带着我们一起热身。", "target_word": "队长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他踢得很好，所以大家选他当队长。", "target_word": "队长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "队长把球传给了跑得最快的队员。", "target_word": "队长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "队长受了伤，今天不能上场。", "target_word": "队长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这支篮球队的队长是一位高个子女生。", "target_word": "队长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们明天要选新队长。", "target_word": "队长", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "比赛输了，队长还是笑着鼓励大家。", "target_word": "队长", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "副队长", "label": "复合"}, {"form": "隊長", "label": "繁体"}], "register": "中性", "sense_fingerprint": "团队或组织中负责指挥和协调的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3b89829-f41d-414c-8971-ebd909ad5235') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11884, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "队长", "is_correct": true, "explanation": "队长指团队的负责人，负责指挥和协调，与“指挥”“进攻”“保护队友”的语境相符。"}, {"text": "队员", "is_correct": false, "explanation": "语义：队员是被指挥的一方，不会发出指挥，与句意相反。"}, {"text": "观众", "is_correct": false, "explanation": "语义：观众在场外，不属于团队，也不负责指挥。"}, {"text": "球迷", "is_correct": false, "explanation": "配价：“听……的指挥”要求发出指挥的人是团队内的负责人，球迷只是为球队加油的人。"}], "explanations": {"队长": "队长指团队的负责人，负责指挥和协调，与“指挥”“进攻”“保护队友”的语境相符。", "队员": "语义：队员是被指挥的一方，不会发出指挥，与句意相反。", "观众": "语义：观众在场外，不属于团队，也不负责指挥。", "球迷": "配价：“听……的指挥”要求发出指挥的人是团队内的负责人，球迷只是为球队加油的人。"}, "sentence_index": 0, "correct_answer": "队长"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家医院的队长今年已经六十岁了。", "explanation": "这里应该用〈院长〉。医院的负责人叫院长，队长一般用于运动队等团队。"}, {"text": "这所学校的队长今天在大会上讲了话。", "explanation": "这里应该用〈校长〉。学校的负责人叫校长，队长指运动队等团队里带领大家的人。"}, {"text": "这家公司的队长刚宣布了新的规定。", "explanation": "这里应该用〈领导〉。公司、机关的负责人叫领导，队长指队伍里带领大家的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'daf369d4-aa4f-4ace-874e-273aacb8e532') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11884, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "队长", "is_correct": true, "explanation": "队长指团队的负责人，句中“受了伤，今天不能上场”说的正是这位负责人。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不会受伤，也不能上场。"}, {"text": "银行", "is_correct": false, "explanation": "语义：银行是机构，不能受伤，也不能上场，与句意不合。"}, {"text": "冰箱", "is_correct": false, "explanation": "配价：“受了伤”的主语须是有生命的人，冰箱不能受伤。"}], "explanations": {"队长": "队长指团队的负责人，句中“受了伤，今天不能上场”说的正是这位负责人。", "桌子": "语义：桌子是家具，不会受伤，也不能上场。", "银行": "语义：银行是机构，不能受伤，也不能上场，与句意不合。", "冰箱": "配价：“受了伤”的主语须是有生命的人，冰箱不能受伤。"}, "sentence_index": 6, "correct_answer": "队长"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这支足球队的队长每天负责给球场浇水，还修理损坏的看台。", "explanation": "这里应该用〈管理员〉。浇水、修理设施是场地管理人员的工作；队长是队内带领大家的人，不负责场地维护。"}, {"text": "这次出国比赛的队长负责办理签证、订机票，还安排大家的住宿。", "explanation": "这里应该用〈领队〉。带队出行、办理签证和行程安排是领队的工作；队长指队伍里带领大家的人，主要负责场上的指挥和协调。"}, {"text": "今天这场比赛的队长吹响了终场哨，比分定格在2比1。", "explanation": "这里应该用〈裁判〉。吹哨、判定比赛结束的是裁判；队长是队内的负责人，没有执法比赛的权力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'daf369d4-aa4f-4ace-874e-273aacb8e532') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11884, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们明天要选一条新队长。", "corrected_sentence": "我们明天要选一位新队长。", "error_description": "量词错误：“队长”指人，量词应用“位”（或“个”），不能用“条”，“条”用于裤子、河流等细长物。正确说法是“一位新队长”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'daf369d4-aa4f-4ace-874e-273aacb8e532') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11884, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这支篮球队来了一把新队长，大家都很高兴。", "corrected_sentence": "这支篮球队来了一位新队长，大家都很高兴。", "error_description": "量词错误：“队长”指人，量词应用“位”或“名”，不能用“把”，“把”用于有柄的器具。正确说法是“一位新队长”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'daf369d4-aa4f-4ace-874e-273aacb8e532') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
