INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11885, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "发令调度，安排或引导别人做某事。", "primary_collocate": null, "pronunciation": "zhǐ huī", "ipa": "tʂɻ̩˨˩ xweɪ˥", "syllable_count": 2, "sentences": [{"text": "好的团队会听队长的指挥，有人负责进攻，有人保护队友。", "target_word": "指挥", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "警察站在路口指挥交通。", "target_word": "指挥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在比赛中指挥队友站好位置。", "target_word": "指挥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她站在台前指挥整个乐队。", "target_word": "指挥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "火灾时，消防员听从队长的指挥。", "target_word": "指挥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "船长指挥大家把船开进港口。", "target_word": "指挥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在队里负责指挥，大家都很信他。", "target_word": "指挥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师指挥同学们排好队。", "target_word": "指挥", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这场演出由王老师指挥。", "target_word": "指挥", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他指挥过很多次救援行动。", "target_word": "指挥", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "指挥了", "label": "完成体"}, {"form": "指挥着", "label": "持续体"}, {"form": "指挥过", "label": "经历体"}, {"form": "指挥官", "label": "复合词"}, {"form": "指挥部", "label": "复合词"}, {"form": "总指挥", "label": "复合词"}, {"form": "指揮", "label": "繁体"}], "register": "中性", "sense_fingerprint": "有组织地发令调度、安排和引导众人行动，如指挥交通、乐队、救援", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee2f9cf7-edee-4641-928c-f58f95f044af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11885, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "指挥", "is_correct": true, "explanation": "指挥 zhǐ huī：发令调度，安排或引导别人做某事。"}, {"text": "智慧", "is_correct": false, "explanation": "智慧 zhì huì 与 zhǐ huī 两个音节的声调都不同（第四声对第三声，第四声对第一声），意思是聪明才智。"}, {"text": "只会", "is_correct": false, "explanation": "只会 zhǐ huì 与 zhǐ huī 只有第二个音节声调不同（huì 第四声，huī 第一声），意思是只能、只知道。"}, {"text": "纸花", "is_correct": false, "explanation": "纸花 zhǐ huā 与 zhǐ huī 第二个音节韵母不同（huā 对 huī），意思是纸做的花。"}], "explanations": {"指挥": "指挥 zhǐ huī：发令调度，安排或引导别人做某事。", "智慧": "智慧 zhì huì 与 zhǐ huī 两个音节的声调都不同（第四声对第三声，第四声对第一声），意思是聪明才智。", "只会": "只会 zhǐ huì 与 zhǐ huī 只有第二个音节声调不同（huì 第四声，huī 第一声），意思是只能、只知道。", "纸花": "纸花 zhǐ huā 与 zhǐ huī 第二个音节韵母不同（huā 对 huī），意思是纸做的花。"}, "sentence_index": null, "correct_answer": "指挥"}, "level_3": {"options": [{"text": "指挥", "is_correct": true, "explanation": "正确。此处为名词，指队长发出的指令和调度，与“听……的”搭配。"}, {"text": "手势", "is_correct": false, "explanation": "搭配：“听”的对象是声音或话语，手势要用“看”，不能说“听队长的手势”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是可以听从的指令，与“听队长的”的语义不合。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：饮料不是可以听从的指令，“听……的”后面不能接饮料。"}], "explanations": {"指挥": "正确。此处为名词，指队长发出的指令和调度，与“听……的”搭配。", "手势": "搭配：“听”的对象是声音或话语，手势要用“看”，不能说“听队长的手势”。", "天气": "语义：天气不是可以听从的指令，与“听队长的”的语义不合。", "饮料": "语义：饮料不是可以听从的指令，“听……的”后面不能接饮料。"}, "sentence_index": 0, "correct_answer": "指挥"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师指挥我们写论文。", "explanation": "这里应该用〈指导〉。指挥强调发令调度、让人行动，指导是给出方法和建议，写论文要用“指导”。"}, {"text": "他熟练地指挥电脑。", "explanation": "这里应该用〈操作〉。指挥的对象是人或成队的行动，电脑要用“操作”。"}, {"text": "老师指挥我们的写作，每周都有详细的批改。", "explanation": "这里应该用〈指点〉。指挥是发令调度、安排人行动；对写作给出具体意见要用“指点”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd226ebe4-c57a-4e4c-9505-fe601732452d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11885, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "指挥", "is_correct": true, "explanation": "正确。此处为动词，指带领大家行动，与“负责”搭配。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“负责”后面要接职责性的行动，睡觉不是可以负责的工作。"}, {"text": "吃饭", "is_correct": false, "explanation": "搭配：“负责”后接的是任务，吃饭不能作为需要负责的事项。"}, {"text": "生病", "is_correct": false, "explanation": "语义：生病是身体状态，不能被“负责”承担。"}], "explanations": {"指挥": "正确。此处为动词，指带领大家行动，与“负责”搭配。", "睡觉": "语义：“负责”后面要接职责性的行动，睡觉不是可以负责的工作。", "吃饭": "搭配：“负责”后接的是任务，吃饭不能作为需要负责的事项。", "生病": "语义：生病是身体状态，不能被“负责”承担。"}, "sentence_index": 6, "correct_answer": "指挥"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他热情地指挥远道而来的客人。", "explanation": "这里应该用〈招待〉。指挥是发令调度、安排别人行动，热情接待远道而来的客人要用“招待”。"}, {"text": "新郎在门口指挥新娘。", "explanation": "这里应该用〈迎接〉。指挥是发令调度、安排别人行动，在门口欢迎新娘要用“迎接”。"}, {"text": "护士一夜都在指挥病人。", "explanation": "这里应该用〈照料〉。指挥是发令调度，照顾病人、护理病人要用“照料”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd226ebe4-c57a-4e4c-9505-fe601732452d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11885, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她指挥的很好，乐队演奏很整齐。", "corrected_sentence": "她指挥得很好，乐队演奏很整齐。", "error_description": "“指挥”后面接表示程度的补语时要用“得”，不能用“的”，应说“指挥得很好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd226ebe4-c57a-4e4c-9505-fe601732452d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11885, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她指挥过很多只演出。", "corrected_sentence": "她指挥过很多次演出。", "error_description": "“只”不能用来计量“演出”，应说“指挥过很多次演出”。“只”多用于某些动物和成对的东西。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd226ebe4-c57a-4e4c-9505-fe601732452d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11887, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "防守", "is_correct": true, "explanation": "防守：与进攻相对，指守住阵地，不主动攻击对方。"}, {"text": "休息", "is_correct": false, "explanation": "休息是普通动词，与进攻没有反义关系。"}, {"text": "观察", "is_correct": false, "explanation": "观察是普通动词，与进攻没有反义关系。"}, {"text": "收集", "is_correct": false, "explanation": "收集是普通动词，与进攻没有反义关系。"}], "correct_answer": "防守", "explanations": {"防守": "防守：与进攻相对，指守住阵地，不主动攻击对方。", "休息": "休息是普通动词，与进攻没有反义关系。", "观察": "观察是普通动词，与进攻没有反义关系。", "收集": "收集是普通动词，与进攻没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd226ebe4-c57a-4e4c-9505-fe601732452d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11887, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "防守", "is_correct": true, "explanation": "防守：与进攻相对，指守住阵地，不主动攻击对方。"}, {"text": "等待", "is_correct": false, "explanation": "等待是普通动词，与进攻没有反义关系。"}, {"text": "储存", "is_correct": false, "explanation": "储存是普通动词，与进攻没有反义关系。"}, {"text": "复习", "is_correct": false, "explanation": "复习是普通动词，与进攻没有反义关系。"}], "correct_answer": "防守", "explanations": {"防守": "防守：与进攻相对，指守住阵地，不主动攻击对方。", "等待": "等待是普通动词，与进攻没有反义关系。", "储存": "储存是普通动词，与进攻没有反义关系。", "复习": "复习是普通动词，与进攻没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd226ebe4-c57a-4e4c-9505-fe601732452d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11887, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指军队或体育比赛中主动向对方发起攻击的行为。", "primary_collocate": null, "pronunciation": "jìn gōng", "ipa": "tɕin˥˩ kʊŋ˥", "syllable_count": 2, "sentences": [{"text": "好的团队会听队长的指挥，有人负责进攻，有人保护队友。", "target_word": "进攻", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "我们队在下半场开始进攻。", "target_word": "进攻", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "敌人从北边进攻了我们的城市。", "target_word": "进攻", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "球队一直在进攻，对方只能被动挨打。", "target_word": "进攻", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他是前锋，主要负责进攻。", "target_word": "进攻", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "军队天亮后向山上进攻。", "target_word": "进攻", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "比赛刚开始，红队就发动了进攻。", "target_word": "进攻", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们进攻了三次，都没有进球。", "target_word": "进攻", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "对方的进攻很快，我们来不及回防。", "target_word": "进攻", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "队长说：“现在不要进攻，先守住球门。”", "target_word": "进攻", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "进攻了", "label": "完成体"}, {"form": "进攻着", "label": "持续体"}, {"form": "进攻过", "label": "经历体"}, {"form": "进攻", "label": "原形"}, {"form": "進攻", "label": "繁体"}], "register": "中性", "sense_fingerprint": "军队或球队主动向对方发起攻击，与防守相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee2f9cf7-edee-4641-928c-f58f95f044af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11887, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "进攻", "is_correct": true, "explanation": "正确。此处为动词，与“负责”搭配，指主动发起攻击的任务。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：“有人负责唱歌”与团队的攻守分工不相合，唱歌不是战术任务。"}, {"text": "生病", "is_correct": false, "explanation": "语义：生病是身体状态，不能被“负责”承担，与攻守分工不合。"}, {"text": "洗澡", "is_correct": false, "explanation": "搭配：“负责”不与“洗澡”搭配，洗澡不是团队分工的内容。"}], "explanations": {"进攻": "正确。此处为动词，与“负责”搭配，指主动发起攻击的任务。", "唱歌": "语义：“有人负责唱歌”与团队的攻守分工不相合，唱歌不是战术任务。", "生病": "语义：生病是身体状态，不能被“负责”承担，与攻守分工不合。", "洗澡": "搭配：“负责”不与“洗澡”搭配，洗澡不是团队分工的内容。"}, "sentence_index": 0, "correct_answer": "进攻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一名歹徒突然进攻了路人。", "explanation": "这里应该用〈攻击〉。进攻多指军队或球队有组织地主动发起攻势，个人伤人要用“攻击”。"}, {"text": "他们一起进攻了教室。", "explanation": "这里应该用〈进入〉。进攻是主动攻击对方，走进房间要用“进入”。"}, {"text": "他进攻了一个球。", "explanation": "这里应该用〈进球〉。进攻指向对方发起攻击，球入网得分要用“进球”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd226ebe4-c57a-4e4c-9505-fe601732452d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11887, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "进攻", "is_correct": true, "explanation": "正确。“发动了进攻”中“进攻”是名词，指主动发起的攻势。"}, {"text": "哭泣", "is_correct": false, "explanation": "语义：“发动”要接攻势、战争之类的对象，哭泣不能被发动。"}, {"text": "散步", "is_correct": false, "explanation": "搭配：“发动”不与“散步”搭配，散步不能作为发动的对象。"}, {"text": "午睡", "is_correct": false, "explanation": "搭配：“发动”不与“午睡”搭配，午睡不能作为发动的对象。"}], "explanations": {"进攻": "正确。“发动了进攻”中“进攻”是名词，指主动发起的攻势。", "哭泣": "语义：“发动”要接攻势、战争之类的对象，哭泣不能被发动。", "散步": "搭配：“发动”不与“散步”搭配，散步不能作为发动的对象。", "午睡": "搭配：“发动”不与“午睡”搭配，午睡不能作为发动的对象。"}, "sentence_index": 6, "correct_answer": "进攻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们进攻了决赛。", "explanation": "这里应该用〈晋级〉。进攻指主动攻击对方，进入决赛要用“晋级”。"}, {"text": "我们进攻了全场的球。", "explanation": "这里应该用〈控球〉。进攻指主动攻击对方，掌握全场的球要用“控球”。"}, {"text": "红队进攻了比赛的主动权。", "explanation": "这里应该用〈夺取〉。进攻指主动攻击对方，取得比赛主动权要用“夺取”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd226ebe4-c57a-4e4c-9505-fe601732452d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11887, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们进攻过三只，都失败了。", "corrected_sentence": "他们进攻过三次，都失败了。", "error_description": "“进攻”计次数应用量词“次”，不能用“只”（“只”多用于某些动物和成对的东西），应说“进攻过三次”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd226ebe4-c57a-4e4c-9505-fe601732452d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11887, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "红队进攻的很猛。", "corrected_sentence": "红队进攻得很猛。", "error_description": "“进攻”后面表示程度的补语要用“得”，不能用“的”，应说“进攻得很猛”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd226ebe4-c57a-4e4c-9505-fe601732452d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
