INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11888, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "属于同一个团队或集体的人，一起合作完成某项任务。", "primary_collocate": null, "pronunciation": "duì yǒu", "ipa": "twei˥˩ jou˨˩", "syllable_count": 2, "sentences": [{"text": "好的团队会听队长的指挥，有人负责进攻，有人保护队友。", "target_word": "队友", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "他把球传给了队友。", "target_word": "队友", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的队友今天没来训练。", "target_word": "队友", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "比赛输了，他没有怪队友。", "target_word": "队友", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好队友会在你需要时帮你。", "target_word": "队友", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他和队友一起练了三个小时。", "target_word": "队友", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "受伤以后，队友们都来看他。", "target_word": "队友", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们是队友，应该互相帮助。", "target_word": "队友", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她和队友们抱在一起哭了。", "target_word": "队友", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新来的队友跑得特别快。", "target_word": "队友", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "队友们", "label": "复数"}, {"form": "个", "label": "量词"}, {"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "隊友", "label": "繁体"}], "register": "中性", "sense_fingerprint": "同属一个队伍、一起比赛或合作完成任务的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee2f9cf7-edee-4641-928c-f58f95f044af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11888, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "队友", "is_correct": true, "explanation": "正确：「队友」指同一队的人，有人保护的正是同队的人，与团队合作的语境相符。"}, {"text": "对手", "is_correct": false, "explanation": "语义：「对手」是竞争的另一方，与团队中互相保护的语境相反。"}, {"text": "敌人", "is_correct": false, "explanation": "语义：「敌人」是对立的一方，团队中要保护的是同队的人，不是敌人。"}, {"text": "对方", "is_correct": false, "explanation": "语义：「对方」指比赛中对立的一方，「保护对方」与团队合作的句意相反。"}], "explanations": {"队友": "正确：「队友」指同一队的人，有人保护的正是同队的人，与团队合作的语境相符。", "对手": "语义：「对手」是竞争的另一方，与团队中互相保护的语境相反。", "敌人": "语义：「敌人」是对立的一方，团队中要保护的是同队的人，不是敌人。", "对方": "语义：「对方」指比赛中对立的一方，「保护对方」与团队合作的句意相反。"}, "sentence_index": 0, "correct_answer": "队友"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我和他是同班队友，每天一起上学。", "explanation": "这里应该用〈同学〉。「队友」指为完成同一任务而合作的同队成员；只是同班上学的人应说「同学」。"}, {"text": "队友每天给我们上课，讲得很清楚。", "explanation": "这里应该用〈老师〉。「队友」是同队的成员，不能用来指给我们上课的人；上课的人应说「老师」。"}, {"text": "队友每月给我们发工资。", "explanation": "这里应该用〈老板〉。「队友」是同队的人，不是发工资的人；发工资的人应说「老板」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd226ebe4-c57a-4e4c-9505-fe601732452d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11888, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "队友", "is_correct": true, "explanation": "正确：「队友们」指同队的人，受伤后来看他，符合语境。"}, {"text": "陌生人", "is_correct": false, "explanation": "语义：陌生人不会因为他受伤而来探望他，与“来看他”的语境不合。"}, {"text": "乘客", "is_correct": false, "explanation": "语义：「乘客」是搭乘交通工具的人，与受伤后来探望的语境不合。"}, {"text": "仇人", "is_correct": false, "explanation": "语义：「仇人」与他有仇，不会因为他受伤而来探望。"}], "explanations": {"队友": "正确：「队友们」指同队的人，受伤后来看他，符合语境。", "陌生人": "语义：陌生人不会因为他受伤而来探望他，与“来看他”的语境不合。", "乘客": "语义：「乘客」是搭乘交通工具的人，与受伤后来探望的语境不合。", "仇人": "语义：「仇人」与他有仇，不会因为他受伤而来探望。"}, "sentence_index": 6, "correct_answer": "队友"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "决赛时我们要对抗的队友很强。", "explanation": "这里应该用〈对手〉。「队友」指同一队的人，要对抗的一方应说「对手」。"}, {"text": "我在地铁上遇到一个队友，我们互相都不认识。", "explanation": "这里应该用〈路人〉。「队友」指一起合作的同队成员，互不认识的人应说「路人」，与「队友」矛盾。"}, {"text": "比赛时，队友吹了三次哨子。", "explanation": "这里应该用〈裁判〉。「队友」是参赛的队员，不能执法；吹哨判罚的是「裁判」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd226ebe4-c57a-4e4c-9505-fe601732452d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11888, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "每个队友们都很努力。", "corrected_sentence": "每个队友都很努力。", "error_description": "「每个」后面不能再加复数后缀「们」。应说「每个队友」或「队友们」，「每个」与「们」不能同时用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd226ebe4-c57a-4e4c-9505-fe601732452d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11888, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一直是我最信任队友。", "corrected_sentence": "他一直是我最信任的队友。", "error_description": "修饰「队友」的短语「最信任」后要加「的」。应说「最信任的队友」，少了「的」，短语就不能修饰名词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd226ebe4-c57a-4e4c-9505-fe601732452d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
