INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11889, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "通过具体事件或困难来检验某人或某物的品质、能力等。", "primary_collocate": null, "pronunciation": "kǎo yàn", "ipa": "kʰaʊ˨˩˦ jɛn˥˩", "syllable_count": 2, "sentences": [{"text": "这样的游戏不仅需要技术，也考验沟通和配合。", "target_word": "考验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛很考验我们的体力。", "target_word": "考验", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "长跑最考验一个人的耐心。", "target_word": "考验", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这道题考验的是你的思考能力。", "target_word": "考验", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师用难题考验学生的思维。", "target_word": "考验", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这份工作很考验人的责任心。", "target_word": "考验", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爬山考验了他的体力和决心。", "target_word": "考验", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "面试时，经理会考验你的反应能力。", "target_word": "考验", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个游戏太难，非常考验手速。", "target_word": "考验", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下棋考验着一个人的耐心。", "target_word": "考验", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "考验了", "label": "体标：完成"}, {"form": "考验着", "label": "体标：持续"}, {"form": "考验过", "label": "体标：经历"}], "register": "通用", "sense_fingerprint": "用事件或困难检验人的能力、品质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee2f9cf7-edee-4641-928c-f58f95f044af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11889, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "考验", "is_correct": true, "explanation": "正确：「考验」指用困难检验技术、沟通等能力，与句意相合。"}, {"text": "吃", "is_correct": false, "explanation": "语义：「吃」的对象不能是「技术」，这里不能说「吃技术」。"}, {"text": "种植", "is_correct": false, "explanation": "语义：「种植」指栽种植物，不能用于技术和沟通。"}, {"text": "搬运", "is_correct": false, "explanation": "搭配：「搬运」的对象是具体的东西，不能与抽象的「沟通和配合」搭配。"}], "explanations": {"考验": "正确：「考验」指用困难检验技术、沟通等能力，与句意相合。", "吃": "语义：「吃」的对象不能是「技术」，这里不能说「吃技术」。", "种植": "语义：「种植」指栽种植物，不能用于技术和沟通。", "搬运": "搭配：「搬运」的对象是具体的东西，不能与抽象的「沟通和配合」搭配。"}, "sentence_index": 0, "correct_answer": "考验"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我很考验你的帮助，你总是很热心。", "explanation": "这里应该用〈感谢〉。「考验」是用困难检验人的品质、能力，表达感激要用「感谢」。"}, {"text": "学校考验了这位优秀的学生，还发了奖状。", "explanation": "这里应该用〈表彰〉。「考验」是检验品质、能力，颁发奖状表示肯定要用「表彰」。"}, {"text": "大家热烈考验新同学的到来。", "explanation": "这里应该用〈欢迎〉。「考验」不表示热情迎接，迎接新同学要用「欢迎」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd226ebe4-c57a-4e4c-9505-fe601732452d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11889, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "考验", "is_correct": true, "explanation": "正确：「考验」指通过爬山这样的困难检验体力和决心，与句意相合。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：「表扬」是称赞，爬山不会「表扬」人的体力和决心。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：「翻译」是把一种语言转换成另一种，不能用于体力和决心。"}, {"text": "拍卖", "is_correct": false, "explanation": "搭配：「拍卖」的对象是物品，不能与「体力和决心」搭配。"}], "explanations": {"考验": "正确：「考验」指通过爬山这样的困难检验体力和决心，与句意相合。", "表扬": "语义：「表扬」是称赞，爬山不会「表扬」人的体力和决心。", "翻译": "语义：「翻译」是把一种语言转换成另一种，不能用于体力和决心。", "拍卖": "搭配：「拍卖」的对象是物品，不能与「体力和决心」搭配。"}, "sentence_index": 6, "correct_answer": "考验"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "朋友考验了哭泣的他，陪他说了很久的话。", "explanation": "这里应该用〈安慰〉。「考验」是用困难检验人的品质、能力，安慰哭泣的人要用「安慰」。"}, {"text": "老师考验了迟到的学生，让他罚站。", "explanation": "这里应该用〈惩罚〉。「考验」是检验品质、能力，罚站这类处罚要用「惩罚」。"}, {"text": "大家都热烈考验这位医生，纷纷送来鲜花。", "explanation": "这里应该用〈赞美〉。「考验」是用困难检验人的品质、能力，不表示热烈称赞；称赞医生要用「赞美」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd226ebe4-c57a-4e4c-9505-fe601732452d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11889, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "明天的比赛考验了我们的体力。", "corrected_sentence": "明天的比赛考验我们的体力。", "error_description": "「明天」指将来，「了」表示已经发生，不能与将来的时间连用。应去掉「了」，说「明天的比赛考验我们的体力」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd226ebe4-c57a-4e4c-9505-fe601732452d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11889, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次旅行很考验过我的耐心。", "corrected_sentence": "这次旅行很考验我的耐心。", "error_description": "「很」修饰的是程度，不能与表示经历的「过」连用；「过」应去掉，说「这次旅行很考验我的耐心」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd226ebe4-c57a-4e4c-9505-fe601732452d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
