INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11890, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd226ebe4-c57a-4e4c-9505-fe601732452d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11890, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "中文是中国的官方语言，也是世界上使用人数最多的语言之一。", "primary_collocate": null, "pronunciation": "zhōng wén", "ipa": "ʈ͡ʂʊŋ˥ wən˧˥", "syllable_count": 2, "sentences": [{"text": "有些玩家来自不同的国家，他们用简单的中文或英语交流。", "target_word": "中文", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "我在学校学习中文。", "target_word": "中文", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她的中文说得很好。", "target_word": "中文", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这本书是用中文写的。", "target_word": "中文", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你会说中文吗？", "target_word": "中文", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "中文是世界上很多人说的语言。", "target_word": "中文", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店的菜单有中文和日文。", "target_word": "中文", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每天听中文歌，练习中文。", "target_word": "中文", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师请我们用中文介绍自己。", "target_word": "中文", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我去北京以后，身边的人都说中文。", "target_word": "中文", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "中文名", "label": "复合"}, {"form": "中文系", "label": "复合"}], "register": "通用", "sense_fingerprint": "中国的官方语言，使用人数最多的语言之一", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee2f9cf7-edee-4641-928c-f58f95f044af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11890, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "数学", "is_correct": false, "explanation": "语义：数学是一门学科，不是用来交流的语言，与“用简单的……或英语交流”的语境不合。"}, {"text": "中文", "is_correct": true, "explanation": "中文：指中国的语言，与“英语”并列，符合“用……交流”的语境。"}, {"text": "音乐", "is_correct": false, "explanation": "搭配：“用简单的音乐交流”不是常用说法，音乐不是可以进行口头交流的语言系统。"}, {"text": "中国", "is_correct": false, "explanation": "语义：中国是国家名称，不是语言，不能作为交流的工具。"}], "explanations": {"数学": "语义：数学是一门学科，不是用来交流的语言，与“用简单的……或英语交流”的语境不合。", "中文": "中文：指中国的语言，与“英语”并列，符合“用……交流”的语境。", "音乐": "搭配：“用简单的音乐交流”不是常用说法，音乐不是可以进行口头交流的语言系统。", "中国": "语义：中国是国家名称，不是语言，不能作为交流的工具。"}, "sentence_index": 0, "correct_answer": "中文"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的爷爷奶奶一直住在中文。", "explanation": "这里应该用〈中国〉。中国是地方，表示“住在”的地点；中文是语言，不能作为居住的地点。"}, {"text": "这个小孩每天能认十个中文。", "explanation": "这里应该用〈汉字〉。“认十个汉字”是按字数计算的；中文指语言，不能用“十个”来数。"}, {"text": "他学了一块中文，进步很快。", "explanation": "量词错误：中文作为学科或课程，应说“学了一门中文”，不能用“块”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd226ebe4-c57a-4e4c-9505-fe601732452d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11890, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "手机", "is_correct": false, "explanation": "语义：菜单上列出的是菜品或语言，不会列出手机，句意不通。"}, {"text": "中文", "is_correct": true, "explanation": "中文：指中国的语言，与“日文”并列，可以作为菜单上的语言选项。"}, {"text": "典籍", "is_correct": false, "explanation": "语域：“典籍”是书面语中的古代书籍，与菜单这种日常语境不符，也不指语言。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不是菜单上的内容，也不是语言，句子不合理。"}], "explanations": {"手机": "语义：菜单上列出的是菜品或语言，不会列出手机，句意不通。", "中文": "中文：指中国的语言，与“日文”并列，可以作为菜单上的语言选项。", "典籍": "语域：“典籍”是书面语中的古代书籍，与菜单这种日常语境不符，也不指语言。", "汽车": "语义：汽车不是菜单上的内容，也不是语言，句子不合理。"}, "sentence_index": 6, "correct_answer": "中文"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那个中文说得很快。", "explanation": "这里应该用〈外国人〉。中文指语言，不指人，不能作为“说得很快”的主语。"}, {"text": "我妈妈会说一只中文，很厉害。", "explanation": "量词错误：“会说中文”不需要量词，“只”多用于动物等，不能用来计量语言。"}, {"text": "我去中文以后，玩得很开心。", "explanation": "这里应该用〈北京〉。北京是城市，表示去的地方；中文是语言，不是地名，不能作为目的地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd226ebe4-c57a-4e4c-9505-fe601732452d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11890, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他说中文得很流利。", "corrected_sentence": "他说中文说得很流利。", "error_description": "补语位置错误：宾语“中文”之后带“得”补语时，动词要重复，应说“说中文说得很流利”；“说中文得很流利”缺少重复的动词，母语者会觉得不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd226ebe4-c57a-4e4c-9505-fe601732452d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11890, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把中文学了好。", "corrected_sentence": "我把中文学好了。", "error_description": "补语位置错误：结果补语“好”应紧跟动词“学”，说“学好了”，“了”放在补语之后；“学了好”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd226ebe4-c57a-4e4c-9505-fe601732452d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
