INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11891, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "英语是主要在英国、美国、澳大利亚等国家使用的语言，也是国际上最通用的语言之一。", "primary_collocate": null, "pronunciation": "yīng yǔ", "ipa": "iŋ˥ y˨˩˦", "syllable_count": 2, "sentences": [{"text": "有些玩家来自不同的国家，他们用简单的中文或英语交流。", "target_word": "英语", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "英语是很多国家使用的语言。", "target_word": "英语", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在英国长大，英语说得很好。", "target_word": "英语", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开会时我们用英语讨论。", "target_word": "英语", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "英语是国际上最通用的语言之一。", "target_word": "英语", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个网站有中文和英语两种版本。", "target_word": "英语", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她在美国学习英语三年了。", "target_word": "英语", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "澳大利亚的人也说英语。", "target_word": "英语", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "去国外旅行时，英语很有用。", "target_word": "英语", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多国际会议用英语发言。", "target_word": "英语", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "英语课", "label": "复合"}, {"form": "英语老师", "label": "复合"}], "register": "通用", "sense_fingerprint": "英国、美国等国使用的国际通用语言", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee2f9cf7-edee-4641-928c-f58f95f044af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11891, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "英语", "is_correct": true, "explanation": "英语 yīngyǔ：主要在英国、美国等国家使用的语言，是这里的正确答案。"}, {"text": "阴雨", "is_correct": false, "explanation": "阴雨 yīnyǔ 与 英语 yīngyǔ 只有第一个音节的韵尾不同（in 与 ing），意思是阴天下雨。"}, {"text": "冰雨", "is_correct": false, "explanation": "冰雨 bīngyǔ 的第一个音节声母是 b，英语 yīngyǔ 的声母是零声母 y，其余相同，意思是冰冻的雨。"}, {"text": "听雨", "is_correct": false, "explanation": "听雨 tīngyǔ 的第一个音节声母是 t，与英语的零声母 y 不同，意思是听雨声。"}, {"text": "盈余", "is_correct": false, "explanation": "盈余 yíngyú 两个音节的声调都与英语不同（第二声与第一声、第二声与第三声），意思是剩余的钱或利润。"}], "explanations": {"英语": "英语 yīngyǔ：主要在英国、美国等国家使用的语言，是这里的正确答案。", "阴雨": "阴雨 yīnyǔ 与 英语 yīngyǔ 只有第一个音节的韵尾不同（in 与 ing），意思是阴天下雨。", "冰雨": "冰雨 bīngyǔ 的第一个音节声母是 b，英语 yīngyǔ 的声母是零声母 y，其余相同，意思是冰冻的雨。", "听雨": "听雨 tīngyǔ 的第一个音节声母是 t，与英语的零声母 y 不同，意思是听雨声。", "盈余": "盈余 yíngyú 两个音节的声调都与英语不同（第二声与第一声、第二声与第三声），意思是剩余的钱或利润。"}, "sentence_index": null, "correct_answer": "英语"}, "level_3": {"options": [{"text": "数学", "is_correct": false, "explanation": "语义：数学是一门学科，不是用来交流的语言，与“用……交流”的语境不合。"}, {"text": "英语", "is_correct": true, "explanation": "英语：主要在英美等国使用的语言，与“中文”并列，符合语境。"}, {"text": "音乐", "is_correct": false, "explanation": "搭配：“用音乐交流”不是常用说法，音乐不是口头交流的语言系统。"}, {"text": "中国", "is_correct": false, "explanation": "语义：中国是国家名称，不是语言，不能作为交流的工具。"}], "explanations": {"数学": "语义：数学是一门学科，不是用来交流的语言，与“用……交流”的语境不合。", "英语": "英语：主要在英美等国使用的语言，与“中文”并列，符合语境。", "音乐": "搭配：“用音乐交流”不是常用说法，音乐不是口头交流的语言系统。", "中国": "语义：中国是国家名称，不是语言，不能作为交流的工具。"}, "sentence_index": 0, "correct_answer": "英语"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在英语长大，说得很流利。", "explanation": "这里应该用〈英国〉。英国是地方，表示“在……长大”的地点；英语是语言，不能作为地点。"}, {"text": "他学了一把英语。", "explanation": "量词错误：学科或课程用“门”，应说“学了一门英语课”，不能用“把”。"}, {"text": "这件衣服要花五个英语。", "explanation": "这里应该用〈英镑〉。英镑是货币单位，用来计算价钱；英语是语言，不能当作钱数来计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd226ebe4-c57a-4e4c-9505-fe601732452d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11891, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "蛋糕", "is_correct": false, "explanation": "搭配：“学习”后面接的是知识或技能，“学习蛋糕”不成立。"}, {"text": "英语", "is_correct": true, "explanation": "英语：学习的对象是语言，与“三年了”搭配，符合语境。"}, {"text": "椅子", "is_correct": false, "explanation": "搭配：“学习椅子”不成立，椅子不是可以学习的对象。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车是器物，不是知识或语言，“学习汽车”句意不通。"}], "explanations": {"蛋糕": "搭配：“学习”后面接的是知识或技能，“学习蛋糕”不成立。", "英语": "英语：学习的对象是语言，与“三年了”搭配，符合语境。", "椅子": "搭配：“学习椅子”不成立，椅子不是可以学习的对象。", "汽车": "语义：汽车是器物，不是知识或语言，“学习汽车”句意不通。"}, "sentence_index": 6, "correct_answer": "英语"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她每年都去英语旅游。", "explanation": "这里应该用〈美国〉。美国是国家，表示去的地方；英语是语言，不能作为旅游的目的地。"}, {"text": "我会说一张英语，很厉害。", "explanation": "量词错误：“张”用于平面的东西，这里不需要量词，直接说“会说英语”即可。"}, {"text": "那个小男孩是英语。", "explanation": "这里应该用〈英雄〉。英雄指有勇敢事迹的人，英语是语言，不能用来指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd226ebe4-c57a-4e4c-9505-fe601732452d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11891, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把英语学了好。", "corrected_sentence": "他把英语学好了。", "error_description": "补语位置错误：结果补语“好”应紧跟动词“学”，说“学好了”，“了”放在补语之后；“学了好”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd226ebe4-c57a-4e4c-9505-fe601732452d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11891, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我练过一个英语。", "corrected_sentence": "我练过英语。", "error_description": "量词错误：“英语”是语言，不用“一个”计量；应说“练过英语”，去掉多余的量词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd226ebe4-c57a-4e4c-9505-fe601732452d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
