INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11892, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "能完成某项活动的本领，如运用语言交流的本领。", "primary_collocate": null, "pronunciation": "néng lì", "ipa": "nɤŋ˧˥ li˥˩", "syllable_count": 2, "sentences": [{"text": "时间久了，他们的语言能力也会提高。", "target_word": "能力", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "她的工作能力很强，大家都信任她。", "target_word": "能力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多读书可以提高孩子的表达能力。", "target_word": "能力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子学习能力强，一教就会。", "target_word": "能力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的口语能力还需要提高，听新闻有困难。", "target_word": "能力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师希望培养学生的思考能力。", "target_word": "能力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面试时，公司很看重你的实际能力。", "target_word": "能力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的汉语交流能力比去年好多了。", "target_word": "能力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个人的能力不一样，不要和别人比。", "target_word": "能力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份工作需要很强的组织能力。", "target_word": "能力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种能力", "label": "量词"}, {"form": "工作能力", "label": "复合"}, {"form": "学习能力", "label": "复合"}], "register": "中性", "sense_fingerprint": "完成某项活动的本领，如语言交流、工作、学习的能力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bc8c19a-b344-4816-9e61-2e91b5fa9608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11892, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "能力", "is_correct": true, "explanation": "能力：运用语言的本领，句中指语言的运用能力。"}, {"text": "人数", "is_correct": false, "explanation": "语义：“人数”指人的数量，不能说语言的人数提高，句子说不通。"}, {"text": "车速", "is_correct": false, "explanation": "语义：“车速”指车辆的行驶速度，与语言无关，句子说不通。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指人的体形，不能用来说语言的提高。"}], "explanations": {"能力": "能力：运用语言的本领，句中指语言的运用能力。", "人数": "语义：“人数”指人的数量，不能说语言的人数提高，句子说不通。", "车速": "语义：“车速”指车辆的行驶速度，与语言无关，句子说不通。", "身材": "体貌：“身材”指人的体形，不能用来说语言的提高。"}, "sentence_index": 0, "correct_answer": "能力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个孩子总是充满能力，玩起来特别有精神。", "explanation": "这里应该用〈能量〉。能力指做事的本领，形容人精神饱满要用“能量”，不能说“充满能力”。"}, {"text": "这个孩子能力充沛，每天到处跑。", "explanation": "这里应该用〈精力〉。“充沛”形容精神、劲头，能力不能充沛，应说“精力充沛”。"}, {"text": "跑完三千米，这个孩子能力不支，坐在地上起不来。", "explanation": "这里应该用〈体力〉。能力指做事的本领，身体累得撑不住要说“体力不支”，不能说“能力不支”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f08d6a5a-8a71-44e5-b4f0-723d74e024c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11892, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "能力", "is_correct": true, "explanation": "能力：实际做事的本领，句中指工作中的实际本领。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“实际”后面不能接“颜色”，应说“实际能力”，句子说不通。"}, {"text": "方言", "is_correct": false, "explanation": "语义：“方言”指地方话，与面试时考察的实际本领无关，句子说不通。"}, {"text": "时速", "is_correct": false, "explanation": "语义：“时速”指每小时的速度，与面试考察的内容无关，句子说不通。"}], "explanations": {"能力": "能力：实际做事的本领，句中指工作中的实际本领。", "颜色": "搭配：“实际”后面不能接“颜色”，应说“实际能力”，句子说不通。", "方言": "语义：“方言”指地方话，与面试时考察的实际本领无关，句子说不通。", "时速": "语义：“时速”指每小时的速度，与面试考察的内容无关，句子说不通。"}, "sentence_index": 6, "correct_answer": "能力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他最大的能力是太心软。", "explanation": "这里应该用〈弱点〉。能力指做事的本领，不能指缺点，指缺点要说弱点。"}, {"text": "这个房间的能力很大，可以住五个人。", "explanation": "这里应该用〈面积〉。能力指做事的本领，不指空间的大小。"}, {"text": "他的能力很大，一顿能吃五碗饭。", "explanation": "这里应该用〈食量〉。能力指做事的本领，不指饭量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f08d6a5a-8a71-44e5-b4f0-723d74e024c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11892, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个孩子有很强记忆能力，学东西很快。", "corrected_sentence": "这个孩子有很强的记忆能力，学东西很快。", "error_description": "错误形式：“很强记忆能力”；正确形式：“很强的记忆能力”。形容词被“很”修饰后再修饰名词，中间要加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f08d6a5a-8a71-44e5-b4f0-723d74e024c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11892, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他有一只很好的交流能力，进步很快。", "corrected_sentence": "他有一种很好的交流能力，进步很快。", "error_description": "错误形式：“一只很好的交流能力”；正确形式：“一种很好的交流能力”。能力是抽象名词，量词用“种”，“只”多用于动物。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f08d6a5a-8a71-44e5-b4f0-723d74e024c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
