INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11893, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指曾经与某人有过一次或多次见面。", "primary_collocate": null, "pronunciation": "jiàn guo miàn", "ipa": "tɕjɛn kwo mjɛn", "syllable_count": 3, "sentences": [{"text": "虽然大家没见过面，但在虚拟世界里，他们成了很好的伙伴。", "target_word": "见过面", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "我们以前见过面，你还记得我吗？", "target_word": "见过面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他和王老师见过面，所以不用介绍了。", "target_word": "见过面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们两个见过面吗？", "target_word": "见过面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我好像和这位小姐见过面。", "target_word": "见过面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在朋友的婚礼上见过面。", "target_word": "见过面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和他只在北京见过面。", "target_word": "见过面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位客人很眼熟，我们可能见过面。", "target_word": "见过面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虽然我们见过面，但是我忘了他的名字。", "target_word": "见过面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你和我哥哥见过面，对不对？", "target_word": "见过面", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "没见过面", "label": "否定式"}, {"form": "见面", "label": "基本形式"}], "register": "口语", "sense_fingerprint": "见过面：以前曾与某人见面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a269e1a5-c59d-4121-a4c6-6e6ac15ab5ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11893, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "见过面", "is_correct": true, "explanation": "正确：“没见过面”指从未当面相见，与后半句“在虚拟世界里成了很好的伙伴”的转折相合。"}, {"text": "下过雪", "is_correct": false, "explanation": "语义：“下雪”是天气现象，主语不能是“大家”，句意不通。"}, {"text": "结过冰", "is_correct": false, "explanation": "语义：“结冰”指水变成冰，不能以“大家”为主语，句意不通。"}, {"text": "打过折", "is_correct": false, "explanation": "语义：“打折”指商品降价，不能用来说人和人之间的关系，句意不通。"}], "explanations": {"见过面": "正确：“没见过面”指从未当面相见，与后半句“在虚拟世界里成了很好的伙伴”的转折相合。", "下过雪": "语义：“下雪”是天气现象，主语不能是“大家”，句意不通。", "结过冰": "语义：“结冰”指水变成冰，不能以“大家”为主语，句意不通。", "打过折": "语义：“打折”指商品降价，不能用来说人和人之间的关系，句意不通。"}, "sentence_index": 0, "correct_answer": "见过面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨天我在超市和一只小猫见过面。", "explanation": "这里应该用〈看见〉。见过面只指人与人当面相见，不能用来指动物。"}, {"text": "我的电脑和手机昨天见过面了。", "explanation": "这里应该用〈连接〉。见过面只指人与人当面相见，电脑和手机之间应说连接过。"}, {"text": "他一个人在屋里见过面了。", "explanation": "这里应该用〈待过〉。见过面需要两方或多方当面相见，只有一个人在屋里，应说待过。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74ace45c-3452-4966-b173-52fdea0e5bc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11893, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "见过面", "is_correct": true, "explanation": "正确：“只在北京见过面”说明两人只在北京当面相见过，句意通顺。"}, {"text": "出过国", "is_correct": false, "explanation": "语义：“出国”需要离开国境，与“只在北京”矛盾，句意不通。"}, {"text": "登过月", "is_correct": false, "explanation": "语义：“登月”发生在月球，与“只在北京”矛盾，句意不通。"}, {"text": "去过南极", "is_correct": false, "explanation": "语义：“南极”与“只在北京”的地点限定矛盾，句意不通。"}], "explanations": {"见过面": "正确：“只在北京见过面”说明两人只在北京当面相见过，句意通顺。", "出过国": "语义：“出国”需要离开国境，与“只在北京”矛盾，句意不通。", "登过月": "语义：“登月”发生在月球，与“只在北京”矛盾，句意不通。", "去过南极": "语义：“南极”与“只在北京”的地点限定矛盾，句意不通。"}, "sentence_index": 6, "correct_answer": "见过面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我和这个问题在会议上见过面了。", "explanation": "这里应该用〈讨论过〉。见过面只用于人与人当面相见，问题是抽象概念，不能说见过面。"}, {"text": "我在报纸上和他的照片见过面了。", "explanation": "这里应该用〈看过〉。见过面的对象必须是真人，不能用来指照片。"}, {"text": "这两个城市在地图上见过面了。", "explanation": "这里应该用〈查看〉。见过面只用于人与人之间，不能用于地点或事物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74ace45c-3452-4966-b173-52fdea0e5bc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11893, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在大学的时候见面过，只是不太熟。", "corrected_sentence": "我们在大学的时候见过面，只是不太熟。", "error_description": "错误：“过”应紧跟动词，“见过面”是正确形式；写成“见面过”是体标位置错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74ace45c-3452-4966-b173-52fdea0e5bc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11893, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我以前和那位老同学不见过面。", "corrected_sentence": "我以前和那位老同学没见过面。", "error_description": "错误：否定“见过面”这种经历要用“没”，不能用“不”；应为“没见过面”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74ace45c-3452-4966-b173-52fdea0e5bc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11895, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "很差", "is_correct": true, "explanation": "反义：“很好”与“很差”相对，表示关系或质量不令人满意。"}, {"text": "很大", "is_correct": false, "explanation": "无关：“很大”表示大小，与“很好”没有反义关系。"}, {"text": "很快", "is_correct": false, "explanation": "无关：“很快”表示速度，与“很好”没有反义关系。"}, {"text": "很厚", "is_correct": false, "explanation": "无关：“很厚”表示厚度，与“很好”没有反义关系。"}], "correct_answer": "很差", "explanations": {"很差": "反义：“很好”与“很差”相对，表示关系或质量不令人满意。", "很大": "无关：“很大”表示大小，与“很好”没有反义关系。", "很快": "无关：“很快”表示速度，与“很好”没有反义关系。", "很厚": "无关：“很厚”表示厚度，与“很好”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74ace45c-3452-4966-b173-52fdea0e5bc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11895, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "很差", "is_correct": true, "explanation": "反义：“很好”与“很差”相对，表示相处的状况不令人满意。"}, {"text": "很高", "is_correct": false, "explanation": "无关：“很高”表示高度，与“很好”没有反义关系。"}, {"text": "很远", "is_correct": false, "explanation": "无关：“很远”表示距离，与“很好”没有反义关系。"}, {"text": "很轻", "is_correct": false, "explanation": "无关：“很轻”表示重量，与“很好”没有反义关系。"}], "correct_answer": "很差", "explanations": {"很差": "反义：“很好”与“很差”相对，表示相处的状况不令人满意。", "很高": "无关：“很高”表示高度，与“很好”没有反义关系。", "很远": "无关：“很远”表示距离，与“很好”没有反义关系。", "很轻": "无关：“很轻”表示重量，与“很好”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74ace45c-3452-4966-b173-52fdea0e5bc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11895, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "非常好；质量、状态或彼此关系令人满意。", "primary_collocate": null, "pronunciation": "hěn hǎo", "ipa": "xən xɑʊ", "syllable_count": 2, "sentences": [{"text": "虽然大家没见过面，但在虚拟世界里，他们成了很好的伙伴。", "target_word": "很好", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "今天天气很好，我们去公园玩吧。", "target_word": "很好", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的中文说得很好。", "target_word": "很好", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我和同事的关系很好。", "target_word": "很好", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你做得很好，老师很满意。", "target_word": "很好", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里的环境很好，很安静。", "target_word": "很好", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他身体很好，每天都去跑步。", "target_word": "很好", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书的质量很好。", "target_word": "很好", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你的主意很好，我同意。", "target_word": "很好", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她和邻居们相处得很好。", "target_word": "很好", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "好", "label": "基本形式"}, {"form": "更好", "label": "比较形式"}, {"form": "最好", "label": "最高级"}], "register": "中性", "sense_fingerprint": "很好：质量、状态、关系非常令人满意", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a269e1a5-c59d-4121-a4c6-6e6ac15ab5ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11895, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "很好", "is_correct": true, "explanation": "正确：“成了很好的伙伴”表示关系令人满意，与前文的转折相合。"}, {"text": "很冷", "is_correct": false, "explanation": "搭配：“很冷”形容温度，不能修饰“伙伴”，句意不通。"}, {"text": "很重", "is_correct": false, "explanation": "搭配：“伙伴”不能用“重”来形容，句意不通。"}, {"text": "很远", "is_correct": false, "explanation": "语义：“很远”表示距离，与虚拟世界中结成伙伴的关系不符。"}], "explanations": {"很好": "正确：“成了很好的伙伴”表示关系令人满意，与前文的转折相合。", "很冷": "搭配：“很冷”形容温度，不能修饰“伙伴”，句意不通。", "很重": "搭配：“伙伴”不能用“重”来形容，句意不通。", "很远": "语义：“很远”表示距离，与虚拟世界中结成伙伴的关系不符。"}, "sentence_index": 0, "correct_answer": "很好"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条路很好，坑坑洼洼的，车都开不过去。", "explanation": "这里应该用〈坏〉。很好表示令人满意，路况差不能用很好来形容。"}, {"text": "这个孩子很好，一共打碎了十二个杯子。", "explanation": "这里应该用〈淘气〉。很好表示令人满意，打碎很多杯子不能用很好来形容。"}, {"text": "这把椅子很好，四条腿都断了。", "explanation": "这里应该用〈坏〉。很好表示令人满意，椅子断了四条腿不能用很好来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74ace45c-3452-4966-b173-52fdea0e5bc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11895, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "很好", "is_correct": true, "explanation": "正确：“身体很好，每天都去跑步”表示身体状况令人满意，与后文相合。"}, {"text": "很热", "is_correct": false, "explanation": "语义：“很热”多指发烧，与“每天都去跑步”矛盾，句意不通。"}, {"text": "很慢", "is_correct": false, "explanation": "搭配：“身体”不用“慢”来形容，句意不通。"}, {"text": "很沉", "is_correct": false, "explanation": "语义：“很沉”表示身体负担重，与每天跑步的状况不符。"}], "explanations": {"很好": "正确：“身体很好，每天都去跑步”表示身体状况令人满意，与后文相合。", "很热": "语义：“很热”多指发烧，与“每天都去跑步”矛盾，句意不通。", "很慢": "搭配：“身体”不用“慢”来形容，句意不通。", "很沉": "语义：“很沉”表示身体负担重，与每天跑步的状况不符。"}, "sentence_index": 6, "correct_answer": "很好"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台电视很好，屏幕裂了一道大缝。", "explanation": "这里应该用〈坏〉。很好表示令人满意，屏幕裂了不能用很好来形容。"}, {"text": "这条河很好，水里全是垃圾。", "explanation": "这里应该用〈脏〉。很好表示令人满意，水里全是垃圾不能用很好来形容。"}, {"text": "这块布很好，洗了一次就缩成一团。", "explanation": "这里应该用〈差〉。很好表示令人满意，布一洗就缩成一团不能用很好来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74ace45c-3452-4966-b173-52fdea0e5bc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11895, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次旅行的天气好很，我们玩得很开心。", "corrected_sentence": "这次旅行的天气很好，我们玩得很开心。", "error_description": "错误：副词“很”应放在“好”前，“好很”语序错误，正确形式为“很好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74ace45c-3452-4966-b173-52fdea0e5bc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11895, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她和邻居们相处很得好，经常互相帮忙。", "corrected_sentence": "她和邻居们相处得很好，经常互相帮忙。", "error_description": "错误：补语标记“得”应紧跟动词“相处”，“很得好”位置错误，正确形式为“相处得很好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74ace45c-3452-4966-b173-52fdea0e5bc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
