INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11896, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指共同从事某种活动或相互合作的人。", "primary_collocate": null, "pronunciation": "huǒ bàn", "ipa": "xwo pan", "syllable_count": 2, "sentences": [{"text": "虽然大家没见过面，但在虚拟世界里，他们成了很好的伙伴。", "target_word": "伙伴", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "他是我最好的伙伴。", "target_word": "伙伴", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们是学习上的好伙伴。", "target_word": "伙伴", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她是我在研究工作中的好伙伴。", "target_word": "伙伴", "complexity_tier": "T3", "furigana": "tā shì wǒ zài yánjiū gōngzuò zhōng de hǎo huǒbàn.", "sentence_source": "generated"}, {"text": "我想找一个旅行伙伴。", "target_word": "伙伴", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们是多年的工作伙伴。", "target_word": "伙伴", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们公司想找一个可靠的伙伴。", "target_word": "伙伴", "complexity_tier": "T3", "furigana": "wǒmen gōngsī xiǎng zhǎo yí ge kěkào de huǒbàn.", "sentence_source": "generated"}, {"text": "孩子们和新伙伴玩得很开心。", "target_word": "伙伴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她是我跑步时的伙伴。", "target_word": "伙伴", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "在这个项目里，你是我的伙伴。", "target_word": "伙伴", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "伙伴们", "label": "复数"}, {"form": "小伙伴", "label": "复合词"}, {"form": "合作伙伴", "label": "复合词"}, {"form": "个", "label": "量词"}, {"form": "夥伴", "label": "繁体"}], "register": "中性", "sense_fingerprint": "伙伴：共同做事或合作的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a269e1a5-c59d-4121-a4c6-6e6ac15ab5ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11896, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "伙伴", "is_correct": true, "explanation": "正确：“伙伴”指共同做事、相互合作的人，与“很好”以及“虚拟世界里”的交往语境相合。"}, {"text": "敌人", "is_correct": false, "explanation": "语义：“很好的”与“敌人”互相矛盾，敌对的人不可能是很好的伙伴。"}, {"text": "宠物", "is_correct": false, "explanation": "语义：“宠物”指饲养的动物，不能指“他们”这样的人。"}, {"text": "司机", "is_correct": false, "explanation": "语义：“司机”与“伙伴”的合作义不符，“成了很好的司机”句意不通。"}], "explanations": {"伙伴": "正确：“伙伴”指共同做事、相互合作的人，与“很好”以及“虚拟世界里”的交往语境相合。", "敌人": "语义：“很好的”与“敌人”互相矛盾，敌对的人不可能是很好的伙伴。", "宠物": "语义：“宠物”指饲养的动物，不能指“他们”这样的人。", "司机": "语义：“司机”与“伙伴”的合作义不符，“成了很好的司机”句意不通。"}, "sentence_index": 0, "correct_answer": "伙伴"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家的伙伴很热情，常常帮我们浇花。", "explanation": "这里应该用〈邻居〉。“伙伴”指共同做事或相互合作的人，不指住得近的人。"}, {"text": "树上挂满了伙伴。", "explanation": "这里应该用〈果子〉。“伙伴”指共同做事的人，不指树上的果实。"}, {"text": "决赛时他是我的伙伴，我一定要打败他。", "explanation": "这里应该用〈对手〉。“伙伴”指共同做事、相互合作的人，不指比赛中要打败的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74ace45c-3452-4966-b173-52fdea0e5bc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11896, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "伙伴", "is_correct": true, "explanation": "正确：公司要找的是能一起合作的人，“伙伴”指相互合作的人，与“可靠的”相合。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“可靠”多用来形容人或服务，不能用来修饰天气。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不能被“找”来做公司的合作对象。"}, {"text": "对手", "is_correct": false, "explanation": "语义：“对手”是竞争的一方，与公司想找合作者的意图相反。"}], "explanations": {"伙伴": "正确：公司要找的是能一起合作的人，“伙伴”指相互合作的人，与“可靠的”相合。", "天气": "搭配：“可靠”多用来形容人或服务，不能用来修饰天气。", "空气": "语义：空气不能被“找”来做公司的合作对象。", "对手": "语义：“对手”是竞争的一方，与公司想找合作者的意图相反。"}, "sentence_index": 6, "correct_answer": "伙伴"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "剧场里坐满了伙伴。", "explanation": "这里应该用“观众”。“伙伴”指共同做事、相互合作的人，不指只是来看的人。"}, {"text": "景区里来了很多伙伴。", "explanation": "这里应该用“游客”。“伙伴”强调一起做事，不指只来参观的人。"}, {"text": "医院里住满了伙伴。", "explanation": "这里应该用“病人”。“伙伴”指合作做事的人，不指需要治疗的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74ace45c-3452-4966-b173-52fdea0e5bc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11896, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想找一只新伙伴一起练习跳舞。", "corrected_sentence": "我想找一个新伙伴一起练习跳舞。", "error_description": "量词错误：“伙伴”指人，应该用量词“个”，不能用“只”（“只”多用于动物或成对的东西）。正确说法是“一个新伙伴”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74ace45c-3452-4966-b173-52fdea0e5bc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11896, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是我们俱乐部的好地伙伴。", "corrected_sentence": "他是我们俱乐部的好伙伴。", "error_description": "结构助词错误：形容词修饰名词“伙伴”时不能用“地”（“地”用于动词前），这里应去掉“地”，说“好伙伴”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74ace45c-3452-4966-b173-52fdea0e5bc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11897, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "开始", "is_correct": true, "explanation": "正确：“开始”与“结束”构成反义，一个指起头，一个指完成或停止。"}, {"text": "散步", "is_correct": false, "explanation": "“散步”与“结束”之间没有反义关系。"}, {"text": "唱歌", "is_correct": false, "explanation": "“唱歌”与“结束”之间没有反义关系。"}, {"text": "睡觉", "is_correct": false, "explanation": "“睡觉”与“结束”之间没有反义关系。"}], "correct_answer": "开始", "explanations": {"开始": "正确：“开始”与“结束”构成反义，一个指起头，一个指完成或停止。", "散步": "“散步”与“结束”之间没有反义关系。", "唱歌": "“唱歌”与“结束”之间没有反义关系。", "睡觉": "“睡觉”与“结束”之间没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74ace45c-3452-4966-b173-52fdea0e5bc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11897, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "开始", "is_correct": true, "explanation": "正确：“开始”与“结束”构成反义，表示事情的起头。"}, {"text": "写信", "is_correct": false, "explanation": "“写信”与“结束”之间没有反义关系。"}, {"text": "跑步", "is_correct": false, "explanation": "“跑步”与“结束”之间没有反义关系。"}, {"text": "画画", "is_correct": false, "explanation": "“画画”与“结束”之间没有反义关系。"}], "correct_answer": "开始", "explanations": {"开始": "正确：“开始”与“结束”构成反义，表示事情的起头。", "写信": "“写信”与“结束”之间没有反义关系。", "跑步": "“跑步”与“结束”之间没有反义关系。", "画画": "“画画”与“结束”之间没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74ace45c-3452-4966-b173-52fdea0e5bc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11897, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指事物或事情完成、停止，不再继续进行。", "primary_collocate": null, "pronunciation": "jié shù", "ipa": "tɕjɛ˧˥ ʂu˥˩", "syllable_count": 2, "sentences": [{"text": "有时候，游戏结束了，他们还在聊天，分享生活中的事情。", "target_word": "结束", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "电影八点开始，十点结束。", "target_word": "结束", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "会议已经结束了，大家都回家了。", "target_word": "结束", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "假期结束了，我要回学校上课。", "target_word": "结束", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛结束后，我们一起吃饭。", "target_word": "结束", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这场雨什么时候才会结束？", "target_word": "结束", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的工作快要结束了。", "target_word": "结束", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "考试结束，学生们都很高兴。", "target_word": "结束", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下课铃一响，今天的课就结束了。", "target_word": "结束", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争结束后，人们回到了家乡。", "target_word": "结束", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "结束了", "label": "体标"}], "register": "中性", "sense_fingerprint": "事情完成或停止，不再继续", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a269e1a5-c59d-4121-a4c6-6e6ac15ab5ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11897, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "结束", "is_correct": true, "explanation": "正确：jiéshù 即“结束”，指事情完成或停止，不再继续。"}, {"text": "届数", "is_correct": false, "explanation": "jiè（第四声）与 jié（第二声）声调不同，意思是届次的数目。"}, {"text": "节税", "is_correct": false, "explanation": "shuì 与 shù 的韵母不同（多一个 i），意思是节省税款。"}, {"text": "解暑", "is_correct": false, "explanation": "jiě 与 jié、shǔ 与 shù 声调都不同（第三声），意思是消除暑热。"}], "explanations": {"结束": "正确：jiéshù 即“结束”，指事情完成或停止，不再继续。", "届数": "jiè（第四声）与 jié（第二声）声调不同，意思是届次的数目。", "节税": "shuì 与 shù 的韵母不同（多一个 i），意思是节省税款。", "解暑": "jiě 与 jié、shǔ 与 shù 声调都不同（第三声），意思是消除暑热。"}, "sentence_index": null, "correct_answer": "结束"}, "level_3": {"options": [{"text": "结束", "is_correct": true, "explanation": "正确：“结束”表示事情停止、完成，与“游戏……了”的语境相合。"}, {"text": "融化", "is_correct": false, "explanation": "语义：“融化”用于冰雪等物体，游戏不能融化。"}, {"text": "竣工", "is_correct": false, "explanation": "语域：“竣工”是工程用语，与游戏、聊天的口语语境不合。"}, {"text": "生长", "is_correct": false, "explanation": "配价：“生长”的主语须是生物，游戏不能生长。"}], "explanations": {"结束": "正确：“结束”表示事情停止、完成，与“游戏……了”的语境相合。", "融化": "语义：“融化”用于冰雪等物体，游戏不能融化。", "竣工": "语域：“竣工”是工程用语，与游戏、聊天的口语语境不合。", "生长": "配价：“生长”的主语须是生物，游戏不能生长。"}, "sentence_index": 0, "correct_answer": "结束"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他结束了那个苹果。", "explanation": "这里应该用“吃完”。“结束”用于活动或事情的停止，不能直接跟“苹果”这样的具体事物搭配。"}, {"text": "他终于结束了那辆自行车。", "explanation": "这里应该用“修好”。“结束”不能用来说修理好一件物品。"}, {"text": "这栋楼终于结束了。", "explanation": "这里应该用“竣工”。“结束”指活动或事情的停止，不用于说建筑物竣工。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74ace45c-3452-4966-b173-52fdea0e5bc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11897, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "结束", "is_correct": true, "explanation": "正确：“结束”表示工作的完成或停止，与“快要……了”相合。"}, {"text": "生病", "is_correct": false, "explanation": "语义：工作不会生病，“生病”只能用于人或动物。"}, {"text": "发芽", "is_correct": false, "explanation": "语义：“发芽”用于植物，工作不能发芽。"}, {"text": "迟到", "is_correct": false, "explanation": "配价：“迟到”的主语须是人，工作不会迟到。"}], "explanations": {"结束": "正确：“结束”表示工作的完成或停止，与“快要……了”相合。", "生病": "语义：工作不会生病，“生病”只能用于人或动物。", "发芽": "语义：“发芽”用于植物，工作不能发芽。", "迟到": "配价：“迟到”的主语须是人，工作不会迟到。"}, "sentence_index": 6, "correct_answer": "结束"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她结束了饭。", "explanation": "这里应该用“做完”。“结束”用于活动或事情的停止，不能直接跟“饭”这样的具体事物搭配。"}, {"text": "她结束了衣服。", "explanation": "这里应该用“洗完”。“结束”不能直接用于衣服这类具体物品。"}, {"text": "他结束了礼物。", "explanation": "这里应该用“包好”。“结束”不能用来说礼物包装完成。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74ace45c-3452-4966-b173-52fdea0e5bc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11897, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "演唱会结束的很晚。", "corrected_sentence": "演唱会结束得很晚。", "error_description": "结构助词错误：“结束”后的补语要用“得”，不能用“的”。正确说法是“结束得很晚”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74ace45c-3452-4966-b173-52fdea0e5bc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11897, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "演出结束着，观众都走了。", "corrected_sentence": "演出结束了，观众都走了。", "error_description": "“着”的误用：“结束”表示动作完成，不能带“着”表示持续。正确说法是“结束了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74ace45c-3452-4966-b173-52fdea0e5bc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
