INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11898, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指人与人之间通过语言交流，闲谈或讨论事情。", "primary_collocate": null, "pronunciation": "liáo tiān", "ipa": "ljɑʊ˧˥ tʰjɛn˥", "syllable_count": 2, "sentences": [{"text": "有时候，游戏结束了，他们还在聊天，分享生活中的事情。", "target_word": "聊天", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "周末我常和朋友聊天。", "target_word": "聊天", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们在公园里一边走路一边聊天。", "target_word": "聊天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚饭后，爷爷喜欢和邻居聊天。", "target_word": "聊天", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我在手机上和妈妈聊天。", "target_word": "聊天", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师在教室里和学生聊天。", "target_word": "聊天", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别在上课的时候聊天。", "target_word": "聊天", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子睡着了，我们小声聊天。", "target_word": "聊天", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下班后，同事们坐在一起聊天。", "target_word": "聊天", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你想和我聊天吗？", "target_word": "聊天", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "聊聊天", "label": "重叠"}, {"form": "聊了天", "label": "体标"}, {"form": "聊天儿", "label": "儿化"}], "register": "口语", "sense_fingerprint": "人与人用语言闲谈交流", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a269e1a5-c59d-4121-a4c6-6e6ac15ab5ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11898, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "聊天", "is_correct": true, "explanation": "聊天：闲谈，与“分享生活中的事情”的语境相符。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：睡觉时无法分享生活中的事情，与“还在……分享”相矛盾。"}, {"text": "争吵", "is_correct": false, "explanation": "搭配：“争吵”与“分享生活中的事情”语义相反，不能搭配。"}, {"text": "打鼾", "is_correct": false, "explanation": "语义：打鼾是睡眠时发出的声音，不能用来分享事情。"}], "explanations": {"聊天": "聊天：闲谈，与“分享生活中的事情”的语境相符。", "睡觉": "语义：睡觉时无法分享生活中的事情，与“还在……分享”相矛盾。", "争吵": "搭配：“争吵”与“分享生活中的事情”语义相反，不能搭配。", "打鼾": "语义：打鼾是睡眠时发出的声音，不能用来分享事情。"}, "sentence_index": 0, "correct_answer": "聊天"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只小狗整个下午都在和我聊天。", "explanation": "“聊天”的主体须是人，小狗不会用语言和人聊天。"}, {"text": "这台洗衣机整个下午都在和我聊天。", "explanation": "“聊天”的主体须是人，洗衣机不能聊天。"}, {"text": "这盆花整个下午都在窗台上和我聊天。", "explanation": "“聊天”的主体须是人，花不能聊天。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74ace45c-3452-4966-b173-52fdea0e5bc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11898, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "聊天", "is_correct": true, "explanation": "聊天：闲谈，符合“别在上课的时候”后面的动作语境，表示上课时不要闲谈。"}, {"text": "下课", "is_correct": false, "explanation": "语义：“下课”与“上课的时候”时间上相互矛盾，不能在上课时进行。"}, {"text": "毕业", "is_correct": false, "explanation": "体貌：“毕业”是一次完成的动作，不能用于进行中的情境“上课的时候”。"}, {"text": "放假", "is_correct": false, "explanation": "语义：“放假”指停课休息，与“上课的时候”语境相冲突。"}], "explanations": {"聊天": "聊天：闲谈，符合“别在上课的时候”后面的动作语境，表示上课时不要闲谈。", "下课": "语义：“下课”与“上课的时候”时间上相互矛盾，不能在上课时进行。", "毕业": "体貌：“毕业”是一次完成的动作，不能用于进行中的情境“上课的时候”。", "放假": "语义：“放假”指停课休息，与“上课的时候”语境相冲突。"}, "sentence_index": 6, "correct_answer": "聊天"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张桌子整个下午都在和我聊天。", "explanation": "“聊天”的主体须是人，桌子不能聊天。"}, {"text": "这棵树整个下午都在和我聊天。", "explanation": "“聊天”的主体须是人，树不能聊天。"}, {"text": "这台冰箱整个下午都在和我聊天。", "explanation": "“聊天”的主体须是人，冰箱不能聊天。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74ace45c-3452-4966-b173-52fdea0e5bc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11898, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们昨天的一个聊天很愉快。", "corrected_sentence": "我们昨天的一次聊天很愉快。", "error_description": "错误：“聊天”用作名词计次时，量词应用“次”，不能用“个”；应为“一次聊天”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74ace45c-3452-4966-b173-52fdea0e5bc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11898, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "下课了，我们去外面聊天聊天吧。", "corrected_sentence": "下课了，我们去外面聊聊天吧。", "error_description": "错误：“聊天”是离合词，重叠时只重叠“聊”，应为“聊聊天”，不能说“聊天聊天”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74ace45c-3452-4966-b173-52fdea0e5bc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
