INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11902, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人所处的情况和条件，如学习、工作、社会、文化方面的情况。", "primary_collocate": null, "pronunciation": "huán jìng", "ipa": "xu̯an˧˥ tɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这种在线游戏社区，不只是玩游戏的地方，也是一个让人学习协作、面对竞争、理解他人的环境。", "target_word": "环境", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "好的学习环境能帮助孩子进步。", "target_word": "环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的工作环境很轻松，同事都很友好。", "target_word": "环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他刚换了工作，还在适应新环境。", "target_word": "环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家里的环境太吵，我没办法认真学习。", "target_word": "环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师想给学生一个安全的学习环境。", "target_word": "环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在压力很大的环境里，人容易生病。", "target_word": "环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不同的文化环境会影响人的想法。", "target_word": "环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "到了陌生的环境，她有点紧张。", "target_word": "环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济环境不好，很多人找不到工作。", "target_word": "环境", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "生活环境", "label": "复合"}, {"form": "工作环境", "label": "复合"}], "register": "中性", "sense_fingerprint": "人所处的情况和条件，如学习、工作、社会、文化的环境", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63f12163-19cc-4b51-bb0d-63aa4777bd4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11902, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "环境", "is_correct": true, "explanation": "正确：环境指人所处的情况和条件，与“让人学习协作、面对竞争”的语境相符。"}, {"text": "食物", "is_correct": false, "explanation": "语义：食物是吃的东西，不能让人“学习协作、理解他人”。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“理解他人的天气”搭配不当，天气不能被“理解”成人际关系中的场所或条件。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是人可以学习协作、面对竞争的场所或条件，与语境不符。"}], "explanations": {"环境": "正确：环境指人所处的情况和条件，与“让人学习协作、面对竞争”的语境相符。", "食物": "语义：食物是吃的东西，不能让人“学习协作、理解他人”。", "天气": "搭配：“理解他人的天气”搭配不当，天气不能被“理解”成人际关系中的场所或条件。", "颜色": "语义：颜色不是人可以学习协作、面对竞争的场所或条件，与语境不符。"}, "sentence_index": 0, "correct_answer": "环境"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的身体环境很好，能参加马拉松比赛。", "explanation": "这里应该用〈条件〉。环境指人所处的外部情况和条件，不用来说身体、个人素质；说“身体条件很好”才自然。"}, {"text": "这个仓库的环境很大，能放很多货。", "explanation": "这里应该用〈空间〉。环境指周围的地方和条件，不用来说仓库的大小；说“空间很大”才自然。"}, {"text": "这家工厂的环境很害羞，产量很高。", "explanation": "这里应该用〈工人〉。“害羞”形容人，环境不会害羞；说工人害羞才自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51c75b3f-3630-4287-8fee-16b933667255') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11902, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "环境", "is_correct": true, "explanation": "正确：环境指人所处的情况和条件，“压力很大的环境”与“人容易生病”的语境相符。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“压力很大”不能修饰气味，“压力很大的味道”说不通。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音不是人可以“压力很大”所处的场所或条件，与“人容易生病”的语境不符。"}, {"text": "花朵", "is_correct": false, "explanation": "语义：花朵不是让人压力很大、容易生病的场所或条件，与语境不符。"}], "explanations": {"环境": "正确：环境指人所处的情况和条件，“压力很大的环境”与“人容易生病”的语境相符。", "味道": "搭配：“压力很大”不能修饰气味，“压力很大的味道”说不通。", "声音": "语义：声音不是人可以“压力很大”所处的场所或条件，与“人容易生病”的语境不符。", "花朵": "语义：花朵不是让人压力很大、容易生病的场所或条件，与语境不符。"}, "sentence_index": 6, "correct_answer": "环境"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这所医院的环境很贵，病人都很满意。", "explanation": "这里应该用〈费用〉。环境指周围的地方和条件，不用“贵”形容价钱；说费用贵才自然。"}, {"text": "他是一个很好的环境，大家都愿意和他相处。", "explanation": "这里应该用〈人〉。环境指周围的地方和条件，不指人；说某人很好，应说“他是一个很好的人”。"}, {"text": "这所学校的教学环境很高，家长们都很放心。", "explanation": "这里应该用〈水平〉。环境指周围的地方和条件，不用“高”形容高低；说教学水平高才自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51c75b3f-3630-4287-8fee-16b933667255') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11902, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条工作环境很好，大家都愿意来。", "corrected_sentence": "这种工作环境很好，大家都愿意来。", "error_description": "错误：“条”用于细长的东西，不能修饰环境；正确的量词是“种”，应说“这种工作环境”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51c75b3f-3630-4287-8fee-16b933667255') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11902, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这里地学习环境很好，孩子们都很认真。", "corrected_sentence": "这里的学习环境很好，孩子们都很认真。", "error_description": "错误：修饰名词“学习环境”应用“的”，“地”用于修饰动词或形容词；应说“这里的学习环境”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51c75b3f-3630-4287-8fee-16b933667255') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
