INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11905, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "通过学习和实践掌握知识、技能或道理。", "primary_collocate": null, "pronunciation": "xué dào", "ipa": "ɕɥe˧˥ taʊ˥˩", "syllable_count": 2, "sentences": [{"text": "自己动手的过程也很有趣，还能学到很多关于自然循环的知识。", "target_word": "学到", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "虽然世界是虚拟的，但学到的东西是真实的。", "target_word": "学到", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "在中国工作，我学到了很多新东西。", "target_word": "学到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从老师那里学到了做饭的方法。", "target_word": "学到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次旅行你学到了什么？", "target_word": "学到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在网上学到一个有用的办法。", "target_word": "学到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在博物馆学到了很多历史知识。", "target_word": "学到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹学到了怎么用电脑画画。", "target_word": "学到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天上课，我学到三个新词。", "target_word": "学到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做错事以后，他学到了一个道理。", "target_word": "学到", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "學到", "label": "繁体"}, {"form": "学到了", "label": "体标（了）"}, {"form": "学到过", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "通过学习和实践掌握知识、技能或道理", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0ed7dbc-a6e5-40ee-911c-fb724370c835') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11905, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "学到", "is_correct": true, "explanation": "学到：通过学习获得自然循环的知识，与“还能”的积极语境一致。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：忘记与前句“还能”的积极语境相反，句意不通。"}, {"text": "浪费", "is_correct": false, "explanation": "搭配：浪费多用于时间、金钱，不能说浪费知识。"}, {"text": "打碎", "is_correct": false, "explanation": "搭配：打碎用于具体的易碎物，不能用于知识。"}], "explanations": {"学到": "学到：通过学习获得自然循环的知识，与“还能”的积极语境一致。", "忘记": "语义：忘记与前句“还能”的积极语境相反，句意不通。", "浪费": "搭配：浪费多用于时间、金钱，不能说浪费知识。", "打碎": "搭配：打碎用于具体的易碎物，不能用于知识。"}, "sentence_index": 0, "correct_answer": "学到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在门外学到了一阵笑声。", "explanation": "这里应该用〈听到〉。学到的宾语是知识或技能，不能指听见的声音，听见声音要说“听到”。"}, {"text": "这次比赛，他学到了一枚金牌。", "explanation": "这里应该用〈得到〉。学到指通过学习掌握知识、技能，不能用来指获得奖牌。"}, {"text": "我昨天学到了一封信。", "explanation": "这里应该用〈收到〉。学到的宾语是知识或技能，不能指收到的信件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45bd0aa-b3bc-4d3c-b5a0-4dd8d9b903d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11905, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "学到", "is_correct": true, "explanation": "学到：孩子们在博物馆通过学习获得历史知识，与句意一致。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：参观的对象是场所或展品，不能说参观很多历史知识。"}, {"text": "出售", "is_correct": false, "explanation": "语义：出售指把物品卖给他人，知识不能在博物馆里出售，与句意不符。"}, {"text": "拍摄", "is_correct": false, "explanation": "搭配：拍摄的对象是照片或视频，不能用于历史知识。"}], "explanations": {"学到": "学到：孩子们在博物馆通过学习获得历史知识，与句意一致。", "参观": "搭配：参观的对象是场所或展品，不能说参观很多历史知识。", "出售": "语义：出售指把物品卖给他人，知识不能在博物馆里出售，与句意不符。", "拍摄": "搭配：拍摄的对象是照片或视频，不能用于历史知识。"}, "sentence_index": 6, "correct_answer": "学到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在比赛中学到了冠军。", "explanation": "这里应该用〈获得〉。学到的是知识或技能，不能说学到荣誉或名次。"}, {"text": "我在路上学到了老朋友。", "explanation": "这里应该用〈遇到〉。学到不能用于人，也不表示偶然碰见。"}, {"text": "他终于学到了一份合同。", "explanation": "这里应该用〈拿到〉。学到的对象是知识或道理，不能指接收的文件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45bd0aa-b3bc-4d3c-b5a0-4dd8d9b903d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11905, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今天的课上，我学到着很多英语单词。", "corrected_sentence": "今天的课上，我学到了很多英语单词。", "error_description": "错误形式：“学到着”；正确形式：“学到了”。“着”表示持续的状态，而“学到”是已经完成的结果，应用“了”表示完成。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45bd0aa-b3bc-4d3c-b5a0-4dd8d9b903d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11905, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次培训，我学到着很多写作技巧。", "corrected_sentence": "这次培训，我学到了很多写作技巧。", "error_description": "错误形式：“学到着”；正确形式：“学到了”。“着”表示持续的状态，而“学到”是已经完成的结果，应用“了”表示完成。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45bd0aa-b3bc-4d3c-b5a0-4dd8d9b903d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
