INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11906, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "从经历或学习中获得的知识或技能", "primary_collocate": null, "pronunciation": "dōng xi", "ipa": "tʊŋ˥˥ ɕi", "syllable_count": 2, "sentences": [{"text": "它可以帮助人写文章，也能学习新东西。", "target_word": "东西", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虽然世界是虚拟的，但学到的东西是真实的。", "target_word": "东西", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "我在这家公司学到了很多东西。", "target_word": "东西", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "旅行让我明白了很多书里没有的东西。", "target_word": "东西", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师教给我们的东西，我们一辈子都会记得。", "target_word": "东西", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份工作很辛苦，但我从中学到了不少东西。", "target_word": "东西", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跟爷爷一起种菜，我学会了不少东西。", "target_word": "东西", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "失败也不是坏事，能让人学到很多东西。", "target_word": "东西", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做完练习以后，要把学到的东西认真整理一下。", "target_word": "东西", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做这个实验，我们得到了不少课堂上学不到的东西。", "target_word": "东西", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "東西", "label": "繁体"}], "register": "通用", "sense_fingerprint": "通过学习或经历得到的知识、技能、体会，常与“学到”搭配", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3728d7ac-a5c9-42ec-9c46-36da5936aa49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11906, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "东西", "is_correct": true, "explanation": "正确答案。“东西”读作 dōng xi，指所学的内容或知识。"}, {"text": "冬季", "is_correct": false, "explanation": "冬季 dōng jì 的第二个音节声母 j 与 x 不同，声调也不同，意思是冬天的季节。"}, {"text": "冬至", "is_correct": false, "explanation": "冬至 dōng zhì 的第二个音节声母 zh 与 x 不同，意思是二十四节气之一。"}, {"text": "冬日", "is_correct": false, "explanation": "冬日 dōng rì 的第二个音节声母 r 与 x 不同，意思是冬天的日子。"}], "explanations": {"东西": "正确答案。“东西”读作 dōng xi，指所学的内容或知识。", "冬季": "冬季 dōng jì 的第二个音节声母 j 与 x 不同，声调也不同，意思是冬天的季节。", "冬至": "冬至 dōng zhì 的第二个音节声母 zh 与 x 不同，意思是二十四节气之一。", "冬日": "冬日 dōng rì 的第二个音节声母 r 与 x 不同，意思是冬天的日子。"}, "sentence_index": null, "correct_answer": "东西"}, "level_3": {"options": [{"text": "东西", "is_correct": true, "explanation": "正确答案。“东西”指所学的知识，与“学习新东西”相符。"}, {"text": "房子", "is_correct": false, "explanation": "语义：“学习”的对象是知识或技能，“房子”不是可以学习的内容。"}, {"text": "衣服", "is_correct": false, "explanation": "搭配：“学习”后接知识、技能，不接“衣服”。"}, {"text": "脚步", "is_correct": false, "explanation": "语义：“脚步”指走路的动作，不能作为“学习”的对象。"}], "explanations": {"东西": "正确答案。“东西”指所学的知识，与“学习新东西”相符。", "房子": "语义：“学习”的对象是知识或技能，“房子”不是可以学习的内容。", "衣服": "搭配：“学习”后接知识、技能，不接“衣服”。", "脚步": "语义：“脚步”指走路的动作，不能作为“学习”的对象。"}, "sentence_index": 0, "correct_answer": "东西"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那个人是我的老师，我很尊敬那个东西。", "explanation": "这里应该用〈人〉。“东西”指物或所学内容，不能用来指人。"}, {"text": "我的东西很聪明，老师经常夸我。", "explanation": "这里应该用〈头脑〉。“东西”指物或所学内容，不能用来形容人聪明。"}, {"text": "妈妈的东西很温柔，大家都喜欢和她说话。", "explanation": "这里应该用〈性格〉。“东西”指物或所学内容，不能用来形容人的温柔性格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1071fff-adda-4667-bf15-73a50625d246') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11906, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "东西", "is_correct": true, "explanation": "正确答案。“学会了不少东西”指学到了不少知识和技能。"}, {"text": "钞票", "is_correct": false, "explanation": "语义：“学会”的对象是知识或技能，钞票不能被学会。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是实物，不能用“学会”来说。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“学会”后接技能、知识，不能接“桌子”。"}], "explanations": {"东西": "正确答案。“学会了不少东西”指学到了不少知识和技能。", "钞票": "语义：“学会”的对象是知识或技能，钞票不能被学会。", "石头": "语义：石头是实物，不能用“学会”来说。", "桌子": "搭配：“学会”后接技能、知识，不能接“桌子”。"}, "sentence_index": 6, "correct_answer": "东西"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的东西渊博，什么都懂。", "explanation": "这里应该用〈学识〉。“东西”不能用来形容人的学识渊博。"}, {"text": "老师的话让我很感动，我学到的东西很快乐。", "explanation": "这里应该用〈收获〉。“东西”指所学的内容，不能用来形容感受，“快乐”的是人，而不是所学的东西。"}, {"text": "我对家乡有很深的东西。", "explanation": "这里应该用〈感情〉。“东西”不能用来表示情感。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1071fff-adda-4667-bf15-73a50625d246') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11906, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次比赛让我学到了一只东西。", "corrected_sentence": "这次比赛让我学到了一点东西。", "error_description": "“东西”的量词不能用“只”，学到的内容应说“一点东西”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1071fff-adda-4667-bf15-73a50625d246') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11906, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我学到的这些东西们都很有用。", "corrected_sentence": "我学到的这些东西都很有用。", "error_description": "“东西”前已有“这些”表示复数，后面不能再加“们”；“们”只用于人。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1071fff-adda-4667-bf15-73a50625d246') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
