INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11908, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "物体表面因折叠或挤压形成的条状痕迹。", "primary_collocate": null, "pronunciation": "zhě zhòu", "ipa": "ʈʂɤ˨˩ ʈʂoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "这件旧外套经过长期反复折叠，袖口与前襟的褶皱已经深深压进纤维，普通熨烫很难将其彻底抚平。", "target_word": "褶皱", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "这件衬衫上有很多褶皱。", "target_word": "褶皱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用熨斗把衣服上的褶皱烫平了。", "target_word": "褶皱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的裤子膝盖上有一道明显的褶皱。", "target_word": "褶皱", "complexity_tier": "T3", "furigana": "tā de kùzi xīgài shang yǒu yí dào míngxiǎn de zhězhòu.", "sentence_source": "generated"}, {"text": "窗帘的褶皱里藏着一点灰尘。", "target_word": "褶皱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张纸压了很久，全是褶皱。", "target_word": "褶皱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她轻轻抚平了裙子上的褶皱。", "target_word": "褶皱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "沙发上的褶皱说明有人刚坐过。", "target_word": "褶皱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "床单上的褶皱让房间看起来很乱。", "target_word": "褶皱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "衣服放进箱子里太久，会出现褶皱。", "target_word": "褶皱", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "道", "label": "量词"}, {"form": "条", "label": "量词"}, {"form": "褶皺", "label": "繁体"}], "register": "中性", "sense_fingerprint": "褶皱：物体表面因折叠或挤压形成的条状痕迹", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81f83eb8-767f-466e-a846-5878bcd12e3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11908, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "灯泡", "is_correct": false, "explanation": "语义：灯泡是照明器具，不会压进衣物纤维，句中讲的是旧外套，“袖口的灯泡”讲不通。"}, {"text": "褶皱", "is_correct": true, "explanation": "正确：“褶皱”指衣物因折叠、挤压而形成的痕迹，与“反复折叠”“压进纤维”的描写相合。"}, {"text": "茶叶", "is_correct": false, "explanation": "搭配：茶叶不会因折叠留下痕迹，也压不进纤维，“袖口的茶叶”讲不通。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙是开锁的小器具，与衣物的折叠和压痕无关，“前襟的钥匙”讲不通。"}], "explanations": {"灯泡": "语义：灯泡是照明器具，不会压进衣物纤维，句中讲的是旧外套，“袖口的灯泡”讲不通。", "褶皱": "正确：“褶皱”指衣物因折叠、挤压而形成的痕迹，与“反复折叠”“压进纤维”的描写相合。", "茶叶": "搭配：茶叶不会因折叠留下痕迹，也压不进纤维，“袖口的茶叶”讲不通。", "钥匙": "语义：钥匙是开锁的小器具，与衣物的折叠和压痕无关，“前襟的钥匙”讲不通。"}, "sentence_index": 0, "correct_answer": "褶皱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他说话时声音里有很多褶皱。", "explanation": "这里应该用〈起伏〉。褶皱是物体表面折叠或挤压形成的痕迹，声音没有表面，不能有褶皱。"}, {"text": "这块木板上有清晰的褶皱。", "explanation": "这里应该用〈纹路〉。褶皱是折叠或挤压形成的痕迹，木材本身的天然花纹要用纹路。"}, {"text": "他的手机屏幕上多了一道褶皱。", "explanation": "这里应该用〈划痕〉。划痕是物体表面被刮擦留下的细痕，屏幕上的刮伤要用划痕；褶皱多指织物、纸张等被折叠或挤压形成的痕迹。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06c83916-8394-421a-97ba-878b69bf559a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11908, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "褶皱", "is_correct": true, "explanation": "“抚平”的对象是布料表面的起伏，“褶皱”正是这种起伏，因此可以被抚平。"}, {"text": "纽扣", "is_correct": false, "explanation": "语义：纽扣是缝在衣服上的小扣子，不是布料表面的起伏，无法被抚平。"}, {"text": "污渍", "is_correct": false, "explanation": "搭配：“抚平”用于表面起伏，不与“污渍”搭配，污渍只能擦掉或洗掉。"}, {"text": "图案", "is_correct": false, "explanation": "搭配：“抚平”不用于花纹、图案，图案是印或织上去的样式，不是表面的起伏。"}], "explanations": {"褶皱": "“抚平”的对象是布料表面的起伏，“褶皱”正是这种起伏，因此可以被抚平。", "纽扣": "语义：纽扣是缝在衣服上的小扣子，不是布料表面的起伏，无法被抚平。", "污渍": "搭配：“抚平”用于表面起伏，不与“污渍”搭配，污渍只能擦掉或洗掉。", "图案": "搭配：“抚平”不用于花纹、图案，图案是印或织上去的样式，不是表面的起伏。"}, "sentence_index": 6, "correct_answer": "褶皱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衬衫上有一朵褶皱。", "explanation": "这里应该用〈道〉。“朵”用于花朵、云朵等，不用于褶皱这种线状折痕。"}, {"text": "床单上有一只褶皱。", "explanation": "这里应该用〈道〉。“只”是动物及成对事物中单个的量词，褶皱是线状的折痕，应用“道”或“条”。"}, {"text": "窗帘上有一颗褶皱。", "explanation": "这里应该用〈道〉。“颗”用于圆形的小颗粒，不用于褶皱这种线状痕迹。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06c83916-8394-421a-97ba-878b69bf559a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11908, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条裤子的腿上有几只褶皱。", "corrected_sentence": "这条裤子的腿上有几道褶皱。", "error_description": "“褶皱”是线状的折痕，量词应用“道”（或“条”）。“只”多用于动物，此处用“只”是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06c83916-8394-421a-97ba-878b69bf559a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11908, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她的裙子上有一本褶皱。", "corrected_sentence": "她的裙子上有一道褶皱。", "error_description": "量词错误：“褶皱”是线状的折痕，量词应用“道”（或“条”）。“本”用于书本，不能用于褶皱。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06c83916-8394-421a-97ba-878b69bf559a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
