INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11910, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c70347ad-27a5-41a9-9ada-627dc309d573') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11910, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "场域指特定社会活动或现象发生的空间或领域，包括物理空间和抽象情境。", "primary_collocate": null, "pronunciation": "chǎng yù", "ipa": "tʂʰaŋ˨˩˦ y˥˩", "syllable_count": 2, "sentences": [{"text": "从全球趋势看，一次性塑料禁令已超越环境议题本身，演变为国家治理能力与国际形象的象征性场域。", "target_word": "场域", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "在当代数字文明的褶皱深处，互联网早已超越信息传递的原始功能，演变为人类社会互动的重构场域。", "target_word": "场域", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "网络已经成为年轻人表达自己的重要场域。", "target_word": "场域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校不只是学知识的地方，也是一个社会场域。", "target_word": "场域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这个文化场域里，艺术家有很大的影响力。", "target_word": "场域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政治场域中的竞争，常常比人们想的更复杂。", "target_word": "场域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "直播让购物从商店走进了新的消费场域。", "target_word": "场域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学者研究的是不同场域里权力如何运作。", "target_word": "场域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在学术场域里工作了二十年，认识很多人。", "target_word": "场域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社交媒体正在改变公共讨论的场域。", "target_word": "场域", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "文化场域", "label": "复合"}, {"form": "政治场域", "label": "复合"}], "register": "书面", "sense_fingerprint": "场域：特定社会活动发生的空间或领域，兼指实体与抽象情境", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd34bc2cc-089b-431f-93cf-0515a2573957') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11910, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "场域", "is_correct": true, "explanation": "正确。“象征性场域”指具有象征意义的抽象领域，与“国家治理能力与国际形象”相合。"}, {"text": "体温", "is_correct": false, "explanation": "语义：“体温”是身体的温度，不能用“象征性”修饰，句意不通。"}, {"text": "身高", "is_correct": false, "explanation": "语义：“身高”与“国家治理能力”“国际形象”无关，句子说不通。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“象征性”不能修饰“天气”，“象征性天气”不成词组。"}], "explanations": {"场域": "正确。“象征性场域”指具有象征意义的抽象领域，与“国家治理能力与国际形象”相合。", "体温": "语义：“体温”是身体的温度，不能用“象征性”修饰，句意不通。", "身高": "语义：“身高”与“国家治理能力”“国际形象”无关，句子说不通。", "天气": "搭配：“象征性”不能修饰“天气”，“象征性天气”不成词组。"}, "sentence_index": 0, "correct_answer": "场域"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这部电影今晚放映第三场域。", "explanation": "这里应该用〈场次〉。场域指空间或领域，不能用来计算放映的次数，放映的次数要用场次。"}, {"text": "他是一个重要的场域。", "explanation": "场域指空间或领域，不能用来指人。这句话把场域当作人来用，不符合这个意思。"}, {"text": "这个晚会的场域唱了三首歌。", "explanation": "场域指空间或领域，不能唱歌；这里应该用〈歌手〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c70347ad-27a5-41a9-9ada-627dc309d573') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11910, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "场域", "is_correct": true, "explanation": "正确。“新的消费场域”指购物行为发生的新领域，与“直播让购物走进”相合。"}, {"text": "心跳", "is_correct": false, "explanation": "语义：“新的消费心跳”不成立，心跳与消费领域毫无关系。"}, {"text": "眼睛", "is_correct": false, "explanation": "语义：“消费眼睛”说不通，眼睛不能指消费的领域。"}, {"text": "手指", "is_correct": false, "explanation": "搭配：“消费”不与“手指”搭配，句子无法成立。"}], "explanations": {"场域": "正确。“新的消费场域”指购物行为发生的新领域，与“直播让购物走进”相合。", "心跳": "语义：“新的消费心跳”不成立，心跳与消费领域毫无关系。", "眼睛": "语义：“消费眼睛”说不通，眼睛不能指消费的领域。", "手指": "搭配：“消费”不与“手指”搭配，句子无法成立。"}, "sentence_index": 6, "correct_answer": "场域"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在会上发表了自己的场域。", "explanation": "这里应该用〈看法〉。场域指空间或领域，不能用来表示想法，发表想法要用看法。"}, {"text": "这段场域很漫长。", "explanation": "这里应该用〈时间〉。场域指空间或领域，一段持续的时间要用时间。"}, {"text": "这台电脑是一个场域。", "explanation": "场域指空间或领域，不能指电脑这类物品，这种用法不符合这个意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c70347ad-27a5-41a9-9ada-627dc309d573') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11910, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "社交平台成了年轻人交流的一条重要场域。", "corrected_sentence": "社交平台成了年轻人交流的一个重要场域。", "error_description": "量词错误：“场域”应配“个”，“条”用于细长之物，不能用来计量场域。应说“一个重要场域”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c70347ad-27a5-41a9-9ada-627dc309d573') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11910, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们被学术场域里讨论问题。", "corrected_sentence": "我们在学术场域里讨论问题。", "error_description": "介词误用：「被」表被动，此处表处所应用「在」，应为「我们在学术场域里讨论问题」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c70347ad-27a5-41a9-9ada-627dc309d573') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11911, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3a74a9a-679b-4ecf-85be-2858191ca49d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11911, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3a74a9a-679b-4ecf-85be-2858191ca49d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11911, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "比喻完全处于某种境界或思想活动中，全身心投入。", "primary_collocate": null, "pronunciation": "chén jìn", "ipa": "ʈʂʰən˧˥ tɕin˥˩", "syllable_count": 2, "sentences": [{"text": "尤其在虚拟世界中，玩家一旦沉浸其中，便不再仅是规则的被动遵循者，而成为动态社会关系的主动缔造者。", "target_word": "沉浸", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "在此类框架下，讲述一则民间传说不仅是在复述往事，更是在执行一种文化实践：说者通过语言激活神圣时空，听者则在沉浸中获得身份认同的再确认。", "target_word": "沉浸", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "她沉浸在音乐里，没听见我叫她。", "target_word": "沉浸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们沉浸在节日的快乐中。", "target_word": "沉浸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他沉浸在回忆里，好久没有说话。", "target_word": "沉浸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "读这本书时，我完全沉浸在故事里。", "target_word": "沉浸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家沉浸在胜利的喜悦中，笑个不停。", "target_word": "沉浸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她总是沉浸在自己的世界里。", "target_word": "沉浸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他沉浸在悲伤中，不想见任何人。", "target_word": "沉浸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电影太好看了，观众都沉浸其中。", "target_word": "沉浸", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "沉浸着", "label": "体标"}, {"form": "沉浸了", "label": "体标"}, {"form": "沉浸式", "label": "复合"}], "register": "中性", "sense_fingerprint": "比喻全身心投入某种境界或思绪", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94b4d57c-ba46-40c9-9d83-b3978f6c429b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11911, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "旁观", "is_correct": false, "explanation": "语义：旁观是置身事外，与后文“玩家……成为主动缔造者”的参与感相反。"}, {"text": "逃避", "is_correct": false, "explanation": "语义：逃避是躲开，与“主动缔造者”的积极参与相矛盾。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：放弃是舍弃，与“成为……的主动缔造者”的积极参与正相反。"}, {"text": "沉浸", "is_correct": true, "explanation": "沉浸指完全投入某种境界，与“玩家一旦……其中”的语境相符。"}], "explanations": {"旁观": "语义：旁观是置身事外，与后文“玩家……成为主动缔造者”的参与感相反。", "逃避": "语义：逃避是躲开，与“主动缔造者”的积极参与相矛盾。", "放弃": "语义：放弃是舍弃，与“成为……的主动缔造者”的积极参与正相反。", "沉浸": "沉浸指完全投入某种境界，与“玩家一旦……其中”的语境相符。"}, "sentence_index": 0, "correct_answer": "沉浸"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他沉浸了一本小说，一个下午就读完了。", "explanation": "这里应该用〈读〉。〈沉浸〉是不及物动词，不能直接带“一本小说”作宾语；“读”可以带书名。"}, {"text": "他沉浸了一身的汗，回家就躺下了。", "explanation": "这里应该用〈淌〉。〈沉浸〉不能与“一身的汗”搭配，“淌了一身的汗”才自然。"}, {"text": "这个想法太沉浸了，大家都听不懂。", "explanation": "这里应该用〈深奥〉。〈沉浸〉是动词，不能用来形容“想法”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3a74a9a-679b-4ecf-85be-2858191ca49d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11911, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "哭泣", "is_correct": false, "explanation": "语义：哭泣与后文“笑个不停”相矛盾。"}, {"text": "发愁", "is_correct": false, "explanation": "语义：发愁是忧虑，与“胜利的喜悦”的心情相反。"}, {"text": "争吵", "is_correct": false, "explanation": "搭配：“争吵”多说与某人争吵，不能接“在……中”这样的状态结构。"}, {"text": "沉浸", "is_correct": true, "explanation": "沉浸指全身心投入某种情绪或境界，与“胜利的喜悦中”的状态相符。"}], "explanations": {"哭泣": "语义：哭泣与后文“笑个不停”相矛盾。", "发愁": "语义：发愁是忧虑，与“胜利的喜悦”的心情相反。", "争吵": "搭配：“争吵”多说与某人争吵，不能接“在……中”这样的状态结构。", "沉浸": "沉浸指全身心投入某种情绪或境界，与“胜利的喜悦中”的状态相符。"}, "sentence_index": 6, "correct_answer": "沉浸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大船在暴风雨中沉浸了，船上的人没能逃出来。", "explanation": "这里应该用〈沉没〉。〈沉浸〉指浸入或投入，不用来指船只沉下去。"}, {"text": "她把全部积蓄沉浸在网店里，半年就关门了。", "explanation": "这里应该用〈投入〉。〈沉浸〉指心神或状态的投入，不用来说把钱投进去。"}, {"text": "他把头沉浸到枕头里，很快就睡着了。", "explanation": "这里应该用〈埋〉。〈沉浸〉指全身心投入，不用来说把头放进某物里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3a74a9a-679b-4ecf-85be-2858191ca49d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11911, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈沉浸回忆中，眼睛湿湿的。", "corrected_sentence": "妈妈沉浸在回忆中，眼睛湿湿的。", "error_description": "介词缺失：“沉浸”后面要用“在……中”引出所沉浸的对象，应说“沉浸在回忆中”，不能省略“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3a74a9a-679b-4ecf-85be-2858191ca49d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11911, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他终于沉浸了在工作里，忘了吃饭。", "corrected_sentence": "他终于沉浸在工作里，忘了吃饭。", "error_description": "“了”的位置错误：“了”不能插在“沉浸”和“在”之间，应说“沉浸在工作里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3a74a9a-679b-4ecf-85be-2858191ca49d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11913, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "主动", "is_correct": true, "explanation": "正确。“主动”与“被动”互为反义，指自己发起行动、不等待外力。"}, {"text": "聪明", "is_correct": false, "explanation": "与“被动”无反义关系，“聪明”描述才智，不是“被动”的对义词。"}, {"text": "安静", "is_correct": false, "explanation": "与“被动”无反义关系，“安静”的对义词是“吵闹”。"}, {"text": "轻松", "is_correct": false, "explanation": "与“被动”无反义关系，“轻松”的对义词是“紧张”。"}], "correct_answer": "主动", "explanations": {"主动": "正确。“主动”与“被动”互为反义，指自己发起行动、不等待外力。", "聪明": "与“被动”无反义关系，“聪明”描述才智，不是“被动”的对义词。", "安静": "与“被动”无反义关系，“安静”的对义词是“吵闹”。", "轻松": "与“被动”无反义关系，“轻松”的对义词是“紧张”。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3a74a9a-679b-4ecf-85be-2858191ca49d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11913, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "主动", "is_correct": true, "explanation": "正确。“主动”与“被动”互为反义，指自己发起行动。"}, {"text": "清楚", "is_correct": false, "explanation": "与“被动”无反义关系，“清楚”的对义词是“模糊”。"}, {"text": "热闹", "is_correct": false, "explanation": "与“被动”无反义关系，“热闹”的对义词是“冷清”。"}, {"text": "复杂", "is_correct": false, "explanation": "与“被动”无反义关系，“复杂”的对义词是“简单”。"}], "correct_answer": "主动", "explanations": {"主动": "正确。“主动”与“被动”互为反义，指自己发起行动。", "清楚": "与“被动”无反义关系，“清楚”的对义词是“模糊”。", "热闹": "与“被动”无反义关系，“热闹”的对义词是“冷清”。", "复杂": "与“被动”无反义关系，“复杂”的对义词是“简单”。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3a74a9a-679b-4ecf-85be-2858191ca49d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11913, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指受外力影响或控制，不能主动行动或做出选择。", "primary_collocate": null, "pronunciation": "bèi dòng", "ipa": "pei˥˩ tʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "尤其在高度沉浸式的虚拟世界中，玩家不再仅是规则的被动遵循者，而成为动态社会关系的主动缔造者。", "target_word": "被动", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "用户不再是被动接受预设行为逻辑的终端使用者，而成为代理演化方向的主导者，其价值观、偏好与伦理准则可被持续嵌入代理的认知循环。", "target_word": "被动", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "在这件事上，他总是很被动。", "target_word": "被动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工作中太被动，机会就会错过。", "target_word": "被动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们不能一直被动地等别人帮忙。", "target_word": "被动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛一开始，我们队就很被动。", "target_word": "被动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "事情发展得太快，我们只能被动地接受结果。", "target_word": "被动", "complexity_tier": "T3", "furigana": "bèi dòng", "sentence_source": "generated"}, {"text": "我不想再被动地过日子了。", "target_word": "被动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "由于没有准备，我们一直处于被动。", "target_word": "被动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学习要主动，不要太被动。", "target_word": "被动", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "被动地", "label": "状语形式"}, {"form": "被动语态", "label": "复合"}], "register": "中性", "sense_fingerprint": "受外力影响或控制，不能主动行动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94b4d57c-ba46-40c9-9d83-b3978f6c429b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11913, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "被动", "is_correct": true, "explanation": "正确。“规则的被动遵循者”与后句“成为……的主动缔造者”形成对比，只有“被动”符合语境。"}, {"text": "叛逆", "is_correct": false, "explanation": "语义：“叛逆”指反抗、不服管束，与“遵循规则”的含义正相反。"}, {"text": "随意", "is_correct": false, "explanation": "语义：“随意”指不受约束、随便，与“遵循规则”的严肃含义相矛盾。"}, {"text": "独立", "is_correct": false, "explanation": "搭配：“遵循”意为依照，需要依附于规则，与“独立”搭配不当。"}], "explanations": {"被动": "正确。“规则的被动遵循者”与后句“成为……的主动缔造者”形成对比，只有“被动”符合语境。", "叛逆": "语义：“叛逆”指反抗、不服管束，与“遵循规则”的含义正相反。", "随意": "语义：“随意”指不受约束、随便，与“遵循规则”的严肃含义相矛盾。", "独立": "搭配：“遵循”意为依照，需要依附于规则，与“独立”搭配不当。"}, "sentence_index": 0, "correct_answer": "被动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他被动地抓住了这次机会，连夜准备了完整的方案。", "explanation": "这里应用〈积极〉。“被动”指不能主动行动，与“抓住机会、连夜准备方案”的主动行为矛盾。"}, {"text": "这个方案是他被动想出来的，细节考虑得非常周全。", "explanation": "这里应用〈主动〉。“被动”指不能主动行动，与“想出方案、考虑周全”的主动思考矛盾。"}, {"text": "他选择得很被动，早就想好了每一步。", "explanation": "这里应用〈自主〉。“被动”指不能做出选择，与“早就想好每一步”的自主决定矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3a74a9a-679b-4ecf-85be-2858191ca49d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11913, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "被动", "is_correct": true, "explanation": "正确。“只能……接受结果”说明没有选择余地，与“被动”相合。"}, {"text": "主动", "is_correct": false, "explanation": "语义：“主动”指自己发起行动，与“只能……接受”的无选择处境相悖。"}, {"text": "自愿", "is_correct": false, "explanation": "语义：“自愿”表示出于本人意愿，与“只能”的被迫处境相矛盾。"}, {"text": "积极", "is_correct": false, "explanation": "语义：“只能”表示别无选择，“积极”指主动努力，与“只能……接受”的无选择处境相悖。"}], "explanations": {"被动": "正确。“只能……接受结果”说明没有选择余地，与“被动”相合。", "主动": "语义：“主动”指自己发起行动，与“只能……接受”的无选择处境相悖。", "自愿": "语义：“自愿”表示出于本人意愿，与“只能”的被迫处境相矛盾。", "积极": "语义：“只能”表示别无选择，“积极”指主动努力，与“只能……接受”的无选择处境相悖。"}, "sentence_index": 6, "correct_answer": "被动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次谈判他很被动，把所有条件都提前摆了出来。", "explanation": "这里应用〈积极〉。“被动”指不能主动行动，与“提前把条件都摆出来”的主动行为矛盾。"}, {"text": "他性格很被动，每次班会都是第一个站起来发言。", "explanation": "这里应用〈踊跃〉。“被动”指不能主动行动，与“每次第一个站起来发言”的积极表现矛盾。"}, {"text": "这件事他被动地亲自跑了三趟，把每个细节都落实了。", "explanation": "这里应用〈自觉〉。“被动”指受外力影响、不能主动行动，与“亲自跑三趟、落实每个细节”的主动行为矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3a74a9a-679b-4ecf-85be-2858191ca49d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11913, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他被动的接受了这个安排。", "corrected_sentence": "他被动地接受了这个安排。", "error_description": "“被动”作状语修饰动词“接受”，应用“地”；此处误用“的”（定语标记）。正确：他被动地接受了这个安排。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3a74a9a-679b-4ecf-85be-2858191ca49d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11913, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他什么都要人催，在家里非常被动地。", "corrected_sentence": "他什么都要人催，在家里非常被动。", "error_description": "“被动地”是状语形式，后面必须接动词；这里“被动”作谓语，句末不能加“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3a74a9a-679b-4ecf-85be-2858191ca49d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11914, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3a74a9a-679b-4ecf-85be-2858191ca49d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11914, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3a74a9a-679b-4ecf-85be-2858191ca49d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11914, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指人与人之间在交往、互动中形成的联系和纽带，如亲戚、朋友、同事等关系。", "primary_collocate": null, "pronunciation": "shè huì guān xì", "ipa": "ʂɤ˥˩ xweɪ˥˩ kwan˥ ɕi˥˩", "syllable_count": 4, "sentences": [{"text": "尤其在高度沉浸式的虚拟世界中，玩家不再仅是规则的被动遵循者，而成为动态社会关系的主动缔造者。", "target_word": "社会关系", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "由此，水资源不仅是物质供给的载体，更是社会关系与文化认同的纽带。", "target_word": "社会关系", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "她刚来这座城市，社会关系还很简单。", "target_word": "社会关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬家以后，他的社会关系发生了很大变化。", "target_word": "社会关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "亲戚、朋友和同事，都是我们的社会关系。", "target_word": "社会关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的社会关系需要用心维护。", "target_word": "社会关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他工作很忙，没有时间处理复杂的社会关系。", "target_word": "社会关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人退休后，社会关系慢慢变少了。", "target_word": "社会关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子上学以后，开始建立自己的社会关系。", "target_word": "社会关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在小镇上，邻居之间的社会关系非常密切。", "target_word": "社会关系", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "社会关系网", "label": "复合"}, {"form": "社會關係", "label": "繁体"}], "register": "中性", "sense_fingerprint": "人与人交往中形成的亲友同事等联系", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94b4d57c-ba46-40c9-9d83-b3978f6c429b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11914, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "社会关系", "is_correct": true, "explanation": "正确。“玩家”“规则”的语境中，“社会关系”指人与人之间的联系，与“动态……的主动缔造者”相合。"}, {"text": "性格", "is_correct": false, "explanation": "搭配：“动态”一般不修饰“性格”，“动态性格”不成搭配。"}, {"text": "数学公式", "is_correct": false, "explanation": "语义：句子讲的是玩家与人际关系的互动，“数学公式”与此语境不符。"}, {"text": "化学反应", "is_correct": false, "explanation": "语义：“化学反应”属于自然科学范畴，与虚拟世界中的社会互动语境不符。"}], "explanations": {"社会关系": "正确。“玩家”“规则”的语境中，“社会关系”指人与人之间的联系，与“动态……的主动缔造者”相合。", "性格": "搭配：“动态”一般不修饰“性格”，“动态性格”不成搭配。", "数学公式": "语义：句子讲的是玩家与人际关系的互动，“数学公式”与此语境不符。", "化学反应": "语义：“化学反应”属于自然科学范畴，与虚拟世界中的社会互动语境不符。"}, "sentence_index": 0, "correct_answer": "社会关系"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的社会关系很高，大家都很尊敬他。", "explanation": "这里应用〈社会地位〉。“社会关系”指人与人之间的联系，不能用“高”来形容；“社会地位”才说“高”。"}, {"text": "他很努力地履行社会关系，从不偷懒。", "explanation": "这里应用〈社会责任〉。“履行”的对象是责任、义务，“社会关系”是人际联系，不能被履行。"}, {"text": "他大学主修社会关系，毕业后去了研究所。", "explanation": "这里应用〈社会学〉。“社会关系”指人与人之间的联系，不是学科名称；学科名称是“社会学”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3a74a9a-679b-4ecf-85be-2858191ca49d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11914, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "社会关系", "is_correct": true, "explanation": "正确。“处理复杂的”后接人际联系，符合句意。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“天气”不能被“处理”，“复杂的天气”也不成搭配。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”不能用“处理”来搭配，“复杂的颜色”也不自然。"}, {"text": "时间", "is_correct": false, "explanation": "语义：句中已说“没有时间”，再以“时间”作宾语造成语义矛盾。"}], "explanations": {"社会关系": "正确。“处理复杂的”后接人际联系，符合句意。", "天气": "搭配：“天气”不能被“处理”，“复杂的天气”也不成搭配。", "颜色": "搭配：“颜色”不能用“处理”来搭配，“复杂的颜色”也不自然。", "时间": "语义：句中已说“没有时间”，再以“时间”作宾语造成语义矛盾。"}, "sentence_index": 6, "correct_answer": "社会关系"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每个月都按时缴纳社会关系，从不拖欠。", "explanation": "这里应用〈社会保险〉。“缴纳”的对象是保险费，“社会关系”指人际联系，不能被缴纳。"}, {"text": "他从小就很遵守社会关系，从不违规。", "explanation": "这里应用〈社会规则〉。“遵守”的对象是规则、法律，社会关系不能被遵守。"}, {"text": "社会关系很关注这件事的进展。", "explanation": "这里应用〈社会舆论〉。“关注”的主体是人或舆论，“社会关系”是联系，不能作施事去关注事情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3a74a9a-679b-4ecf-85be-2858191ca49d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11914, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他刚毕业，就建立了一棵新的社会关系。", "corrected_sentence": "他刚毕业，就建立了一种新的社会关系。", "error_description": "量词错误：“社会关系”是抽象的人际联系，“棵”只用于植物，应用量词“种”。正确：他刚毕业，就建立了一种新的社会关系。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3a74a9a-679b-4ecf-85be-2858191ca49d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11914, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他刚搬进新小区，社会关系们很简单。", "corrected_sentence": "他刚搬进新小区，社会关系很简单。", "error_description": "“社会关系”是抽象名词，不能加“们”表示复数；此处误加“们”。正确：他刚搬进新小区，社会关系很简单。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3a74a9a-679b-4ecf-85be-2858191ca49d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11915, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06c83916-8394-421a-97ba-878b69bf559a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11915, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06c83916-8394-421a-97ba-878b69bf559a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11915, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指建立、创立某个组织、国家或重大事业的人。", "primary_collocate": null, "pronunciation": "dì zào zhě", "ipa": "ti˥˩ tsɑʊ˥˩ ʈʂɤ˨˩", "syllable_count": 3, "sentences": [{"text": "在那场深刻的社会变革中，他们不再只是制度的被动承受者，而成为新国家体制的主动缔造者。", "target_word": "缔造者", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "他是这家公司的缔造者。", "target_word": "缔造者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "人们尊敬这个国家的缔造者。", "target_word": "缔造者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位缔造者用一生建立了这所大学。", "target_word": "缔造者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他是新中国的缔造者之一。", "target_word": "缔造者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "作为公司的缔造者，他很少休息。", "target_word": "缔造者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座城市的缔造者在二百年前来到这里。", "target_word": "缔造者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的缔造者把全部财产捐给了学生。", "target_word": "缔造者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "缔造者去世后，大家继续他的事业。", "target_word": "缔造者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她是这个品牌的缔造者，也是第一位员工。", "target_word": "缔造者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "締造者", "label": "繁体"}], "register": "书面", "sense_fingerprint": "缔造者：建立、创立组织、国家或重大事业的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81f83eb8-767f-466e-a846-5878bcd12e3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11915, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "受害者", "is_correct": false, "explanation": "语义：“主动”与“受害者”语义矛盾，受害者是被动承受伤害的人。"}, {"text": "旁观者", "is_correct": false, "explanation": "语义：旁观者不参与事情，与“主动”以及“缔造新国家体制”的语境相悖。"}, {"text": "乘客", "is_correct": false, "explanation": "搭配：“乘客”指乘坐交通工具的人，与“缔造新国家体制”的语境无关，不能充当缔造者。"}, {"text": "缔造者", "is_correct": true, "explanation": "正确：“缔造者”指主动创立组织、国家或事业的人，与“主动”搭配，符合句中语境。"}], "explanations": {"受害者": "语义：“主动”与“受害者”语义矛盾，受害者是被动承受伤害的人。", "旁观者": "语义：旁观者不参与事情，与“主动”以及“缔造新国家体制”的语境相悖。", "乘客": "搭配：“乘客”指乘坐交通工具的人，与“缔造新国家体制”的语境无关，不能充当缔造者。", "缔造者": "正确：“缔造者”指主动创立组织、国家或事业的人，与“主动”搭配，符合句中语境。"}, "sentence_index": 0, "correct_answer": "缔造者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位诗人是这首诗的缔造者。", "explanation": "这里应该用〈作者〉。缔造多用于组织、国家、重大事业；诗歌等作品的创作者叫作者。"}, {"text": "他是这个小错误的缔造者。", "explanation": "这里应该用〈制造者〉。缔造指创立组织、国家或重大事业，带庄重褒义，不能用于小错误。"}, {"text": "妈妈是这盘饺子的缔造者。", "explanation": "这里应该用〈做的人〉。缔造指创立组织、国家或重大事业，做饭这类日常小事不能用缔造者。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06c83916-8394-421a-97ba-878b69bf559a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11915, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "缔造者", "is_correct": true, "explanation": "“缔造者”指创立城市、事业的人，可以在二百年前来到这里，符合句子语境。"}, {"text": "图书馆", "is_correct": false, "explanation": "配价：“来到”要求有生命的人作主语，“图书馆”是建筑，不能“来到这里”。"}, {"text": "河流", "is_correct": false, "explanation": "配价：河流不能“来到”某地，且与“缔造者”指人的语境不合。"}, {"text": "墓碑", "is_correct": false, "explanation": "语义：墓碑是立于墓地的石碑，没有行动能力，也与创立城市的人的身份不合。"}], "explanations": {"缔造者": "“缔造者”指创立城市、事业的人，可以在二百年前来到这里，符合句子语境。", "图书馆": "配价：“来到”要求有生命的人作主语，“图书馆”是建筑，不能“来到这里”。", "河流": "配价：河流不能“来到”某地，且与“缔造者”指人的语境不合。", "墓碑": "语义：墓碑是立于墓地的石碑，没有行动能力，也与创立城市的人的身份不合。"}, "sentence_index": 6, "correct_answer": "缔造者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位老人是这所学校的一颗缔造者。", "explanation": "这里应该用〈位〉。“颗”用于圆形的小颗粒，不用于指人的“缔造者”。"}, {"text": "那位工程师是这座桥的一条缔造者。", "explanation": "这里应该用〈位〉。“条”用于细长的事物，不用于指人的“缔造者”。"}, {"text": "这位商人是这家公司的一只缔造者。", "explanation": "这里应该用〈位〉。“只”多用于动物，不用于指人的“缔造者”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06c83916-8394-421a-97ba-878b69bf559a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11915, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是这家工厂的一只缔造者。", "corrected_sentence": "他是这家工厂的一位缔造者。", "error_description": "“缔造者”指人，量词应用“位”。“只”多用于动物，此处用“只”是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06c83916-8394-421a-97ba-878b69bf559a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11915, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她是这所大学的缔造者一。", "corrected_sentence": "她是这所大学的缔造者之一。", "error_description": "“缔造者之一”是固定组合，“之”不能省略；这里漏掉了“之”，应为“缔造者之一”，“缔造者一”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06c83916-8394-421a-97ba-878b69bf559a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
