INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11917, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "宇宙指包括所有天体、空间、时间及其中的一切物质和能量的总称。", "primary_collocate": null, "pronunciation": "yǔ zhòu", "ipa": "y˨˩ ʈʂoʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "这些由代码编织的宇宙，既容纳着零和博弈的激烈竞争，也孕育着超越物理边界、文化隔阂的深度协作。", "target_word": "宇宙", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "科学家一直在研究宇宙是怎样开始的。", "target_word": "宇宙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宇宙非常大，人类只知道其中很小一部分。", "target_word": "宇宙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里看着星空，我常想宇宙到底有多大。", "target_word": "宇宙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就对宇宙的秘密很感兴趣。", "target_word": "宇宙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宇宙中有数不清的星系。", "target_word": "宇宙", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师给我们讲了宇宙的年龄。", "target_word": "宇宙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宇宙里没有声音，因为那里没有空气。", "target_word": "宇宙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家用大望远镜观察遥远的宇宙。", "target_word": "宇宙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影讲的是人类探索宇宙的故事。", "target_word": "宇宙", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "宇宙飞船", "label": "复合"}, {"form": "宇宙空间", "label": "复合"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "宇宙|包括一切天体、时空、物质和能量的总体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2591be7d-c461-4a95-9b42-c5a8240a6d00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11917, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "花瓶", "is_correct": false, "explanation": "语义：花瓶是器物，不能孕育协作，也不能容纳激烈竞争。"}, {"text": "宇宙", "is_correct": true, "explanation": "宇宙指包括一切天体、时空和物质的总体，既能容纳竞争，也能孕育协作，符合句意。"}, {"text": "毛衣", "is_correct": false, "explanation": "搭配：“容纳”和“孕育”要求的主语是空间或整体，“毛衣”不能与这两个动词搭配。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟是计时器具，不能容纳竞争，也不能孕育协作。"}], "explanations": {"花瓶": "语义：花瓶是器物，不能孕育协作，也不能容纳激烈竞争。", "宇宙": "宇宙指包括一切天体、时空和物质的总体，既能容纳竞争，也能孕育协作，符合句意。", "毛衣": "搭配：“容纳”和“孕育”要求的主语是空间或整体，“毛衣”不能与这两个动词搭配。", "闹钟": "语义：闹钟是计时器具，不能容纳竞争，也不能孕育协作。"}, "sentence_index": 0, "correct_answer": "宇宙"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个房间的宇宙很大，可以放下两张床。", "explanation": "这里应该用〈空间〉。宇宙指天体、时空与其中的一切物质，不用来形容房间这样有限的范围。"}, {"text": "这本书的宇宙是关于友谊的。", "explanation": "这里应该用〈内容〉。宇宙指天体、时空与其中一切物质的总称，说书里讲了什么要用“内容”。"}, {"text": "宇宙上最高的山是珠穆朗玛峰。", "explanation": "这里应该用〈世界〉。宇宙指天体与时空的总和，不能用“宇宙上”来指地球上的地理位置。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f3c368d-00d4-4a6c-a492-be7f979f4ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11917, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "语义：颜色没有年龄，无法讲述它的年龄。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“年龄”一般用于有生命或有历史的事物，“声音”不能与“年龄”搭配。"}, {"text": "宇宙", "is_correct": true, "explanation": "宇宙有诞生至今的时间，可以讲述它的年龄，符合句意。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是短暂变化的现象，没有可以讲述的年龄。"}], "explanations": {"颜色": "语义：颜色没有年龄，无法讲述它的年龄。", "声音": "搭配：“年龄”一般用于有生命或有历史的事物，“声音”不能与“年龄”搭配。", "宇宙": "宇宙有诞生至今的时间，可以讲述它的年龄，符合句意。", "天气": "语义：天气是短暂变化的现象，没有可以讲述的年龄。"}, "sentence_index": 6, "correct_answer": "宇宙"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "傍晚的宇宙很蓝，像被染过一样。", "explanation": "这里应该用〈天空〉。宇宙指天体、时空与其中的物质，没有可以被看作蓝色的景象，描写颜色要用“天空”。"}, {"text": "他把宇宙擦得干干净净。", "explanation": "“擦”的对象是窗户、桌面等具体物体，宇宙是天体与时空的总称，不能被擦。"}, {"text": "我们村子很小，宇宙只有三十户人家。", "explanation": "这里应该用〈村子〉。宇宙指天体、时空和其中一切物质的总称，不能用来指只有三十户人家的小地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f3c368d-00d4-4a6c-a492-be7f979f4ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11917, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "科学家猜测，除了我们这个宇宙，可能还有另一颗宇宙。", "corrected_sentence": "科学家猜测，除了我们这个宇宙，可能还有另一个宇宙。", "error_description": "“宇宙”的量词应用“个”。“颗”用于星星、行星等天体，“另一颗宇宙”误用了量词，应为“另一个宇宙”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f3c368d-00d4-4a6c-a492-be7f979f4ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11917, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们不知道宇宙的有多大。", "corrected_sentence": "我们不知道宇宙有多大。", "error_description": "“宇宙”后多加了“的”，“有多大”是谓语，应为“宇宙有多大”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f3c368d-00d4-4a6c-a492-be7f979f4ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
