INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11918, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指空间或范围能装下或包含某物，也可以比喻接受意见或不同观点。", "primary_collocate": null, "pronunciation": "róng nà", "ipa": "ɻʊŋ˧˥ na˥˩", "syllable_count": 2, "sentences": [{"text": "这些由代码编织的宇宙，既容纳着零和博弈的激烈竞争，也孕育着超越物理边界、文化隔阂的深度协作。", "target_word": "容纳", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个体育馆可以容纳五万名观众。", "target_word": "容纳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教室太小，容纳不下五十个学生。", "target_word": "容纳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家餐厅能同时容纳两百人吃饭。", "target_word": "容纳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大海容纳了无数条河流的水。", "target_word": "容纳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个好领导要能容纳不同的意见。", "target_word": "容纳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个书架已经满了，容纳不了新书。", "target_word": "容纳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的心胸很宽，能容纳别人的批评。", "target_word": "容纳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆车最多容纳七个人。", "target_word": "容纳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "城市太拥挤，容纳不了更多的人。", "target_word": "容纳", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "容纳了", "label": "体标"}, {"form": "容纳着", "label": "体标"}, {"form": "容纳过", "label": "体标"}, {"form": "容纳不下", "label": "复合"}], "register": "中性", "sense_fingerprint": "容纳|空间或范围能装下某物，也指接受不同意见", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2591be7d-c461-4a95-9b42-c5a8240a6d00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11918, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "收藏", "is_correct": false, "explanation": "语义：“收藏”指把物品保存起来，不能用来说收藏竞争。"}, {"text": "容纳", "is_correct": true, "explanation": "容纳指空间或范围能包含某物，此处说宇宙包含竞争，符合句意。"}, {"text": "朗读", "is_correct": false, "explanation": "搭配：“朗读”的对象是文字，不能用来说“竞争”。"}, {"text": "抛弃", "is_correct": false, "explanation": "语义：“抛弃”表示丢弃，与后文“孕育”的语义相反，句意不通。"}], "explanations": {"收藏": "语义：“收藏”指把物品保存起来，不能用来说收藏竞争。", "容纳": "容纳指空间或范围能包含某物，此处说宇宙包含竞争，符合句意。", "朗读": "搭配：“朗读”的对象是文字，不能用来说“竞争”。", "抛弃": "语义：“抛弃”表示丢弃，与后文“孕育”的语义相反，句意不通。"}, "sentence_index": 0, "correct_answer": "容纳"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天都容纳书。", "explanation": "这里应该用〈看〉。容纳指空间能装下或包含某物，阅读书籍要用“看”，不能说“容纳书”。"}, {"text": "我把书容纳在桌子上。", "explanation": "这里应该用〈放〉。容纳表示能装下，把东西放置在某处要用“放”。"}, {"text": "我把桌子容纳到了客厅。", "explanation": "这里应该用〈搬〉。容纳不表示移动，把家具搬到另一处要用“搬”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f3c368d-00d4-4a6c-a492-be7f979f4ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11918, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "阅读", "is_correct": false, "explanation": "语义：书架已满与“阅读”无关，“阅读不了新书”的原因不是空间。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”的对象是损坏的物品，不能与“新书”搭配。"}, {"text": "容纳", "is_correct": true, "explanation": "容纳指空间能装下某物，书架已满，所以“容纳不了新书”，符合句意。"}, {"text": "朗读", "is_correct": false, "explanation": "语义：朗读是出声念书，与书架空间已满的原因毫无关系。"}], "explanations": {"阅读": "语义：书架已满与“阅读”无关，“阅读不了新书”的原因不是空间。", "修理": "搭配：“修理”的对象是损坏的物品，不能与“新书”搭配。", "容纳": "容纳指空间能装下某物，书架已满，所以“容纳不了新书”，符合句意。", "朗读": "语义：朗读是出声念书，与书架空间已满的原因毫无关系。"}, "sentence_index": 6, "correct_answer": "容纳"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他已经容纳了这个任务。", "explanation": "这里应该用〈完成〉。容纳指能装下或包含，做完任务要用“完成”。"}, {"text": "妈妈正在容纳厨房。", "explanation": "这里应该用〈收拾〉。容纳指空间能装下某物，整理厨房要用“收拾”。"}, {"text": "我每天早上都容纳新衣服。", "explanation": "这里应该用〈穿〉。容纳表示能装下，穿衣服要用“穿”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f3c368d-00d4-4a6c-a492-be7f979f4ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11918, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个停车场可以容纳得三百辆车。", "corrected_sentence": "这个停车场可以容纳三百辆车。", "error_description": "错误：“容纳得三百辆车”，正确：“容纳三百辆车”。“得”是补语标记，不能插在动词“容纳”和宾语之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f3c368d-00d4-4a6c-a492-be7f979f4ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11918, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个图书馆曾经容纳了过上千名读者。", "corrected_sentence": "这个图书馆曾经容纳过上千名读者。", "error_description": "“过”已表示曾有的经历，“容纳”后不能再加“了”，应为“曾经容纳过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f3c368d-00d4-4a6c-a492-be7f979f4ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11920, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "温和", "is_correct": true, "explanation": "正确。“温和”指不猛烈、不强硬，与“激烈”构成反义。"}, {"text": "漂亮", "is_correct": false, "explanation": "无关：“漂亮”形容外表好看，与“激烈”没有反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "无关：“明亮”形容光线或颜色，与“激烈”没有反义关系。"}, {"text": "干净", "is_correct": false, "explanation": "无关：“干净”形容洁净，与“激烈”没有反义关系。"}], "correct_answer": "温和", "explanations": {"温和": "正确。“温和”指不猛烈、不强硬，与“激烈”构成反义。", "漂亮": "无关：“漂亮”形容外表好看，与“激烈”没有反义关系。", "明亮": "无关：“明亮”形容光线或颜色，与“激烈”没有反义关系。", "干净": "无关：“干净”形容洁净，与“激烈”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f3c368d-00d4-4a6c-a492-be7f979f4ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11920, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "平和", "is_correct": true, "explanation": "正确。“平和”指平静、温和，与争论、竞争的激烈相对。"}, {"text": "宽阔", "is_correct": false, "explanation": "无关：“宽阔”形容面积或空间大，与“激烈”没有反义关系。"}, {"text": "悠久", "is_correct": false, "explanation": "无关：“悠久”形容时间长，与“激烈”没有反义关系。"}, {"text": "聪明", "is_correct": false, "explanation": "无关：“聪明”形容智力水平，与“激烈”没有反义关系。"}], "correct_answer": "平和", "explanations": {"平和": "正确。“平和”指平静、温和，与争论、竞争的激烈相对。", "宽阔": "无关：“宽阔”形容面积或空间大，与“激烈”没有反义关系。", "悠久": "无关：“悠久”形容时间长，与“激烈”没有反义关系。", "聪明": "无关：“聪明”形容智力水平，与“激烈”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f3c368d-00d4-4a6c-a492-be7f979f4ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11920, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容动作、争论、比赛等非常强烈、不温和。", "primary_collocate": null, "pronunciation": "jī liè", "ipa": "tɕi˥ liɛ˥˩", "syllable_count": 2, "sentences": [{"text": "这些由代码编织的宇宙，既容纳着零和博弈的激烈竞争，也孕育着超越物理边界、文化隔阂的深度协作。", "target_word": "激烈", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "昨天的篮球比赛非常激烈。", "target_word": "激烈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个人为这件事进行了激烈的争论。", "target_word": "激烈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市场上的竞争越来越激烈。", "target_word": "激烈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在会上展开了激烈的讨论。", "target_word": "激烈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场足球赛打得很激烈，大家都很紧张。", "target_word": "激烈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛进行得十分激烈，没有人愿意认输。", "target_word": "激烈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不喜欢激烈的运动，只想慢慢散步。", "target_word": "激烈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个队在决赛中打得难分难解，场面激烈。", "target_word": "激烈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们为价格吵得很激烈，最后谁也没让步。", "target_word": "激烈", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "激烈地", "label": "状语形式"}, {"form": "激烈的", "label": "定语形式"}], "register": "中性", "sense_fingerprint": "激烈：形容竞争、争论、比赛等强烈而不温和", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2591be7d-c461-4a95-9b42-c5a8240a6d00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11920, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "激烈", "is_correct": true, "explanation": "正确。激烈形容竞争、争论、比赛等非常强烈、不温和。"}, {"text": "机械", "is_correct": false, "explanation": "xiè（第四声）与 liè（第四声）声母不同，意思是机器、器械。"}, {"text": "激励", "is_correct": false, "explanation": "lì 与 liè 韵母不同（少一个 e），意思是鼓舞、鼓励。"}, {"text": "基业", "is_correct": false, "explanation": "yè 与 liè 声母不同，意思是事业的基础。"}, {"text": "积液", "is_correct": false, "explanation": "yè 与 liè 声母不同，意思是体内积存的液体。"}], "explanations": {"激烈": "正确。激烈形容竞争、争论、比赛等非常强烈、不温和。", "机械": "xiè（第四声）与 liè（第四声）声母不同，意思是机器、器械。", "激励": "lì 与 liè 韵母不同（少一个 e），意思是鼓舞、鼓励。", "基业": "yè 与 liè 声母不同，意思是事业的基础。", "积液": "yè 与 liè 声母不同，意思是体内积存的液体。"}, "sentence_index": null, "correct_answer": "激烈"}, "level_3": {"options": [{"text": "激烈", "is_correct": true, "explanation": "正确。“激烈”修饰竞争，与“零和博弈”的对抗相符。"}, {"text": "温和", "is_correct": false, "explanation": "语义：零和博弈是你死我活的对抗，“温和”与之矛盾。"}, {"text": "平淡", "is_correct": false, "explanation": "语义：“平淡”说竞争没有波澜，与“零和博弈”的对抗不符。"}, {"text": "悠闲", "is_correct": false, "explanation": "搭配：“悠闲”形容人的状态，一般不用来修饰“竞争”。"}], "explanations": {"激烈": "正确。“激烈”修饰竞争，与“零和博弈”的对抗相符。", "温和": "语义：零和博弈是你死我活的对抗，“温和”与之矛盾。", "平淡": "语义：“平淡”说竞争没有波澜，与“零和博弈”的对抗不符。", "悠闲": "搭配：“悠闲”形容人的状态，一般不用来修饰“竞争”。"}, "sentence_index": 0, "correct_answer": "激烈"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的肚子激烈地疼了好几个小时。", "explanation": "这里应该用〈剧烈〉。激烈多用于竞争、争论、比赛等，身体疼痛要用剧烈。"}, {"text": "他对这个问题有激烈的兴趣。", "explanation": "这里应该用〈强烈〉。激烈多指竞争、争论等紧张的局面，表示兴趣、感情要用强烈。"}, {"text": "大家激烈地欢迎新来的老师。", "explanation": "这里应该用〈热烈〉。欢迎的热情要用热烈，激烈不用于表示欢迎。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f3c368d-00d4-4a6c-a492-be7f979f4ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11920, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "激烈", "is_correct": true, "explanation": "正确。“激烈”描述比赛的紧张程度，与“没有人愿意认输”相符。"}, {"text": "平静", "is_correct": false, "explanation": "语义：“平静”与“没有人愿意认输”的紧张气氛相反。"}, {"text": "轻松", "is_correct": false, "explanation": "语义：“轻松”说比赛不紧张，与“没有人愿意认输”矛盾。"}, {"text": "散漫", "is_correct": false, "explanation": "语义：“散漫”指松懈、不集中，与“没有人愿意认输”的紧张气氛矛盾。"}], "explanations": {"激烈": "正确。“激烈”描述比赛的紧张程度，与“没有人愿意认输”相符。", "平静": "语义：“平静”与“没有人愿意认输”的紧张气氛相反。", "轻松": "语义：“轻松”说比赛不紧张，与“没有人愿意认输”矛盾。", "散漫": "语义：“散漫”指松懈、不集中，与“没有人愿意认输”的紧张气氛矛盾。"}, "sentence_index": 6, "correct_answer": "激烈"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个苹果很激烈，酸得我眼睛都闭上了。", "explanation": "这里应该用〈酸〉。激烈形容动作、争论、比赛等强烈、不温和，形容水果味道要用“酸”。"}, {"text": "厨房里飘着激烈的香味。", "explanation": "这里应该用〈浓烈〉。激烈形容动作、争论、比赛等强烈、不温和，香气浓重要用浓烈。"}, {"text": "听到这个好消息，全家人都非常激烈。", "explanation": "这里应该用〈激动〉。激烈形容动作、争论、比赛等强烈、不温和，人的情绪激动要用激动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f3c368d-00d4-4a6c-a492-be7f979f4ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11920, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两家公司的价格竞争非常激烈地。", "corrected_sentence": "两家公司的价格竞争非常激烈。", "error_description": "错误：句末“非常激烈地”多了“地”，应为“非常激烈”。“激烈”在此作谓语；“地”用于状语，须修饰其后的动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f3c368d-00d4-4a6c-a492-be7f979f4ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11920, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "比赛的最后阶段比激烈，观众一直在喊。", "corrected_sentence": "比赛的最后阶段比较激烈，观众一直在喊。", "error_description": "错误：“比”后须有比较对象，“比激烈”不完整；表示程度时应说“比较激烈”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f3c368d-00d4-4a6c-a492-be7f979f4ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
