INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11921, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指怀胎生育，也比喻在原有事物中酝酿、发展出新的东西。", "primary_collocate": null, "pronunciation": "yùn yù", "ipa": "yn˥˩ y˥˩", "syllable_count": 2, "sentences": [{"text": "这些由代码编织的宇宙，既容纳着零和博弈的激烈竞争，也孕育着超越物理边界、文化隔阂的深度协作。", "target_word": "孕育", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "母亲正在孕育一个新的生命。", "target_word": "孕育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片土地孕育了灿烂的文化。", "target_word": "孕育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "黄河孕育了中华文明。", "target_word": "孕育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天的寒冷里孕育着春天的希望。", "target_word": "孕育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市孕育出许多有名的作家。", "target_word": "孕育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她孕育孩子的时候，每天都很小心。", "target_word": "孕育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "失败中往往孕育着成功。", "target_word": "孕育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大海孕育着无数的生命。", "target_word": "孕育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次讨论孕育了一个新的想法。", "target_word": "孕育", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "孕育着", "label": "进行体"}, {"form": "孕育了", "label": "完成体"}, {"form": "孕育出", "label": "趋向补语形式"}], "register": "书面", "sense_fingerprint": "孕育：怀胎生育；比喻在原有事物中酝酿出新事物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2591be7d-c461-4a95-9b42-c5a8240a6d00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11921, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "孕育", "is_correct": true, "explanation": "正确。“孕育”表示在原有事物中酝酿出新的东西，与“深度协作”的产生相符。"}, {"text": "摧毁", "is_correct": false, "explanation": "语义：“摧毁”与“深度协作”的产生相反，与“也”并列时语义矛盾。"}, {"text": "熄灭", "is_correct": false, "explanation": "搭配：“熄灭”的对象多是火、灯，不能说“熄灭协作”，也与“孕育”的产生义不符。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃”表示不再坚持，与“深度协作”的建立不符。"}], "explanations": {"孕育": "正确。“孕育”表示在原有事物中酝酿出新的东西，与“深度协作”的产生相符。", "摧毁": "语义：“摧毁”与“深度协作”的产生相反，与“也”并列时语义矛盾。", "熄灭": "搭配：“熄灭”的对象多是火、灯，不能说“熄灭协作”，也与“孕育”的产生义不符。", "放弃": "语义：“放弃”表示不再坚持，与“深度协作”的建立不符。"}, "sentence_index": 0, "correct_answer": "孕育"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈孕育了一碗热腾腾的面条。", "explanation": "这里应该用〈煮〉。孕育指怀胎或酝酿、发展出新的东西，煮面条要用煮。"}, {"text": "工厂孕育了大量汽车。", "explanation": "这里应该用〈生产〉。孕育表示酝酿、成形的过程，工厂制造汽车要用生产。"}, {"text": "他孕育了一把椅子。", "explanation": "这里应该用〈做〉。孕育表示酝酿、发展出新的东西，制作有形的器具要用“做”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f3c368d-00d4-4a6c-a492-be7f979f4ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11921, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "孕育", "is_correct": true, "explanation": "正确。“孕育孩子”指怀胎，与“小心”的语境相符。"}, {"text": "丢弃", "is_correct": false, "explanation": "语义：“丢弃”与“每天都很小心”的照顾语境矛盾。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”用于场所或物品，不用来搭配“孩子”。"}, {"text": "遗忘", "is_correct": false, "explanation": "语义：“遗忘”与“每天都很小心”的照顾语境矛盾。"}], "explanations": {"孕育": "正确。“孕育孩子”指怀胎，与“小心”的语境相符。", "丢弃": "语义：“丢弃”与“每天都很小心”的照顾语境矛盾。", "打扫": "搭配：“打扫”用于场所或物品，不用来搭配“孩子”。", "遗忘": "语义：“遗忘”与“每天都很小心”的照顾语境矛盾。"}, "sentence_index": 6, "correct_answer": "孕育"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "施工队孕育了一座小桥。", "explanation": "这里应该用〈建造〉。孕育指怀胎或酝酿、发展出新的东西，建造桥梁要用建造。"}, {"text": "工人孕育了一台机器。", "explanation": "这里应该用〈制造〉。孕育不用于具体机器的制造，制造机器要用制造。"}, {"text": "修理工孕育了一台旧收音机。", "explanation": "这里应该用〈修理〉。孕育指怀胎或酝酿、发展出新的东西，修理旧物是对已有东西的维修，要用修理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f3c368d-00d4-4a6c-a492-be7f979f4ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11921, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个小镇孕育着了一代优秀的画家。", "corrected_sentence": "这个小镇孕育了一代优秀的画家。", "error_description": "错误：“孕育着了”，正确：“孕育了”。“着”和“了”都是动态助词，不能同时用在同一个动词后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f3c368d-00d4-4a6c-a492-be7f979f4ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11921, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位母亲孕育得一个健康的男孩。", "corrected_sentence": "这位母亲孕育了一个健康的男孩。", "error_description": "错误：“孕育得”，正确：“孕育了”。“得”是补语的标记，“孕育”后面没有补语，表示完成要用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f3c368d-00d4-4a6c-a492-be7f979f4ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
