INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11922, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "彼此思想、感情或意见上的距离或障碍。", "primary_collocate": null, "pronunciation": "gé hé", "ipa": "kɤ˧˥ xɤ˧˥", "syllable_count": 2, "sentences": [{"text": "这些由代码编织的宇宙，既容纳着零和博弈的激烈竞争，也孕育着超越物理边界、文化隔阂的深度协作。", "target_word": "隔阂", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "两家人之间有一层隔阂。", "target_word": "隔阂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多聊聊天，可以消除彼此的隔阂。", "target_word": "隔阂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "语言不同常常造成隔阂。", "target_word": "隔阂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父母和孩子之间不应该有隔阂。", "target_word": "隔阂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一次真诚的谈话让他们心里的隔阂少了很多。", "target_word": "隔阂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年龄的差别让他们产生了隔阂。", "target_word": "隔阂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们之间的隔阂越来越深。", "target_word": "隔阂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想办法打破同事之间的隔阂。", "target_word": "隔阂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们因为误会产生了隔阂，很久不说话。", "target_word": "隔阂", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一层隔阂", "label": "量词：层"}, {"form": "一道隔阂", "label": "量词：道"}], "register": "中性", "sense_fingerprint": "隔阂：人与人之间思想、感情上的距离或障碍", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2591be7d-c461-4a95-9b42-c5a8240a6d00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11922, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "隔阂", "is_correct": true, "explanation": "「隔阂」指人与人之间思想、感情上的距离，与「文化」搭配，表示文化差异造成的心理障碍，正好是「超越」的对象。"}, {"text": "友谊", "is_correct": false, "explanation": "语义：「友谊」是亲近的关系，不是需要超越的障碍，「超越文化友谊」说不通。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：「超越」后接界限或障碍，不接「温度」，「超越文化温度」不成话。"}, {"text": "天气", "is_correct": false, "explanation": "语义：「天气」与「文化」无法构成可以超越的对象，整句意思不通。"}], "explanations": {"隔阂": "「隔阂」指人与人之间思想、感情上的距离，与「文化」搭配，表示文化差异造成的心理障碍，正好是「超越」的对象。", "友谊": "语义：「友谊」是亲近的关系，不是需要超越的障碍，「超越文化友谊」说不通。", "温度": "搭配：「超越」后接界限或障碍，不接「温度」，「超越文化温度」不成话。", "天气": "语义：「天气」与「文化」无法构成可以超越的对象，整句意思不通。"}, "sentence_index": 0, "correct_answer": "隔阂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这两份报告的数字之间有隔阂。", "explanation": "这里应该用〈矛盾〉。隔阂只指人与人之间思想、感情上的距离，不能用来说数字或资料之间的不一致。"}, {"text": "前面那片山成了我们回家路上的隔阂。", "explanation": "这里应该用〈障碍〉。隔阂指人心里的距离，不指路上实际挡住行人的东西。"}, {"text": "他们在会议上爆发了隔阂，争了一个下午。", "explanation": "这里应该用〈冲突〉。隔阂是一种状态，不能「爆发」；发生的对立事件要用〈冲突〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f3c368d-00d4-4a6c-a492-be7f979f4ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11922, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "隔阂", "is_correct": true, "explanation": "「隔阂」指因年龄差别而在思想、感情上产生的距离，与「产生了」搭配自然，是正确的填入。"}, {"text": "方向", "is_correct": false, "explanation": "语义：年龄的差别不会产生「方向」，前后因果不通，句子不成立。"}, {"text": "脚步", "is_correct": false, "explanation": "语义：「脚步」是走路时的动作，不是年龄差别带来的结果，「产生了脚步」说不通。"}, {"text": "体力", "is_correct": false, "explanation": "搭配：「产生」后不接「体力」，体力是人具有或消耗的，不能说「产生体力」。"}], "explanations": {"隔阂": "「隔阂」指因年龄差别而在思想、感情上产生的距离，与「产生了」搭配自然，是正确的填入。", "方向": "语义：年龄的差别不会产生「方向」，前后因果不通，句子不成立。", "脚步": "语义：「脚步」是走路时的动作，不是年龄差别带来的结果，「产生了脚步」说不通。", "体力": "搭配：「产生」后不接「体力」，体力是人具有或消耗的，不能说「产生体力」。"}, "sentence_index": 6, "correct_answer": "隔阂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "客厅和厨房之间砌了一道隔阂，挡住了光线。", "explanation": "隔阂指人与人之间思想、感情上的距离，不指墙壁之类的实物。这里说的是墙，不是隔阂的意思。"}, {"text": "他们俩之间有一张隔阂，谁也不愿靠近。", "explanation": "这里量词用错。〈张〉用于桌子、纸张等平面的东西，隔阂应该用〈层〉或〈道〉。"}, {"text": "他们之间有一把隔阂，很久不说话。", "explanation": "这里量词用错。〈把〉用于有柄的器具，隔阂应该用〈层〉或〈道〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f3c368d-00d4-4a6c-a492-be7f979f4ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11922, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们之间有一颗隔阂。", "corrected_sentence": "我们之间有一层隔阂。", "error_description": "量词错误：「颗」用于小而圆的东西，不能修饰「隔阂」。应改为「层」（或「道」），表示一层或一道心理上的距离。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f3c368d-00d4-4a6c-a492-be7f979f4ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11922, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "父亲和儿子之间吃了隔阂，平时很少聊天。", "corrected_sentence": "父亲和儿子之间有隔阂，平时很少聊天。", "error_description": "动词搭配错误：「吃」不能与「隔阂」搭配；应改为「有」，表示「之间存在」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f3c368d-00d4-4a6c-a492-be7f979f4ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11924, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07ddb37a-1479-43aa-b31d-1a56168df47a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11924, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07ddb37a-1479-43aa-b31d-1a56168df47a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11924, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "像素是构成数字图像的最小基本单元，每个像素对应一个颜色值，多个像素排列形成完整的图像。", "primary_collocate": null, "pronunciation": "xiàng sù", "ipa": "ɕjɑŋ˥˩ su˥˩", "syllable_count": 2, "sentences": [{"text": "表面上，个体在像素构建的战场或奇幻大陆中追逐虚拟成就；实质上，他们正参与一场关于信任、角色分配与集体智慧的社会实验。", "target_word": "像素", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这张照片的像素太低，放大以后很模糊。", "target_word": "像素", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手机的像素越高，拍出来的照片越清楚。", "target_word": "像素", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "屏幕上的每个像素都能发出不同的颜色。", "target_word": "像素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏的画面是用很大的像素画成的。", "target_word": "像素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想把这张图的像素改成一千万。", "target_word": "像素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，一张图由很多像素组成。", "target_word": "像素", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "放大图片以后，你能看见一个一个的像素。", "target_word": "像素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台相机有两千万像素，拍夜景也很清楚。", "target_word": "像素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把图片的像素降低了，文件就变小了。", "target_word": "像素", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "像素点", "label": "复合"}, {"form": "像素值", "label": "复合"}], "register": "中性", "sense_fingerprint": "数字图像的最小单元，每个像素对应一个颜色值", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2f2f380-84e6-4cc1-b3ea-516ce01c2dc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11924, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "像素", "is_correct": true, "explanation": "正确。像素是构成数字图像的最小单位，每个像素对应一个颜色值。"}, {"text": "项目", "is_correct": false, "explanation": "声母不同：项目（xiàng mù）与像素只有第二音节声母不同（m 与 s），意思是工作或活动的事项。"}, {"text": "橡树", "is_correct": false, "explanation": "声母不同：橡树（xiàng shù）与像素只有第二音节声母不同（sh 与 s），意思是一种树木。"}, {"text": "限速", "is_correct": false, "explanation": "韵尾不同：限速（xiàn sù）与像素只有第一音节韵尾不同（-n 与 -ng），意思是限制车速。"}], "explanations": {"像素": "正确。像素是构成数字图像的最小单位，每个像素对应一个颜色值。", "项目": "声母不同：项目（xiàng mù）与像素只有第二音节声母不同（m 与 s），意思是工作或活动的事项。", "橡树": "声母不同：橡树（xiàng shù）与像素只有第二音节声母不同（sh 与 s），意思是一种树木。", "限速": "韵尾不同：限速（xiàn sù）与像素只有第一音节韵尾不同（-n 与 -ng），意思是限制车速。"}, "sentence_index": null, "correct_answer": "像素"}, "level_3": {"options": [{"text": "像素", "is_correct": true, "explanation": "正确。“在像素构建的战场”指由像素组成的虚拟战场，与“虚拟成就”相符。"}, {"text": "泥土", "is_correct": false, "explanation": "语义：“泥土”是实体材料，与“虚拟成就”和“奇幻大陆”冲突，不能作为虚拟战场的构成单位。"}, {"text": "微笑", "is_correct": false, "explanation": "搭配：“构建”要求可搭建的材料或结构，“微笑”不能用来构建战场。"}, {"text": "数学", "is_correct": false, "explanation": "搭配：“构建”的对象应是具体的材料或单位，“数学”是学科，不能被构建成战场。"}], "explanations": {"像素": "正确。“在像素构建的战场”指由像素组成的虚拟战场，与“虚拟成就”相符。", "泥土": "语义：“泥土”是实体材料，与“虚拟成就”和“奇幻大陆”冲突，不能作为虚拟战场的构成单位。", "微笑": "搭配：“构建”要求可搭建的材料或结构，“微笑”不能用来构建战场。", "数学": "搭配：“构建”的对象应是具体的材料或单位，“数学”是学科，不能被构建成战场。"}, "sentence_index": 0, "correct_answer": "像素"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种花的花瓣里含有很多像素。", "explanation": "这里应该用〈色素〉。像素是数字图像的最小单位，花瓣里的颜色物质要说色素。"}, {"text": "这幅画的像素很鲜艳。", "explanation": "这里应该用〈色彩〉。像素是图像的构成单位，不能用来形容画面鲜艳。"}, {"text": "纸上落了几个像素。", "explanation": "这里应该用〈墨点〉。像素只指数字图像中的最小单位，不指纸上的墨迹。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07ddb37a-1479-43aa-b31d-1a56168df47a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11924, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "像素", "is_correct": true, "explanation": "正确。“一张图由很多像素组成”符合数字图像的构成方式。"}, {"text": "音符", "is_correct": false, "explanation": "语义：音符属于乐谱，不能组成一张图。"}, {"text": "句子", "is_correct": false, "explanation": "搭配：“组成”一张图的应是像素这类构成单位，“句子”不能组成图像。"}, {"text": "琴弦", "is_correct": false, "explanation": "语义：琴弦是乐器部件，不能组成一张图。"}], "explanations": {"像素": "正确。“一张图由很多像素组成”符合数字图像的构成方式。", "音符": "语义：音符属于乐谱，不能组成一张图。", "句子": "搭配：“组成”一张图的应是像素这类构成单位，“句子”不能组成图像。", "琴弦": "语义：琴弦是乐器部件，不能组成一张图。"}, "sentence_index": 6, "correct_answer": "像素"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这幅画的像素很暖和。", "explanation": "这里应该用〈色调〉。色调指画面的冷暖和色彩倾向，像素是图像的最小单位，不能用“暖和”来形容。"}, {"text": "这些像素很细，倒进水里很快就化开了。", "explanation": "这里应该用〈粉末〉。粉末可以细到倒进水里化开，像素是图像的最小单位，不能用来形容粉末。"}, {"text": "这首歌太吵了，我把像素降低了，耳朵就舒服了。", "explanation": "这里应该用〈音量〉。降低音量能让声音变小，像素是图像单位，不能用来调节声音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07ddb37a-1479-43aa-b31d-1a56168df47a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11924, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "屏幕上有一百万只像素。", "corrected_sentence": "屏幕上有一百万个像素。", "error_description": "量词错误：像素应用量词“个”，“只”多用于动物。错误形式“一百万只像素”，正确形式“一百万个像素”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07ddb37a-1479-43aa-b31d-1a56168df47a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11924, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台手机有一千二百万条像素。", "corrected_sentence": "这台手机有一千二百万个像素。", "error_description": "量词错误：像素应用量词“个”，“条”多用于细长的东西，不能用于像素。错误形式“一千二百万条像素”，正确形式“一千二百万个像素”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07ddb37a-1479-43aa-b31d-1a56168df47a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11925, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07ddb37a-1479-43aa-b31d-1a56168df47a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11925, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07ddb37a-1479-43aa-b31d-1a56168df47a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11925, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "两军交战的区域。", "primary_collocate": null, "pronunciation": "zhàn chǎng", "ipa": "ʈ͡ʂan˥˩ ʈ͡ʂʰɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "表面上，个体在像素构建的战场或奇幻大陆中追逐虚拟成就；实质上，他们正参与一场关于信任、角色分配与集体智慧的社会实验。", "target_word": "战场", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "士兵们在战场上勇敢地战斗。", "target_word": "战场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里曾经是一个很大的战场。", "target_word": "战场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "战场上到处都是烟和火。", "target_word": "战场", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "医生跑到战场上去救受伤的士兵。", "target_word": "战场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "战争结束后，战场慢慢变成了公园。", "target_word": "战场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在战场上失去了一条腿。", "target_word": "战场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位将军一生都在战场上度过。", "target_word": "战场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在博物馆里看到了古代战场的地图。", "target_word": "战场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两支军队在河边的战场上相遇了。", "target_word": "战场", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "戰場", "label": "繁体"}, {"form": "主战场", "label": "复合"}], "register": "中性", "sense_fingerprint": "两军交战的区域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2f2f380-84e6-4cc1-b3ea-516ce01c2dc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11925, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "战场", "is_correct": true, "explanation": "正确。战场指两军交战的区域。"}, {"text": "展场", "is_correct": false, "explanation": "声调不同：展场（zhǎn chǎng）与战场只有第一音节声调不同（第三声与第四声），意思是展览的场地。"}, {"text": "站长", "is_correct": false, "explanation": "声母不同：站长（zhàn zhǎng）与战场只有第二音节声母不同（zh 与 ch），意思是车站的负责人。"}, {"text": "散场", "is_correct": false, "explanation": "声母不同：散场（sàn chǎng）与战场只有第一音节声母不同（s 与 zh），意思是演出或活动结束后人群离开。"}], "explanations": {"战场": "正确。战场指两军交战的区域。", "展场": "声调不同：展场（zhǎn chǎng）与战场只有第一音节声调不同（第三声与第四声），意思是展览的场地。", "站长": "声母不同：站长（zhàn zhǎng）与战场只有第二音节声母不同（zh 与 ch），意思是车站的负责人。", "散场": "声母不同：散场（sàn chǎng）与战场只有第一音节声母不同（s 与 zh），意思是演出或活动结束后人群离开。"}, "sentence_index": null, "correct_answer": "战场"}, "level_3": {"options": [{"text": "战场", "is_correct": true, "explanation": "正确。“在……构建的战场或奇幻大陆中”指虚拟的交战地点，与“虚拟成就”相符。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕是食物，不能被构建成交战或虚拟的战场。"}, {"text": "数学", "is_correct": false, "explanation": "搭配：“构建”的对象应是具体的材料或单位，“数学”是学科，不能被构建成战场。"}, {"text": "乐谱", "is_correct": false, "explanation": "语义：乐谱记录音乐，不能由像素构建成交战的场所。"}], "explanations": {"战场": "正确。“在……构建的战场或奇幻大陆中”指虚拟的交战地点，与“虚拟成就”相符。", "蛋糕": "语义：蛋糕是食物，不能被构建成交战或虚拟的战场。", "数学": "搭配：“构建”的对象应是具体的材料或单位，“数学”是学科，不能被构建成战场。", "乐谱": "语义：乐谱记录音乐，不能由像素构建成交战的场所。"}, "sentence_index": 0, "correct_answer": "战场"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那场战场结束于一九四五年。", "explanation": "这里应该用〈战争〉。战场是交战的地点，不能说它结束于某年，结束的是战争。"}, {"text": "这次战场打了三天三夜。", "explanation": "这里应该用〈战役〉。战役是一次交战的过程，可以持续多天，战场只指地点。"}, {"text": "那个战场很勇敢。", "explanation": "这里应该用〈士兵〉。战场是地点，不能用“勇敢”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07ddb37a-1479-43aa-b31d-1a56168df47a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11925, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "战场", "is_correct": true, "explanation": "正确。“他在战场上失去了一条腿”中，“在……上”表示地点，与“战场”相符。"}, {"text": "战争", "is_correct": false, "explanation": "搭配：“在……上”要求地点或平面，“战争”是事件，不能用于“在……上失去”。"}, {"text": "公式", "is_correct": false, "explanation": "语义：公式是数学表达式，不能作为失去一条腿的地点。"}, {"text": "战斗", "is_correct": false, "explanation": "搭配：“战斗”是活动，不能与“在……上”组成表示地点的短语。"}], "explanations": {"战场": "正确。“他在战场上失去了一条腿”中，“在……上”表示地点，与“战场”相符。", "战争": "搭配：“在……上”要求地点或平面，“战争”是事件，不能用于“在……上失去”。", "公式": "语义：公式是数学表达式，不能作为失去一条腿的地点。", "战斗": "搭配：“战斗”是活动，不能与“在……上”组成表示地点的短语。"}, "sentence_index": 6, "correct_answer": "战场"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个战场很大，能坐下三万人。", "explanation": "这里应该用〈体育场〉。体育场是能容纳观众的场地，战场是交战的区域，不能用来形容能坐多少人。"}, {"text": "这个战场的菜很好吃。", "explanation": "这里应该用〈饭店〉。饭店的菜才讲究好吃，战场是交战的区域，不能用来评价菜的味道。"}, {"text": "这个战场里有两千名学生在上课。", "explanation": "这里应该用〈学校〉。学校里有学生上课，战场是交战的区域，不能有学生在里面上课。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07ddb37a-1479-43aa-b31d-1a56168df47a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11925, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那片平原曾经是一只重要的战场。", "corrected_sentence": "那片平原曾经是一个重要的战场。", "error_description": "量词错误：战场应用量词“个”，“只”多用于动物。错误形式“一只重要的战场”，正确形式“一个重要的战场”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07ddb37a-1479-43aa-b31d-1a56168df47a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11925, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "很多炮弹落在了远处的战场下。", "corrected_sentence": "很多炮弹落在了远处的战场上。", "error_description": "方位词错误：表示在交战区域里，“战场”后面用“上”，说“在战场上”，不说“在战场下”。错误形式“落在了远处的战场下”，正确形式“落在了远处的战场上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07ddb37a-1479-43aa-b31d-1a56168df47a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
