INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11926, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容美妙奇异，像幻想中的景象。", "primary_collocate": null, "pronunciation": "qí huàn", "ipa": "t͡ɕʰi˧˥ xwan˥˩", "syllable_count": 2, "sentences": [{"text": "表面上，个体在像素构建的战场或奇幻大陆中追逐虚拟成就；实质上，他们正参与一场关于信任、角色分配与集体智慧的社会实验。", "target_word": "奇幻", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "夜空中的极光看起来非常奇幻。", "target_word": "奇幻", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个电影里有一个奇幻的世界。", "target_word": "奇幻", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水下的灯光让整个房间变得很奇幻。", "target_word": "奇幻", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他画了一幅色彩奇幻的画。", "target_word": "奇幻", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们在山里看到了奇幻的云海。", "target_word": "奇幻", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们喜欢这个奇幻的故事。", "target_word": "奇幻", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "灯亮起来以后，整座城市变得奇幻极了。", "target_word": "奇幻", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "森林里的萤火虫飞来飞去，样子很奇幻。", "target_word": "奇幻", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店的设计很奇幻，像进了童话世界。", "target_word": "奇幻", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "奇幻小说", "label": "复合"}, {"form": "奇幻电影", "label": "复合"}], "register": "中性", "sense_fingerprint": "美妙奇异，像幻想中的景象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2f2f380-84e6-4cc1-b3ea-516ce01c2dc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11926, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "奇幻", "is_correct": true, "explanation": "正确：“奇幻大陆”指充满幻想色彩的虚构大陆，与“像素构建的战场”“虚拟成就”的语境相合。"}, {"text": "真实", "is_correct": false, "explanation": "语义：“真实”与前文“像素构建”“虚拟成就”的虚拟语境相矛盾。"}, {"text": "现实", "is_correct": false, "explanation": "语义：“现实”指与虚拟相对的真实世界，与前文“像素构建”“虚拟”的语境相矛盾。"}, {"text": "平淡", "is_correct": false, "explanation": "搭配：“平淡”多用于生活或情节，不修饰“大陆”这类地理空间。"}], "explanations": {"奇幻": "正确：“奇幻大陆”指充满幻想色彩的虚构大陆，与“像素构建的战场”“虚拟成就”的语境相合。", "真实": "语义：“真实”与前文“像素构建”“虚拟成就”的虚拟语境相矛盾。", "现实": "语义：“现实”指与虚拟相对的真实世界，与前文“像素构建”“虚拟”的语境相矛盾。", "平淡": "搭配：“平淡”多用于生活或情节，不修饰“大陆”这类地理空间。"}, "sentence_index": 0, "correct_answer": "奇幻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他说话的样子很奇幻。", "explanation": "这里应该用〈奇怪〉。奇幻形容像幻想中的美景，形容人说话的样子古怪要用奇怪。"}, {"text": "这个案子的经过很奇幻。", "explanation": "这里应该用〈离奇〉。奇幻不用来形容真实案件的经过，案件情节稀奇古怪要用离奇。"}, {"text": "这道数学题很奇幻。", "explanation": "这里应该用〈难〉。奇幻形容像幻想中的景象，数学题难要用“难”或“复杂”，不能用奇幻。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07ddb37a-1479-43aa-b31d-1a56168df47a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11926, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "奇幻", "is_correct": true, "explanation": "正确：“奇幻的故事”指充满幻想色彩的故事，与“孩子们喜欢”相合。"}, {"text": "枯燥", "is_correct": false, "explanation": "语义：“枯燥”与“孩子们喜欢”的情感相矛盾，孩子们不会喜欢枯燥的故事。"}, {"text": "沉闷", "is_correct": false, "explanation": "语义：“沉闷”形容气氛压抑、乏味，与“孩子们喜欢”相矛盾。"}, {"text": "乏味", "is_correct": false, "explanation": "语义：乏味的故事不会受孩子们喜欢，与“喜欢”相矛盾。"}], "explanations": {"奇幻": "正确：“奇幻的故事”指充满幻想色彩的故事，与“孩子们喜欢”相合。", "枯燥": "语义：“枯燥”与“孩子们喜欢”的情感相矛盾，孩子们不会喜欢枯燥的故事。", "沉闷": "语义：“沉闷”形容气氛压抑、乏味，与“孩子们喜欢”相矛盾。", "乏味": "语义：乏味的故事不会受孩子们喜欢，与“喜欢”相矛盾。"}, "sentence_index": 6, "correct_answer": "奇幻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他对这个笑话的反应很奇幻。", "explanation": "这里应该用〈古怪〉。奇幻指像幻想中的美景，形容人的反应古怪要用古怪。"}, {"text": "这份合同写得很奇幻。", "explanation": "这里应该用〈严谨〉。奇幻形容美妙奇异的景象，合同条款周密要用严谨。"}, {"text": "他的表情很奇幻。", "explanation": "这里应该用〈怪异〉。奇幻不用来形容人的表情，表情古怪异常要用怪异。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07ddb37a-1479-43aa-b31d-1a56168df47a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11926, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "月光把湖面照很奇幻。", "corrected_sentence": "月光把湖面照得很奇幻。", "error_description": "错误：“照很奇幻”漏掉补语标记“得”。正确：“照得很奇幻”，“得”引出“很奇幻”这一结果补语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07ddb37a-1479-43aa-b31d-1a56168df47a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11926, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一个奇幻得地方。", "corrected_sentence": "这是一个奇幻的地方。", "error_description": "错误：“得”用于动词或形容词之后作补语，不能修饰名词；修饰名词应用“的”。错误形式“奇幻得地方”，正确形式“奇幻的地方”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07ddb37a-1479-43aa-b31d-1a56168df47a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
