INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11927, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指中国除台湾、香港、澳门以外的地区，即中国内地。", "primary_collocate": null, "pronunciation": "dà lù", "ipa": "ta˥˩ lu˥˩", "syllable_count": 2, "sentences": [{"text": "他来自中国大陆，住在北京。", "target_word": "大陆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想去大陆旅游，看看长城。", "target_word": "大陆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家公司在大陆和香港都有店。", "target_word": "大陆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "从香港到大陆，坐火车很方便。", "target_word": "大陆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在台湾工作，家人都住在大陆。", "target_word": "大陆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她每年春节都从香港回大陆看父母。", "target_word": "大陆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他第一次到大陆来工作，觉得很新鲜。", "target_word": "大陆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大陆北方的冬天很冷，要穿厚衣服。", "target_word": "大陆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我在大陆买了一部新手机。", "target_word": "大陆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张地图上有大陆，也有台湾。", "target_word": "大陆", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "大陸", "label": "繁体"}], "register": "中性", "sense_fingerprint": "中国内地，与台湾、香港、澳门相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2f2f380-84e6-4cc1-b3ea-516ce01c2dc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11927, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大陆", "is_correct": true, "explanation": "正确：大陆（dà lù），指中国大陆或广大的陆地。"}, {"text": "大炉", "is_correct": false, "explanation": "lú（第二声）与 lù（第四声）声调不同，大炉指大型的炉子。"}, {"text": "大怒", "is_correct": false, "explanation": "nù 与 lù 声母不同（n/l），大怒指非常生气。"}, {"text": "带路", "is_correct": false, "explanation": "dài 与 dà 韵母不同，带路指给人领路。"}], "explanations": {"大陆": "正确：大陆（dà lù），指中国大陆或广大的陆地。", "大炉": "lú（第二声）与 lù（第四声）声调不同，大炉指大型的炉子。", "大怒": "nù 与 lù 声母不同（n/l），大怒指非常生气。", "带路": "dài 与 dà 韵母不同，带路指给人领路。"}, "sentence_index": null, "correct_answer": "大陆"}, "level_3": {"options": [{"text": "大陆", "is_correct": true, "explanation": "正确：“中国大陆”指中国除台湾、香港、澳门以外的地区，与“来自”“住在北京”相合。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：海洋不是中国的地域，“中国海洋”与“来自”的地域概念相矛盾。"}, {"text": "太空", "is_correct": false, "explanation": "语义：太空不是中国的地域，“中国太空”不成立。"}, {"text": "大洲", "is_correct": false, "explanation": "搭配：“大洲”指洲际大陆，不能与“中国”组成地域说法。"}], "explanations": {"大陆": "正确：“中国大陆”指中国除台湾、香港、澳门以外的地区，与“来自”“住在北京”相合。", "海洋": "语义：海洋不是中国的地域，“中国海洋”与“来自”的地域概念相矛盾。", "太空": "语义：太空不是中国的地域，“中国太空”不成立。", "大洲": "搭配：“大洲”指洲际大陆，不能与“中国”组成地域说法。"}, "sentence_index": 0, "correct_answer": "大陆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "美国有五十个大陆。", "explanation": "这里应该用〈州〉。美国的行政区是州，大陆指大片陆地，不能用来指行政区。"}, {"text": "鸟儿把大陆叼进了窝里。", "explanation": "这里应该用〈树枝〉。大陆是大片陆地，不能叼进窝里。"}, {"text": "他的大陆很大。", "explanation": "这里应该用〈眼睛〉。大陆指很大的一块土地，不能用来形容人的眼睛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07ddb37a-1479-43aa-b31d-1a56168df47a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11927, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "大陆", "is_correct": true, "explanation": "正确：大陆（dà lù），指中国大陆或广大的陆地。"}, {"text": "道路", "is_correct": false, "explanation": "dào 与 dà 韵母不同，道路指供车马行人通行的路。"}, {"text": "大步", "is_correct": false, "explanation": "bù 与 lù 声母不同（b/l），大步指迈开的大步子。"}, {"text": "大度", "is_correct": false, "explanation": "dù 与 lù 声母不同（d/l），大度指心胸宽广、不计较。"}], "explanations": {"大陆": "正确：大陆（dà lù），指中国大陆或广大的陆地。", "道路": "dào 与 dà 韵母不同，道路指供车马行人通行的路。", "大步": "bù 与 lù 声母不同（b/l），大步指迈开的大步子。", "大度": "dù 与 lù 声母不同（d/l），大度指心胸宽广、不计较。"}, "sentence_index": null, "correct_answer": "大陆"}, "level_3": {"options": [{"text": "大陆", "is_correct": true, "explanation": "正确：“到大陆来工作”指从别处来到中国大陆工作，与“第一次”和“新鲜”相合。"}, {"text": "老家", "is_correct": false, "explanation": "语义：“老家”是本来居住的地方，与“第一次到”相矛盾。"}, {"text": "墓地", "is_correct": false, "explanation": "搭配：墓地不是工作场所，不说“到墓地来工作”。"}, {"text": "礼物", "is_correct": false, "explanation": "语义：礼物是赠送的物品，不是可以前去工作的地方。"}], "explanations": {"大陆": "正确：“到大陆来工作”指从别处来到中国大陆工作，与“第一次”和“新鲜”相合。", "老家": "语义：“老家”是本来居住的地方，与“第一次到”相矛盾。", "墓地": "搭配：墓地不是工作场所，不说“到墓地来工作”。", "礼物": "语义：礼物是赠送的物品，不是可以前去工作的地方。"}, "sentence_index": 6, "correct_answer": "大陆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "台湾是一个大陆。", "explanation": "这里应该用〈岛屿〉。台湾是岛屿，大陆指大片陆地，不能用来指一个岛。"}, {"text": "这条河的大陆很宽。", "explanation": "这里应该用〈河面〉。大陆指陆地，河的宽度要说河面。"}, {"text": "小王喝了一个大陆的牛奶。", "explanation": "这里应该用〈杯〉。大陆是大片陆地，不能用来量牛奶。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07ddb37a-1479-43aa-b31d-1a56168df47a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11927, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我哥哥明年要从大陆工作。", "corrected_sentence": "我哥哥明年要去大陆工作。", "error_description": "介词错误：表示前往中国内地工作，“大陆”前面应该用“去”，不能用“从”。错误形式“从大陆工作”，正确形式“去大陆工作”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07ddb37a-1479-43aa-b31d-1a56168df47a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11927, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她对大陆读完了大学。", "corrected_sentence": "她在大陆读完了大学。", "error_description": "介词错误：表示在中国内地这个地点，“大陆”前面应该用“在”，不能用“对”。错误形式“对大陆”，正确形式“在大陆”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07ddb37a-1479-43aa-b31d-1a56168df47a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
