INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11928, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "追赶；追求。", "primary_collocate": null, "pronunciation": "zhuī zhú", "ipa": "ʈʂuei˥ ʈʂu˧˥", "syllable_count": 2, "sentences": [{"text": "表面上，个体在像素构建的战场或奇幻大陆中追逐虚拟成就；实质上，他们正参与一场关于信任、角色分配与集体智慧的社会实验。", "target_word": "追逐", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "孩子们在公园里追逐着蝴蝶。", "target_word": "追逐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人都在追逐自己的梦想。", "target_word": "追逐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一生都在追逐名和利。", "target_word": "追逐", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小狗追逐着皮球，跑得很快。", "target_word": "追逐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从来没有追逐过名牌。", "target_word": "追逐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人为了追逐财富，离开了家乡。", "target_word": "追逐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别只追逐分数，也要多读书。", "target_word": "追逐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两只猫在院子里互相追逐。", "target_word": "追逐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把追逐成功当成人生的目标。", "target_word": "追逐", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "追逐着", "label": "体标"}, {"form": "追逐过", "label": "体标"}, {"form": "追逐了", "label": "体标"}], "register": "中性", "sense_fingerprint": "动词：追赶某物，或追求梦想、名利等目标", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2f2f380-84e6-4cc1-b3ea-516ce01c2dc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11928, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "追逐", "is_correct": true, "explanation": "正确：「追逐虚拟成就」指在游戏中追求成就，与句意相符。"}, {"text": "建造", "is_correct": false, "explanation": "搭配：「建造」的对象是建筑、房屋，不能说「建造虚拟成就」。"}, {"text": "测量", "is_correct": false, "explanation": "搭配：「测量」用于长度、重量等可量化的事物，不能用于「虚拟成就」。"}, {"text": "躲避", "is_correct": false, "explanation": "语义：「躲避」与「追逐」意思相反，前一分句说个体主动去追求虚拟成就，不能是回避。"}], "explanations": {"追逐": "正确：「追逐虚拟成就」指在游戏中追求成就，与句意相符。", "建造": "搭配：「建造」的对象是建筑、房屋，不能说「建造虚拟成就」。", "测量": "搭配：「测量」用于长度、重量等可量化的事物，不能用于「虚拟成就」。", "躲避": "语义：「躲避」与「追逐」意思相反，前一分句说个体主动去追求虚拟成就，不能是回避。"}, "sentence_index": 0, "correct_answer": "追逐"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子们在公园里追逐丢失的玩具。", "explanation": "这里应该用〈寻找〉。追逐要有可以追赶的对象，丢失的玩具已不在眼前，应说寻找。"}, {"text": "妈妈每天追逐那张旧沙发。", "explanation": "这里应该用〈擦拭〉。沙发不会跑，追逐要有可以追赶的对象，应说擦拭。"}, {"text": "工人们在仓库里追逐货物。", "explanation": "这里应该用〈搬运〉。追逐要有可以追赶或追求的对象，货物只是被搬动，应说搬运。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07ddb37a-1479-43aa-b31d-1a56168df47a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11928, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "追逐", "is_correct": true, "explanation": "正确：「追逐财富」指为了得到财富而奔走，与「离开了家乡」的因果相符。"}, {"text": "拆除", "is_correct": false, "explanation": "搭配：「拆除」的对象是建筑、设施，不能用于「财富」。"}, {"text": "修复", "is_correct": false, "explanation": "搭配：「修复」用于破损的物品或关系，「财富」不能被修复。"}, {"text": "怀念", "is_correct": false, "explanation": "语义：「怀念」是对过去事物的思念，与「为了……而离开家乡」的追求逻辑不符。"}], "explanations": {"追逐": "正确：「追逐财富」指为了得到财富而奔走，与「离开了家乡」的因果相符。", "拆除": "搭配：「拆除」的对象是建筑、设施，不能用于「财富」。", "修复": "搭配：「修复」用于破损的物品或关系，「财富」不能被修复。", "怀念": "语义：「怀念」是对过去事物的思念，与「为了……而离开家乡」的追求逻辑不符。"}, "sentence_index": 6, "correct_answer": "追逐"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他终于追逐了压力。", "explanation": "这里应该用〈摆脱〉。摆脱是离开某种负担，追逐是朝目标跑去，二者方向相反。"}, {"text": "孩子们追逐了危险的河边。", "explanation": "这里应该用〈远离〉。追逐的对象是跑动中的人或物，地点不能被追逐，句意也与远离相反。"}, {"text": "他一直追逐记者的追问。", "explanation": "这里应该用〈躲避〉。追逐是主动去追，「追问」是别人提出的问题，他是在躲开它，二者方向相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07ddb37a-1479-43aa-b31d-1a56168df47a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11928, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "猫在院子里追逐了着一只蝴蝶。", "corrected_sentence": "猫在院子里追逐着一只蝴蝶。", "error_description": "错误：「追逐」后同时用了「了」和「着」，二者不能并用，「追逐了着」不成句。正确：「追逐着一只蝴蝶」，只用「着」表示正在进行的动作。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07ddb37a-1479-43aa-b31d-1a56168df47a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11928, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只狗从来没追逐过猫过。", "corrected_sentence": "这只狗从来没追逐过猫。", "error_description": "错误在于句末多出一个「过」。「追逐过」中的「过」已紧跟动词，宾语「猫」之后不能再加「过」。正确写法是「追逐过猫」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07ddb37a-1479-43aa-b31d-1a56168df47a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
