INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11929, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07ddb37a-1479-43aa-b31d-1a56168df47a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11929, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事业上的成绩。", "primary_collocate": null, "pronunciation": "chéng jiù", "ipa": "ʈʂʰɤŋ˧˥ tɕiou˥˩", "syllable_count": 2, "sentences": [{"text": "表面上，他在公司里埋头苦干多年；实质上，他最看重的是能否在事业上取得真正的成就。", "target_word": "成就", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "这种基于绩效的认可机制，与现实社会的成就导向形成镜像。", "target_word": "成就", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他在科学上取得了很大的成就。", "target_word": "成就", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的成就让全家人都很骄傲。", "target_word": "成就", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位老人一生有很多成就。", "target_word": "成就", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每一项成就都来自努力。", "target_word": "成就", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他不为自己的成就骄傲，还在继续学习。", "target_word": "成就", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在事业上，她已经有了很高的成就。", "target_word": "成就", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位医生在医学上的成就很高。", "target_word": "成就", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，努力工作才会有成就。", "target_word": "成就", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "项", "label": "量词"}, {"form": "成就感", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词：事业、学业等方面取得的成绩", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2f2f380-84e6-4cc1-b3ea-516ce01c2dc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11929, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "成就", "is_correct": true, "explanation": "正确：「取得真正的成就」指在事业上做出的成绩，与「事业上」的语境相符。"}, {"text": "石块", "is_correct": false, "explanation": "搭配：「石块」不是事业上取得的成绩，不能与「取得真正的」搭配。"}, {"text": "体重", "is_correct": false, "explanation": "语义：「体重」指身体的重量，不是事业上取得的成绩，与「取得真正的」搭配不通。"}, {"text": "账单", "is_correct": false, "explanation": "语义：「账单」是需要付的钱，不是事业上取得的成绩，与「取得真正的」搭配不通。"}], "explanations": {"成就": "正确：「取得真正的成就」指在事业上做出的成绩，与「事业上」的语境相符。", "石块": "搭配：「石块」不是事业上取得的成绩，不能与「取得真正的」搭配。", "体重": "语义：「体重」指身体的重量，不是事业上取得的成绩，与「取得真正的」搭配不通。", "账单": "语义：「账单」是需要付的钱，不是事业上取得的成绩，与「取得真正的」搭配不通。"}, "sentence_index": 0, "correct_answer": "成就"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我这次数学考试的成就提高了不少。", "explanation": "这里应该用〈成绩〉。单次考试的分数是一次测验的结果，不算取得的成就，应说成绩。"}, {"text": "这家公司今年的成就是三百万元。", "explanation": "这里应该用〈收入〉。成就指做成的事，不指金钱数额，公司赚了多少钱要用〈收入〉。"}, {"text": "这家饭店的成就是红烧鱼。", "explanation": "这里应该用〈招牌菜〉。成就指事业上取得的成绩，饭店最有名的菜要说招牌菜，不能说成就。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07ddb37a-1479-43aa-b31d-1a56168df47a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11929, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "成就", "is_correct": true, "explanation": "正确：「不为自己的成就骄傲」指不因取得的成绩而自满，与「继续学习」相符。"}, {"text": "病痛", "is_correct": false, "explanation": "语义：「病痛」是身体的痛苦，不是值得骄傲的事，与「骄傲」矛盾。"}, {"text": "体温", "is_correct": false, "explanation": "语义：「体温」是身体的温度，不是可以因之骄傲的成绩，与「不为……骄傲」搭配不通。"}, {"text": "脸色", "is_correct": false, "explanation": "搭配：「骄傲」不用来形容脸色，「脸色」也不是可以取得的成绩。"}], "explanations": {"成就": "正确：「不为自己的成就骄傲」指不因取得的成绩而自满，与「继续学习」相符。", "病痛": "语义：「病痛」是身体的痛苦，不是值得骄傲的事，与「骄傲」矛盾。", "体温": "语义：「体温」是身体的温度，不是可以因之骄傲的成绩，与「不为……骄傲」搭配不通。", "脸色": "搭配：「骄傲」不用来形容脸色，「脸色」也不是可以取得的成绩。"}, "sentence_index": 6, "correct_answer": "成就"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把椅子的成就很结实。", "explanation": "这里应该用〈做工〉。「结实」形容物品的质地，「成就」指取得的成绩，不能用来形容椅子。"}, {"text": "这条路的成就很长。", "explanation": "这里应该用〈距离〉。「长」形容距离或时间，「成就」指取得的成绩，不能说长短。"}, {"text": "这顿饭的成就很好吃。", "explanation": "这里应该用〈味道〉。「好吃」形容食物的味道，「成就」指取得的成绩，不能用来形容饭菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07ddb37a-1479-43aa-b31d-1a56168df47a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11929, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是她的一场重要成就。", "corrected_sentence": "这是她的一项重要成就。", "error_description": "量词错误：「场」用于比赛、演出等活动，「成就」应用量词「项」。错误形式「一场重要成就」，正确形式「一项重要成就」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07ddb37a-1479-43aa-b31d-1a56168df47a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11929, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她成就得到了大家的认可。", "corrected_sentence": "她的成就得到了大家的认可。", "error_description": "错误在于「她」和「成就」之间缺少定语标记「的」，应为「她的成就」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07ddb37a-1479-43aa-b31d-1a56168df47a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
