INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11933, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "根据不同人的能力或任务需要指派职责", "primary_collocate": null, "pronunciation": "fēn pèi", "ipa": "fən pʰei", "syllable_count": 2, "sentences": [{"text": "表面上，个体在像素构建的战场或奇幻大陆中追逐虚拟成就；实质上，他们正参与一场关于信任、角色分配与集体智慧的社会实验。", "target_word": "分配", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "老师给每个学生分配了不同的任务。", "target_word": "分配", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理按能力给大家分配工作。", "target_word": "分配", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次活动，谁来分配每个人的工作？", "target_word": "分配", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板把新项目分配给了小李。", "target_word": "分配", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司按每个人的特长分配职位。", "target_word": "分配", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小组长负责给组员分配任务。", "target_word": "分配", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁做什么，要先分配好再开始。", "target_word": "分配", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈给我们三个孩子分配了家务。", "target_word": "分配", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "导演怎么分配演员的角色，大家都很关心。", "target_word": "分配", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "分配了", "label": "完成体"}, {"form": "分配过", "label": "经历体"}, {"form": "重新分配", "label": "复合"}], "register": "中性", "sense_fingerprint": "按能力和需要给不同的人指派工作、任务、角色", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a504ff71-c661-4a1d-b12d-34e4e5063915') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11933, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "分贝", "is_correct": false, "explanation": "分贝（fēn bèi）与分配（fēn pèi）只有第二音节声母不同（b 与 p），意思是声音强度的单位。"}, {"text": "分配", "is_correct": true, "explanation": "分配（fēn pèi）指按能力和需要把工作指派给人，是正确答案。"}, {"text": "丰沛", "is_correct": false, "explanation": "丰沛（fēng pèi）与分配（fēn pèi）第一音节韵尾不同（ng 与 n），意思是丰富充沛。"}, {"text": "分类", "is_correct": false, "explanation": "分类（fēn lèi）与分配（fēn pèi）只有第二音节声母不同（l 与 p），意思是按类别归类。"}], "explanations": {"分贝": "分贝（fēn bèi）与分配（fēn pèi）只有第二音节声母不同（b 与 p），意思是声音强度的单位。", "分配": "分配（fēn pèi）指按能力和需要把工作指派给人，是正确答案。", "丰沛": "丰沛（fēng pèi）与分配（fēn pèi）第一音节韵尾不同（ng 与 n），意思是丰富充沛。", "分类": "分类（fēn lèi）与分配（fēn pèi）只有第二音节声母不同（l 与 p），意思是按类别归类。"}, "sentence_index": null, "correct_answer": "分配"}, "level_3": {"options": [{"text": "分配", "is_correct": true, "explanation": "分配：“角色分配”是固定的名词用法，指按需要指派角色，句中正确。"}, {"text": "计算", "is_correct": false, "explanation": "搭配：“计算”的对象是数字或数量，不说“角色计算”。"}, {"text": "点燃", "is_correct": false, "explanation": "语义：“点燃”指使物体燃烧，与“角色”无关，句意不通。"}, {"text": "拍摄", "is_correct": false, "explanation": "搭配：“拍摄”的对象是画面或影片，不说“角色拍摄”。"}], "explanations": {"分配": "分配：“角色分配”是固定的名词用法，指按需要指派角色，句中正确。", "计算": "搭配：“计算”的对象是数字或数量，不说“角色计算”。", "点燃": "语义：“点燃”指使物体燃烧，与“角色”无关，句意不通。", "拍摄": "搭配：“拍摄”的对象是画面或影片，不说“角色拍摄”。"}, "sentence_index": 0, "correct_answer": "分配"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们应该一起分配彼此的痛苦。", "explanation": "这里应该用〈分担〉。分配指按需要把工作、资源指派给人，痛苦要说分担。"}, {"text": "我把这个好消息分配给了大家。", "explanation": "这里应该用〈分享〉。分配用于可以划分的工作、资源，消息要说分享。"}, {"text": "我们一起分配成功的喜悦。", "explanation": "这里应该用〈享受〉。分配指把工作、资源派给人，喜悦是感受，要说享受。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf5d48ef-4b40-4f5e-8fb2-d5452eeb113f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11933, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "分批", "is_correct": false, "explanation": "分批（fēn pī）与分配（fēn pèi）韵母与声调都不同，意思是分成若干批次。"}, {"text": "分袂", "is_correct": false, "explanation": "分袂（fēn mèi）与分配（fēn pèi）只有第二音节声母不同（m 与 p），意思是离别、分手。"}, {"text": "分配", "is_correct": true, "explanation": "分配（fēn pèi）指按能力和需要把工作指派给人，是正确答案。"}, {"text": "丰沛", "is_correct": false, "explanation": "丰沛（fēng pèi）与分配（fēn pèi）只有第一音节韵尾不同（ng 与 n），意思是丰富充沛。"}], "explanations": {"分批": "分批（fēn pī）与分配（fēn pèi）韵母与声调都不同，意思是分成若干批次。", "分袂": "分袂（fēn mèi）与分配（fēn pèi）只有第二音节声母不同（m 与 p），意思是离别、分手。", "分配": "分配（fēn pèi）指按能力和需要把工作指派给人，是正确答案。", "丰沛": "丰沛（fēng pèi）与分配（fēn pèi）只有第一音节韵尾不同（ng 与 n），意思是丰富充沛。"}, "sentence_index": null, "correct_answer": "分配"}, "level_3": {"options": [{"text": "分配", "is_correct": true, "explanation": "分配：正确，指把任务指派给组员，与“组员”“任务”搭配。"}, {"text": "制造", "is_correct": false, "explanation": "搭配：“制造”后接麻烦、矛盾等，不说“制造任务”。"}, {"text": "发明", "is_correct": false, "explanation": "语义：“发明”指创造出新的事物或方法，任务不是被发明出来分给组员的。"}, {"text": "吞下", "is_correct": false, "explanation": "语义：“吞下”指咽进去，任务不能被吞下，句意不通。"}], "explanations": {"分配": "分配：正确，指把任务指派给组员，与“组员”“任务”搭配。", "制造": "搭配：“制造”后接麻烦、矛盾等，不说“制造任务”。", "发明": "语义：“发明”指创造出新的事物或方法，任务不是被发明出来分给组员的。", "吞下": "语义：“吞下”指咽进去，任务不能被吞下，句意不通。"}, "sentence_index": 6, "correct_answer": "分配"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天都在分配自己的心事。", "explanation": "这里应该用〈倾诉〉。分配是把工作、任务指派给人，心事要说倾诉。"}, {"text": "这块土地被分配成了三个部分。", "explanation": "这里应该用〈分割〉。分配是把东西交给人或单位，切成几部分要用分割。"}, {"text": "我们要学会分配新闻的真假。", "explanation": "这里应该用〈分辨〉。分配指把工作、资源派给人，判断真假要说分辨。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf5d48ef-4b40-4f5e-8fb2-d5452eeb113f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11933, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "经理按能力把任务分配了新员工。", "corrected_sentence": "经理按能力把任务分配给了新员工。", "error_description": "错误在于“分配”后漏了“给”。应说“分配给新员工”，表示把任务交给新员工。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf5d48ef-4b40-4f5e-8fb2-d5452eeb113f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11933, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "组长把任务分配了组员。", "corrected_sentence": "组长把任务分配给了组员。", "error_description": "错误在于“分配”后漏了“给”。应说“分配给了组员”，表示把任务交给组员。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf5d48ef-4b40-4f5e-8fb2-d5452eeb113f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
