INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11934, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一种观察人们如何合作与互动的研究活动", "primary_collocate": null, "pronunciation": "shí yàn", "ipa": "ʂɻ̩ jɛn", "syllable_count": 2, "sentences": [{"text": "表面上，个体在像素构建的战场或奇幻大陆中追逐虚拟成就；实质上，他们正参与一场关于信任、角色分配与集体智慧的社会实验。", "target_word": "实验", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个实验观察大家怎样合作。", "target_word": "实验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们做了一个关于信任的社会实验。", "target_word": "实验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们参加一个合作实验。", "target_word": "实验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项实验让十个陌生人一起完成任务。", "target_word": "实验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验结束后，大家都成了朋友。", "target_word": "实验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这个实验里，每个人都要帮助别人。", "target_word": "实验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究者用实验观察人们怎么互动。", "target_word": "实验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次实验的目的是了解人们怎样合作。", "target_word": "实验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "参加实验的学生要先分成两组。", "target_word": "实验", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个实验", "label": "量词"}, {"form": "一项实验", "label": "量词"}, {"form": "一次实验", "label": "量词"}, {"form": "實驗", "label": "繁体"}], "register": "中性", "sense_fingerprint": "观察人们合作与互动的社会研究活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a504ff71-c661-4a1d-b12d-34e4e5063915') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11934, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "食盐", "is_correct": false, "explanation": "食盐（shí yán）与实验（shí yàn）只有第二音节声调不同，意思是食用的盐。"}, {"text": "实验", "is_correct": true, "explanation": "实验（shí yàn）指研究人们如何合作互动的研究活动，是正确答案。"}, {"text": "实言", "is_correct": false, "explanation": "实言（shí yán）与实验（shí yàn）只有第二音节声调不同，意思是老实的话。"}, {"text": "失言", "is_correct": false, "explanation": "失言（shī yán）与实验（shí yàn）第一音节声调不同，第二音节声调也不同，意思是说错话。"}], "explanations": {"食盐": "食盐（shí yán）与实验（shí yàn）只有第二音节声调不同，意思是食用的盐。", "实验": "实验（shí yàn）指研究人们如何合作互动的研究活动，是正确答案。", "实言": "实言（shí yán）与实验（shí yàn）只有第二音节声调不同，意思是老实的话。", "失言": "失言（shī yán）与实验（shí yàn）第一音节声调不同，第二音节声调也不同，意思是说错话。"}, "sentence_index": null, "correct_answer": "实验"}, "level_3": {"options": [{"text": "实验", "is_correct": true, "explanation": "实验：“社会实验”指研究人们如何互动合作的研究活动，与前文的信任、集体智慧相符。"}, {"text": "菜谱", "is_correct": false, "explanation": "语义：“菜谱”指菜肴的做法，与信任、集体智慧等社会研究无关。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：“黑板”是教学用具，“社会黑板”无法指代社会研究。"}, {"text": "午餐", "is_correct": false, "explanation": "搭配：“社会”修饰的名词应表示社会活动或研究，不说“社会午餐”。"}], "explanations": {"实验": "实验：“社会实验”指研究人们如何互动合作的研究活动，与前文的信任、集体智慧相符。", "菜谱": "语义：“菜谱”指菜肴的做法，与信任、集体智慧等社会研究无关。", "黑板": "语义：“黑板”是教学用具，“社会黑板”无法指代社会研究。", "午餐": "搭配：“社会”修饰的名词应表示社会活动或研究，不说“社会午餐”。"}, "sentence_index": 0, "correct_answer": "实验"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师让我们写一个合作实验。", "explanation": "这里应该用〈报告〉。“写”搭配文字类对象，实验要说“做”或“参加”。"}, {"text": "他是一位很有名的实验。", "explanation": "这里应该用〈研究员〉。实验指研究活动，不指人，不能用“一位”来修饰。"}, {"text": "这个实验很甜，大家都爱吃。", "explanation": "这里应该用〈蛋糕〉。实验是研究活动，不能吃，也不能说很甜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf5d48ef-4b40-4f5e-8fb2-d5452eeb113f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11934, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "实验", "is_correct": true, "explanation": "实验：“这个实验”指正在进行的研究活动，与“帮助别人”的互动情境相符。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：“冰箱”是冷藏食物的电器，人们不会在冰箱里相互帮助。"}, {"text": "书架", "is_correct": false, "explanation": "语义：“书架”是放书的家具，无法容纳人们相互帮助的活动。"}, {"text": "灯泡", "is_correct": false, "explanation": "语义：灯泡是照明器具，人不会在灯泡里相互帮助。"}], "explanations": {"实验": "实验：“这个实验”指正在进行的研究活动，与“帮助别人”的互动情境相符。", "冰箱": "语义：“冰箱”是冷藏食物的电器，人们不会在冰箱里相互帮助。", "书架": "语义：“书架”是放书的家具，无法容纳人们相互帮助的活动。", "灯泡": "语义：灯泡是照明器具，人不会在灯泡里相互帮助。"}, "sentence_index": 6, "correct_answer": "实验"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天早上喝一杯实验。", "explanation": "这里应该用〈牛奶〉。实验是研究活动，不能喝。"}, {"text": "她唱了一个实验。", "explanation": "这里应该用〈歌〉。“唱”搭配歌曲，不能唱实验。"}, {"text": "他很有实验，大家都很喜欢他。", "explanation": "这里应该用〈礼貌〉。实验是研究活动，不能用来形容人的品质。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf5d48ef-4b40-4f5e-8fb2-d5452eeb113f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11934, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只社会实验的参与者来自不同的学校。", "corrected_sentence": "这项社会实验的参与者来自不同的学校。", "error_description": "错误是量词用错。“实验”应用“项”，“只”多用于动物，不能修饰“实验”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf5d48ef-4b40-4f5e-8fb2-d5452eeb113f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11934, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们上个月写了一项关于合作的实验。", "corrected_sentence": "他们上个月做了一项关于合作的实验。", "error_description": "搭配错误：“实验”应与“做”搭配，说“做实验”，不说“写实验”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf5d48ef-4b40-4f5e-8fb2-d5452eeb113f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
