INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11935, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指跟别人争抢、竞争，想要得到某个东西或赢过对方。", "primary_collocate": null, "pronunciation": "zhēng duó", "ipa": "ʈʂɤŋ˥ tuo˧˥", "syllable_count": 2, "sentences": [{"text": "它不仅是资源争夺或排名晋升的显性对抗，更深层地体现为声望资本的隐性积累。", "target_word": "争夺", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "两支球队正在争夺冠军。", "target_word": "争夺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两家公司都想争夺这个大客户。", "target_word": "争夺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛最后，两个人争夺第一名。", "target_word": "争夺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多城市都在争夺这次大会的举办权。", "target_word": "争夺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了市场份额，他们争夺得很激烈。", "target_word": "争夺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三位老师争夺着最后一个名额。", "target_word": "争夺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个奖杯，他们已经争夺过三次了。", "target_word": "争夺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司之间争夺人才，工资越来越高。", "target_word": "争夺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个国家一直在争夺这片海域的资源。", "target_word": "争夺", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "争夺了", "label": "体标"}, {"form": "争夺着", "label": "体标"}, {"form": "争夺过", "label": "体标"}, {"form": "争夺战", "label": "复合"}], "register": "中性", "sense_fingerprint": "与他人竞争以取得某物或胜过对方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a504ff71-c661-4a1d-b12d-34e4e5063915') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11935, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "争夺", "is_correct": true, "explanation": "正确：“资源争夺”指为获取资源而竞争，与“排名晋升的显性对抗”语义一致。"}, {"text": "合作", "is_correct": false, "explanation": "语义：“合作”与“对抗”意思相反，与句中的“显性对抗”矛盾。"}, {"text": "分享", "is_correct": false, "explanation": "语义：“分享”与“对抗”不协调，句中强调的是对抗关系。"}, {"text": "回避", "is_correct": false, "explanation": "搭配：“回避”的对象是问题或责任，不能直接与“资源”搭配。"}], "explanations": {"争夺": "正确：“资源争夺”指为获取资源而竞争，与“排名晋升的显性对抗”语义一致。", "合作": "语义：“合作”与“对抗”意思相反，与句中的“显性对抗”矛盾。", "分享": "语义：“分享”与“对抗”不协调，句中强调的是对抗关系。", "回避": "搭配：“回避”的对象是问题或责任，不能直接与“资源”搭配。"}, "sentence_index": 0, "correct_answer": "争夺"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们在争夺这个问题。", "explanation": "这里应该用〈争论〉。争夺指争抢实物或名额，不能用于问题。"}, {"text": "他很想争夺一个好身体。", "explanation": "这里应该用〈争取〉。争夺指抢夺已有的东西或名额，身体要靠锻炼获得，应说争取。"}, {"text": "他每天争夺英语单词。", "explanation": "这里应该用〈学习〉。争夺需要竞争对象，记单词不涉及与他人抢夺。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf5d48ef-4b40-4f5e-8fb2-d5452eeb113f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11935, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "争夺", "is_correct": true, "explanation": "正确：“三位老师争夺着最后一个名额”表示为了名额而互相竞争，与句意相符。"}, {"text": "欣赏", "is_correct": false, "explanation": "搭配：“欣赏”的对象是作品或风景，不与“名额”搭配。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”的对象是机器或物品，不与“名额”搭配。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发出歌声，无法用于“名额”。"}], "explanations": {"争夺": "正确：“三位老师争夺着最后一个名额”表示为了名额而互相竞争，与句意相符。", "欣赏": "搭配：“欣赏”的对象是作品或风景，不与“名额”搭配。", "修理": "搭配：“修理”的对象是机器或物品，不与“名额”搭配。", "唱": "语义：“唱”指发出歌声，无法用于“名额”。"}, "sentence_index": 6, "correct_answer": "争夺"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他向灾区争夺了很多衣服。", "explanation": "这里应该用〈捐赠〉。争夺是争抢，不能用于无偿送给别人。"}, {"text": "妈妈每天争夺奶奶。", "explanation": "这里应该用〈照顾〉。争夺指争抢，不能用来描述照料他人。"}, {"text": "他经常争夺邻居。", "explanation": "这里应该用〈帮助〉。争夺含有与他人抢夺之意，不能用于施以援助。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf5d48ef-4b40-4f5e-8fb2-d5452eeb113f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11935, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "三家公司在争夺了这块地。", "corrected_sentence": "三家公司在争夺这块地。", "error_description": "体标误用：“在”表示动作正在进行，不能与“了”同用，应去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf5d48ef-4b40-4f5e-8fb2-d5452eeb113f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11935, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两个人争夺了着一张门票。", "corrected_sentence": "两个人争夺着一张门票。", "error_description": "体标误用：“了”与“着”不能同时用在动词后，应去掉“了”，说“争夺着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf5d48ef-4b40-4f5e-8fb2-d5452eeb113f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
