INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11936, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "表示人或事物在某个序列或比较中所处的位置或名次。", "primary_collocate": null, "pronunciation": "pái míng", "ipa": "pʰaɪ˧˥ miŋ˧˥", "syllable_count": 2, "sentences": [{"text": "它不仅是资源争夺或排名晋升的显性对抗，更深层地体现为声望资本的隐性积累。", "target_word": "排名", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "这所大学的排名很高。", "target_word": "排名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在班里的排名是第三。", "target_word": "排名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年我们学校的排名上升了。", "target_word": "排名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的排名每年都在变化。", "target_word": "排名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他成绩不错，排名靠前。", "target_word": "排名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的排名从第十升到了第五。", "target_word": "排名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛，他的排名是第一。", "target_word": "排名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不太关心排名，只想学好。", "target_word": "排名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试以后，老师公布了大家的排名。", "target_word": "排名", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "排名表", "label": "复合"}, {"form": "总排名", "label": "复合"}], "register": "中性", "sense_fingerprint": "人或事物在比较中所处的名次", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a504ff71-c661-4a1d-b12d-34e4e5063915') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11936, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：天气没有名次，不能与“晋升”搭配，句意不通。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子不是可以排出先后次序的事物，与句中的“对抗”语境不符。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：体重没有名次，不能与“晋升”搭配。"}, {"text": "排名", "is_correct": true, "explanation": "排名指名次，“排名晋升”表示名次上升，符合句意。"}], "explanations": {"天气": "语义：天气没有名次，不能与“晋升”搭配，句意不通。", "房子": "语义：房子不是可以排出先后次序的事物，与句中的“对抗”语境不符。", "体重": "搭配：体重没有名次，不能与“晋升”搭配。", "排名": "排名指名次，“排名晋升”表示名次上升，符合句意。"}, "sentence_index": 0, "correct_answer": "排名"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他这个月的排名增加了三公斤。", "explanation": "这里应该用〈体重〉。排名表示位置或名次，不能用“公斤”计量。"}, {"text": "这次活动的排名定在周六。", "explanation": "这里应该用〈日期〉。排名表示位置，不能“定在”某一天。"}, {"text": "他这次考试的排名是八十分。", "explanation": "这里应该用〈分数〉。排名表示位置或名次，不是分数，不能说“八十分”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf5d48ef-4b40-4f5e-8fb2-d5452eeb113f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11936, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "年龄", "is_correct": false, "explanation": "语义：年龄不能按名次排出先后，句子无法成立。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色没有名次，“从第十升到第五”说的不是颜色。"}, {"text": "嗓音", "is_correct": false, "explanation": "搭配：“升到第五”说的是名次，不能用于嗓音。"}, {"text": "排名", "is_correct": true, "explanation": "排名指名次，“从第十升到第五”描述的正是名次的变化，符合句意。"}], "explanations": {"年龄": "语义：年龄不能按名次排出先后，句子无法成立。", "颜色": "语义：颜色没有名次，“从第十升到第五”说的不是颜色。", "嗓音": "搭配：“升到第五”说的是名次，不能用于嗓音。", "排名": "排名指名次，“从第十升到第五”描述的正是名次的变化，符合句意。"}, "sentence_index": 6, "correct_answer": "排名"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的排名是三十岁。", "explanation": "这里应该用〈年龄〉。排名表示位置，不能用来说明年龄。"}, {"text": "妈妈做的排名很好吃。", "explanation": "这里应该用〈饭菜〉。排名表示位置或名次，不能吃，不能说“很好吃”。"}, {"text": "他的排名会游泳。", "explanation": "这里应该用〈人〉作主语。“会游泳”要求主语能游泳，排名不是人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf5d48ef-4b40-4f5e-8fb2-d5452eeb113f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11936, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小王的排名又往前了进一位。", "corrected_sentence": "小王的排名又往前进了一位。", "error_description": "语序错误：完成标记“了”应紧跟动词“进”，应说“往前进了一位”，而非“往前了进一位”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf5d48ef-4b40-4f5e-8fb2-d5452eeb113f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11936, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她的排名是五第。", "corrected_sentence": "她的排名是第五。", "error_description": "错误形式“五第”，正确形式“第五”。序数词要把“第”放在前面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf5d48ef-4b40-4f5e-8fb2-d5452eeb113f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11937, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "降职", "is_correct": true, "explanation": "降职指职位降低，与晋升的意思相反，是词典所列的反义词。"}, {"text": "搬运", "is_correct": false, "explanation": "搬运是搬动物品的动作，与晋升没有反义关系。"}, {"text": "烹饪", "is_correct": false, "explanation": "烹饪是做饭的动作，与晋升没有反义关系。"}, {"text": "赞美", "is_correct": false, "explanation": "赞美是称赞别人，与晋升没有反义关系。"}], "correct_answer": "降职", "explanations": {"降职": "降职指职位降低，与晋升的意思相反，是词典所列的反义词。", "搬运": "搬运是搬动物品的动作，与晋升没有反义关系。", "烹饪": "烹饪是做饭的动作，与晋升没有反义关系。", "赞美": "赞美是称赞别人，与晋升没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf5d48ef-4b40-4f5e-8fb2-d5452eeb113f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11937, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "降职", "is_correct": true, "explanation": "降职指职位降低，与晋升的意思相反，是词典所列的反义词。"}, {"text": "旅行", "is_correct": false, "explanation": "旅行是出门游览，与晋升没有反义关系。"}, {"text": "修理", "is_correct": false, "explanation": "修理是把坏的东西弄好，与晋升没有反义关系。"}, {"text": "翻译", "is_correct": false, "explanation": "翻译是转换语言，与晋升没有反义关系。"}], "correct_answer": "降职", "explanations": {"降职": "降职指职位降低，与晋升的意思相反，是词典所列的反义词。", "旅行": "旅行是出门游览，与晋升没有反义关系。", "修理": "修理是把坏的东西弄好，与晋升没有反义关系。", "翻译": "翻译是转换语言，与晋升没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf5d48ef-4b40-4f5e-8fb2-d5452eeb113f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11937, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "晋升指在组织或机构中，职位、等级或地位向更高层次提升。", "primary_collocate": null, "pronunciation": "jìn shēng", "ipa": "tɕin˥˩ ʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "它不仅是资源争夺或排名晋升的显性对抗，更深层地体现为声望资本的隐性积累。", "target_word": "晋升", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "他工作很努力，今年晋升为经理。", "target_word": "晋升", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她晋升以后，工资高了很多。", "target_word": "晋升", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司今年有三个人晋升。", "target_word": "晋升", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想要晋升，你要先做出成绩。", "target_word": "晋升", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在公司工作十年才晋升为部长。", "target_word": "晋升", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王晋升了，大家都为他高兴。", "target_word": "晋升", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位军官去年晋升为上校。", "target_word": "晋升", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她三年内晋升过两次。", "target_word": "晋升", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理说，下个月会让他晋升。", "target_word": "晋升", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "晋升了", "label": "体标"}, {"form": "晋升过", "label": "体标"}, {"form": "晋升为", "label": "补语"}], "register": "中性", "sense_fingerprint": "在组织中职位或等级升高", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a504ff71-c661-4a1d-b12d-34e4e5063915') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11937, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "散步", "is_correct": false, "explanation": "语义：散步不是资源争夺或对抗的行为，“排名散步的对抗”说不通。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：打扫与争夺和对抗无关，句意不通。"}, {"text": "研究", "is_correct": false, "explanation": "搭配：“研究”通常要接对象，“排名研究的显性对抗”搭配不当。"}, {"text": "晋升", "is_correct": true, "explanation": "晋升指职位或等级向上提升，“排名晋升”描述的正是争夺向上的过程，符合句意。"}], "explanations": {"散步": "语义：散步不是资源争夺或对抗的行为，“排名散步的对抗”说不通。", "打扫": "语义：打扫与争夺和对抗无关，句意不通。", "研究": "搭配：“研究”通常要接对象，“排名研究的显性对抗”搭配不当。", "晋升": "晋升指职位或等级向上提升，“排名晋升”描述的正是争夺向上的过程，符合句意。"}, "sentence_index": 0, "correct_answer": "晋升"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台电脑晋升了。", "explanation": "这里应该用〈升级〉。晋升只用于人或组织的职位和等级，电脑的版本要说“升级”。"}, {"text": "他的成绩晋升了。", "explanation": "这里应该用〈提高〉。晋升用于职位和等级，成绩要说“提高”。"}, {"text": "这家店的价格晋升了。", "explanation": "这里应该用〈上涨〉。晋升用于职位和等级，价格要说“上涨”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf5d48ef-4b40-4f5e-8fb2-d5452eeb113f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11937, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "咳嗽", "is_correct": false, "explanation": "语义：咳嗽是身体反应，不是能让大家为他高兴的事情。"}, {"text": "迟到", "is_correct": false, "explanation": "语义：迟到不是值得大家高兴的事，句意不通。"}, {"text": "发胖", "is_correct": false, "explanation": "体貌：“发胖”描述外形变化，与句中的喜事语境不合。"}, {"text": "晋升", "is_correct": true, "explanation": "晋升指职位向上提升，是值得大家高兴的事，符合句意。"}], "explanations": {"咳嗽": "语义：咳嗽是身体反应，不是能让大家为他高兴的事情。", "迟到": "语义：迟到不是值得大家高兴的事，句意不通。", "发胖": "体貌：“发胖”描述外形变化，与句中的喜事语境不合。", "晋升": "晋升指职位向上提升，是值得大家高兴的事，符合句意。"}, "sentence_index": 6, "correct_answer": "晋升"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的体重晋升了五公斤。", "explanation": "这里应该用〈增加〉。晋升用于职位和等级，体重的增加要说“增加”，不说“晋升”。"}, {"text": "他的年龄晋升了。", "explanation": "这里应该用〈增长〉。晋升用于职位和等级，年龄要说“增长”。"}, {"text": "今年的销量晋升了。", "explanation": "这里应该用〈上升〉。晋升用于职位和等级，销量要说“上升”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf5d48ef-4b40-4f5e-8fb2-d5452eeb113f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11937, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小李去年晋升着科长。", "corrected_sentence": "小李去年晋升为科长。", "error_description": "错误形式“晋升着”，正确形式“晋升为”。“晋升”后接职位要用补语“为”，不能用“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf5d48ef-4b40-4f5e-8fb2-d5452eeb113f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11937, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我哥哥上个月已经晋升着。", "corrected_sentence": "我哥哥上个月已经晋升了。", "error_description": "错误形式“晋升着”，正确形式“晋升了”。表示已经完成的变化要用“了”，不能用“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf5d48ef-4b40-4f5e-8fb2-d5452eeb113f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11938, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "隐性", "is_correct": true, "explanation": "隐性：与显性相对，指特征不容易被察觉。"}, {"text": "快速", "is_correct": false, "explanation": "与“显性”无反义关系。快速指速度快，与显性不构成相对的概念。"}, {"text": "复杂", "is_correct": false, "explanation": "与“显性”无反义关系。复杂指结构繁多，与显性不构成相对的概念。"}, {"text": "温暖", "is_correct": false, "explanation": "与“显性”无反义关系。温暖指温度或情感的状态，与显性不构成相对的概念。"}], "correct_answer": "隐性", "explanations": {"隐性": "隐性：与显性相对，指特征不容易被察觉。", "快速": "与“显性”无反义关系。快速指速度快，与显性不构成相对的概念。", "复杂": "与“显性”无反义关系。复杂指结构繁多，与显性不构成相对的概念。", "温暖": "与“显性”无反义关系。温暖指温度或情感的状态，与显性不构成相对的概念。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86eb21fd-0132-4568-ae7c-75f9765876f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11938, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "隐性", "is_correct": true, "explanation": "隐性：与显性相对，指特征不容易被察觉。"}, {"text": "粗糙", "is_correct": false, "explanation": "与“显性”无反义关系。粗糙指质地不光滑，与显性不构成相对的概念。"}, {"text": "善良", "is_correct": false, "explanation": "与“显性”无反义关系。善良指品性和心地，与显性不构成相对的概念。"}, {"text": "陡峭", "is_correct": false, "explanation": "与“显性”无反义关系。陡峭指地势或坡度，与显性不构成相对的概念。"}], "correct_answer": "隐性", "explanations": {"隐性": "隐性：与显性相对，指特征不容易被察觉。", "粗糙": "与“显性”无反义关系。粗糙指质地不光滑，与显性不构成相对的概念。", "善良": "与“显性”无反义关系。善良指品性和心地，与显性不构成相对的概念。", "陡峭": "与“显性”无反义关系。陡峭指地势或坡度，与显性不构成相对的概念。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86eb21fd-0132-4568-ae7c-75f9765876f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11938, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指事物容易察觉或明确表现出来的特征。", "primary_collocate": null, "pronunciation": "xiǎn xìng", "ipa": "ɕi̯ɛn˨˩ ɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "它不仅是资源争夺或排名晋升的显性对抗，更深层地体现为声望资本的隐性积累。", "target_word": "显性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这家公司的显性成本很低，隐性成本却很高。", "target_word": "显性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的不安是显性的，说话时手一直在抖。", "target_word": "显性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题不是显性的，所以很难发现。", "target_word": "显性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "显性的矛盾解决了，隐性的矛盾还在。", "target_word": "显性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地位的差别是显性的，看衣服就知道。", "target_word": "显性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "与显性知识不同，经验很难写成文字。", "target_word": "显性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "显性的收入好算，隐性的收入难算。", "target_word": "显性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种病没有显性症状，检查才能发现。", "target_word": "显性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对工作的不满是显性的，同事都看得出来。", "target_word": "显性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "显性基因", "label": "复合"}, {"form": "显性成本", "label": "复合"}], "register": "书面", "sense_fingerprint": "事物的特征容易被察觉、明确表现出来，与隐性相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6b2369b-e895-4499-98cc-06ea7bf3828e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11938, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "显性", "is_correct": true, "explanation": "显性（xiǎn xìng）：指事物容易察觉或明确表现出来的特征，与“隐性”相对。"}, {"text": "线性", "is_correct": false, "explanation": "线性（xiàn xìng）与显性的第一音节声调不同：xiàn 为第四声，xiǎn 为第三声。意思是呈直线关系，与“明显”无关。"}, {"text": "现行", "is_correct": false, "explanation": "现行（xiàn xíng）与显性的声调不同：第一音节 xiàn 为第四声，第二音节 xíng 为第二声。意思是当前正在实行的。"}, {"text": "显形", "is_correct": false, "explanation": "显形（xiǎn xíng）与显性的第二音节声调不同：xíng 为第二声，xìng 为第四声。意思是显露出原本的形状。"}, {"text": "限行", "is_correct": false, "explanation": "限行（xiàn xíng）与显性的两个音节声调都不同。意思是限制车辆或人员通行。"}], "explanations": {"显性": "显性（xiǎn xìng）：指事物容易察觉或明确表现出来的特征，与“隐性”相对。", "线性": "线性（xiàn xìng）与显性的第一音节声调不同：xiàn 为第四声，xiǎn 为第三声。意思是呈直线关系，与“明显”无关。", "现行": "现行（xiàn xíng）与显性的声调不同：第一音节 xiàn 为第四声，第二音节 xíng 为第二声。意思是当前正在实行的。", "显形": "显形（xiǎn xíng）与显性的第二音节声调不同：xíng 为第二声，xìng 为第四声。意思是显露出原本的形状。", "限行": "限行（xiàn xíng）与显性的两个音节声调都不同。意思是限制车辆或人员通行。"}, "sentence_index": null, "correct_answer": "显性"}, "level_3": {"options": [{"text": "显性", "is_correct": true, "explanation": "显性：指对抗公开可见，与后文“隐性积累”形成对照。"}, {"text": "温柔", "is_correct": false, "explanation": "语义：温柔与“对抗”的竞争含义相矛盾，与前文“资源争夺”也不协调。"}, {"text": "和平", "is_correct": false, "explanation": "语义：和平与“对抗”相互矛盾，不能作“对抗”的修饰语。"}, {"text": "甜蜜", "is_correct": false, "explanation": "语义：甜蜜形容感情或味道，“甜蜜的对抗”自相矛盾。"}], "explanations": {"显性": "显性：指对抗公开可见，与后文“隐性积累”形成对照。", "温柔": "语义：温柔与“对抗”的竞争含义相矛盾，与前文“资源争夺”也不协调。", "和平": "语义：和平与“对抗”相互矛盾，不能作“对抗”的修饰语。", "甜蜜": "语义：甜蜜形容感情或味道，“甜蜜的对抗”自相矛盾。"}, "sentence_index": 0, "correct_answer": "显性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个问题很显性，所以一直没人注意到。", "explanation": "这里应该用〈隐性〉。显性指特征容易察觉，不会因此“没人注意到”，应说“隐性”。"}, {"text": "他的真实想法很显性，从不露出一点痕迹。", "explanation": "这里应该用〈隐秘〉。显性指容易察觉，“从不露出一点痕迹”与之矛盾，应说“隐秘”。"}, {"text": "他穿了一件很显性的灰裙子，走进教室谁也没注意。", "explanation": "这里应该用〈不显眼〉。显性指特征容易察觉，“谁也没注意”与之矛盾，应说“不显眼”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86eb21fd-0132-4568-ae7c-75f9765876f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11938, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "显性", "is_correct": true, "explanation": "显性（xiǎn xìng）：指事物容易察觉或明确表现出来的特征，与“隐性”相对。"}, {"text": "先行", "is_correct": false, "explanation": "先行（xiān xíng）与显性的两个音节声调都不同：xiān 为第一声，xíng 为第二声。意思是事先走在前面。"}, {"text": "线形", "is_correct": false, "explanation": "线形（xiàn xíng）与显性的两个音节声调都不同。意思是线条的形状，如直线形。"}, {"text": "线型", "is_correct": false, "explanation": "线型（xiàn xíng）与显性的两个音节声调都不同。意思是线条的类型或样式。"}, {"text": "现形", "is_correct": false, "explanation": "现形（xiàn xíng）与显性的两个音节声调都不同。意思是露出本来面目。"}], "explanations": {"显性": "显性（xiǎn xìng）：指事物容易察觉或明确表现出来的特征，与“隐性”相对。", "先行": "先行（xiān xíng）与显性的两个音节声调都不同：xiān 为第一声，xíng 为第二声。意思是事先走在前面。", "线形": "线形（xiàn xíng）与显性的两个音节声调都不同。意思是线条的形状，如直线形。", "线型": "线型（xiàn xíng）与显性的两个音节声调都不同。意思是线条的类型或样式。", "现形": "现形（xiàn xíng）与显性的两个音节声调都不同。意思是露出本来面目。"}, "sentence_index": null, "correct_answer": "显性"}, "level_3": {"options": [{"text": "显性", "is_correct": true, "explanation": "显性：指可以明确表述的知识，与“经验很难写成文字”形成对照。"}, {"text": "明亮", "is_correct": false, "explanation": "搭配：明亮多形容光线或颜色，不用来修饰“知识”。"}, {"text": "轻快", "is_correct": false, "explanation": "语义：轻快描述节奏或心情，与“知识”的类别不相干。"}, {"text": "柔软", "is_correct": false, "explanation": "搭配：柔软多形容质地，不用来修饰“知识”。"}], "explanations": {"显性": "显性：指可以明确表述的知识，与“经验很难写成文字”形成对照。", "明亮": "搭配：明亮多形容光线或颜色，不用来修饰“知识”。", "轻快": "语义：轻快描述节奏或心情，与“知识”的类别不相干。", "柔软": "搭配：柔软多形容质地，不用来修饰“知识”。"}, "sentence_index": 6, "correct_answer": "显性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他对这件事的看法很显性，却从来不说出口。", "explanation": "这里应该用〈含蓄〉。显性指特征容易察觉，“从来不说出口”与之矛盾，应说“含蓄”。"}, {"text": "他的感情很显性，每次见面都藏得很深。", "explanation": "这里应该用〈内敛〉。显性指容易察觉，“藏得很深”与之矛盾，应说“内敛”。"}, {"text": "这个人的脾气很显性，平时总是不声不响。", "explanation": "这里应该用〈温和〉。显性指特征容易察觉，与“平时总是不声不响”矛盾，形容这种脾气应说“温和”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86eb21fd-0132-4568-ae7c-75f9765876f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11938, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种过敏反应很显性的，症状很快就出现了。", "corrected_sentence": "这种过敏反应是显性的，症状很快就出现了。", "error_description": "“显性”是区别词性质的形容词，不受“很”修饰，作谓语要用“是……的”，应改为“是显性的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86eb21fd-0132-4568-ae7c-75f9765876f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11938, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种矛盾是显性，大家一开会就能看出来。", "corrected_sentence": "这种矛盾是显性的，大家一开会就能看出来。", "error_description": "“显性”作表语时要带“的”，应说“是显性的”，不能只说“是显性”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86eb21fd-0132-4568-ae7c-75f9765876f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
