INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11943, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86eb21fd-0132-4568-ae7c-75f9765876f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11943, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指巧妙的技能或方法。", "primary_collocate": null, "pronunciation": "jì qiǎo", "ipa": "tɕi˥˩ tɕʰiɑu̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "这位画家的绘画技巧非常高。", "target_word": "技巧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的演奏技巧让观众不停鼓掌。", "target_word": "技巧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打篮球需要力量，也需要技巧。", "target_word": "技巧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的写作技巧一年比一年好。", "target_word": "技巧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师傅的雕刻技巧很高超。", "target_word": "技巧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她游泳的技巧比我好得多。", "target_word": "技巧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "练习了三年后，他的技巧更熟练了。", "target_word": "技巧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个舞蹈有很多难度大的技巧。", "target_word": "技巧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位运动员的比赛技巧很丰富。", "target_word": "技巧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的歌手要有声音，也要有唱歌技巧。", "target_word": "技巧", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "技巧性", "label": "复合词"}], "register": "中性", "sense_fingerprint": "技巧|名词|艺术、体育等方面巧妙熟练的技能", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6b2369b-e895-4499-98cc-06ea7bf3828e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11943, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "技巧", "is_correct": true, "explanation": "正确。“绘画技巧”指绘画方面巧妙熟练的技能，与“非常高”相合。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”不能用“高”来形容，“绘画颜色非常高”不成话。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”指岁数，不是画家的绘画能力，句意不通。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“时间”不说“非常高”，只能说“很长”或“很短”。"}], "explanations": {"技巧": "正确。“绘画技巧”指绘画方面巧妙熟练的技能，与“非常高”相合。", "颜色": "搭配：“颜色”不能用“高”来形容，“绘画颜色非常高”不成话。", "年龄": "语义：“年龄”指岁数，不是画家的绘画能力，句意不通。", "时间": "搭配：“时间”不说“非常高”，只能说“很长”或“很短”。"}, "sentence_index": 0, "correct_answer": "技巧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次旅行是我最难忘的技巧。", "explanation": "这里应该用〈经验〉。“经验”指亲身经历后得到的体会，旅行本身不是技能或方法，不能说“最难忘的技巧”。"}, {"text": "他是我最好的技巧。", "explanation": "这里应该用〈朋友〉。“朋友”指关系亲近的人，“技巧”指做事的方法，不能用来指人。"}, {"text": "我每天早上喝一杯技巧。", "explanation": "这里应该用〈牛奶〉。“技巧”指巧妙的技能或方法，不是饮料，不能“喝”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86eb21fd-0132-4568-ae7c-75f9765876f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11943, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "技巧", "is_correct": true, "explanation": "正确。“技巧”指熟练的技能，与“练习了三年后”和“更熟练”相合。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”是身体的重量，不会因为练习而“更熟练”，句意不通。"}, {"text": "发型", "is_correct": false, "explanation": "搭配：“熟练”用于技能，不能说“发型更熟练”。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”是性情，不是可以通过练习变得熟练的东西。"}], "explanations": {"技巧": "正确。“技巧”指熟练的技能，与“练习了三年后”和“更熟练”相合。", "体重": "语义：“体重”是身体的重量，不会因为练习而“更熟练”，句意不通。", "发型": "搭配：“熟练”用于技能，不能说“发型更熟练”。", "脾气": "语义：“脾气”是性情，不是可以通过练习变得熟练的东西。"}, "sentence_index": 6, "correct_answer": "技巧"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的技巧穿在身上很舒服。", "explanation": "这里应该用〈衣服〉。“衣服”可以穿在身上；“技巧”是技能或方法，不能穿。"}, {"text": "他的技巧是三十岁。", "explanation": "这里应该用〈年龄〉。“年龄”指年数，“技巧”不能用来表示人的岁数。"}, {"text": "我家的技巧是北京。", "explanation": "这里应该用〈地址〉。“地址”指住所的位置，“技巧”不能表示地点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86eb21fd-0132-4568-ae7c-75f9765876f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11943, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他教我一把绘画的新技巧。", "corrected_sentence": "他教我一种绘画的新技巧。", "error_description": "量词错误：“技巧”应用“种”或“个”，应为“一种绘画的新技巧”。“把”用于有柄的物件，不能修饰“技巧”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86eb21fd-0132-4568-ae7c-75f9765876f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11943, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的技巧比以前很熟练了。", "corrected_sentence": "他的技巧比以前更熟练了。", "error_description": "错误形式：“比以前很熟练”。正确形式：“比以前更熟练”。“比”字句中形容词前不能用“很”，可以用“更”或“还”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86eb21fd-0132-4568-ae7c-75f9765876f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
